/**\n * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.\n *\n * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload\n */\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { createLogger } from \"@/lib/logger\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { signPayload } from \"@/server/services/webhook-service\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { runJob } from \"./types\";\nimport type { JobResult } from \"@/server/jobs/types\";\nimport type { OrgId } from \"@/types/common\";\n\n/** How many deliveries one pass claims. */\nconst CLAIM_BATCH = 25;\n\n/** Attempts after which a delivery is marked failed for good. */\nconst MAX_ATTEMPTS = 6;\n\nconst logger = createLogger(\"webhook-delivery-job\");\n\n/**\n * Delivers each claimed row. There is no outbound HTTP in Taskflow — the\n * corpus builds and runs offline — so \"delivery\" means computing the\n * signature the receiver would verify and logging the attempt. The retry\n * bookkeeping around it is the part that has to be right.\n */\nexport async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {\n  return runJob(\"webhook-delivery\", async (result) => {\n    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);\n\n    for (const delivery of claimed) {\n      const orgId = delivery.orgId as OrgId;\n\n      if (!(await orgAllowsWebhooks(orgId))) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          \"webhooks are not included in this organization's plan\",\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      if (delivery.attempts > MAX_ATTEMPTS) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          `giving up after ${delivery.attempts} attempts`,\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(\n        (row) => row.id === delivery.endpointId,\n      );\n\n      if (!endpoint || !endpoint.enabled) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          \"endpoint is missing or disabled\",\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      const signature = signPayload(endpoint.secret, delivery.payload);\n\n      logger.info(\"webhook delivered\", {\n        deliveryId: delivery.id,\n        endpoint: endpoint.url,\n        eventType: delivery.eventType,\n        signature: signature.slice(0, 16),\n        backoffMs: backoffMs(delivery.attempts),\n      });\n\n      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));\n      result.processed += 1;\n    }\n  });\n}\n\n/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */\nexport function backoffMs(attempts: number): number {\n  if (attempts <= 0) return 0;\n  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);\n}\n\nasync function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {\n  const org = await orgRepo.findOrgById(orgId);\n  if (!org) return false;\n\n  if (getPlanLimits(org.plan).webhooks <= 0) return false;\n  return isEnabled(\"webhooks\", buildFlagContext(null, org));\n}\n","import {\n  AppRouteRouteModule,\n  type AppRouteRouteHandlerContext,\n  type AppRouteRouteModuleOptions,\n} from '../../server/route-modules/app-route/module.compiled'\nimport { RouteKind } from '../../server/route-kind'\nimport { patchFetch as _patchFetch } from '../../server/lib/patch-fetch'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport {\n  addRequestMeta,\n  getRequestMeta,\n  setRequestMeta,\n  type RequestMeta,\n} from '../../server/request-meta'\nimport {\n  getTracer,\n  type Span,\n  SpanKind,\n  SpanStatusCode,\n} from '../../server/lib/trace/tracer'\nimport { setManifestsSingleton } from '../../server/app-render/manifests-singleton'\nimport { normalizeAppPath } from '../../shared/lib/router/utils/app-paths'\nimport { NodeNextRequest, NodeNextResponse } from '../../server/base-http/node'\nimport {\n  NextRequestAdapter,\n  signalFromNodeResponse,\n} from '../../server/web/spec-extension/adapters/next-request'\nimport { BaseServerSpan } from '../../server/lib/trace/constants'\nimport { getRevalidateReason } from '../../server/instrumentation/utils'\nimport { sendResponse } from '../../server/send-response'\nimport {\n  fromNodeOutgoingHttpHeaders,\n  toNodeOutgoingHttpHeaders,\n} from '../../server/web/utils'\nimport { getCacheControlHeader } from '../../server/lib/cache-control'\nimport { INFINITE_CACHE, NEXT_CACHE_TAGS_HEADER } from '../../lib/constants'\nimport { NoFallbackError } from '../../shared/lib/no-fallback-error.external'\nimport {\n  CachedRouteKind,\n  type ResponseCacheEntry,\n  type ResponseGenerator,\n} from '../../server/response-cache'\n\n// These are injected by the loader afterwards. This is injected as a variable\n// instead of a replacement because this could also be `undefined` instead of\n// an empty string.\ndeclare const nextConfigOutput: AppRouteRouteModuleOptions['nextConfigOutput']\n\n// We inject the nextConfigOutput here so that we can use them in the route\n// module.\n// INJECT:nextConfigOutput\n\nconst routeModule = new AppRouteRouteModule({\n  definition: {\n    kind: RouteKind.APP_ROUTE,\n    page: 'VAR_DEFINITION_PAGE',\n    pathname: 'VAR_DEFINITION_PATHNAME',\n    filename: 'VAR_DEFINITION_FILENAME',\n    bundlePath: 'VAR_DEFINITION_BUNDLE_PATH',\n  },\n  distDir: process.env.__NEXT_RELATIVE_DIST_DIR || '',\n  relativeProjectDir: process.env.__NEXT_RELATIVE_PROJECT_DIR || '',\n  resolvedPagePath: 'VAR_RESOLVED_PAGE_PATH',\n  nextConfigOutput,\n  // The lazy require factory ensures that:\n  // - In dev: devRequestTimingInternalsEnd is set before userland executes,\n  //   correctly attributing module load time to application-code rather than\n  //   framework internals.\n  // - In all modes: async modules (route files with top-level await) are\n  //   handled correctly — require() returns a Promise for such modules, which\n  //   ensureUserland() awaits before the first request is handled.\n  userland: () => require('VAR_USERLAND') as typeof import('VAR_USERLAND'),\n  // In Turbopack dev mode, also provide a synchronous per-request getter so\n  // server HMR updates are picked up without re-executing the entry chunk.\n  // Using require() (synchronous) avoids adding async overhead that would be\n  // incorrectly attributed to application-code time in devRequestTiming.\n  ...(process.env.TURBOPACK && process.env.__NEXT_DEV_SERVER\n    ? {\n        getUserland: () =>\n          require('VAR_USERLAND') as typeof import('VAR_USERLAND'),\n      }\n    : {}),\n})\n\n// Pull out the exports that we need to expose from the module. This should\n// be eliminated when we've moved the other routes to the new format. These\n// are used to hook into the route.\nconst { workAsyncStorage, workUnitAsyncStorage, serverHooks } = routeModule\n\nfunction patchFetch() {\n  return _patchFetch({\n    workAsyncStorage,\n    workUnitAsyncStorage,\n  })\n}\n\nexport {\n  routeModule,\n  workAsyncStorage,\n  workUnitAsyncStorage,\n  serverHooks,\n  patchFetch,\n}\n\nexport async function handler(\n  req: IncomingMessage,\n  res: ServerResponse,\n  ctx: {\n    waitUntil?: (prom: Promise<void>) => void\n    requestMeta?: RequestMeta\n  }\n) {\n  if (ctx.requestMeta) {\n    setRequestMeta(req, ctx.requestMeta)\n  }\n  if (routeModule.isDev) {\n    addRequestMeta(req, 'devRequestTimingInternalsEnd', process.hrtime.bigint())\n  }\n  let srcPage = 'VAR_DEFINITION_PAGE'\n\n  // turbopack doesn't normalize `/index` in the page name\n  // so we need to to process dynamic routes properly\n  // TODO: fix turbopack providing differing value from webpack\n  if (process.env.TURBOPACK) {\n    srcPage = srcPage.replace(/\\/index$/, '') || '/'\n  } else if (srcPage === '/index') {\n    // we always normalize /index specifically\n    srcPage = '/'\n  }\n  const multiZoneDraftMode = process.env\n    .__NEXT_MULTI_ZONE_DRAFT_MODE as any as boolean\n\n  const prepareResult = await routeModule.prepare(req, res, {\n    srcPage,\n    multiZoneDraftMode,\n  })\n\n  if (!prepareResult) {\n    res.statusCode = 400\n    res.end('Bad Request')\n    ctx.waitUntil?.(Promise.resolve())\n    return null\n  }\n\n  const {\n    buildId,\n    deploymentId,\n    params,\n    nextConfig,\n    parsedUrl,\n    isDraftMode,\n    prerenderManifest,\n    routerServerContext,\n    isOnDemandRevalidate,\n    revalidateOnlyGenerated,\n    resolvedPathname,\n    clientReferenceManifest,\n    serverActionsManifest,\n  } = prepareResult\n\n  const normalizedSrcPage = normalizeAppPath(srcPage)\n\n  let isIsr = Boolean(\n    prerenderManifest.dynamicRoutes[normalizedSrcPage] ||\n      prerenderManifest.routes[resolvedPathname]\n  )\n\n  const render404 = async () => {\n    // TODO: should route-module itself handle rendering the 404\n    if (routerServerContext?.render404) {\n      await routerServerContext.render404(req, res, parsedUrl, false)\n    } else {\n      res.end('This page could not be found')\n    }\n    return null\n  }\n\n  if (isIsr && !isDraftMode) {\n    const isPrerendered = Boolean(prerenderManifest.routes[resolvedPathname])\n    const prerenderInfo = prerenderManifest.dynamicRoutes[normalizedSrcPage]\n\n    if (prerenderInfo) {\n      if (prerenderInfo.fallback === false && !isPrerendered) {\n        if (nextConfig.adapterPath) {\n          return await render404()\n        }\n        throw new NoFallbackError()\n      }\n    }\n  }\n\n  let cacheKey: string | null = null\n\n  if (isIsr && !routeModule.isDev && !isDraftMode) {\n    cacheKey = resolvedPathname\n    // ensure /index and / is normalized to one key\n    cacheKey = cacheKey === '/index' ? '/' : cacheKey\n  }\n\n  const supportsDynamicResponse: boolean =\n    // If we're in development, we always support dynamic HTML\n    routeModule.isDev === true ||\n    // If this is not SSG or does not have static paths, then it supports\n    // dynamic HTML.\n    !isIsr\n\n  // This is a revalidation request if the request is for a static\n  // page and it is not being resumed from a postponed render and\n  // it is not a dynamic RSC request then it is a revalidation\n  // request.\n  const isStaticGeneration = isIsr && !supportsDynamicResponse\n\n  // Before rendering (which initializes component tree modules), we have to\n  // set the reference manifests to our global store so Server Action's\n  // encryption util can access to them at the top level of the page module.\n  if (serverActionsManifest && clientReferenceManifest) {\n    setManifestsSingleton({\n      page: srcPage,\n      clientReferenceManifest,\n      serverActionsManifest,\n    })\n  }\n\n  const method = req.method || 'GET'\n  const tracer = getTracer()\n  const activeSpan = tracer.getActiveScopeSpan()\n  const isWrappedByNextServer = Boolean(\n    routerServerContext?.isWrappedByNextServer\n  )\n  const isMinimalMode = Boolean(getRequestMeta(req, 'minimalMode'))\n\n  const incrementalCache =\n    getRequestMeta(req, 'incrementalCache') ||\n    (await routeModule.getIncrementalCache(\n      req,\n      nextConfig,\n      prerenderManifest,\n      isMinimalMode\n    ))\n\n  incrementalCache?.resetRequestCache()\n  ;(globalThis as any).__incrementalCache = incrementalCache\n\n  const context: AppRouteRouteHandlerContext = {\n    params,\n    previewProps: prerenderManifest.preview,\n    renderOpts: {\n      experimental: {\n        authInterrupts: Boolean(nextConfig.experimental.authInterrupts),\n        useCacheTimeout: nextConfig.experimental.useCacheTimeout,\n      },\n      cacheComponents: Boolean(nextConfig.cacheComponents),\n      validationLevel: nextConfig.experimental.instantInsights.validationLevel,\n      supportsDynamicResponse,\n      incrementalCache,\n      hmrRefreshHash: getRequestMeta(req, 'hmrRefreshHash'),\n      cacheLifeProfiles: nextConfig.cacheLife,\n      staticPageGenerationTimeout: nextConfig.staticPageGenerationTimeout,\n      waitUntil: ctx.waitUntil,\n      onClose: (cb) => {\n        res.on('close', cb)\n      },\n      onAfterTaskError: undefined,\n      onInstrumentationRequestError: (\n        error,\n        _request,\n        errorContext,\n        silenceLog\n      ) =>\n        routeModule.onRequestError(\n          req,\n          error,\n          errorContext,\n          silenceLog,\n          routerServerContext\n        ),\n    },\n    sharedContext: {\n      buildId,\n      deploymentId,\n    },\n  }\n  const nodeNextReq = new NodeNextRequest(req)\n  const nodeNextRes = new NodeNextResponse(res)\n\n  const nextReq = NextRequestAdapter.fromNodeNextRequest(\n    nodeNextReq,\n    signalFromNodeResponse(res)\n  )\n\n  const responseGenerator: ResponseGenerator = async ({\n    previousCacheEntry,\n  }) => {\n    try {\n      if (\n        !isMinimalMode &&\n        isOnDemandRevalidate &&\n        revalidateOnlyGenerated &&\n        !previousCacheEntry\n      ) {\n        res.statusCode = 404\n        // on-demand revalidate always sets this header\n        res.setHeader('x-nextjs-cache', 'REVALIDATED')\n        res.end('This page could not be found')\n        return null\n      }\n\n      const response = await routeModule.handle(nextReq, context)\n\n      ;(req as any).fetchMetrics = (context.renderOpts as any).fetchMetrics\n      let pendingWaitUntil = context.renderOpts.pendingWaitUntil\n\n      // Attempt using provided waitUntil if available\n      // if it's not we fallback to sendResponse's handling\n      if (pendingWaitUntil) {\n        if (ctx.waitUntil) {\n          ctx.waitUntil(pendingWaitUntil)\n          pendingWaitUntil = undefined\n        }\n      }\n      const cacheTags = context.renderOpts.collectedTags\n\n      // If the request is for a static response, we can cache it so long\n      // as it's not edge.\n      if (isIsr) {\n        const blob = await response.blob()\n\n        // Copy the headers from the response.\n        const headers = toNodeOutgoingHttpHeaders(response.headers)\n\n        if (cacheTags) {\n          headers[NEXT_CACHE_TAGS_HEADER] = cacheTags\n        }\n\n        if (!headers['content-type'] && blob.type) {\n          headers['content-type'] = blob.type\n        }\n\n        const revalidate =\n          typeof context.renderOpts.collectedRevalidate === 'undefined' ||\n          context.renderOpts.collectedRevalidate >= INFINITE_CACHE\n            ? false\n            : context.renderOpts.collectedRevalidate\n\n        const expire =\n          typeof context.renderOpts.collectedExpire === 'undefined' ||\n          context.renderOpts.collectedExpire >= INFINITE_CACHE\n            ? // Fall back to the global `expireTime` config when the\n              // route has a numeric `revalidate` but didn't declare an\n              // explicit `expire` (e.g. via `cacheLife`). This mirrors the\n              // build-time fallback in `build/index.ts` so cache entries\n              // and the response Cache-Control header agree on the route's\n              // effective expire. Routes that opt out of revalidation\n              // (`revalidate: false`) or that are dynamic (`revalidate: 0`)\n              // keep `expire: undefined`.\n              revalidate !== false && revalidate > 0\n              ? nextConfig.expireTime\n              : undefined\n            : context.renderOpts.collectedExpire\n\n        // Create the cache entry for the response.\n        const cacheEntry: ResponseCacheEntry = {\n          value: {\n            kind: CachedRouteKind.APP_ROUTE,\n            status: response.status,\n            body: Buffer.from(await blob.arrayBuffer()),\n            headers,\n          },\n          cacheControl: { revalidate, expire },\n        }\n\n        return cacheEntry\n      } else {\n        // send response without caching if not ISR\n        await sendResponse(nodeNextReq, nodeNextRes, response, pendingWaitUntil)\n        return null\n      }\n    } catch (err) {\n      // if this is a background revalidate we need to report\n      // the request error here as it won't be bubbled\n      if (previousCacheEntry?.isStale) {\n        const silenceLog = false\n        await routeModule.onRequestError(\n          req,\n          err,\n          {\n            routerKind: 'App Router',\n            routePath: srcPage,\n            routeType: 'route',\n            revalidateReason: getRevalidateReason({\n              isStaticGeneration,\n              isOnDemandRevalidate,\n            }),\n          },\n          silenceLog,\n          routerServerContext\n        )\n      }\n      throw err\n    }\n  }\n\n  const handleResponse = async (\n    currentSpan: Span | undefined,\n    parentSpan: Span | undefined\n  ) => {\n    try {\n      const cacheEntry = await routeModule.handleResponse({\n        req,\n        nextConfig,\n        cacheKey,\n        routeKind: RouteKind.APP_ROUTE,\n        isFallback: false,\n        prerenderManifest,\n        isRoutePPREnabled: false,\n        isOnDemandRevalidate,\n        revalidateOnlyGenerated,\n        responseGenerator,\n        waitUntil: ctx.waitUntil,\n        isMinimalMode,\n      })\n\n      // we don't create a cacheEntry for ISR\n      if (!isIsr) {\n        return\n      }\n\n      if (cacheEntry?.value?.kind !== CachedRouteKind.APP_ROUTE) {\n        throw new Error(\n          `Invariant: app-route received invalid cache entry ${cacheEntry?.value?.kind}`\n        )\n      }\n\n      if (!isMinimalMode) {\n        res.setHeader(\n          'x-nextjs-cache',\n          isOnDemandRevalidate\n            ? 'REVALIDATED'\n            : cacheEntry.isMiss\n              ? 'MISS'\n              : cacheEntry.isStale\n                ? 'STALE'\n                : 'HIT'\n        )\n      }\n\n      // Draft mode should never be cached\n      if (isDraftMode) {\n        res.setHeader(\n          'Cache-Control',\n          'private, no-cache, no-store, max-age=0, must-revalidate'\n        )\n      }\n\n      const headers = fromNodeOutgoingHttpHeaders(cacheEntry.value.headers)\n\n      if (!(isMinimalMode && isIsr)) {\n        headers.delete(NEXT_CACHE_TAGS_HEADER)\n      }\n\n      // If cache control is already set on the response we don't\n      // override it to allow users to customize it via next.config\n      if (\n        cacheEntry.cacheControl &&\n        !res.getHeader('Cache-Control') &&\n        !headers.get('Cache-Control')\n      ) {\n        headers.set(\n          'Cache-Control',\n          getCacheControlHeader(cacheEntry.cacheControl)\n        )\n      }\n\n      await sendResponse(\n        nodeNextReq,\n        nodeNextRes,\n        // @ts-expect-error - Argument of type 'Buffer<ArrayBufferLike>' is not assignable to parameter of type 'BodyInit | null | undefined'.\n        new Response(cacheEntry.value.body, {\n          headers,\n          status: cacheEntry.value.status || 200,\n        })\n      )\n      return\n    } catch (err) {\n      if (!(err instanceof NoFallbackError)) {\n        const silenceLog = false\n        await routeModule.onRequestError(\n          req,\n          err,\n          {\n            routerKind: 'App Router',\n            routePath: normalizedSrcPage,\n            routeType: 'route',\n            revalidateReason: getRevalidateReason({\n              isStaticGeneration,\n              isOnDemandRevalidate,\n            }),\n          },\n          silenceLog,\n          routerServerContext\n        )\n      }\n\n      // rethrow so that we can handle serving error page\n\n      // If this is during static generation, throw the error again.\n      if (isIsr) throw err\n\n      // Otherwise, send a 500 response.\n      await sendResponse(\n        nodeNextReq,\n        nodeNextRes,\n        new Response(null, { status: 500 })\n      )\n      return\n    } finally {\n      ;(() => {\n        if (!currentSpan) {\n          return\n        }\n\n        let statusCode = res.statusCode\n\n        currentSpan.setAttributes({\n          'http.status_code': statusCode,\n          'next.rsc': false,\n        })\n\n        if (statusCode && statusCode >= 500) {\n          // For 5xx status codes: SHOULD be set to 'Error' span status.\n          // x-ref: https://opentelemetry.io/docs/specs/semconv/http/http-spans/#status\n          currentSpan.setStatus({\n            code: SpanStatusCode.ERROR,\n          })\n          // For span status 'Error', SHOULD set 'error.type' attribute.\n          currentSpan.setAttribute('error.type', statusCode.toString())\n        }\n\n        const rootSpanAttributes = tracer.getRootSpanAttributes()\n        // We were unable to get attributes, probably OTEL is not enabled\n        if (!rootSpanAttributes) {\n          return\n        }\n\n        if (\n          rootSpanAttributes.get('next.span_type') !==\n          BaseServerSpan.handleRequest\n        ) {\n          console.warn(\n            `Unexpected root span type '${rootSpanAttributes.get(\n              'next.span_type'\n            )}'. Please report this Next.js issue https://github.com/vercel/next.js`\n          )\n          return\n        }\n\n        const route = rootSpanAttributes.get('next.route') || normalizedSrcPage\n        const name = `${method} ${route}`\n\n        currentSpan.setAttributes({\n          'next.route': route,\n          'http.route': route,\n          'next.span_name': name,\n        })\n        currentSpan.updateName(name)\n\n        // Propagate http.route to the parent span if one exists (e.g.\n        // a platform-created HTTP span in adapter deployments).\n        if (parentSpan && parentSpan !== currentSpan) {\n          parentSpan.setAttribute('http.route', route)\n          parentSpan.updateName(name)\n        }\n      })()\n    }\n  }\n\n  // TODO: activeSpan code path is for when wrapped by\n  // next-server can be removed when this is no longer used\n  if (isWrappedByNextServer && activeSpan) {\n    await handleResponse(activeSpan, undefined)\n  } else {\n    let parentSpan = tracer.getActiveScopeSpan()\n    await tracer.withPropagatedContext(\n      req.headers,\n      () =>\n        tracer.trace(\n          BaseServerSpan.handleRequest,\n          {\n            spanName: `${method} ${srcPage}`,\n            kind: SpanKind.SERVER,\n            attributes: {\n              'http.method': method,\n              'http.target': req.url,\n            },\n          },\n          (span) => handleResponse(span, parentSpan)\n        ),\n      undefined,\n      !isWrappedByNextServer\n    )\n  }\n}\n","/**\n * Password and token hashing built on `node:crypto` scrypt. No external\n * dependency — the corpus builds offline, and scrypt is the strongest KDF the\n * platform ships without one.\n *\n * Server-only: never import this from a client component.\n */\nimport {\n  createHash,\n  randomBytes,\n  scrypt,\n  timingSafeEqual,\n} from \"node:crypto\";\n\nconst KEY_LENGTH = 64;\nconst SALT_BYTES = 16;\nconst PREFIX = \"scrypt\";\n\nfunction deriveKey(password: string, salt: Buffer): Promise<Buffer> {\n  return new Promise((resolve, reject) => {\n    scrypt(password.normalize(\"NFKC\"), salt, KEY_LENGTH, (error, key) => {\n      if (error) reject(error);\n      else resolve(key);\n    });\n  });\n}\n\n/** Returns `scrypt:<saltHex>:<keyHex>` — self-describing, so the verifier\n *  can change parameters later without a migration. */\nexport async function hashPassword(password: string): Promise<string> {\n  const salt = randomBytes(SALT_BYTES);\n  const key = await deriveKey(password, salt);\n  return `${PREFIX}:${salt.toString(\"hex\")}:${key.toString(\"hex\")}`;\n}\n\n/** Constant-time comparison; a malformed stored hash simply fails to verify. */\nexport async function verifyPassword(\n  password: string,\n  hash: string,\n): Promise<boolean> {\n  const [scheme, saltHex, keyHex] = hash.split(\":\");\n  if (scheme !== PREFIX || !saltHex || !keyHex) return false;\n\n  const expected = Buffer.from(keyHex, \"hex\");\n  if (expected.length !== KEY_LENGTH) return false;\n\n  const actual = await deriveKey(password, Buffer.from(saltHex, \"hex\"));\n  return timingSafeEqual(actual, expected);\n}\n\n/** One-way digest for invitation and session tokens, which are high-entropy\n *  already and so need no salt or work factor. */\nexport function hashToken(token: string): string {\n  return createHash(\"sha256\").update(token).digest(\"hex\");\n}\n\n/** URL-safe random token; the default width matches the session schema's\n *  32-character minimum. */\nexport function randomToken(bytes = 32): string {\n  return randomBytes(bytes).toString(\"base64url\");\n}\n","/**\n * Product name, description, support links and the marketing metadata\n * defaults. The marketing pages and the email footer both read from here, so\n * the product never introduces itself two different ways.\n */\n\nexport type SiteConfig = {\n  name: string;\n  tagline: string;\n  description: string;\n  url: string;\n  supportEmail: string;\n  docsUrl: string;\n};\n\nexport const SITE_CONFIG: SiteConfig = {\n  name: \"Taskflow\",\n  tagline: \"Issue tracking that keeps up with the work\",\n  description:\n    \"Taskflow is a multi-tenant project and issue tracker for product teams: \" +\n    \"projects, issues, comments and a shared activity trail, with per-plan \" +\n    \"quotas and role-aware access built in.\",\n  url: \"https://taskflow.example.com\",\n  supportEmail: \"support@taskflow.example.com\",\n  docsUrl: \"https://docs.taskflow.example.com\",\n};\n","/**\n * Validated environment access. Nothing else in Taskflow reads `process.env`\n * — call sites import `env` (or `loadEnv()` when they need to validate a\n * different source, as the tests do) so a missing or malformed variable fails\n * once, loudly, instead of surfacing as `undefined` deep in a request.\n */\nimport { SITE_CONFIG } from \"./site\";\n\nexport type AppEnv = {\n  nodeEnv: \"development\" | \"test\" | \"production\";\n  databasePath: string;\n  appUrl: string;\n  digestEnabled: boolean;\n};\n\nconst NODE_ENVS = [\"development\", \"test\", \"production\"] as const;\n\ntype NodeEnvValue = (typeof NODE_ENVS)[number];\n\nfunction readNodeEnv(raw: string | undefined): NodeEnvValue {\n  const value = (raw ?? \"development\").trim();\n  const match = NODE_ENVS.find((candidate) => candidate === value);\n  return match ?? \"development\";\n}\n\n/** Accepts `1`/`true`/`yes`/`on` (case-insensitive) as true; anything else false. */\nfunction readBoolean(raw: string | undefined, fallback: boolean): boolean {\n  if (raw === undefined || raw.trim() === \"\") return fallback;\n  const value = raw.trim().toLowerCase();\n  if ([\"1\", \"true\", \"yes\", \"on\"].includes(value)) return true;\n  if ([\"0\", \"false\", \"no\", \"off\"].includes(value)) return false;\n  throw new Error(`Invalid boolean environment value: \"${raw}\"`);\n}\n\nfunction readUrl(raw: string | undefined, fallback: string): string {\n  const value = (raw ?? \"\").trim() || fallback;\n  try {\n    // Normalises away a trailing slash so `${appUrl}${path}` never doubles up.\n    const parsed = new URL(value);\n    return parsed.origin + parsed.pathname.replace(/\\/$/, \"\");\n  } catch {\n    throw new Error(`Invalid TASKFLOW_APP_URL: \"${value}\"`);\n  }\n}\n\n/**\n * Reads and validates the environment. Defaults are chosen so a fresh\n * checkout runs with no `.env` at all — the corpus must build offline.\n */\nexport function loadEnv(source: NodeJS.ProcessEnv = process.env): AppEnv {\n  const nodeEnv = readNodeEnv(source.NODE_ENV);\n  const databasePath =\n    (source.TASKFLOW_DB_PATH ?? \"\").trim() ||\n    (nodeEnv === \"test\" ? \":memory:\" : \"./data/taskflow.db\");\n\n  return {\n    nodeEnv,\n    databasePath,\n    appUrl: readUrl(source.TASKFLOW_APP_URL, SITE_CONFIG.url),\n    digestEnabled: readBoolean(source.TASKFLOW_DIGEST_ENABLED, nodeEnv !== \"test\"),\n  };\n}\n\nexport const env: AppEnv = loadEnv();\n","/**\n * Structured logger. The only place `console` is allowed.\n *\n * Every line is one JSON object so job output and request output can be\n * grepped the same way. The threshold comes from `TASKFLOW_LOG_LEVEL`, or\n * defaults to `warn` under test so a suite run stays quiet.\n */\nimport { env } from \"@/config/env\";\n\nexport type LogFields = Readonly<Record<string, string | number | boolean | null>>;\n\nexport type Logger = {\n  debug: (message: string, fields?: LogFields) => void;\n  info: (message: string, fields?: LogFields) => void;\n  warn: (message: string, fields?: LogFields) => void;\n  error: (message: string, fields?: LogFields) => void;\n};\n\ntype Level = \"debug\" | \"info\" | \"warn\" | \"error\";\n\nconst LEVEL_RANK: Readonly<Record<Level, number>> = {\n  debug: 10,\n  info: 20,\n  warn: 30,\n  error: 40,\n};\n\nfunction configuredLevel(): Level {\n  const raw = (process.env.TASKFLOW_LOG_LEVEL ?? \"\").trim().toLowerCase();\n  if (raw in LEVEL_RANK) return raw as Level;\n  if (env.nodeEnv === \"test\") return \"warn\";\n  return env.nodeEnv === \"production\" ? \"info\" : \"debug\";\n}\n\nconst threshold = LEVEL_RANK[configuredLevel()];\n\nfunction write(level: Level, scope: string, message: string, fields?: LogFields): void {\n  if (LEVEL_RANK[level] < threshold) return;\n\n  const line = JSON.stringify({\n    level,\n    scope,\n    message,\n    time: new Date().toISOString(),\n    ...(fields ?? {}),\n  });\n\n  // This module is the sanctioned `console` sink; nothing else may call it.\n  if (level === \"error\") console.error(line);\n  else if (level === \"warn\") console.warn(line);\n  else console.log(line);\n}\n\n/**\n * A logger bound to one scope, e.g. `createLogger(\"issue-service\")`. Scopes\n * are module-shaped so a log line always names the code that emitted it.\n */\nexport function createLogger(scope: string): Logger {\n  return {\n    debug: (message, fields) => write(\"debug\", scope, message, fields),\n    info: (message, fields) => write(\"info\", scope, message, fields),\n    warn: (message, fields) => write(\"warn\", scope, message, fields),\n    error: (message, fields) => write(\"error\", scope, message, fields),\n  };\n}\n","/**\n * Result envelope every job returns to the scheduler.\n */\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { IsoTimestamp } from \"@/types/common\";\n\nexport type JobResult = {\n  kind: string;\n  processed: number;\n  failed: number;\n  durationMs: number;\n  startedAt: IsoTimestamp;\n};\n\n/** The zero value a job starts from and mutates as it works. */\nexport function emptyJobResult(\n  kind: string,\n  startedAt: IsoTimestamp,\n): JobResult {\n  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };\n}\n\n/**\n * Convenience for a job body: stamps the start, runs the work and fills in\n * `durationMs`. Kept here so every job reports the same shape.\n */\nexport async function runJob(\n  kind: string,\n  work: (result: JobResult) => Promise<void>,\n): Promise<JobResult> {\n  const startedAt = toIsoTimestamp(new Date());\n  const began = Date.now();\n  const result = emptyJobResult(kind, startedAt);\n\n  await work(result);\n\n  return { ...result, durationMs: Date.now() - began };\n}\n","/**\n * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.\n *\n * Must call (do not reimplement): shouldFilterArchived\n */\nimport { eq, isNull } from \"drizzle-orm\";\nimport { shouldFilterArchived } from \"@/lib/soft-delete\";\nimport type { ArchiveScope, OrgId } from \"@/types/common\";\nimport type { SQL } from \"drizzle-orm\";\nimport type { SQLiteColumn } from \"drizzle-orm/sqlite-core\";\n\nconst CURSOR_SEPARATOR = \"|\";\n\n/**\n * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the\n * sort value alongside the id is what lets `listX` resume from a stable point\n * even when two rows share a timestamp.\n */\nexport function encodeCursor(id: string, sortValue: string): string {\n  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, \"utf8\").toString(\n    \"base64url\",\n  );\n}\n\nexport function decodeCursor(\n  cursor: string,\n): { id: string; sortValue: string } | null {\n  let decoded: string;\n  try {\n    decoded = Buffer.from(cursor, \"base64url\").toString(\"utf8\");\n  } catch {\n    return null;\n  }\n\n  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);\n  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;\n\n  return {\n    sortValue: decoded.slice(0, separatorAt),\n    id: decoded.slice(separatorAt + 1),\n  };\n}\n\n/**\n * The tenant predicate. Every repository read and write composes this — a\n * query that does not mention `org_id` is a cross-tenant leak waiting to\n * happen, so this is the only sanctioned way to express it.\n */\nexport function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {\n  return eq(column, orgId);\n}\n\n/**\n * The soft-delete predicate, or `undefined` when the caller explicitly asked\n * for archived rows. The `includeArchived` decision itself lives in\n * `shouldFilterArchived()` so it cannot drift per repository.\n */\nexport function livePredicate(\n  column: SQLiteColumn,\n  scope: ArchiveScope,\n): SQL | undefined {\n  return shouldFilterArchived(scope) ? isNull(column) : undefined;\n}\n","/**\n * Organization rows plus slug uniqueness lookups.\n *\n * Must call (do not reimplement): archivePatch, uniqueSlug\n */\nimport { and, eq, isNull, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { uniqueSlug } from \"@/lib/slug\";\nimport { archivePatch } from \"@/lib/soft-delete\";\nimport { getDb, members, organizations } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { toOrganization } from \"./_mappers\";\nimport type {\n  CreateOrganizationInput,\n  UpdateOrganizationInput,\n} from \"@/schemas/organization\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { Organization } from \"@/types/organization\";\n\nexport async function findOrgById(orgId: OrgId): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(eq(organizations.id, orgId))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\nexport async function findOrgBySlug(slug: string): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\n/** Every org the user still holds a live membership in. */\nexport async function listOrgsForUser(\n  userId: UserId,\n): Promise<readonly Organization[]> {\n  const rows = getDb()\n    .select({ org: organizations })\n    .from(members)\n    .innerJoin(organizations, eq(organizations.id, members.orgId))\n    .where(\n      and(\n        eq(members.userId, userId),\n        isNull(members.archivedAt),\n        isNull(organizations.archivedAt),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => toOrganization(row.org));\n}\n\n/**\n * Creates the org row. The slug is de-duplicated here rather than in the\n * service so a race on the unique index still resolves to a usable slug.\n */\nexport async function insertOrg(\n  input: CreateOrganizationInput,\n  ownerId: UserId,\n): Promise<Organization> {\n  const taken = await listTakenOrgSlugs(input.slug);\n  const slug = uniqueSlug(input.slug, taken);\n  const stamp = toIsoTimestamp(new Date());\n\n  const row = getDb()\n    .insert(organizations)\n    .values({\n      id: newId(),\n      name: input.name,\n      slug,\n      ownerId,\n      plan: input.plan,\n      logoUrl: null,\n      trialEndsAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function updateOrg(\n  orgId: OrgId,\n  patch: UpdateOrganizationInput,\n): Promise<Organization> {\n  const current = await findOrgById(orgId);\n  if (!current) throw new Error(`Organization ${orgId} not found`);\n\n  const settings = { ...current.settings, ...(patch.settings ?? {}) };\n\n  const row = getDb()\n    .update(organizations)\n    .set({\n      ...(patch.name === undefined ? {} : { name: patch.name }),\n      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),\n      defaultIssueStatus: settings.defaultIssueStatus,\n      allowPublicProjects: settings.allowPublicProjects,\n      requireTwoFactor: settings.requireTwoFactor,\n      digestHourUtc: settings.digestHourUtc,\n      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function archiveOrg(orgId: OrgId): Promise<Organization> {\n  const row = getDb()\n    .update(organizations)\n    .set(archivePatch())\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Organization ${orgId} not found`);\n  return toOrganization(row);\n}\n\n/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */\nexport async function listTakenOrgSlugs(\n  prefix: string,\n): Promise<readonly string[]> {\n  const rows = getDb()\n    .select({ slug: organizations.slug })\n    .from(organizations)\n    .where(like(organizations.slug, `${prefix}%`))\n    .all();\n  return rows.map((row) => row.slug);\n}\n","/**\n * Webhook endpoints and their delivery attempts.\n */\nimport { and, asc, count, eq } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, webhookDeliveries, webhookEndpoints } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport type { CreateWebhookInput, UpdateWebhookInput } from \"@/schemas/webhook\";\nimport type {\n  WebhookDeliveryRow,\n  WebhookEndpointRow,\n} from \"@/server/db/schema/webhooks\";\nimport type { IsoTimestamp, OrgId, WebhookId } from \"@/types/common\";\n\nexport async function listEndpoints(\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  return getDb()\n    .select()\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .orderBy(asc(webhookEndpoints.createdAt))\n    .all();\n}\n\nexport async function insertEndpoint(\n  input: CreateWebhookInput,\n  secret: string,\n): Promise<WebhookEndpointRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookEndpoints)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      url: input.url,\n      secret,\n      eventTypes: JSON.stringify(input.eventTypes),\n      enabled: true,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\nexport async function updateEndpoint(\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  const row = getDb()\n    .update(webhookEndpoints)\n    .set({\n      ...(input.url === undefined ? {} : { url: input.url }),\n      ...(input.eventTypes === undefined\n        ? {}\n        : { eventTypes: JSON.stringify(input.eventTypes) }),\n      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, input.orgId),\n        eq(webhookEndpoints.id, input.webhookId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);\n  return row;\n}\n\nexport async function deleteEndpoint(\n  orgId: OrgId,\n  webhookId: WebhookId,\n): Promise<void> {\n  const db = getDb();\n  db.delete(webhookDeliveries)\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.endpointId, webhookId),\n      ),\n    )\n    .run();\n  db.delete(webhookEndpoints)\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, orgId),\n        eq(webhookEndpoints.id, webhookId),\n      ),\n    )\n    .run();\n}\n\n/** The `webhooks` quota compares against this. */\nexport async function countEndpoints(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function enqueueDelivery(\n  orgId: OrgId,\n  endpointId: string,\n  eventType: string,\n  payload: string,\n): Promise<WebhookDeliveryRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookDeliveries)\n    .values({\n      id: newId(),\n      orgId,\n      endpointId,\n      eventType,\n      payload,\n      status: \"pending\",\n      attempts: 0,\n      lastError: null,\n      deliveredAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\n/**\n * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is\n * drained by a background worker, not by a request — and the attempt counter\n * is bumped on claim so a crashed worker cannot retry forever.\n */\nexport async function claimPendingDeliveries(\n  limit: number,\n): Promise<readonly WebhookDeliveryRow[]> {\n  const db = getDb();\n  const pending = db\n    .select()\n    .from(webhookDeliveries)\n    .where(eq(webhookDeliveries.status, \"pending\"))\n    .orderBy(asc(webhookDeliveries.createdAt))\n    .limit(Math.max(1, limit))\n    .all();\n\n  return pending.map((row) =>\n    db\n      .update(webhookDeliveries)\n      .set({\n        attempts: row.attempts + 1,\n        updatedAt: toIsoTimestamp(new Date()),\n      })\n      .where(eq(webhookDeliveries.id, row.id))\n      .returning()\n      .get(),\n  );\n}\n\nexport async function markDelivered(\n  orgId: OrgId,\n  deliveryId: string,\n  at: IsoTimestamp,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({ status: \"delivered\", deliveredAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n\nexport async function markDeliveryFailed(\n  orgId: OrgId,\n  deliveryId: string,\n  error: string,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({\n      status: \"failed\",\n      lastError: error.slice(0, 500),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n","/**\n * Private helpers shared by the service layer.\n *\n * Two jobs only: build the `PermissionResource` descriptors `can()` expects\n * from a loaded row, and stamp the `EventEnvelope` every domain event carries.\n * Neither re-implements a cross-cutting concern — they are adapters onto\n * `@/lib/permissions` and `@/lib/event-bus`.\n */\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { Comment } from \"@/types/comment\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { EventEnvelope } from \"@/types/event\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Actor, Member } from \"@/types/member\";\nimport type { PermissionResource } from \"@/types/permission\";\nimport type { Project } from \"@/types/project\";\nimport type { WebhookId } from \"@/types/common\";\n\n/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */\nexport class NotFoundError extends Error {\n  readonly code = \"not_found\" as const;\n\n  constructor(\n    readonly entity: string,\n    readonly id: string,\n  ) {\n    super(`${entity} ${id} was not found`);\n    this.name = \"NotFoundError\";\n  }\n}\n\n/** Unwraps a repository read, turning the `null` case into a domain error. */\nexport function requireFound<T>(\n  value: T | null | undefined,\n  entity: string,\n  id: string,\n): T {\n  if (value === null || value === undefined) {\n    throw new NotFoundError(entity, id);\n  }\n  return value;\n}\n\nexport function orgResource(orgId: OrgId): PermissionResource {\n  return { kind: \"organization\", orgId };\n}\n\nexport function billingResource(orgId: OrgId): PermissionResource {\n  return { kind: \"billing\", orgId };\n}\n\nexport function activityResource(orgId: OrgId): PermissionResource {\n  return { kind: \"activity\", orgId };\n}\n\nexport function notificationResource(\n  orgId: OrgId,\n  recipientId: UserId,\n): PermissionResource {\n  return { kind: \"notification\", orgId, recipientId };\n}\n\nexport function webhookResource(\n  orgId: OrgId,\n  webhookId: WebhookId | null,\n): PermissionResource {\n  return { kind: \"webhook\", orgId, webhookId };\n}\n\nexport function memberResource(member: Member): PermissionResource {\n  return {\n    kind: \"member\",\n    orgId: member.orgId,\n    memberId: member.id,\n    targetUserId: member.userId,\n    targetRole: member.role,\n  };\n}\n\nexport function projectResource(project: Project): PermissionResource {\n  return {\n    kind: \"project\",\n    orgId: project.orgId,\n    projectId: project.id,\n    visibility: project.visibility,\n    leadId: project.leadId,\n  };\n}\n\nexport function issueResource(issue: Issue): PermissionResource {\n  return {\n    kind: \"issue\",\n    orgId: issue.orgId,\n    projectId: issue.projectId,\n    issueId: issue.id,\n    authorId: issue.authorId,\n    assigneeId: issue.assigneeId,\n  };\n}\n\nexport function commentResource(comment: Comment): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId: comment.orgId,\n    commentId: comment.id,\n    authorId: comment.authorId,\n  };\n}\n\n/** The three fields the bus stamps on every payload. */\nexport function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {\n  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };\n}\n\n/** Same envelope, taken from an `Actor` rather than assembled by hand. */\nexport function actorEnvelope(actor: Actor): EventEnvelope {\n  return envelope(actor.orgId, actor.userId);\n}\n\n/** Names the fields an update actually changed, for `issue.updated`. */\nexport function changedFields<T extends object>(\n  before: T,\n  after: T,\n): readonly string[] {\n  return Object.keys(after).filter(\n    (key) =>\n      JSON.stringify(before[key as keyof T]) !==\n      JSON.stringify(after[key as keyof T]),\n  );\n}\n","/**\n * Server-side flag context construction and the org-level override toggle.\n *\n * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit\n */\nimport { emit } from \"@/lib/event-bus\";\nimport { isEnabled, snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { getFlagDefinition } from \"@/config/feature-flags\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport { actorEnvelope, orgResource, requireFound } from \"./_support\";\nimport type { ToggleFeatureFlagInput } from \"@/schemas/feature-flag\";\nimport type { FeatureFlagSnapshot, FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\n/**\n * Builds the evaluation context every `isEnabled()` call needs. Both halves\n * are nullable so marketing pages — no session, no org — can still ask about\n * a flag and get the free-plan answer.\n */\nexport function buildFlagContext(\n  actor: Actor | null,\n  org: Organization | null,\n): FlagContext {\n  return {\n    orgId: org?.id ?? actor?.orgId ?? null,\n    userId: actor?.userId ?? null,\n    plan: org?.plan ?? \"free\",\n    role: actor?.role ?? null,\n    overrides: org?.settings.enabledFlagOverrides,\n  };\n}\n\n/**\n * The serialisable snapshot the dashboard layout hands to the client provider,\n * so `useFeatureFlag()` answers without a round trip and cannot disagree with\n * the server.\n */\nexport function getSnapshot(\n  actor: Actor,\n  org: Organization,\n): FeatureFlagSnapshot {\n  return snapshotFlags(buildFlagContext(actor, org));\n}\n\n/**\n * Adds or removes an org-level override. Only flags declared `overridable`\n * accept one — a flag gated purely on plan cannot be switched on by an admin,\n * which is what keeps the plan boundary meaningful.\n */\nexport async function toggleFlag(\n  actor: Actor,\n  input: ToggleFeatureFlagInput,\n): Promise<Organization> {\n  assertCan(actor, \"org:manage_flags\", orgResource(input.orgId));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  const definition = getFlagDefinition(input.flag);\n  if (!definition.overridable) {\n    throw new Error(`Feature \"${input.flag}\" cannot be overridden per org`);\n  }\n\n  const current = new Set(org.settings.enabledFlagOverrides);\n  if (input.enabled) {\n    current.add(input.flag);\n  } else {\n    current.delete(input.flag);\n  }\n\n  const updated = await orgRepo.updateOrg(input.orgId, {\n    orgId: input.orgId,\n    settings: { enabledFlagOverrides: [...current] },\n  });\n\n  await emit(\"flag.toggled\", {\n    ...actorEnvelope(actor),\n    flag: input.flag,\n    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),\n  });\n\n  return updated;\n}\n","/**\n * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit\n */\nimport { createHmac } from \"node:crypto\";\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { randomToken } from \"@/lib/hash\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { requireFound, webhookResource } from \"./_support\";\nimport type {\n  CreateWebhookInput,\n  DeleteWebhookInput,\n  UpdateWebhookInput,\n} from \"@/schemas/webhook\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\n\n/** Length in bytes of a generated endpoint signing secret. */\nconst SECRET_BYTES = 32;\n\nexport async function listWebhooks(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(orgId, null));\n  return webhookRepo.listEndpoints(orgId);\n}\n\n/**\n * Creating an endpoint is gated twice: the `webhooks` flag has to be on for\n * the org's plan, and the plan's endpoint count must have room. A secret is\n * minted here and never regenerated — rotating it means deleting the endpoint.\n */\nexport async function createWebhook(\n  actor: Actor,\n  input: CreateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, null));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  if (!isEnabled(\"webhooks\", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {\n    throw new Error(\"Outgoing webhooks are not included in this plan\");\n  }\n\n  const used = await webhookRepo.countEndpoints(input.orgId);\n  if (wouldExceedLimit(org.plan, \"webhooks\", used)) {\n    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);\n  }\n\n  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));\n}\n\nexport async function updateWebhook(\n  actor: Actor,\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  return webhookRepo.updateEndpoint(input);\n}\n\nexport async function deleteWebhook(\n  actor: Actor,\n  input: DeleteWebhookInput,\n): Promise<void> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);\n}\n\n/**\n * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes\n * this from the same secret — it is the only thing proving the delivery came\n * from Taskflow, so the payload string must be signed byte-for-byte as sent.\n */\nexport function signPayload(secret: string, payload: string): string {\n  return createHmac(\"sha256\", secret).update(payload, \"utf8\").digest(\"hex\");\n}\n\n/**\n * Fans domain events out into the delivery table. Each org's endpoints\n * declare which event types they want, so an endpoint only ever receives what\n * it subscribed to; the job drains the rows afterwards.\n */\nexport function registerWebhookListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"webhook.delivery_requested\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        payload.eventType,\n        JSON.stringify(payload.payload),\n      );\n    }),\n    subscribe(\"issue.created\", async (payload) => {\n      await enqueueForOrg(payload.orgId, \"issue.created\", JSON.stringify(payload));\n    }),\n    subscribe(\"issue.status_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"issue.status_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"comment.created\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"billing.plan_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"billing.plan_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nasync function enqueueForOrg(\n  orgId: OrgId,\n  eventType: string,\n  payload: string,\n): Promise<void> {\n  const endpoints = await webhookRepo.listEndpoints(orgId);\n\n  for (const endpoint of endpoints) {\n    if (!endpoint.enabled) continue;\n\n    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];\n    if (!wanted.includes(eventType)) continue;\n\n    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);\n  }\n}\n\nfunction flagContextFor(\n  actor: Actor,\n  plan: FlagContext[\"plan\"],\n  overrides: readonly string[],\n): FlagContext {\n  return {\n    orgId: actor.orgId,\n    userId: actor.userId,\n    plan,\n    role: actor.role,\n    overrides,\n  };\n}\n"],"names":["CLAIM_BATCH","MAX_ATTEMPTS","logger","runWebhookDeliveryJob","now","result","claimed","delivery","orgId","orgAllowsWebhooks","id","failed","attempts","endpoint","find","row","endpointId","enabled","signature","secret","payload","info","deliveryId","url","eventType","slice","backoffMs","processed","Math","min","org","plan","webhooks","AppRouteRouteModule","RouteKind","patchFetch","_pa