./.next/server/chunks/[root-of-the-server]__0tmmj0v._.js.map:1:{"version":3,"sources":["../../../../../corpus/taskflow/src/config/plan-limits.ts","../../../../../corpus/taskflow/src/lib/event-bus.ts","../../../../../corpus/taskflow/src/config/feature-flags.ts","../../../../../corpus/taskflow/src/lib/feature-flags.ts","../../../../../corpus/taskflow/src/types/member.ts","../../../../../corpus/taskflow/src/lib/hash.ts","../../../../../corpus/taskflow/src/lib/id.ts","../../../../../corpus/taskflow/src/config/site.ts","../../../../../corpus/taskflow/src/config/env.ts","../../../../../corpus/taskflow/src/lib/logger.ts","../../../../../corpus/taskflow/src/types/common.ts","../../../../../corpus/taskflow/src/server/jobs/types.ts","../../../../../corpus/taskflow/src/server/jobs/webhook-delivery-job.ts","../../../../../corpus/taskflow/src/server/repositories/base-repository.ts","../../../../../corpus/taskflow/src/lib/soft-delete.ts","../../../../../corpus/taskflow/src/server/repositories/organization-repository.ts","../../../../../corpus/taskflow/src/server/repositories/webhook-repository.ts","../../../../../corpus/taskflow/src/server/services/feature-flag-service.ts","../../../../../corpus/taskflow/src/server/services/webhook-service.ts"],"sourcesContent":["import type { LimitedResource, PlanId } from \"@/types/billing\";\nimport type { FeatureFlagKey } from \"@/types/feature-flag\";\n\n/**\n * The one place plan quotas are declared.\n *\n * `BillingService`, the invite flow, the project-create action, the webhook\n * settings page, the usage meter component and the seat-limit job all read\n * their numbers from here via `getPlanLimits()`. Adding a field to\n * `PlanLimits` therefore ripples into every one of those call sites — that\n * ripple is intentional and is what keeps the quotas honest.\n */\nexport interface PlanLimits {\n  readonly plan: PlanId;\n  readonly seats: number;\n  readonly projects: number;\n  readonly issuesPerProject: number;\n  readonly storageMb: number;\n  readonly apiRequestsPerHour: number;\n  readonly webhooks: number;\n  readonly retentionDays: number;\n  readonly includedFlags: readonly FeatureFlagKey[];\n  readonly priceCentsPerSeatMonthly: number;\n}\n\n/** `Infinity` is the sanctioned representation of \"no limit\". */\nexport const UNLIMITED = Number.POSITIVE_INFINITY;\n\nexport const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {\n  free: {\n    plan: \"free\",\n    seats: 3,\n    projects: 2,\n    issuesPerProject: 100,\n    storageMb: 100,\n    apiRequestsPerHour: 100,\n    webhooks: 0,\n    retentionDays: 30,\n    includedFlags: [\"command_palette\"],\n    priceCentsPerSeatMonthly: 0,\n  },\n  starter: {\n    plan: \"starter\",\n    seats: 10,\n    projects: 10,\n    issuesPerProject: 1_000,\n    storageMb: 2_000,\n    apiRequestsPerHour: 1_000,\n    webhooks: 2,\n    retentionDays: 90,\n    includedFlags: [\"command_palette\", \"kanban_board\", \"csv_export\"],\n    priceCentsPerSeatMonthly: 900,\n  },\n  growth: {\n    plan: \"growth\",\n    seats: 50,\n    projects: 100,\n    issuesPerProject: 10_000,\n    storageMb: 20_000,\n    apiRequestsPerHour: 10_000,\n    webhooks: 10,\n    retentionDays: 365,\n    includedFlags: [\n      \"command_palette\",\n      \"kanban_board\",\n      \"csv_export\",\n      \"activity_feed\",\n      \"digest_email\",\n      \"webhooks\",\n      \"issue_templates\",\n    ],\n    priceCentsPerSeatMonthly: 1_900,\n  },\n  enterprise: {\n    plan: \"enterprise\",\n    seats: UNLIMITED,\n    projects: UNLIMITED,\n    issuesPerProject: UNLIMITED,\n    storageMb: 500_000,\n    apiRequestsPerHour: 100_000,\n    webhooks: UNLIMITED,\n    retentionDays: 2_555,\n    includedFlags: [\n      \"command_palette\",\n      \"kanban_board\",\n      \"csv_export\",\n      \"activity_feed\",\n      \"digest_email\",\n      \"webhooks\",\n      \"issue_templates\",\n      \"advanced_search\",\n      \"public_projects\",\n      \"ai_issue_summary\",\n    ],\n    priceCentsPerSeatMonthly: 3_900,\n  },\n};\n\n/** Plans ordered cheapest → richest; used for \"at least this plan\" checks. */\nexport const PLAN_ORDER: readonly PlanId[] = [\n  \"free\",\n  \"starter\",\n  \"growth\",\n  \"enterprise\",\n];\n\nexport function getPlanLimits(plan: PlanId): PlanLimits {\n  return PLAN_LIMITS[plan];\n}\n\n/** Reads one numeric quota without the caller destructuring `PlanLimits`. */\nexport function getLimit(plan: PlanId, resource: LimitedResource): number {\n  return getPlanLimits(plan)[resource];\n}\n\n/** True when `plan` is at least as rich as `minPlan`. */\nexport function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {\n  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);\n}\n\n/** True when consuming `requested` more units would breach the quota. */\nexport function wouldExceedLimit(\n  plan: PlanId,\n  resource: LimitedResource,\n  used: number,\n  requested = 1,\n): boolean {\n  return used + requested > getLimit(plan, resource);\n}\n","import type {\n  EventHandler,\n  TaskflowEventMap,\n  TaskflowEventPayload,\n  TaskflowEventType,\n  Unsubscribe,\n} from \"@/types/event\";\n\n/**\n * In-process, typed publish/subscribe bus.\n *\n * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the\n * search indexer and the webhook dispatcher decoupled: writers `emit()`, and\n * every reactive concern `subscribe()`s at module init (see\n * `src/server/services/event-registry.ts`). Handlers are isolated — one\n * throwing handler never fails the emit or the sibling handlers.\n */\n\ntype HandlerSet = Set<EventHandler<TaskflowEventType>>;\n\nconst handlers = new Map<TaskflowEventType, HandlerSet>();\n\nconst errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();\n\n/** Registers a handler for one event type. Call the return value to detach. */\nexport function subscribe<K extends TaskflowEventType>(\n  type: K,\n  handler: EventHandler<K>,\n): Unsubscribe {\n  const set = handlers.get(type) ?? new Set();\n  set.add(handler as EventHandler<TaskflowEventType>);\n  handlers.set(type, set);\n  return () => {\n    set.delete(handler as EventHandler<TaskflowEventType>);\n  };\n}\n\n/** Registers a handler that detaches itself after the first delivery. */\nexport function subscribeOnce<K extends TaskflowEventType>(\n  type: K,\n  handler: EventHandler<K>,\n): Unsubscribe {\n  const off = subscribe(type, (payload) => {\n    off();\n    return handler(payload);\n  });\n  return off;\n}\n\n/**\n * Publishes an event to every subscriber. Resolves once all handlers settle;\n * rejected handlers are reported to the error sinks, never rethrown.\n */\nexport async function emit<K extends TaskflowEventType>(\n  type: K,\n  payload: TaskflowEventPayload<K>,\n): Promise<void> {\n  const set = handlers.get(type);\n  if (!set || set.size === 0) return;\n\n  const results = await Promise.allSettled(\n    [...set].map(async (handler) => {\n      await (handler as EventHandler<K>)(payload);\n    }),\n  );\n\n  for (const result of results) {\n    if (result.status === \"rejected\") {\n      reportHandlerError(type, result.reason);\n    }\n  }\n}\n\n/** Fire-and-forget variant for call sites that must not await delivery. */\nexport function emitAndForget<K extends TaskflowEventType>(\n  type: K,\n  payload: TaskflowEventPayload<K>,\n): void {\n  void emit(type, payload).catch((error: unknown) => {\n    reportHandlerError(type, error);\n  });\n}\n\nexport function onHandlerError(\n  sink: (type: TaskflowEventType, error: unknown) => void,\n): Unsubscribe {\n  errorSinks.add(sink);\n  return () => {\n    errorSinks.delete(sink);\n  };\n}\n\nfunction reportHandlerError(type: TaskflowEventType, error: unknown): void {\n  for (const sink of errorSinks) {\n    try {\n      sink(type, error);\n    } catch {\n      // A failing error sink must never escalate.\n    }\n  }\n}\n\n/** Number of live subscribers for an event; used by tests and diagnostics. */\nexport function subscriberCount(type: TaskflowEventType): number {\n  return handlers.get(type)?.size ?? 0;\n}\n\n/** Detaches every handler. Test-only — never call from application code. */\nexport function resetEventBus(): void {\n  handlers.clear();\n  errorSinks.clear();\n}\n\nexport type { TaskflowEventMap, TaskflowEventType, Unsubscribe };\n","import type {\n  FeatureFlagDefinition,\n  FeatureFlagKey,\n} from \"@/types/feature-flag\";\n\n/**\n * Declarative registry of every feature flag. `isEnabled()` in\n * `src/lib/feature-flags.ts` is the only reader — UI and server code go\n * through that function, never through this table directly.\n */\nexport const FEATURE_FLAG_DEFINITIONS: Readonly<\n  Record<FeatureFlagKey, FeatureFlagDefinition>\n> = {\n  kanban_board: {\n    key: \"kanban_board\",\n    label: \"Kanban board\",\n    description: \"Drag-and-drop board view for a project's issues.\",\n    strategy: { kind: \"plan\", minPlan: \"starter\" },\n    overridable: true,\n  },\n  ai_issue_summary: {\n    key: \"ai_issue_summary\",\n    label: \"AI issue summary\",\n    description: \"Generates a short summary of a long issue thread.\",\n    strategy: { kind: \"percentage\", percent: 25 },\n    overridable: true,\n  },\n  command_palette: {\n    key: \"command_palette\",\n    label: \"Command palette\",\n    description: \"Ctrl+K quick navigation and actions.\",\n    strategy: { kind: \"on\" },\n    overridable: false,\n  },\n  activity_feed: {\n    key: \"activity_feed\",\n    label: \"Activity feed\",\n    description: \"Organization-wide audit trail view.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: true,\n  },\n  public_projects: {\n    key: \"public_projects\",\n    label: \"Public projects\",\n    description: \"Share a read-only project page outside the organization.\",\n    strategy: { kind: \"plan\", minPlan: \"enterprise\" },\n    overridable: true,\n  },\n  webhooks: {\n    key: \"webhooks\",\n    label: \"Outgoing webhooks\",\n    description: \"Deliver domain events to an external HTTP endpoint.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: false,\n  },\n  csv_export: {\n    key: \"csv_export\",\n    label: \"CSV export\",\n    description: \"Export issues and the audit log as CSV.\",\n    strategy: { kind: \"plan\", minPlan: \"starter\" },\n    overridable: true,\n  },\n  digest_email: {\n    key: \"digest_email\",\n    label: \"Daily digest email\",\n    description: \"Batches notifications into one daily email.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: true,\n  },\n  issue_templates: {\n    key: \"issue_templates\",\n    label: \"Issue templates\",\n    description: \"Prefilled issue bodies per project.\",\n    strategy: { kind: \"role\", minRole: \"admin\" },\n    overridable: true,\n  },\n  advanced_search: {\n    key: \"advanced_search\",\n    label: \"Advanced search\",\n    description: \"Field-scoped query syntax across issues and comments.\",\n    strategy: { kind: \"plan\", minPlan: \"enterprise\" },\n    overridable: true,\n  },\n};\n\nexport const FEATURE_FLAG_KEYS = Object.keys(\n  FEATURE_FLAG_DEFINITIONS,\n) as readonly FeatureFlagKey[];\n\nexport function getFlagDefinition(key: FeatureFlagKey): FeatureFlagDefinition {\n  return FEATURE_FLAG_DEFINITIONS[key];\n}\n\nexport function isFeatureFlagKey(value: string): value is FeatureFlagKey {\n  return Object.prototype.hasOwnProperty.call(FEATURE_FLAG_DEFINITIONS, value);\n}\n","import {\n  FEATURE_FLAG_DEFINITIONS,\n  FEATURE_FLAG_KEYS,\n} from \"@/config/feature-flags\";\nimport { planAtLeast } from \"@/config/plan-limits\";\nimport { ROLE_RANK } from \"@/types/member\";\nimport type {\n  FeatureFlagKey,\n  FeatureFlagSnapshot,\n  FlagContext,\n} from \"@/types/feature-flag\";\n\n/**\n * Feature-flag evaluation, shared verbatim by server and client.\n *\n * Server code builds a `FlagContext` from the session and calls `isEnabled()`\n * directly; the dashboard layout serialises `snapshotFlags()` into the client\n * provider so `useFeatureFlag()` answers the same way without a round trip.\n * Both sides must agree — never re-implement a strategy at a call site.\n */\nexport function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {\n  const definition = FEATURE_FLAG_DEFINITIONS[flag];\n  if (!definition) return false;\n\n  if (definition.overridable && ctx.overrides?.includes(flag)) {\n    return true;\n  }\n\n  const strategy = definition.strategy;\n  switch (strategy.kind) {\n    case \"off\":\n      return false;\n    case \"on\":\n      return true;\n    case \"plan\":\n      return planAtLeast(ctx.plan, strategy.minPlan);\n    case \"role\":\n      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];\n    case \"percentage\":\n      return bucketOf(flag, ctx) < strategy.percent;\n    default:\n      return false;\n  }\n}\n\n/** Evaluates every flag at once, for handoff to the client provider. */\nexport function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {\n  const snapshot = {} as Record<FeatureFlagKey, boolean>;\n  for (const key of FEATURE_FLAG_KEYS) {\n    snapshot[key] = isEnabled(key, ctx);\n  }\n  return snapshot;\n}\n\n/** Throwing guard for server actions gated behind a flag. */\nexport class FeatureDisabledError extends Error {\n  readonly code = \"forbidden\" as const;\n\n  constructor(readonly flag: FeatureFlagKey) {\n    super(`Feature \"${flag}\" is not enabled for this organization.`);\n    this.name = \"FeatureDisabledError\";\n  }\n}\n\nexport function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {\n  if (!isEnabled(flag, ctx)) {\n    throw new FeatureDisabledError(flag);\n  }\n}\n\n/**\n * Deterministic 0–99 bucket for percentage rollouts. Stable per\n * (flag, org, user) so a viewer never sees the feature flicker.\n */\nfunction bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {\n  const seed = `${flag}:${ctx.orgId ?? \"-\"}:${ctx.userId ?? \"-\"}`;\n  let hash = 2_166_136_261;\n  for (let i = 0; i < seed.length; i += 1) {\n    hash ^= seed.charCodeAt(i);\n    hash = Math.imul(hash, 16_777_619);\n  }\n  return Math.abs(hash) % 100;\n}\n","import type {\n  IsoTimestamp,\n  MemberId,\n  OrgId,\n  SoftDeletable,\n  TenantScoped,\n  Timestamps,\n  UserId,\n  InvitationId,\n} from \"./common\";\n\n/**\n * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`\n * below is the single source of truth for \"at least this role\" comparisons —\n * never compare role strings directly.\n */\nexport type Role = \"owner\" | \"admin\" | \"member\" | \"viewer\";\n\nexport const ROLES: readonly Role[] = [\"owner\", \"admin\", \"member\", \"viewer\"];\n\nexport const ROLE_RANK: Readonly<Record<Role, number>> = {\n  owner: 4,\n  admin: 3,\n  member: 2,\n  viewer: 1,\n};\n\nexport type MemberStatus = \"active\" | \"invited\" | \"suspended\";\n\nexport interface User extends Timestamps {\n  readonly id: UserId;\n  readonly email: string;\n  readonly name: string;\n  readonly avatarUrl: string | null;\n  readonly timezone: string;\n  readonly emailVerifiedAt: IsoTimestamp | null;\n}\n\nexport interface Member extends Timestamps, TenantScoped, SoftDeletable {\n  readonly id: MemberId;\n  readonly userId: UserId;\n  readonly role: Role;\n  readonly status: MemberStatus;\n  readonly invitedBy: UserId | null;\n  readonly joinedAt: IsoTimestamp | null;\n  readonly lastSeenAt: IsoTimestamp | null;\n}\n\n/** A member joined with the user record it points at, for list UIs. */\nexport interface MemberWithUser extends Member {\n  readonly user: User;\n}\n\nexport interface Invitation extends Timestamps, TenantScoped {\n  readonly id: InvitationId;\n  readonly email: string;\n  readonly role: Role;\n  readonly invitedBy: UserId;\n  readonly token: string;\n  readonly expiresAt: IsoTimestamp;\n  readonly acceptedAt: IsoTimestamp | null;\n  readonly revokedAt: IsoTimestamp | null;\n}\n\n/**\n * The authenticated principal for one request, always resolved for exactly one\n * organization. Everything that authorizes a mutation takes an `Actor` — see\n * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in\n * `src/lib/tenant.ts`.\n */\nexport interface Actor {\n  readonly userId: UserId;\n  readonly orgId: OrgId;\n  readonly role: Role;\n  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */\n  readonly isPlatformStaff?: boolean;\n}\n\nexport interface SessionPrincipal {\n  readonly userId: UserId;\n  readonly email: string;\n  readonly activeOrgId: OrgId | null;\n  readonly expiresAt: IsoTimestamp;\n}\n\n/** True when `role` is at least as privileged as `atLeast`. */\nexport function hasRoleAtLeast(role: Role, atLeast: Role): boolean {\n  return ROLE_RANK[role] >= ROLE_RANK[atLeast];\n}\n","/**\n * Password and token hashing built on `node:crypto` scrypt. No external\n * dependency — the corpus builds offline, and scrypt is the strongest KDF the\n * platform ships without one.\n *\n * Server-only: never import this from a client component.\n */\nimport {\n  createHash,\n  randomBytes,\n  scrypt,\n  timingSafeEqual,\n} from \"node:crypto\";\n\nconst KEY_LENGTH = 64;\nconst SALT_BYTES = 16;\nconst PREFIX = \"scrypt\";\n\nfunction deriveKey(password: string, salt: Buffer): Promise<Buffer> {\n  return new Promise((resolve, reject) => {\n    scrypt(password.normalize(\"NFKC\"), salt, KEY_LENGTH, (error, key) => {\n      if (error) reject(error);\n      else resolve(key);\n    });\n  });\n}\n\n/** Returns `scrypt:<saltHex>:<keyHex>` — self-describing, so the verifier\n *  can change parameters later without a migration. */\nexport async function hashPassword(password: string): Promise<string> {\n  const salt = randomBytes(SALT_BYTES);\n  const key = await deriveKey(password, salt);\n  return `${PREFIX}:${salt.toString(\"hex\")}:${key.toString(\"hex\")}`;\n}\n\n/** Constant-time comparison; a malformed stored hash simply fails to verify. */\nexport async function verifyPassword(\n  password: string,\n  hash: string,\n): Promise<boolean> {\n  const [scheme, saltHex, keyHex] = hash.split(\":\");\n  if (scheme !== PREFIX || !saltHex || !keyHex) return false;\n\n  const expected = Buffer.from(keyHex, \"hex\");\n  if (expected.length !== KEY_LENGTH) return false;\n\n  const actual = await deriveKey(password, Buffer.from(saltHex, \"hex\"));\n  return timingSafeEqual(actual, expected);\n}\n\n/** One-way digest for invitation and session tokens, which are high-entropy\n *  already and so need no salt or work factor. */\nexport function hashToken(token: string): string {\n  return createHash(\"sha256\").update(token).digest(\"hex\");\n}\n\n/** URL-safe random token; the default width matches the session schema's\n *  32-character minimum. */\nexport function randomToken(bytes = 32): string {\n  return randomBytes(bytes).toString(\"base64url\");\n}\n","/**\n * ULID generation and validation. Every branded id in the app is produced\n * here, so ids sort lexicographically by creation time and the repositories\n * can use them as pagination cursors without a separate sort column.\n */\n/** Crockford base32, minus I, L, O and U. */\nconst ALPHABET = \"0123456789ABCDEFGHJKMNPQRSTVWXYZ\";\nconst TIME_LENGTH = 10;\nconst RANDOM_LENGTH = 16;\n\nconst ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;\n\nfunction encodeTime(time: number): string {\n  let remaining = time;\n  let out = \"\";\n  for (let i = 0; i < TIME_LENGTH; i += 1) {\n    const mod = remaining % 32;\n    out = ALPHABET[mod] + out;\n    remaining = (remaining - mod) / 32;\n  }\n  return out;\n}\n\nfunction encodeRandom(next: () => number): string {\n  let out = \"\";\n  for (let i = 0; i < RANDOM_LENGTH; i += 1) {\n    out += ALPHABET[next() % 32];\n  }\n  return out;\n}\n\n/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same\n *  implementation runs on the server, in the browser and on the edge. */\nexport function newId(): string {\n  const bytes = new Uint8Array(RANDOM_LENGTH);\n  globalThis.crypto.getRandomValues(bytes);\n  let cursor = 0;\n  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);\n}\n\nexport function isUlid(value: string): boolean {\n  return ULID_PATTERN.test(value);\n}\n\n/**\n * A deterministic id generator for tests and the seed script: same seed,\n * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so\n * fixtures are byte-stable across runs.\n */\nexport function idFactory(seed: number): () => string {\n  let state = (seed | 0) || 0x2545_f491;\n  let counter = 0;\n\n  const next = (): number => {\n    state ^= state << 13;\n    state ^= state >>> 17;\n    state ^= state << 5;\n    return Math.abs(state);\n  };\n\n  return () => {\n    counter += 1;\n    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.\n    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);\n  };\n}\n","/**\n * Product name, description, support links and the marketing metadata\n * defaults. The marketing pages and the email footer both read from here, so\n * the product never introduces itself two different ways.\n */\n\nexport type SiteConfig = {\n  name: string;\n  tagline: string;\n  description: string;\n  url: string;\n  supportEmail: string;\n  docsUrl: string;\n};\n\nexport const SITE_CONFIG: SiteConfig = {\n  name: \"Taskflow\",\n  tagline: \"Issue tracking that keeps up with the work\",\n  description:\n    \"Taskflow is a multi-tenant project and issue tracker for product teams: \" +\n    \"projects, issues, comments and a shared activity trail, with per-plan \" +\n    \"quotas and role-aware access built in.\",\n  url: \"https://taskflow.example.com\",\n  supportEmail: \"support@taskflow.example.com\",\n  docsUrl: \"https://docs.taskflow.example.com\",\n};\n","/**\n * Validated environment access. Nothing else in Taskflow reads `process.env`\n * — call sites import `env` (or `loadEnv()` when they need to validate a\n * different source, as the tests do) so a missing or malformed variable fails\n * once, loudly, instead of surfacing as `undefined` deep in a request.\n */\nimport { SITE_CONFIG } from \"./site\";\n\nexport type AppEnv = {\n  nodeEnv: \"development\" | \"test\" | \"production\";\n  databasePath: string;\n  appUrl: string;\n  digestEnabled: boolean;\n};\n\nconst NODE_ENVS = [\"development\", \"test\", \"production\"] as const;\n\ntype NodeEnvValue = (typeof NODE_ENVS)[number];\n\nfunction readNodeEnv(raw: string | undefined): NodeEnvValue {\n  const value = (raw ?? \"development\").trim();\n  const match = NODE_ENVS.find((candidate) => candidate === value);\n  return match ?? \"development\";\n}\n\n/** Accepts `1`/`true`/`yes`/`on` (case-insensitive) as true; anything else false. */\nfunction readBoolean(raw: string | undefined, fallback: boolean): boolean {\n  if (raw === undefined || raw.trim() === \"\") return fallback;\n  const value = raw.trim().toLowerCase();\n  if ([\"1\", \"true\", \"yes\", \"on\"].includes(value)) return true;\n  if ([\"0\", \"false\", \"no\", \"off\"].includes(value)) return false;\n  throw new Error(`Invalid boolean environment value: \"${raw}\"`);\n}\n\nfunction readUrl(raw: string | undefined, fallback: string): string {\n  const value = (raw ?? \"\").trim() || fallback;\n  try {\n    // Normalises away a trailing slash so `${appUrl}${path}` never doubles up.\n    const parsed = new URL(value);\n    return parsed.origin + parsed.pathname.replace(/\\/$/, \"\");\n  } catch {\n    throw new Error(`Invalid TASKFLOW_APP_URL: \"${value}\"`);\n  }\n}\n\n/**\n * Reads and validates the environment. Defaults are chosen so a fresh\n * checkout runs with no `.env` at all — the corpus must build offline.\n */\nexport function loadEnv(source: NodeJS.ProcessEnv = process.env): AppEnv {\n  const nodeEnv = readNodeEnv(source.NODE_ENV);\n  const databasePath =\n    (source.TASKFLOW_DB_PATH ?? \"\").trim() ||\n    (nodeEnv === \"test\" ? \":memory:\" : \"./data/taskflow.db\");\n\n  return {\n    nodeEnv,\n    databasePath,\n    appUrl: readUrl(source.TASKFLOW_APP_URL, SITE_CONFIG.url),\n    digestEnabled: readBoolean(source.TASKFLOW_DIGEST_ENABLED, nodeEnv !== \"test\"),\n  };\n}\n\nexport const env: AppEnv = loadEnv();\n","/**\n * Structured logger. The only place `console` is allowed.\n *\n * Every line is one JSON object so job output and request output can be\n * grepped the same way. The threshold comes from `TASKFLOW_LOG_LEVEL`, or\n * defaults to `warn` under test so a suite run stays quiet.\n */\nimport { env } from \"@/config/env\";\n\nexport type LogFields = Readonly<Record<string, string | number | boolean | null>>;\n\nexport type Logger = {\n  debug: (message: string, fields?: LogFields) => void;\n  info: (message: string, fields?: LogFields) => void;\n  warn: (message: string, fields?: LogFields) => void;\n  error: (message: string, fields?: LogFields) => void;\n};\n\ntype Level = \"debug\" | \"info\" | \"warn\" | \"error\";\n\nconst LEVEL_RANK: Readonly<Record<Level, number>> = {\n  debug: 10,\n  info: 20,\n  warn: 30,\n  error: 40,\n};\n\nfunction configuredLevel(): Level {\n  const raw = (process.env.TASKFLOW_LOG_LEVEL ?? \"\").trim().toLowerCase();\n  if (raw in LEVEL_RANK) return raw as Level;\n  if (env.nodeEnv === \"test\") return \"warn\";\n  return env.nodeEnv === \"production\" ? \"info\" : \"debug\";\n}\n\nconst threshold = LEVEL_RANK[configuredLevel()];\n\nfunction write(level: Level, scope: string, message: string, fields?: LogFields): void {\n  if (LEVEL_RANK[level] < threshold) return;\n\n  const line = JSON.stringify({\n    level,\n    scope,\n    message,\n    time: new Date().toISOString(),\n    ...(fields ?? {}),\n  });\n\n  // This module is the sanctioned `console` sink; nothing else may call it.\n  if (level === \"error\") console.error(line);\n  else if (level === \"warn\") console.warn(line);\n  else console.log(line);\n}\n\n/**\n * A logger bound to one scope, e.g. `createLogger(\"issue-service\")`. Scopes\n * are module-shaped so a log line always names the code that emitted it.\n */\nexport function createLogger(scope: string): Logger {\n  return {\n    debug: (message, fields) => write(\"debug\", scope, message, fields),\n    info: (message, fields) => write(\"info\", scope, message, fields),\n    warn: (message, fields) => write(\"warn\", scope, message, fields),\n    error: (message, fields) => write(\"error\", scope, message, fields),\n  };\n}\n","/**\n * Primitive identifier and envelope types shared by every Taskflow domain type.\n *\n * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`\n * can never be silently passed where a `ProjectId` is expected. Ids are ULID\n * strings at runtime; the brand exists only at the type level.\n */\n\ndeclare const brand: unique symbol;\n\n/** Attaches a compile-time-only tag to a primitive type. */\nexport type Branded<T, B extends string> = T & { readonly [brand]: B };\n\nexport type UserId = Branded<string, \"UserId\">;\nexport type OrgId = Branded<string, \"OrgId\">;\nexport type ProjectId = Branded<string, \"ProjectId\">;\nexport type IssueId = Branded<string, \"IssueId\">;\nexport type CommentId = Branded<string, \"CommentId\">;\nexport type MemberId = Branded<string, \"MemberId\">;\nexport type NotificationId = Branded<string, \"NotificationId\">;\nexport type ActivityId = Branded<string, \"ActivityId\">;\nexport type InvitationId = Branded<string, \"InvitationId\">;\nexport type LabelId = Branded<string, \"LabelId\">;\nexport type AttachmentId = Branded<string, \"AttachmentId\">;\nexport type SubscriptionId = Branded<string, \"SubscriptionId\">;\nexport type SessionId = Branded<string, \"SessionId\">;\nexport type WebhookId = Branded<string, \"WebhookId\">;\n\n/** Union of every branded id used in the app, for generic id helpers. */\nexport type AnyId =\n  | UserId\n  | OrgId\n  | ProjectId\n  | IssueId\n  | CommentId\n  | MemberId\n  | NotificationId\n  | ActivityId\n  | InvitationId\n  | LabelId\n  | AttachmentId\n  | SubscriptionId\n  | SessionId\n  | WebhookId;\n\n/** ISO-8601 timestamp string as stored in SQLite text columns. */\nexport type IsoTimestamp = Branded<string, \"IsoTimestamp\">;\n\n/** Rows carrying the standard created/updated bookkeeping columns. */\nexport interface Timestamps {\n  readonly createdAt: IsoTimestamp;\n  readonly updatedAt: IsoTimestamp;\n}\n\n/**\n * Soft-delete marker. `archivedAt === null` means the row is live. Repositories\n * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than\n * writing the predicate by hand.\n */\nexport interface SoftDeletable {\n  readonly archivedAt: IsoTimestamp | null;\n}\n\n/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */\nexport interface TenantScoped {\n  readonly orgId: OrgId;\n}\n\nexport type SortDirection = \"asc\" | \"desc\";\n\nexport interface SortSpec<TField extends string = string> {\n  readonly field: TField;\n  readonly direction: SortDirection;\n}\n\n/** Cursor pagination request shared by every repository `list*` method. */\nexport interface PageRequest {\n  readonly limit: number;\n  readonly cursor?: string | null;\n}\n\n/** Cursor pagination response shared by every repository `list*` method. */\nexport interface Page<T> {\n  readonly items: readonly T[];\n  readonly nextCursor: string | null;\n  readonly total: number;\n}\n\n/** Options accepted by every soft-delete-aware repository read. */\nexport interface ArchiveScope {\n  readonly includeArchived?: boolean;\n}\n\nexport function makePage<T>(\n  items: readonly T[],\n  nextCursor: string | null,\n  total: number,\n): Page<T> {\n  return { items, nextCursor, total };\n}\n\nexport function toIsoTimestamp(value: Date | string): IsoTimestamp {\n  const date = typeof value === \"string\" ? new Date(value) : value;\n  return date.toISOString() as IsoTimestamp;\n}\n","/**\n * Result envelope every job returns to the scheduler.\n */\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { IsoTimestamp } from \"@/types/common\";\n\nexport type JobResult = {\n  kind: string;\n  processed: number;\n  failed: number;\n  durationMs: number;\n  startedAt: IsoTimestamp;\n};\n\n/** The zero value a job starts from and mutates as it works. */\nexport function emptyJobResult(\n  kind: string,\n  startedAt: IsoTimestamp,\n): JobResult {\n  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };\n}\n\n/**\n * Convenience for a job body: stamps the start, runs the work and fills in\n * `durationMs`. Kept here so every job reports the same shape.\n */\nexport async function runJob(\n  kind: string,\n  work: (result: JobResult) => Promise<void>,\n): Promise<JobResult> {\n  const startedAt = toIsoTimestamp(new Date());\n  const began = Date.now();\n  const result = emptyJobResult(kind, startedAt);\n\n  await work(result);\n\n  return { ...result, durationMs: Date.now() - began };\n}\n","/**\n * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.\n *\n * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload\n */\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { createLogger } from \"@/lib/logger\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { signPayload } from \"@/server/services/webhook-service\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { runJob } from \"./types\";\nimport type { JobResult } from \"@/server/jobs/types\";\nimport type { OrgId } from \"@/types/common\";\n\n/** How many deliveries one pass claims. */\nconst CLAIM_BATCH = 25;\n\n/** Attempts after which a delivery is marked failed for good. */\nconst MAX_ATTEMPTS = 6;\n\nconst logger = createLogger(\"webhook-delivery-job\");\n\n/**\n * Delivers each claimed row. There is no outbound HTTP in Taskflow — the\n * corpus builds and runs offline — so \"delivery\" means computing the\n * signature the receiver would verify and logging the attempt. The retry\n * bookkeeping around it is the part that has to be right.\n */\nexport async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {\n  return runJob(\"webhook-delivery\", async (result) => {\n    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);\n\n    for (const delivery of claimed) {\n      const orgId = delivery.orgId as OrgId;\n\n      if (!(await orgAllowsWebhooks(orgId))) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          \"webhooks are not included in this organization's plan\",\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      if (delivery.attempts > MAX_ATTEMPTS) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          `giving up after ${delivery.attempts} attempts`,\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(\n        (row) => row.id === delivery.endpointId,\n      );\n\n      if (!endpoint || !endpoint.enabled) {\n        await webhookRepo.markDeliveryFailed(\n          orgId,\n          delivery.id,\n          \"endpoint is missing or disabled\",\n        );\n        result.failed += 1;\n        continue;\n      }\n\n      const signature = signPayload(endpoint.secret, delivery.payload);\n\n      logger.info(\"webhook delivered\", {\n        deliveryId: delivery.id,\n        endpoint: endpoint.url,\n        eventType: delivery.eventType,\n        signature: signature.slice(0, 16),\n        backoffMs: backoffMs(delivery.attempts),\n      });\n\n      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));\n      result.processed += 1;\n    }\n  });\n}\n\n/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */\nexport function backoffMs(attempts: number): number {\n  if (attempts <= 0) return 0;\n  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);\n}\n\nasync function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {\n  const org = await orgRepo.findOrgById(orgId);\n  if (!org) return false;\n\n  if (getPlanLimits(org.plan).webhooks <= 0) return false;\n  return isEnabled(\"webhooks\", buildFlagContext(null, org));\n}\n","/**\n * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.\n *\n * Must call (do not reimplement): shouldFilterArchived\n */\nimport { eq, isNull } from \"drizzle-orm\";\nimport { shouldFilterArchived } from \"@/lib/soft-delete\";\nimport type { ArchiveScope, OrgId } from \"@/types/common\";\nimport type { SQL } from \"drizzle-orm\";\nimport type { SQLiteColumn } from \"drizzle-orm/sqlite-core\";\n\nconst CURSOR_SEPARATOR = \"|\";\n\n/**\n * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the\n * sort value alongside the id is what lets `listX` resume from a stable point\n * even when two rows share a timestamp.\n */\nexport function encodeCursor(id: string, sortValue: string): string {\n  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, \"utf8\").toString(\n    \"base64url\",\n  );\n}\n\nexport function decodeCursor(\n  cursor: string,\n): { id: string; sortValue: string } | null {\n  let decoded: string;\n  try {\n    decoded = Buffer.from(cursor, \"base64url\").toString(\"utf8\");\n  } catch {\n    return null;\n  }\n\n  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);\n  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;\n\n  return {\n    sortValue: decoded.slice(0, separatorAt),\n    id: decoded.slice(separatorAt + 1),\n  };\n}\n\n/**\n * The tenant predicate. Every repository read and write composes this — a\n * query that does not mention `org_id` is a cross-tenant leak waiting to\n * happen, so this is the only sanctioned way to express it.\n */\nexport function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {\n  return eq(column, orgId);\n}\n\n/**\n * The soft-delete predicate, or `undefined` when the caller explicitly asked\n * for archived rows. The `includeArchived` decision itself lives in\n * `shouldFilterArchived()` so it cannot drift per repository.\n */\nexport function livePredicate(\n  column: SQLiteColumn,\n  scope: ArchiveScope,\n): SQL | undefined {\n  return shouldFilterArchived(scope) ? isNull(column) : undefined;\n}\n","import type { ArchiveScope, IsoTimestamp, SoftDeletable } from \"@/types/common\";\nimport { toIsoTimestamp } from \"@/types/common\";\n\n/**\n * Soft-delete conventions.\n *\n * Issues, projects and comments are never physically removed — they get an\n * `archived_at` timestamp. Repositories must express \"live rows only\" through\n * these helpers so the predicate stays in one place; a raw\n * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the\n * drift this module prevents.\n */\n\nexport function isArchived(row: SoftDeletable): boolean {\n  return row.archivedAt !== null;\n}\n\nexport function isLive(row: SoftDeletable): boolean {\n  return row.archivedAt === null;\n}\n\n/** Filters an in-memory collection according to an `ArchiveScope`. */\nexport function applyArchiveScope<T extends SoftDeletable>(\n  rows: readonly T[],\n  scope: ArchiveScope = {},\n): readonly T[] {\n  return scope.includeArchived === true ? rows : rows.filter(isLive);\n}\n\n/** True when the repository should add the `archived_at IS NULL` predicate. */\nexport function shouldFilterArchived(scope: ArchiveScope = {}): boolean {\n  return scope.includeArchived !== true;\n}\n\n/** The column patch that archives a row. */\nexport function archivePatch(now: Date = new Date()): {\n  archivedAt: IsoTimestamp;\n  updatedAt: IsoTimestamp;\n} {\n  const stamp = toIsoTimestamp(now);\n  return { archivedAt: stamp, updatedAt: stamp };\n}\n\n/** The column patch that restores an archived row. */\nexport function restorePatch(now: Date = new Date()): {\n  archivedAt: null;\n  updatedAt: IsoTimestamp;\n} {\n  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };\n}\n\nexport class AlreadyArchivedError extends Error {\n  readonly code = \"conflict\" as const;\n\n  constructor(readonly entity: string, readonly id: string) {\n    super(`${entity} ${id} is already archived.`);\n    this.name = \"AlreadyArchivedError\";\n  }\n}\n\n/** Guard for archive actions, so double-archiving is a domain-level conflict. */\nexport function assertNotArchived(\n  entity: string,\n  id: string,\n  row: SoftDeletable,\n): void {\n  if (isArchived(row)) {\n    throw new AlreadyArchivedError(entity, id);\n  }\n}\n","/**\n * Organization rows plus slug uniqueness lookups.\n *\n * Must call (do not reimplement): archivePatch, uniqueSlug\n */\nimport { and, eq, isNull, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { uniqueSlug } from \"@/lib/slug\";\nimport { archivePatch } from \"@/lib/soft-delete\";\nimport { getDb, members, organizations } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { toOrganization } from \"./_mappers\";\nimport type {\n  CreateOrganizationInput,\n  UpdateOrganizationInput,\n} from \"@/schemas/organization\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { Organization } from \"@/types/organization\";\n\nexport async function findOrgById(orgId: OrgId): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(eq(organizations.id, orgId))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\nexport async function findOrgBySlug(slug: string): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\n/** Every org the user still holds a live membership in. */\nexport async function listOrgsForUser(\n  userId: UserId,\n): Promise<readonly Organization[]> {\n  const rows = getDb()\n    .select({ org: organizations })\n    .from(members)\n    .innerJoin(organizations, eq(organizations.id, members.orgId))\n    .where(\n      and(\n        eq(members.userId, userId),\n        isNull(members.archivedAt),\n        isNull(organizations.archivedAt),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => toOrganization(row.org));\n}\n\n/**\n * Creates the org row. The slug is de-duplicated here rather than in the\n * service so a race on the unique index still resolves to a usable slug.\n */\nexport async function insertOrg(\n  input: CreateOrganizationInput,\n  ownerId: UserId,\n): Promise<Organization> {\n  const taken = await listTakenOrgSlugs(input.slug);\n  const slug = uniqueSlug(input.slug, taken);\n  const stamp = toIsoTimestamp(new Date());\n\n  const row = getDb()\n    .insert(organizations)\n    .values({\n      id: newId(),\n      name: input.name,\n      slug,\n      ownerId,\n      plan: input.plan,\n      logoUrl: null,\n      trialEndsAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function updateOrg(\n  orgId: OrgId,\n  patch: UpdateOrganizationInput,\n): Promise<Organization> {\n  const current = await findOrgById(orgId);\n  if (!current) throw new Error(`Organization ${orgId} not found`);\n\n  const settings = { ...current.settings, ...(patch.settings ?? {}) };\n\n  const row = getDb()\n    .update(organizations)\n    .set({\n      ...(patch.name === undefined ? {} : { name: patch.name }),\n      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),\n      defaultIssueStatus: settings.defaultIssueStatus,\n      allowPublicProjects: settings.allowPublicProjects,\n      requireTwoFactor: settings.requireTwoFactor,\n      digestHourUtc: settings.digestHourUtc,\n      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function archiveOrg(orgId: OrgId): Promise<Organization> {\n  const row = getDb()\n    .update(organizations)\n    .set(archivePatch())\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Organization ${orgId} not found`);\n  return toOrganization(row);\n}\n\n/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */\nexport async function listTakenOrgSlugs(\n  prefix: string,\n): Promise<readonly string[]> {\n  const rows = getDb()\n    .select({ slug: organizations.slug })\n    .from(organizations)\n    .where(like(organizations.slug, `${prefix}%`))\n    .all();\n  return rows.map((row) => row.slug);\n}\n","/**\n * Webhook endpoints and their delivery attempts.\n */\nimport { and, asc, count, eq } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, webhookDeliveries, webhookEndpoints } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport type { CreateWebhookInput, UpdateWebhookInput } from \"@/schemas/webhook\";\nimport type {\n  WebhookDeliveryRow,\n  WebhookEndpointRow,\n} from \"@/server/db/schema/webhooks\";\nimport type { IsoTimestamp, OrgId, WebhookId } from \"@/types/common\";\n\nexport async function listEndpoints(\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  return getDb()\n    .select()\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .orderBy(asc(webhookEndpoints.createdAt))\n    .all();\n}\n\nexport async function insertEndpoint(\n  input: CreateWebhookInput,\n  secret: string,\n): Promise<WebhookEndpointRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookEndpoints)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      url: input.url,\n      secret,\n      eventTypes: JSON.stringify(input.eventTypes),\n      enabled: true,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\nexport async function updateEndpoint(\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  const row = getDb()\n    .update(webhookEndpoints)\n    .set({\n      ...(input.url === undefined ? {} : { url: input.url }),\n      ...(input.eventTypes === undefined\n        ? {}\n        : { eventTypes: JSON.stringify(input.eventTypes) }),\n      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, input.orgId),\n        eq(webhookEndpoints.id, input.webhookId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);\n  return row;\n}\n\nexport async function deleteEndpoint(\n  orgId: OrgId,\n  webhookId: WebhookId,\n): Promise<void> {\n  const db = getDb();\n  db.delete(webhookDeliveries)\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.endpointId, webhookId),\n      ),\n    )\n    .run();\n  db.delete(webhookEndpoints)\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, orgId),\n        eq(webhookEndpoints.id, webhookId),\n      ),\n    )\n    .run();\n}\n\n/** The `webhooks` quota compares against this. */\nexport async function countEndpoints(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function enqueueDelivery(\n  orgId: OrgId,\n  endpointId: string,\n  eventType: string,\n  payload: string,\n): Promise<WebhookDeliveryRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookDeliveries)\n    .values({\n      id: newId(),\n      orgId,\n      endpointId,\n      eventType,\n      payload,\n      status: \"pending\",\n      attempts: 0,\n      lastError: null,\n      deliveredAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\n/**\n * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is\n * drained by a background worker, not by a request — and the attempt counter\n * is bumped on claim so a crashed worker cannot retry forever.\n */\nexport async function claimPendingDeliveries(\n  limit: number,\n): Promise<readonly WebhookDeliveryRow[]> {\n  const db = getDb();\n  const pending = db\n    .select()\n    .from(webhookDeliveries)\n    .where(eq(webhookDeliveries.status, \"pending\"))\n    .orderBy(asc(webhookDeliveries.createdAt))\n    .limit(Math.max(1, limit))\n    .all();\n\n  return pending.map((row) =>\n    db\n      .update(webhookDeliveries)\n      .set({\n        attempts: row.attempts + 1,\n        updatedAt: toIsoTimestamp(new Date()),\n      })\n      .where(eq(webhookDeliveries.id, row.id))\n      .returning()\n      .get(),\n  );\n}\n\nexport async function markDelivered(\n  orgId: OrgId,\n  deliveryId: string,\n  at: IsoTimestamp,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({ status: \"delivered\", deliveredAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n\nexport async function markDeliveryFailed(\n  orgId: OrgId,\n  deliveryId: string,\n  error: string,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({\n      status: \"failed\",\n      lastError: error.slice(0, 500),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n","/**\n * Server-side flag context construction and the org-level override toggle.\n *\n * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit\n */\nimport { emit } from \"@/lib/event-bus\";\nimport { isEnabled, snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { getFlagDefinition } from \"@/config/feature-flags\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport { actorEnvelope, orgResource, requireFound } from \"./_support\";\nimport type { ToggleFeatureFlagInput } from \"@/schemas/feature-flag\";\nimport type { FeatureFlagSnapshot, FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\n/**\n * Builds the evaluation context every `isEnabled()` call needs. Both halves\n * are nullable so marketing pages — no session, no org — can still ask about\n * a flag and get the free-plan answer.\n */\nexport function buildFlagContext(\n  actor: Actor | null,\n  org: Organization | null,\n): FlagContext {\n  return {\n    orgId: org?.id ?? actor?.orgId ?? null,\n    userId: actor?.userId ?? null,\n    plan: org?.plan ?? \"free\",\n    role: actor?.role ?? null,\n    overrides: org?.settings.enabledFlagOverrides,\n  };\n}\n\n/**\n * The serialisable snapshot the dashboard layout hands to the client provider,\n * so `useFeatureFlag()` answers without a round trip and cannot disagree with\n * the server.\n */\nexport function getSnapshot(\n  actor: Actor,\n  org: Organization,\n): FeatureFlagSnapshot {\n  return snapshotFlags(buildFlagContext(actor, org));\n}\n\n/**\n * Adds or removes an org-level override. Only flags declared `overridable`\n * accept one — a flag gated purely on plan cannot be switched on by an admin,\n * which is what keeps the plan boundary meaningful.\n */\nexport async function toggleFlag(\n  actor: Actor,\n  input: ToggleFeatureFlagInput,\n): Promise<Organization> {\n  assertCan(actor, \"org:manage_flags\", orgResource(input.orgId));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  const definition = getFlagDefinition(input.flag);\n  if (!definition.overridable) {\n    throw new Error(`Feature \"${input.flag}\" cannot be overridden per org`);\n  }\n\n  const current = new Set(org.settings.enabledFlagOverrides);\n  if (input.enabled) {\n    current.add(input.flag);\n  } else {\n    current.delete(input.flag);\n  }\n\n  const updated = await orgRepo.updateOrg(input.orgId, {\n    orgId: input.orgId,\n    settings: { enabledFlagOverrides: [...current] },\n  });\n\n  await emit(\"flag.toggled\", {\n    ...actorEnvelope(actor),\n    flag: input.flag,\n    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),\n  });\n\n  return updated;\n}\n","/**\n * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit\n */\nimport { createHmac } from \"node:crypto\";\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { randomToken } from \"@/lib/hash\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { requireFound, webhookResource } from \"./_support\";\nimport type {\n  CreateWebhookInput,\n  DeleteWebhookInput,\n  UpdateWebhookInput,\n} from \"@/schemas/webhook\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\n\n/** Length in bytes of a generated endpoint signing secret. */\nconst SECRET_BYTES = 32;\n\nexport async function listWebhooks(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(orgId, null));\n  return webhookRepo.listEndpoints(orgId);\n}\n\n/**\n * Creating an endpoint is gated twice: the `webhooks` flag has to be on for\n * the org's plan, and the plan's endpoint count must have room. A secret is\n * minted here and never regenerated — rotating it means deleting the endpoint.\n */\nexport async function createWebhook(\n  actor: Actor,\n  input: CreateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, null));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  if (!isEnabled(\"webhooks\", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {\n    throw new Error(\"Outgoing webhooks are not included in this plan\");\n  }\n\n  const used = await webhookRepo.countEndpoints(input.orgId);\n  if (wouldExceedLimit(org.plan, \"webhooks\", used)) {\n    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);\n  }\n\n  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));\n}\n\nexport async function updateWebhook(\n  actor: Actor,\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  return webhookRepo.updateEndpoint(input);\n}\n\nexport async function deleteWebhook(\n  actor: Actor,\n  input: DeleteWebhookInput,\n): Promise<void> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);\n}\n\n/**\n * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes\n * this from the same secret — it is the only thing proving the delivery came\n * from Taskflow, so the payload string must be signed byte-for-byte as sent.\n */\nexport function signPayload(secret: string, payload: string): string {\n  return createHmac(\"sha256\", secret).update(payload, \"utf8\").digest(\"hex\");\n}\n\n/**\n * Fans domain events out into the delivery table. Each org's endpoints\n * declare which event types they want, so an endpoint only ever receives what\n * it subscribed to; the job drains the rows afterwards.\n */\nexport function registerWebhookListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"webhook.delivery_requested\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        payload.eventType,\n        JSON.stringify(payload.payload),\n      );\n    }),\n    subscribe(\"issue.created\", async (payload) => {\n      await enqueueForOrg(payload.orgId, \"issue.created\", JSON.stringify(payload));\n    }),\n    subscribe(\"issue.status_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"issue.status_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"comment.created\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"billing.plan_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"billing.plan_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nasync function enqueueForOrg(\n  orgId: OrgId,\n  eventType: string,\n  payload: string,\n): Promise<void> {\n  const endpoints = await webhookRepo.listEndpoints(orgId);\n\n  for (const endpoint of endpoints) {\n    if (!endpoint.enabled) continue;\n\n    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];\n    if (!wanted.includes(eventType)) continue;\n\n    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);\n  }\n}\n\nfunction flagContextFor(\n  actor: Actor,\n  plan: FlagContext[\"plan\"],\n  overrides: readonly string[],\n): FlagContext {\n  return {\n    orgId: actor.orgId,\n    userId: actor.userId,\n    plan,\n    role: actor.role,\n    overrides,\n  };\n}\n"],"names":["UNLIMITED","Number","POSITIVE_INFINITY","PLAN_LIMITS","free","plan","seats","projects","issuesPerProject","storageMb","apiRequestsPerHour","webhooks","retentionDays","includedFlags","priceCentsPerSeatMonthly","starter","growth","enterprise","PLAN_ORDER","getPlanLimits","getLimit","resource","planAtLeast","minPlan","indexOf","wouldExceedLimit","used","requested","handlers","Map","errorSinks","Set","subscribe","type","handler","set","get","add","delete","subscribeOnce","off","payload","emit","size","results","Promise","allSettled","map","result","status","reportHandlerError","reason","emitAndForget","catch","error","onHandlerError","sink","subscriberCount","resetEventBus","clear","FEATURE_FLAG_DEFINITIONS","kanban_board","key","label","description","strategy","kind","overridable","ai_issue_summary","percent","command_palette","activity_feed","public_projects","csv_export","digest_email","issue_templates","minRole","advanced_search","FEATURE_FLAG_KEYS1","Object","keys","getFlagDefinition","isFeatureFlagKey","value","prototype","hasOwnProperty","call","KEY_LENGTH","SALT_BYTES","PREFIX","derive