const;\n\n  constructor(readonly orgSlug: string) {\n    super(`You are not a member of \"${orgSlug}\".`);\n    this.name = \"NoMembershipError\";\n  }\n}\n\n/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */\nexport async function getActor(orgSlug: string): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n\n  const actor = await resolveActorForOrg(principal, orgSlug);\n  if (actor === null) throw new NoMembershipError(orgSlug);\n\n  return actor;\n}\n\n/** Non-throwing variant, for layouts that render a signed-out state. */\nexport async function tryGetActor(orgSlug: string): Promise<Actor | null> {\n  try {\n    return await getActor(orgSlug);\n  } catch (error) {\n    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {\n      return null;\n    }\n    throw error;\n  }\n}\n\n/**\n * The `Actor` for an org already identified by id — used by Route Handlers\n * that receive an `orgId` in the payload rather than a slug in the path. The\n * session's active org must match, which `assertOrgScope()` enforces.\n *\n * `resolveActorForOrg` keys off the org *slug*, so the id is translated here\n * with a single repository lookup rather than by widening that signature —\n * the slug is the only handle the session layer knows.\n */\nexport async function requireActorFor(orgId: OrgId): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);\n\n  const org = await findOrgById(orgId);\n  if (org === null) throw new NoMembershipError(orgId);\n\n  const actor = await resolveActorForOrg(principal, org.slug);\n  if (actor === null) throw new NoMembershipError(org.slug);\n\n  assertOrgScope(actor, orgId);\n  return actor;\n}\n","/**\n * Password and token hashing built on `node:crypto` scrypt. No external\n * dependency — the corpus builds offline, and scrypt is the strongest KDF the\n * platform ships without one.\n *\n * Server-only: never import this from a client component.\n */\nimport {\n  createHash,\n  randomBytes,\n  scrypt,\n  timingSafeEqual,\n} from \"node:crypto\";\n\nconst KEY_LENGTH = 64;\nconst SALT_BYTES = 16;\nconst PREFIX = \"scrypt\";\n\nfunction deriveKey(password: string, salt: Buffer): Promise<Buffer> {\n  return new Promise((resolve, reject) => {\n    scrypt(password.normalize(\"NFKC\"), salt, KEY_LENGTH, (error, key) => {\n      if (error) reject(error);\n      else resolve(key);\n    });\n  });\n}\n\n/** Returns `scrypt:<saltHex>:<keyHex>` — self-describing, so the verifier\n *  can change parameters later without a migration. */\nexport async function hashPassword(password: string): Promise<string> {\n  const salt = randomBytes(SALT_BYTES);\n  const key = await deriveKey(password, salt);\n  return `${PREFIX}:${salt.toString(\"hex\")}:${key.toString(\"hex\")}`;\n}\n\n/** Constant-time comparison; a malformed stored hash simply fails to verify. */\nexport async function verifyPassword(\n  password: string,\n  hash: string,\n): Promise<boolean> {\n  const [scheme, saltHex, keyHex] = hash.split(\":\");\n  if (scheme !== PREFIX || !saltHex || !keyHex) return false;\n\n  const expected = Buffer.from(keyHex, \"hex\");\n  if (expected.length !== KEY_LENGTH) return false;\n\n  const actual = await deriveKey(password, Buffer.from(saltHex, \"hex\"));\n  return timingSafeEqual(actual, expected);\n}\n\n/** One-way digest for invitation and session tokens, which are high-entropy\n *  already and so need no salt or work factor. */\nexport function hashToken(token: string): string {\n  return createHash(\"sha256\").update(token).digest(\"hex\");\n}\n\n/** URL-safe random token; the default width matches the session schema's\n *  32-character minimum. */\nexport function randomToken(bytes = 32): string {\n  return randomBytes(bytes).toString(\"base64url\");\n}\n","/**\n * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.\n *\n * Must call (do not reimplement): shouldFilterArchived\n */\nimport { eq, isNull } from \"drizzle-orm\";\nimport { shouldFilterArchived } from \"@/lib/soft-delete\";\nimport type { ArchiveScope, OrgId } from \"@/types/common\";\nimport type { SQL } from \"drizzle-orm\";\nimport type { SQLiteColumn } from \"drizzle-orm/sqlite-core\";\n\nconst CURSOR_SEPARATOR = \"|\";\n\n/**\n * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the\n * sort value alongside the id is what lets `listX` resume from a stable point\n * even when two rows share a timestamp.\n */\nexport function encodeCursor(id: string, sortValue: string): string {\n  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, \"utf8\").toString(\n    \"base64url\",\n  );\n}\n\nexport function decodeCursor(\n  cursor: string,\n): { id: string; sortValue: string } | null {\n  let decoded: string;\n  try {\n    decoded = Buffer.from(cursor, \"base64url\").toString(\"utf8\");\n  } catch {\n    return null;\n  }\n\n  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);\n  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;\n\n  return {\n    sortValue: decoded.slice(0, separatorAt),\n    id: decoded.slice(separatorAt + 1),\n  };\n}\n\n/**\n * The tenant predicate. Every repository read and write composes this — a\n * query that does not mention `org_id` is a cross-tenant leak waiting to\n * happen, so this is the only sanctioned way to express it.\n */\nexport function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {\n  return eq(column, orgId);\n}\n\n/**\n * The soft-delete predicate, or `undefined` when the caller explicitly asked\n * for archived rows. The `includeArchived` decision itself lives in\n * `shouldFilterArchived()` so it cannot drift per repository.\n */\nexport function livePredicate(\n  column: SQLiteColumn,\n  scope: ArchiveScope,\n): SQL | undefined {\n  return shouldFilterArchived(scope) ? isNull(column) : undefined;\n}\n","/**\n * Organization rows plus slug uniqueness lookups.\n *\n * Must call (do not reimplement): archivePatch, uniqueSlug\n */\nimport { and, eq, isNull, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { uniqueSlug } from \"@/lib/slug\";\nimport { archivePatch } from \"@/lib/soft-delete\";\nimport { getDb, members, organizations } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { toOrganization } from \"./_mappers\";\nimport type {\n  CreateOrganizationInput,\n  UpdateOrganizationInput,\n} from \"@/schemas/organization\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { Organization } from \"@/types/organization\";\n\nexport async function findOrgById(orgId: OrgId): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(eq(organizations.id, orgId))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\nexport async function findOrgBySlug(slug: string): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\n/** Every org the user still holds a live membership in. */\nexport async function listOrgsForUser(\n  userId: UserId,\n): Promise<readonly Organization[]> {\n  const rows = getDb()\n    .select({ org: organizations })\n    .from(members)\n    .innerJoin(organizations, eq(organizations.id, members.orgId))\n    .where(\n      and(\n        eq(members.userId, userId),\n        isNull(members.archivedAt),\n        isNull(organizations.archivedAt),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => toOrganization(row.org));\n}\n\n/**\n * Creates the org row. The slug is de-duplicated here rather than in the\n * service so a race on the unique index still resolves to a usable slug.\n */\nexport async function insertOrg(\n  input: CreateOrganizationInput,\n  ownerId: UserId,\n): Promise<Organization> {\n  const taken = await listTakenOrgSlugs(input.slug);\n  const slug = uniqueSlug(input.slug, taken);\n  const stamp = toIsoTimestamp(new Date());\n\n  const row = getDb()\n    .insert(organizations)\n    .values({\n      id: newId(),\n      name: input.name,\n      slug,\n      ownerId,\n      plan: input.plan,\n      logoUrl: null,\n      trialEndsAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function updateOrg(\n  orgId: OrgId,\n  patch: UpdateOrganizationInput,\n): Promise<Organization> {\n  const current = await findOrgById(orgId);\n  if (!current) throw new Error(`Organization ${orgId} not found`);\n\n  const settings = { ...current.settings, ...(patch.settings ?? {}) };\n\n  const row = getDb()\n    .update(organizations)\n    .set({\n      ...(patch.name === undefined ? {} : { name: patch.name }),\n      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),\n      defaultIssueStatus: settings.defaultIssueStatus,\n      allowPublicProjects: settings.allowPublicProjects,\n      requireTwoFactor: settings.requireTwoFactor,\n      digestHourUtc: settings.digestHourUtc,\n      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function archiveOrg(orgId: OrgId): Promise<Organization> {\n  const row = getDb()\n    .update(organizations)\n    .set(archivePatch())\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Organization ${orgId} not found`);\n  return toOrganization(row);\n}\n\n/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */\nexport async function listTakenOrgSlugs(\n  prefix: string,\n): Promise<readonly string[]> {\n  const rows = getDb()\n    .select({ slug: organizations.slug })\n    .from(organizations)\n    .where(like(organizations.slug, `${prefix}%`))\n    .all();\n  return rows.map((row) => row.slug);\n}\n","/**\n * Webhook endpoints and their delivery attempts.\n */\nimport { and, asc, count, eq } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, webhookDeliveries, webhookEndpoints } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport type { CreateWebhookInput, UpdateWebhookInput } from \"@/schemas/webhook\";\nimport type {\n  WebhookDeliveryRow,\n  WebhookEndpointRow,\n} from \"@/server/db/schema/webhooks\";\nimport type { IsoTimestamp, OrgId, WebhookId } from \"@/types/common\";\n\nexport async function listEndpoints(\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  return getDb()\n    .select()\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .orderBy(asc(webhookEndpoints.createdAt))\n    .all();\n}\n\nexport async function insertEndpoint(\n  input: CreateWebhookInput,\n  secret: string,\n): Promise<WebhookEndpointRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookEndpoints)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      url: input.url,\n      secret,\n      eventTypes: JSON.stringify(input.eventTypes),\n      enabled: true,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\nexport async function updateEndpoint(\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  const row = getDb()\n    .update(webhookEndpoints)\n    .set({\n      ...(input.url === undefined ? {} : { url: input.url }),\n      ...(input.eventTypes === undefined\n        ? {}\n        : { eventTypes: JSON.stringify(input.eventTypes) }),\n      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, input.orgId),\n        eq(webhookEndpoints.id, input.webhookId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);\n  return row;\n}\n\nexport async function deleteEndpoint(\n  orgId: OrgId,\n  webhookId: WebhookId,\n): Promise<void> {\n  const db = getDb();\n  db.delete(webhookDeliveries)\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.endpointId, webhookId),\n      ),\n    )\n    .run();\n  db.delete(webhookEndpoints)\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, orgId),\n        eq(webhookEndpoints.id, webhookId),\n      ),\n    )\n    .run();\n}\n\n/** The `webhooks` quota compares against this. */\nexport async function countEndpoints(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function enqueueDelivery(\n  orgId: OrgId,\n  endpointId: string,\n  eventType: string,\n  payload: string,\n): Promise<WebhookDeliveryRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookDeliveries)\n    .values({\n      id: newId(),\n      orgId,\n      endpointId,\n      eventType,\n      payload,\n      status: \"pending\",\n      attempts: 0,\n      lastError: null,\n      deliveredAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\n/**\n * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is\n * drained by a background worker, not by a request — and the attempt counter\n * is bumped on claim so a crashed worker cannot retry forever.\n */\nexport async function claimPendingDeliveries(\n  limit: number,\n): Promise<readonly WebhookDeliveryRow[]> {\n  const db = getDb();\n  const pending = db\n    .select()\n    .from(webhookDeliveries)\n    .where(eq(webhookDeliveries.status, \"pending\"))\n    .orderBy(asc(webhookDeliveries.createdAt))\n    .limit(Math.max(1, limit))\n    .all();\n\n  return pending.map((row) =>\n    db\n      .update(webhookDeliveries)\n      .set({\n        attempts: row.attempts + 1,\n        updatedAt: toIsoTimestamp(new Date()),\n      })\n      .where(eq(webhookDeliveries.id, row.id))\n      .returning()\n      .get(),\n  );\n}\n\nexport async function markDelivered(\n  orgId: OrgId,\n  deliveryId: string,\n  at: IsoTimestamp,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({ status: \"delivered\", deliveredAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n\nexport async function markDeliveryFailed(\n  orgId: OrgId,\n  deliveryId: string,\n  error: string,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({\n      status: \"failed\",\n      lastError: error.slice(0, 500),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n","/**\n * Private helpers shared by the service layer.\n *\n * Two jobs only: build the `PermissionResource` descriptors `can()` expects\n * from a loaded row, and stamp the `EventEnvelope` every domain event carries.\n * Neither re-implements a cross-cutting concern — they are adapters onto\n * `@/lib/permissions` and `@/lib/event-bus`.\n */\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { Comment } from \"@/types/comment\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { EventEnvelope } from \"@/types/event\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Actor, Member } from \"@/types/member\";\nimport type { PermissionResource } from \"@/types/permission\";\nimport type { Project } from \"@/types/project\";\nimport type { WebhookId } from \"@/types/common\";\n\n/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */\nexport class NotFoundError extends Error {\n  readonly code = \"not_found\" as const;\n\n  constructor(\n    readonly entity: string,\n    readonly id: string,\n  ) {\n    super(`${entity} ${id} was not found`);\n    this.name = \"NotFoundError\";\n  }\n}\n\n/** Unwraps a repository read, turning the `null` case into a domain error. */\nexport function requireFound<T>(\n  value: T | null | undefined,\n  entity: string,\n  id: string,\n): T {\n  if (value === null || value === undefined) {\n    throw new NotFoundError(entity, id);\n  }\n  return value;\n}\n\nexport function orgResource(orgId: OrgId): PermissionResource {\n  return { kind: \"organization\", orgId };\n}\n\nexport function billingResource(orgId: OrgId): PermissionResource {\n  return { kind: \"billing\", orgId };\n}\n\nexport function activityResource(orgId: OrgId): PermissionResource {\n  return { kind: \"activity\", orgId };\n}\n\nexport function notificationResource(\n  orgId: OrgId,\n  recipientId: UserId,\n): PermissionResource {\n  return { kind: \"notification\", orgId, recipientId };\n}\n\nexport function webhookResource(\n  orgId: OrgId,\n  webhookId: WebhookId | null,\n): PermissionResource {\n  return { kind: \"webhook\", orgId, webhookId };\n}\n\nexport function memberResource(member: Member): PermissionResource {\n  return {\n    kind: \"member\",\n    orgId: member.orgId,\n    memberId: member.id,\n    targetUserId: member.userId,\n    targetRole: member.role,\n  };\n}\n\nexport function projectResource(project: Project): PermissionResource {\n  return {\n    kind: \"project\",\n    orgId: project.orgId,\n    projectId: project.id,\n    visibility: project.visibility,\n    leadId: project.leadId,\n  };\n}\n\nexport function issueResource(issue: Issue): PermissionResource {\n  return {\n    kind: \"issue\",\n    orgId: issue.orgId,\n    projectId: issue.projectId,\n    issueId: issue.id,\n    authorId: issue.authorId,\n    assigneeId: issue.assigneeId,\n  };\n}\n\nexport function commentResource(comment: Comment): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId: comment.orgId,\n    commentId: comment.id,\n    authorId: comment.authorId,\n  };\n}\n\n/** The three fields the bus stamps on every payload. */\nexport function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {\n  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };\n}\n\n/** Same envelope, taken from an `Actor` rather than assembled by hand. */\nexport function actorEnvelope(actor: Actor): EventEnvelope {\n  return envelope(actor.orgId, actor.userId);\n}\n\n/** Names the fields an update actually changed, for `issue.updated`. */\nexport function changedFields<T extends object>(\n  before: T,\n  after: T,\n): readonly string[] {\n  return Object.keys(after).filter(\n    (key) =>\n      JSON.stringify(before[key as keyof T]) !==\n      JSON.stringify(after[key as keyof T]),\n  );\n}\n","/**\n * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit\n */\nimport { createHmac } from \"node:crypto\";\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { randomToken } from \"@/lib/hash\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { requireFound, webhookResource } from \"./_support\";\nimport type {\n  CreateWebhookInput,\n  DeleteWebhookInput,\n  UpdateWebhookInput,\n} from \"@/schemas/webhook\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\n\n/** Length in bytes of a generated endpoint signing secret. */\nconst SECRET_BYTES = 32;\n\nexport async function listWebhooks(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(orgId, null));\n  return webhookRepo.listEndpoints(orgId);\n}\n\n/**\n * Creating an endpoint is gated twice: the `webhooks` flag has to be on for\n * the org's plan, and the plan's endpoint count must have room. A secret is\n * minted here and never regenerated — rotating it means deleting the endpoint.\n */\nexport async function createWebhook(\n  actor: Actor,\n  input: CreateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, null));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  if (!isEnabled(\"webhooks\", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {\n    throw new Error(\"Outgoing webhooks are not included in this plan\");\n  }\n\n  const used = await webhookRepo.countEndpoints(input.orgId);\n  if (wouldExceedLimit(org.plan, \"webhooks\", used)) {\n    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);\n  }\n\n  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));\n}\n\nexport async function updateWebhook(\n  actor: Actor,\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  return webhookRepo.updateEndpoint(input);\n}\n\nexport async function deleteWebhook(\n  actor: Actor,\n  input: DeleteWebhookInput,\n): Promise<void> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);\n}\n\n/**\n * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes\n * this from the same secret — it is the only thing proving the delivery came\n * from Taskflow, so the payload string must be signed byte-for-byte as sent.\n */\nexport function signPayload(secret: string, payload: string): string {\n  return createHmac(\"sha256\", secret).update(payload, \"utf8\").digest(\"hex\");\n}\n\n/**\n * Fans domain events out into the delivery table. Each org's endpoints\n * declare which event types they want, so an endpoint only ever receives what\n * it subscribed to; the job drains the rows afterwards.\n */\nexport function registerWebhookListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"webhook.delivery_requested\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        payload.eventType,\n        JSON.stringify(payload.payload),\n      );\n    }),\n    subscribe(\"issue.created\", async (payload) => {\n      await enqueueForOrg(payload.orgId, \"issue.created\", JSON.stringify(payload));\n    }),\n    subscribe(\"issue.status_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"issue.status_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"comment.created\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"billing.plan_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"billing.plan_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nasync function enqueueForOrg(\n  orgId: OrgId,\n  eventType: string,\n  payload: string,\n): Promise<void> {\n  const endpoints = await webhookRepo.listEndpoints(orgId);\n\n  for (const endpoint of endpoints) {\n    if (!endpoint.enabled) continue;\n\n    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];\n    if (!wanted.includes(eventType)) continue;\n\n    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);\n  }\n}\n\nfunction flagContextFor(\n  actor: Actor,\n  plan: FlagContext[\"plan\"],\n  overrides: readonly string[],\n): FlagContext {\n  return {\n    orgId: actor.orgId,\n    userId: actor.userId,\n    plan,\n    role: actor.role,\n    overrides,\n  };\n}\n"],"names":["dynamic","POST","request","context","url","URL","orgSlug","searchParams","get","endpointId","params","parsedId","safeParse","success","actor","allowed","kind","orgId","webhookId","data","endpoints","endpoint","find","row","id","undefined","payload","JSON","stringify","eventType","sentAt","Date","toISOString","Response","json","delivered","enabled","signature","secret","error","AppRouteRouteModule","RouteKind","patchFetch","_patchFetch","addRequestMeta","getRequestMeta","setRequestMeta","getTracer","SpanKind","SpanStatusCode","setManifestsSingleton","normalizeAppPath","NodeNextRequest","NodeNextResponse","NextRequestAdapter","signalFromNodeResponse","BaseServerSpan","getRevalidateReason","sendResponse","fromNodeOutgoingHttpHeaders","toNodeOutgoingHttpHeaders","getCacheControlHeader","INFINITE_CACHE","NEXT_CACHE_TAGS_HEADER","NoFallbackError","CachedRouteKind","routeModule","definition","APP_ROUTE","page","path