./.next/server/chunks/corpus_taskflow_src_09qvkgr._.js.map:1:{"version":3,"sources":["../../../../../corpus/taskflow/src/lib/rate-limit.ts","../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts"],"sourcesContent":["/**\n * Token-bucket limiter applied to invites, comments, search and password\n * resets.\n *\n * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow\n * runs single-writer, and the corpus has no external cache. Capacity scales\n * with the org's plan through `getPlanLimits()`, so a growth org is not held\n * to a free org's ceiling; the per-bucket shape below is the base rate.\n */\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport type { PlanId } from \"@/types/billing\";\nimport type { IsoTimestamp, OrgId } from \"@/types/common\";\nimport { toIsoTimestamp } from \"@/types/common\";\n\nexport type RateLimitVerdict = {\n  allowed: boolean;\n  remaining: number;\n  resetAt: IsoTimestamp;\n};\n\nexport type RateLimitConfig = { capacity: number; refillPerMinute: number };\n\nexport const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {\n  \"member:invite\": { capacity: 20, refillPerMinute: 2 },\n  \"comment:create\": { capacity: 60, refillPerMinute: 20 },\n  \"issue:create\": { capacity: 60, refillPerMinute: 20 },\n  \"search:query\": { capacity: 120, refillPerMinute: 60 },\n  \"auth:password-reset\": { capacity: 5, refillPerMinute: 1 },\n  \"webhook:deliver\": { capacity: 100, refillPerMinute: 50 },\n};\n\n/** Applied to any key not in the table above. */\nconst DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };\n\ntype BucketState = { tokens: number; updatedAt: number };\n\nconst buckets = new Map<string, BucketState>();\n\n/** Plan-aware org context; services set this when they know the org's plan. */\nconst planByOrg = new Map<OrgId, PlanId>();\n\n/** Records an org's plan so subsequent bucket sizes scale with its quota. */\nexport function setOrgPlan(orgId: OrgId, plan: PlanId): void {\n  planByOrg.set(orgId, plan);\n}\n\nexport function getBucketConfig(bucketKey: string): RateLimitConfig {\n  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;\n}\n\n/**\n * Scales the base bucket by the org's hourly API allowance, so the limiter\n * and the plan catalogue can never drift apart: the plan is the source of\n * the ceiling, this table only sets the relative shape.\n */\nfunction configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {\n  const base = getBucketConfig(bucketKey);\n  const plan = planByOrg.get(orgId) ?? \"free\";\n  const hourly = getPlanLimits(plan).apiRequestsPerHour;\n  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;\n\n  return {\n    capacity: Math.min(base.capacity * factor, base.capacity * 100),\n    refillPerMinute: Math.min(\n      base.refillPerMinute * factor,\n      base.refillPerMinute * 100,\n    ),\n  };\n}\n\n/**\n * Spends `cost` tokens from the bucket, refilling first for the elapsed time.\n * Async because the production limiter is expected to move behind a store —\n * every call site already awaits it.\n */\nexport async function consumeRateLimit(\n  orgId: OrgId,\n  bucketKey: string,\n  cost = 1,\n): Promise<RateLimitVerdict> {\n  const config = configFor(orgId, bucketKey);\n  const key = `${orgId}:${bucketKey}`;\n  const nowMs = Date.now();\n\n  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };\n  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;\n  const tokens = Math.min(\n    config.capacity,\n    state.tokens + elapsedMinutes * config.refillPerMinute,\n  );\n\n  const allowed = tokens >= cost;\n  const remaining = allowed ? tokens - cost : tokens;\n  buckets.set(key, { tokens: remaining, updatedAt: nowMs });\n\n  const deficit = allowed ? config.capacity - remaining : cost - remaining;\n  const minutesToReset =\n    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;\n\n  return {\n    allowed,\n    remaining: Math.floor(remaining),\n    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),\n  };\n}\n\n/** Test-only: drops every bucket and org plan association. */\nexport function resetRateLimits(): void {\n  buckets.clear();\n  planByOrg.clear();\n}\n","/**\n * Comment rows, soft deleted so a deleted comment keeps its place in the thread.\n *\n * Must call (do not reimplement): archivePatch, shouldFilterArchived\n */\nimport { and, asc, count, desc, eq, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { archivePatch, shouldFilterArchived } from \"@/lib/soft-delete\";\nimport { comments, getDb, users } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toComment, toUser } from \"./_mappers\";\nimport type {\n  CreateCommentInput,\n  ListCommentsInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type {\n  Comment,\n  CommentThreadNode,\n  CommentWithAuthor,\n} from \"@/types/comment\";\nimport type { CommentId, IssueId, OrgId, Page, UserId } from \"@/types/common\";\n\nexport async function findCommentById(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment | null> {\n  const row = getDb()\n    .select()\n    .from(comments)\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .get();\n  return row ? toComment(row) : null;\n}\n\nexport async function listComments(\n  input: ListCommentsInput,\n): Promise<Page<CommentWithAuthor>> {\n  const db = getDb();\n  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };\n\n  const filters = compact(\n    orgPredicate(comments.orgId, input.orgId),\n    eq(comments.issueId, input.issueId),\n    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(comments)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(comments.createdAt), desc(comments.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),\n    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),\n  );\n}\n\n/**\n * The whole thread for one issue, in reading order: top-level comments oldest\n * first, each followed by its replies. Archived comments are kept so a reply\n * chain never loses its anchor — the UI renders them as \"deleted\".\n */\nexport async function listThread(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  const rows = getDb()\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(comments.createdAt))\n    .all();\n\n  const decorated: CommentWithAuthor[] = rows.map((row) => ({\n    ...toComment(row.comment),\n    author: toUser(row.author),\n  }));\n\n  const repliesBy = new Map<string, CommentWithAuthor[]>();\n  for (const comment of decorated) {\n    if (comment.parentId === null) continue;\n    const bucket = repliesBy.get(comment.parentId) ?? [];\n    bucket.push(comment);\n    repliesBy.set(comment.parentId, bucket);\n  }\n\n  return decorated\n    .filter((comment) => comment.parentId === null)\n    .map((comment) => ({\n      comment,\n      replies: repliesBy.get(comment.id) ?? [],\n    }));\n}\n\nexport async function countComments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(comments)\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n        isNull(comments.archivedAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertComment(\n  input: CreateCommentInput,\n  authorId: UserId,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(comments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      authorId,\n      body: input.body,\n      parentId: input.parentId,\n      editedAt: null,\n      mentionedUserIds: JSON.stringify(input.mentionedUserIds),\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toComment(row);\n}\n\n/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */\nexport async function updateComment(\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .update(comments)\n    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })\n    .where(\n      and(\n        orgPredicate(comments.orgId, input.orgId),\n        eq(comments.id, input.commentId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${input.commentId} not found`);\n  return toComment(row);\n}\n\nexport async function archiveComment(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment> {\n  const row = getDb()\n    .update(comments)\n    .set(archivePatch())\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${commentId} not found`);\n  return toComment(row);\n}\n"],"names":["RATE_LIMIT_BUCKETS","capacity","refillPerMinute","DEFAULT_BUCKET","buckets","Map","planByOrg","setOrgPlan","orgId","plan","set","getBucketConfig","bucketKey","configFor","base","get","hourly","apiRequestsPerHour","factor","Number","isFinite","Math","max","min","consumeRateLimit","cost","config","key","nowMs","Date","now","state","tokens","updatedAt","elapsedMinutes","allowed","remaining","deficit","minutesToReset","floor","resetAt","resetRateLimits","clear","findCommentById","commentId","row","select","from","where","id","toComment","listComments","input","db","sort","sortColumn","createdAt","idColumn","filters","compact","issueId","shouldFilterArchived","archivedAt","undefined","total","value","rows","comment","author","users","innerJoin","authorId","keysetPredicate","cursor","orderBy","desc","limit","probeLimit","all","toPage","toUser","sortValue","listThread","asc","decorated","map","repliesBy","parentId","bucket","push","filter","replies","countComments","insertComment","stamp","toIsoTimestamp","insert","values","newId","body","editedAt","mentionedUserIds","JSON","stringify","returning","updateComment","update","Error","archiveComment","archivePatch"],"mappings":"uCASA,IAAA,EAAA,EAAA,CAAA,CAAA,OAGA,EAAA,EAAA,CAAA,CAAA,OAUO,IAAMA,EAAgE,CAC3E,gBAAiB,CAAEC,SAAU,GAAIC,gBAAiB,CAAE,EACpD,iBAAkB,CAAED,SAAU,GAAIC,gBAAiB,EAAG,EACtD,eAAgB,CAAED,SAAU,GAAIC,gBAAiB,EAAG,EACpD,eAAgB,CAAED,SAAU,IAAKC,gBAAiB,EAAG,EACrD,sBAAuB,CAAED,SAAU,EAAGC,gBAAiB,CAAE,EACzD,kBAAmB,CAAED,SAAU,IAAKC,gBAAiB,EAAG,CAC1D,EAGMC,EAAkC,CAAEF,SAAU,GAAIC,gBAAiB,EAAG,EAItEE,EAAU,IAAIC,IAGdC,EAAY,IAAID,IAoCf,eAAemB,EACpBhB,CAAY,CACZI,CAAiB,CACjBa,EAAO,CAAC,cArBFhB,EACAO,EACAE,EAqBAQ,GAzBWlB,EAyBQA,EAxBnBM,CADuB,CAyBdD,AAjCRb,CAAkB,AAQMY,CAyBCA,AAjCNA,EAAU,CASvBD,CAT2BR,IAQQ,AAEnCG,EAAUS,GAAG,CAACP,IAAU,CADRI,QAGdO,OAAOC,QAAQ,CAACJ,EADhB,CAAA,EAAA,EAAA,aAAA,AAAa,EAACP,GAAMQ,kBAAkB,EACZI,KAAKC,GAAG,CAAC,EAAGN,EAAS,KAAO,IAE9D,CACLf,SAAUoB,KAAKE,GAAG,CAACT,EAAKb,QAAQ,CAAGiB,EAAwB,IAAhBJ,EAAKb,QAAQ,EACxDC,gBAAiBmB,KAAKE,GAAG,CACvBT,EAAKZ,eAAe,CAAGgB,EACA,AAAvBJ,MAAKZ,eAAe,CAExB,GAcMyB,EAAM,CAAA,EAAGnB,EAAM,CAAC,EAAEI,EAAAA,CAAW,CAC7BgB,EAAQC,KAAKC,GAAG,GAEhBC,EAAQ3B,EAAQW,GAAG,CAACY,IAAQ,CAAEK,OAAQN,EAAOzB,QAAQ,CAAEgC,UAAWL,CAAM,EACxEM,EAAiB,CAACN,EAAQG,EAAME,SAAAA,AAAS,EAAI,IAC7CD,EAASX,KAAKE,GAAG,CACrBG,EAAOzB,QAAQ,CACf8B,EAAMC,MAAM,CAAGE,EAAiBR,EAAOxB,eAAe,EAGlDiC,EAAUH,GAAUP,EACpBW,EAAYD,EAAUH,EAASP,EAAOO,EAC5C5B,EAAQM,GAAG,CAACiB,EAAK,CAAEK,OAAQI,EAAWH,UAAWL,CAAM,GAEvD,IAAMS,EAAUF,EAAUT,EAAOzB,QAAQ,CAAGmC,EAAYX,EAAOW,EACzDE,EACJZ,EAAOxB,eAAe,CAAG,EAAImB,KAAKC,GAAG,CAAC,EAAGe,GAAWX,EAAOxB,eAAe,CAAG,EAE/E,MAAO,SACLiC,EACAC,UAAWf,KAAKkB,KAAK,CAACH,GACtBI,QAAS,CAAA,EAAA,EAAA,cAAA,AAAc,EAAC,IAAIX,KAAKD,EAAyB,IAAjBU,GAC3C,CACF,uDCnGA,IAAA,EAAA,EAAA,CAAA,CAAA,OAAA,EAAA,EAAA,CAAA,CAAA,OAGA,EAAA,CAAA,CAAA,OAAA,IAAA,EAAA,EAAA,CAAA,CAAA,OAAA,EAAA,EAAA,CAAA,CAAA,OAEA,EAAA,EAAA,CAAA,CAAA,OA0GO,eAAesD,EACpBpF,CAAY,CACZoD,CAAgB,EAEhB,IAAMf,EAAM,CAAA,EAAA,EAAA,KAAA,AAAK,IACdC,MAAM,CAAC,CAAEmB,MAAO,CAAA,EAAA,EAAA,KAAA,AAAK,GAAG,GACxBlB,IAAI,CAAC,EAAA,QAAQ,EACbC,KAAK,CACJ,CAAA,EAAA,EAAA,GAAA,AAAG,EACD,CAAA,EAAA,EAAA,YAAA,AAAY,EAAC,EAAA,QAAQ,CAACxC,KAAK,CAAEA,GAC7B,CAAA,EAAA,EAAA,EAAA,AAAE,EAAC,EAAA,QAAQ,CAACoD,OAAO,CAAEA,GACrB,CAAA,EAAA,EAAA,MAAA,AAAM,EAAC,EAAA,QAAQ,CAACE,UAAU,IAG7B/C,GAAG,GACN,OAAO8B,GAAKoB,OAAS,CACvB"}
./.next/server/chunks/corpus_taskflow_1-_1h_v._.js.map:1:{"version":3,"sources":["../../../../../corpus/taskflow/src/app/api/export/activity/route.ts","../../../../../corpus/taskflow/src/schemas/activity.ts","../../../../../corpus/taskflow/node_modules/.pnpm/next%4016.3.4_%40babel%2Bcore%407.29.7_%40types%2Bnode%4025.9.5_react-dom%4019.2.8_react%4019.2.8__react%4019.2.8/node_modules/next/src/build/templates/app-route.ts"],"sourcesContent":["/**\n * Streams the audit-log CSV; requires `activity:export`.\n *\n * Owner D. `activity:export` sits above `activity:read` in `ROLE_MATRIX` —\n * reading the feed in the UI and walking off with the whole audit trail are\n * different privileges.\n *\n * Must call (do not reimplement): can, isEnabled, toCsv\n */\n\nimport { errorResponse, failure } from \"@/app/api/_lib/responses\";\nimport { getActor } from \"@/lib/actor\";\nimport { csvResponseHeaders, toCsv } from \"@/lib/csv\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { can } from \"@/lib/permissions\";\nimport { exportActivitySchema } from \"@/schemas/activity\";\nimport { listActivity } from \"@/server/services/activity-service\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { getOrganizationSummary } from \"@/server/services/organization-service\";\nimport type { ActivityEvent } from \"@/types/activity\";\n\nexport const dynamic = \"force-dynamic\";\n\nconst EXPORT_PAGE_LIMIT = 100;\n\nconst COLUMNS: readonly string[] = [\n  \"occurredAt\",\n  \"action\",\n  \"actorId\",\n  \"subjectKind\",\n  \"subjectId\",\n  \"projectId\",\n  \"summary\",\n];\n\nexport async function GET(request: Request): Promise<Response> {\n  try {\n    const url = new URL(request.url);\n    const orgSlug = url.searchParams.get(\"orgSlug\");\n    if (orgSlug === null) {\n      return failure(\"validation_failed\", \"orgSlug is required.\");\n    }\n\n    const actor = await getActor(orgSlug);\n    const { organization } = await getOrganizationSummary(actor, actor.orgId);\n\n    if (!can(actor, \"activity:export\", { kind: \"activity\", orgId: actor.orgId })) {\n      return failure(\"forbidden\", \"Exporting the audit log requires an admin.\");\n    }\n\n    if (!isEnabled(\"csv_export\", buildFlagContext(actor, organization))) {\n      return failure(\"forbidden\", \"CSV export is not included in this plan.\");\n    }\n\n    const parsed = exportActivitySchema.safeParse({\n      orgId: actor.orgId,\n      since: url.searchParams.get(\"since\"),\n      until: url.searchParams.get(\"until\"),\n      format: url.searchParams.get(\"format\") ?? \"csv\",\n    });\n    if (!parsed.success) {\n      return failure(\n        \"validation_failed\",\n        \"since and until must be ISO-8601 timestamps.\",\n      );\n    }\n\n    const page = await listActivity(actor, {\n      orgId: parsed.data.orgId,\n      since: parsed.data.since,\n      until: parsed.data.until,\n      limit: EXPORT_PAGE_LIMIT,\n    });\n\n    if (parsed.data.format === \"json\") {\n      return Response.json({ items: page.items, total: page.total });\n    }\n\n    const csv = toCsv(page.items.map(toRow), COLUMNS);\n    return new Response(csv, {\n      headers: csvResponseHeaders(`taskflow-activity-${organization.slug}.csv`),\n    });\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n\nfunction toRow(\n  event: ActivityEvent,\n): Record<string, string | number | boolean | null> {\n  return {\n    occurredAt: event.occurredAt,\n    action: event.action,\n    actorId: event.actorId,\n    subjectKind: event.subjectKind,\n    subjectId: event.subjectId,\n    projectId: event.projectId,\n    summary: event.summary,\n  };\n}\n","import { z } from \"zod\";\nimport {\n  isoTimestampSchema,\n  orgIdSchema,\n  pageRequestSchema,\n  projectIdSchema,\n  userIdSchema,\n} from \"./common\";\n\nexport const activityActionSchema = z.enum([\n  \"organization.updated\",\n  \"project.created\",\n  \"project.updated\",\n  \"project.archived\",\n  \"project.restored\",\n  \"issue.created\",\n  \"issue.updated\",\n  \"issue.status_changed\",\n  \"issue.assigned\",\n  \"issue.archived\",\n  \"issue.restored\",\n  \"comment.created\",\n  \"comment.updated\",\n  \"comment.deleted\",\n  \"member.invited\",\n  \"member.joined\",\n  \"member.role_changed\",\n  \"member.removed\",\n  \"billing.plan_changed\",\n  \"flag.toggled\",\n]);\n\nexport const activitySubjectKindSchema = z.enum([\n  \"organization\",\n  \"project\",\n  \"issue\",\n  \"comment\",\n  \"member\",\n  \"subscription\",\n  \"feature_flag\",\n]);\n\nexport const activityFilterSchema = z\n  .object({\n    orgId: orgIdSchema,\n    action: z.array(activityActionSchema).optional(),\n    actorId: userIdSchema.optional(),\n    projectId: projectIdSchema.optional(),\n    subjectKind: activitySubjectKindSchema.optional(),\n    since: isoTimestampSchema.optional(),\n    until: isoTimestampSchema.optional(),\n  })\n  .extend(pageRequestSchema.shape);\n\nexport const exportActivitySchema = z.object({\n  orgId: orgIdSchema,\n  since: isoTimestampSchema,\n  until: isoTimestampSchema,\n  format: z.enum([\"csv\", \"json\"]).default(\"csv\"),\n});\n\nexport type ActivityFilterInput = z.infer<typeof activityFilterSchema>;\nexport type ExportActivityInput = z.infer<typeof exportActivitySchema>;\n","import {\n  AppRouteRouteModule,\n  type AppRouteRouteHandlerContext,\n  type AppRouteRouteModuleOptions,\n} from '../../server/route-modules/app-route/module.compiled'\nimport { RouteKind } from '../../server/route-kind'\nimport { patchFetch as _patchFetch } from '../../server/lib/patch-fetch'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport {\n  addRequestMeta,\n  getRequestMeta,\n  setRequestMeta,\n  type RequestMeta,\n} from '../../server/request-meta'\nimport {\n  getTracer,\n  type Span,\n  SpanKind,\n  SpanStatusCode,\n} from '../../server/lib/trace/tracer'\nimport { setManifestsSingleton } from '../../server/app-render/manifests-singlet