H,EACpB,YAAY,CACd,GAEIA,GAAcA,GAAc,KAAK,CAGnCwG,EAAYa,SAAS,CAAC,CACpBC,KAAM7K,EAAAA,cAAAA,CAAe8K,KAAK,AAC5B,GAEAf,EAAYgB,YAAY,CAAC,aAAcxH,EAAWyH,QAAQ,KAG5D,IAAMC,EAAqB1F,EAAO2F,qBAAqB,GAEvD,GAAI,CAACD,EACH,OAGF,GACEA,EAAmBT,GAAG,CAAC,EALA,kBAMvBjK,EAAAA,cAAAA,CAAe4K,aAAa,CAC5B,OACAC,QAAQC,IAAI,CACV,CAAC,2BAA2B,EAAEJ,EAAmBT,GAAG,CAClD,kBACA,qEAAqE,CAAC,EAK5E,IAAMc,EAAQL,EAAmBT,GAAG,CAAC,eAAiB/F,EAChD8G,EAAO,CAAA,EAAGjG,EAAO,CAAC,EAAEgG,EAAAA,CAAO,CAEjCvB,EAAYY,aAAa,CAAC,CACxB,aAAcW,EACd,aAAcA,EACd,iBAAkBC,CACpB,GACAxB,EAAYyB,UAAU,CAACD,GAInBvB,GAAcA,IAAeD,IAC/BC,EAAWe,OADiC,KACrB,CAAC,aAAcO,GACtCtB,EAAWwB,UAAU,CAACD,IAE1B,CAAA,EACF,CACF,EAIA,GAAI7F,GAAyBF,EAC3B,MAAMsE,EAAetE,EADkB,KACN2B,OAC5B,CACL,IAAI6C,EAAazE,EAAOE,kBAAkB,EAC1C,OAAMF,EAAOkG,qBAAqB,CAChC/I,EAAI+F,OAAO,CACX,IACElD,EAAOmG,KAAK,CACVnL,EAAAA,cAAAA,CAAe4K,aAAa,CAC5B,CACEQ,SAAU,CAAA,EAAGrG,EAAO,CAAC,EAAErC,EAAAA,CAAS,CAChC9B,KAAMpB,EAAAA,QAAAA,CAAS6L,MAAM,CACrBC,WAAY,CACV,cAAevG,EACf,cAAe5C,EAAIoJ,GAAG,AACxB,CACF,EACA,AAACC,GAASjC,EAAeiC,EAAM/B,SAEnC7C,EACA,CAACzB,EAEL,CACF,mCAhgBA,SAASjG,EACP,MAAA,CAAA,EAAOC,EAAAA,UAAAA,EAAY,kBACjB4C,uBACAC,CACF,EACF","ignoreList":[2]}
./.next/server/chunks/[root-of-the-server]__0e8mv7e._.js.map:1:{"version":3,"sources":["../../../../../corpus/taskflow/src/config/plan-limits.ts","../../../../../corpus/taskflow/src/lib/event-bus.ts","../../../../../corpus/taskflow/src/config/feature-flags.ts","../../../../../corpus/taskflow/src/lib/feature-flags.ts","../../../../../corpus/taskflow/src/types/member.ts","../../../../../corpus/taskflow/src/lib/hash.ts","../../../../../corpus/taskflow/src/lib/id.ts","../../../../../corpus/taskflow/src/server/jobs/queue.ts","../../../../../corpus/taskflow/src/server/repositories/activity-repository.ts","../../../../../corpus/taskflow/src/server/repositories/notification-repository.ts","../../../../../corpus/taskflow/src/server/repositories/notification-preference-repository.ts","../../../../../corpus/taskflow/src/server/repositories/organization-repository.ts","../../../../../corpus/taskflow/src/server/repositories/search-repository.ts","../../../../../corpus/taskflow/src/server/repositories/usage-repository.ts","../../../../../corpus/taskflow/src/server/repositories/webhook-repository.ts","../../../../../corpus/taskflow/src/server/services/event-registry.ts","../../../../../corpus/taskflow/src/server/services/activity-service.ts","../../../../../corpus/taskflow/src/server/services/notification-service.ts","../../../../../corpus/taskflow/src/server/services/_support.ts","../../../../../corpus/taskflow/src/server/services/search-service.ts","../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts","../../../../../corpus/taskflow/src/server/repositories/project-repository.ts","../../../../../corpus/taskflow/src/server/services/usage-service.ts","../../../../../corpus/taskflow/src/server/services/webhook-service.ts"],"sourcesContent":["import type { LimitedResource, PlanId } from \"@/types/billing\";\nimport type { FeatureFlagKey } from \"@/types/feature-flag\";\n\n/**\n * The one place plan quotas are declared.\n *\n * `BillingService`, the invite flow, the project-create action, the webhook\n * settings page, the usage meter component and the seat-limit job all read\n * their numbers from here via `getPlanLimits()`. Adding a field to\n * `PlanLimits` therefore ripples into every one of those call sites — that\n * ripple is intentional and is what keeps the quotas honest.\n */\nexport interface PlanLimits {\n  readonly plan: PlanId;\n  readonly seats: number;\n  readonly projects: number;\n  readonly issuesPerProject: number;\n  readonly storageMb: number;\n  readonly apiRequestsPerHour: number;\n  readonly webhooks: number;\n  readonly retentionDays: number;\n  readonly includedFlags: readonly FeatureFlagKey[];\n  readonly priceCentsPerSeatMonthly: number;\n}\n\n/** `Infinity` is the sanctioned representation of \"no limit\". */\nexport const UNLIMITED = Number.POSITIVE_INFINITY;\n\nexport const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {\n  free: {\n    plan: \"free\",\n    seats: 3,\n    projects: 2,\n    issuesPerProject: 100,\n    storageMb: 100,\n    apiRequestsPerHour: 100,\n    webhooks: 0,\n    retentionDays: 30,\n    includedFlags: [\"command_palette\"],\n    priceCentsPerSeatMonthly: 0,\n  },\n  starter: {\n    plan: \"starter\",\n    seats: 10,\n    projects: 10,\n    issuesPerProject: 1_000,\n    storageMb: 2_000,\n    apiRequestsPerHour: 1_000,\n    webhooks: 2,\n    retentionDays: 90,\n    includedFlags: [\"command_palette\", \"kanban_board\", \"csv_export\"],\n    priceCentsPerSeatMonthly: 900,\n  },\n  growth: {\n    plan: \"growth\",\n    seats: 50,\n    projects: 100,\n    issuesPerProject: 10_000,\n    storageMb: 20_000,\n    apiRequestsPerHour: 10_000,\n    webhooks: 10,\n    retentionDays: 365,\n    includedFlags: [\n      \"command_palette\",\n      \"kanban_board\",\n      \"csv_export\",\n      \"activity_feed\",\n      \"digest_email\",\n      \"webhooks\",\n      \"issue_templates\",\n    ],\n    priceCentsPerSeatMonthly: 1_900,\n  },\n  enterprise: {\n    plan: \"enterprise\",\n    seats: UNLIMITED,\n    projects: UNLIMITED,\n    issuesPerProject: UNLIMITED,\n    storageMb: 500_000,\n    apiRequestsPerHour: 100_000,\n    webhooks: UNLIMITED,\n    retentionDays: 2_555,\n    includedFlags: [\n      \"command_palette\",\n      \"kanban_board\",\n      \"csv_export\",\n      \"activity_feed\",\n      \"digest_email\",\n      \"webhooks\",\n      \"issue_templates\",\n      \"advanced_search\",\n      \"public_projects\",\n      \"ai_issue_summary\",\n    ],\n    priceCentsPerSeatMonthly: 3_900,\n  },\n};\n\n/** Plans ordered cheapest → richest; used for \"at least this plan\" checks. */\nexport const PLAN_ORDER: readonly PlanId[] = [\n  \"free\",\n  \"starter\",\n  \"growth\",\n  \"enterprise\",\n];\n\nexport function getPlanLimits(plan: PlanId): PlanLimits {\n  return PLAN_LIMITS[plan];\n}\n\n/** Reads one numeric quota without the caller destructuring `PlanLimits`. */\nexport function getLimit(plan: PlanId, resource: LimitedResource): number {\n  return getPlanLimits(plan)[resource];\n}\n\n/** True when `plan` is at least as rich as `minPlan`. */\nexport function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {\n  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);\n}\n\n/** True when consuming `requested` more units would breach the quota. */\nexport function wouldExceedLimit(\n  plan: PlanId,\n  resource: LimitedResource,\n  used: number,\n  requested = 1,\n): boolean {\n  return used + requested > getLimit(plan, resource);\n}\n","import type {\n  EventHandler,\n  TaskflowEventMap,\n  TaskflowEventPayload,\n  TaskflowEventType,\n  Unsubscribe,\n} from \"@/types/event\";\n\n/**\n * In-process, typed publish/subscribe bus.\n *\n * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the\n * search indexer and the webhook dispatcher decoupled: writers `emit()`, and\n * every reactive concern `subscribe()`s at module init (see\n * `src/server/services/event-registry.ts`). Handlers are isolated — one\n * throwing handler never fails the emit or the sibling handlers.\n */\n\ntype HandlerSet = Set<EventHandler<TaskflowEventType>>;\n\nconst handlers = new Map<TaskflowEventType, HandlerSet>();\n\nconst errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();\n\n/** Registers a handler for one event type. Call the return value to detach. */\nexport function subscribe<K extends TaskflowEventType>(\n  type: K,\n  handler: EventHandler<K>,\n): Unsubscribe {\n  const set = handlers.get(type) ?? new Set();\n  set.add(handler as EventHandler<TaskflowEventType>);\n  handlers.set(type, set);\n  return () => {\n    set.delete(handler as EventHandler<TaskflowEventType>);\n  };\n}\n\n/** Registers a handler that detaches itself after the first delivery. */\nexport function subscribeOnce<K extends TaskflowEventType>(\n  type: K,\n  handler: EventHandler<K>,\n): Unsubscribe {\n  const off = subscribe(type, (payload) => {\n    off();\n    return handler(payload);\n  });\n  return off;\n}\n\n/**\n * Publishes an event to every subscriber. Resolves once all handlers settle;\n * rejected handlers are reported to the error sinks, never rethrown.\n */\nexport async function emit<K extends TaskflowEventType>(\n  type: K,\n  payload: TaskflowEventPayload<K>,\n): Promise<void> {\n  const set = handlers.get(type);\n  if (!set || set.size === 0) return;\n\n  const results = await Promise.allSettled(\n    [...set].map(async (handler) => {\n      await (handler as EventHandler<K>)(payload);\n    }),\n  );\n\n  for (const result of results) {\n    if (result.status === \"rejected\") {\n      reportHandlerError(type, result.reason);\n    }\n  }\n}\n\n/** Fire-and-forget variant for call sites that must not await delivery. */\nexport function emitAndForget<K extends TaskflowEventType>(\n  type: K,\n  payload: TaskflowEventPayload<K>,\n): void {\n  void emit(type, payload).catch((error: unknown) => {\n    reportHandlerError(type, error);\n  });\n}\n\nexport function onHandlerError(\n  sink: (type: TaskflowEventType, error: unknown) => void,\n): Unsubscribe {\n  errorSinks.add(sink);\n  return () => {\n    errorSinks.delete(sink);\n  };\n}\n\nfunction reportHandlerError(type: TaskflowEventType, error: unknown): void {\n  for (const sink of errorSinks) {\n    try {\n      sink(type, error);\n    } catch {\n      // A failing error sink must never escalate.\n    }\n  }\n}\n\n/** Number of live subscribers for an event; used by tests and diagnostics. */\nexport function subscriberCount(type: TaskflowEventType): number {\n  return handlers.get(type)?.size ?? 0;\n}\n\n/** Detaches every handler. Test-only — never call from application code. */\nexport function resetEventBus(): void {\n  handlers.clear();\n  errorSinks.clear();\n}\n\nexport type { TaskflowEventMap, TaskflowEventType, Unsubscribe };\n","import type {\n  FeatureFlagDefinition,\n  FeatureFlagKey,\n} from \"@/types/feature-flag\";\n\n/**\n * Declarative registry of every feature flag. `isEnabled()` in\n * `src/lib/feature-flags.ts` is the only reader — UI and server code go\n * through that function, never through this table directly.\n */\nexport const FEATURE_FLAG_DEFINITIONS: Readonly<\n  Record<FeatureFlagKey, FeatureFlagDefinition>\n> = {\n  kanban_board: {\n    key: \"kanban_board\",\n    label: \"Kanban board\",\n    description: \"Drag-and-drop board view for a project's issues.\",\n    strategy: { kind: \"plan\", minPlan: \"starter\" },\n    overridable: true,\n  },\n  ai_issue_summary: {\n    key: \"ai_issue_summary\",\n    label: \"AI issue summary\",\n    description: \"Generates a short summary of a long issue thread.\",\n    strategy: { kind: \"percentage\", percent: 25 },\n    overridable: true,\n  },\n  command_palette: {\n    key: \"command_palette\",\n    label: \"Command palette\",\n    description: \"Ctrl+K quick navigation and actions.\",\n    strategy: { kind: \"on\" },\n    overridable: false,\n  },\n  activity_feed: {\n    key: \"activity_feed\",\n    label: \"Activity feed\",\n    description: \"Organization-wide audit trail view.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: true,\n  },\n  public_projects: {\n    key: \"public_projects\",\n    label: \"Public projects\",\n    description: \"Share a read-only project page outside the organization.\",\n    strategy: { kind: \"plan\", minPlan: \"enterprise\" },\n    overridable: true,\n  },\n  webhooks: {\n    key: \"webhooks\",\n    label: \"Outgoing webhooks\",\n    description: \"Deliver domain events to an external HTTP endpoint.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: false,\n  },\n  csv_export: {\n    key: \"csv_export\",\n    label: \"CSV export\",\n    description: \"Export issues and the audit log as CSV.\",\n    strategy: { kind: \"plan\", minPlan: \"starter\" },\n    overridable: true,\n  },\n  digest_email: {\n    key: \"digest_email\",\n    label: \"Daily digest email\",\n    description: \"Batches notifications into one daily email.\",\n    strategy: { kind: \"plan\", minPlan: \"growth\" },\n    overridable: true,\n  },\n  issue_templates: {\n    key: \"issue_templates\",\n    label: \"Issue templates\",\n    description: \"Prefilled issue bodies per project.\",\n    strategy: { kind: \"role\", minRole: \"admin\" },\n    overridable: true,\n  },\n  advanced_search: {\n    key: \"advanced_search\",\n    label: \"Advanced search\",\n    description: \"Field-scoped query syntax across issues and comments.\",\n    strategy: { kind: \"plan\", minPlan: \"enterprise\" },\n    overridable: true,\n  },\n};\n\nexport const FEATURE_FLAG_KEYS = Object.keys(\n  FEATURE_FLAG_DEFINITIONS,\n) as readonly FeatureFlagKey[];\n\nexport function getFlagDefinition(key: FeatureFlagKey): FeatureFlagDefinition {\n  return FEATURE_FLAG_DEFINITIONS[key];\n}\n\nexport function isFeatureFlagKey(value: string): value is FeatureFlagKey {\n  return Object.prototype.hasOwnProperty.call(FEATURE_FLAG_DEFINITIONS, value);\n}\n","import {\n  FEATURE_FLAG_DEFINITIONS,\n  FEATURE_FLAG_KEYS,\n} from \"@/config/feature-flags\";\nimport { planAtLeast } from \"@/config/plan-limits\";\nimport { ROLE_RANK } from \"@/types/member\";\nimport type {\n  FeatureFlagKey,\n  FeatureFlagSnapshot,\n  FlagContext,\n} from \"@/types/feature-flag\";\n\n/**\n * Feature-flag evaluation, shared verbatim by server and client.\n *\n * Server code builds a `FlagContext` from the session and calls `isEnabled()`\n * directly; the dashboard layout serialises `snapshotFlags()` into the client\n * provider so `useFeatureFlag()` answers the same way without a round trip.\n * Both sides must agree — never re-implement a strategy at a call site.\n */\nexport function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {\n  const definition = FEATURE_FLAG_DEFINITIONS[flag];\n  if (!definition) return false;\n\n  if (definition.overridable && ctx.overrides?.includes(flag)) {\n    return true;\n  }\n\n  const strategy = definition.strategy;\n  switch (strategy.kind) {\n    case \"off\":\n      return false;\n    case \"on\":\n      return true;\n    case \"plan\":\n      return planAtLeast(ctx.plan, strategy.minPlan);\n    case \"role\":\n      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];\n    case \"percentage\":\n      return bucketOf(flag, ctx) < strategy.percent;\n    default:\n      return false;\n  }\n}\n\n/** Evaluates every flag at once, for handoff to the client provider. */\nexport function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {\n  const snapshot = {} as Record<FeatureFlagKey, boolean>;\n  for (const key of FEATURE_FLAG_KEYS) {\n    snapshot[key] = isEnabled(key, ctx);\n  }\n  return snapshot;\n}\n\n/** Throwing guard for server actions gated behind a flag. */\nexport class FeatureDisabledError extends Error {\n  readonly code = \"forbidden\" as const;\n\n  constructor(readonly flag: FeatureFlagKey) {\n    super(`Feature \"${flag}\" is not enabled for this organization.`);\n    this.name = \"FeatureDisabledError\";\n  }\n}\n\nexport function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {\n  if (!isEnabled(flag, ctx)) {\n    throw new FeatureDisabledError(flag);\n  }\n}\n\n/**\n * Deterministic 0–99 bucket for percentage rollouts. Stable per\n * (flag, org, user) so a viewer never sees the feature flicker.\n */\nfunction bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {\n  const seed = `${flag}:${ctx.orgId ?? \"-\"}:${ctx.userId ?? \"-\"}`;\n  let hash = 2_166_136_261;\n  for (let i = 0; i < seed.length; i += 1) {\n    hash ^= seed.charCodeAt(i);\n    hash = Math.imul(hash, 16_777_619);\n  }\n  return Math.abs(hash) % 100;\n}\n","import type {\n  IsoTimestamp,\n  MemberId,\n  OrgId,\n  SoftDeletable,\n  TenantScoped,\n  Timestamps,\n  UserId,\n  InvitationId,\n} from \"./common\";\n\n/**\n * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`\n * below is the single source of truth for \"at least this role\" comparisons —\n * never compare role strings directly.\n */\nexport type Role = \"owner\" | \"admin\" | \"member\" | \"viewer\";\n\nexport const ROLES: readonly Role[] = [\"owner\", \"admin\", \"member\", \"viewer\"];\n\nexport const ROLE_RANK: Readonly<Record<Role, number>> = {\n  owner: 4,\n  admin: 3,\n  member: 2,\n  viewer: 1,\n};\n\nexport type MemberStatus = \"active\" | \"invited\" | \"suspended\";\n\nexport interface User extends Timestamps {\n  readonly id: UserId;\n  readonly email: string;\n  readonly name: string;\n  readonly avatarUrl: string | null;\n  readonly timezone: string;\n  readonly emailVerifiedAt: IsoTimestamp | null;\n}\n\nexport interface Member extends Timestamps, TenantScoped, SoftDeletable {\n  readonly id: MemberId;\n  readonly userId: UserId;\n  readonly role: Role;\n  readonly status: MemberStatus;\n  readonly invitedBy: UserId | null;\n  readonly joinedAt: IsoTimestamp | null;\n  readonly lastSeenAt: IsoTimestamp | null;\n}\n\n/** A member joined with the user record it points at, for list UIs. */\nexport interface MemberWithUser extends Member {\n  readonly user: User;\n}\n\nexport interface Invitation extends Timestamps, TenantScoped {\n  readonly id: InvitationId;\n  readonly email: string;\n  readonly role: Role;\n  readonly invitedBy: UserId;\n  readonly token: string;\n  readonly expiresAt: IsoTimestamp;\n  readonly acceptedAt: IsoTimestamp | null;\n  readonly revokedAt: IsoTimestamp | null;\n}\n\n/**\n * The authenticated principal for one request, always resolved for exactly one\n * organization. Everything that authorizes a mutation takes an `Actor` — see\n * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in\n * `src/lib/tenant.ts`.\n */\nexport interface Actor {\n  readonly userId: UserId;\n  readonly orgId: OrgId;\n  readonly role: Role;\n  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */\n  readonly isPlatformStaff?: boolean;\n}\n\nexport interface SessionPrincipal {\n  readonly userId: UserId;\n  readonly email: string;\n  readonly activeOrgId: OrgId | null;\n  readonly expiresAt: IsoTimestamp;\n}\n\n/** True when `role` is at least as privileged as `atLeast`. */\nexport function hasRoleAtLeast(role: Role, atLeast: Role): boolean {\n  return ROLE_RANK[role] >= ROLE_RANK[atLeast];\n}\n","/**\n * Password and token hashing built on `node:crypto` scrypt. No external\n * dependency — the corpus builds offline, and scrypt is the strongest KDF the\n * platform ships without one.\n *\n * Server-only: never import this from a client component.\n */\nimport {\n  createHash,\n  randomBytes,\n  scrypt,\n  timingSafeEqual,\n} from \"node:crypto\";\n\nconst KEY_LENGTH = 64;\nconst SALT_BYTES = 16;\nconst PREFIX = \"scrypt\";\n\nfunction deriveKey(password: string, salt: Buffer): Promise<Buffer> {\n  return new Promise((resolve, reject) => {\n    scrypt(password.normalize(\"NFKC\"), salt, KEY_LENGTH, (error, key) => {\n      if (error) reject(error);\n      else resolve(key);\n    });\n  });\n}\n\n/** Returns `scrypt:<saltHex>:<keyHex>` — self-describing, so the verifier\n *  can change parameters later without a migration. */\nexport async function hashPassword(password: string): Promise<string> {\n  const salt = randomBytes(SALT_BYTES);\n  const key = await deriveKey(password, salt);\n  return `${PREFIX}:${salt.toString(\"hex\")}:${key.toString(\"hex\")}`;\n}\n\n/** Constant-time comparison; a malformed stored hash simply fails to verify. */\nexport async function verifyPassword(\n  password: string,\n  hash: string,\n): Promise<boolean> {\n  const [scheme, saltHex, keyHex] = hash.split(\":\");\n  if (scheme !== PREFIX || !saltHex || !keyHex) return false;\n\n  const expected = Buffer.from(keyHex, \"hex\");\n  if (expected.length !== KEY_LENGTH) return false;\n\n  const actual = await deriveKey(password, Buffer.from(saltHex, \"hex\"));\n  return timingSafeEqual(actual, expected);\n}\n\n/** One-way digest for invitation and session tokens, which are high-entropy\n *  already and so need no salt or work factor. */\nexport function hashToken(token: string): string {\n  return createHash(\"sha256\").update(token).digest(\"hex\");\n}\n\n/** URL-safe random token; the default width matches the session schema's\n *  32-character minimum. */\nexport function randomToken(bytes = 32): string {\n  return randomBytes(bytes).toString(\"base64url\");\n}\n","/**\n * ULID generation and validation. Every branded id in the app is produced\n * here, so ids sort lexicographically by creation time and the repositories\n * can use them as pagination cursors without a separate sort column.\n */\n/** Crockford base32, minus I, L, O and U. */\nconst ALPHABET = \"0123456789ABCDEFGHJKMNPQRSTVWXYZ\";\nconst TIME_LENGTH = 10;\nconst RANDOM_LENGTH = 16;\n\nconst ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;\n\nfunction encodeTime(time: number): string {\n  let remaining = time;\n  let out = \"\";\n  for (let i = 0; i < TIME_LENGTH; i += 1) {\n    const mod = remaining % 32;\n    out = ALPHABET[mod] + out;\n    remaining = (remaining - mod) / 32;\n  }\n  return out;\n}\n\nfunction encodeRandom(next: () => number): string {\n  let out = \"\";\n  for (let i = 0; i < RANDOM_LENGTH; i += 1) {\n    out += ALPHABET[next() % 32];\n  }\n  return out;\n}\n\n/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same\n *  implementation runs on the server, in the browser and on the edge. */\nexport function newId(): string {\n  const bytes = new Uint8Array(RANDOM_LENGTH);\n  globalThis.crypto.getRandomValues(bytes);\n  let cursor = 0;\n  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);\n}\n\nexport function isUlid(value: string): boolean {\n  return ULID_PATTERN.test(value);\n}\n\n/**\n * A deterministic id generator for tests and the seed script: same seed,\n * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so\n * fixtures are byte-stable across runs.\n */\nexport function idFactory(seed: number): () => string {\n  let state = (seed | 0) || 0x2545_f491;\n  let counter = 0;\n\n  const next = (): number => {\n    state ^= state << 13;\n    state ^= state >>> 17;\n    state ^= state << 5;\n    return Math.abs(state);\n  };\n\n  return () => {\n    counter += 1;\n    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.\n    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);\n  };\n}\n","/**\n * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.\n */\nimport { createLogger } from \"@/lib/logger\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { IsoTimestamp } from \"@/types/common\";\n\nexport type QueuedJob = {\n  id: string;\n  kind: JobKind;\n  runAt: IsoTimestamp;\n  attempts: number;\n  payload: Readonly<Record<string, unknown>>;\n};\n\nexport type JobKind =\n  | \"digest-email\"\n  | \"overdue-issues\"\n  | \"webhook-delivery\"\n  | \"usage-rollup\"\n  | \"search-reindex\"\n  | \"cleanup-archived\"\n  | \"trial-expiry\";\n\n/** Attempts after which a job is dropped rather than retried again. */\nconst MAX_ATTEMPTS = 5;\n\n/** How many jobs `drain()` takes in one pass when no limit is given. */\nconst DEFAULT_DRAIN = 25;\n\nconst logger = createLogger(\"job-queue\");\n\n/**\n * The queue lives in module scope: Taskflow runs one server process and the\n * scheduler is started from `instrumentation.ts`, so there is no second\n * consumer to coordinate with. Swapping this for a real broker means\n * reimplementing these four functions and nothing else.\n */\nconst pending: QueuedJob[] = [];\n\n/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */\nexport function enqueue(job: QueuedJob): void {\n  if (pending.some((queued) => queued.id === job.id)) return;\n  pending.push(job);\n}\n\n/**\n * Runs everything that is due, oldest first. A handler that throws is put back\n * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line\n * — an infinitely retrying job is worse than a lost one.\n */\nexport async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {\n  const now = new Date().toISOString();\n  const due = pending\n    .filter((job) => job.runAt <= now)\n    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))\n    .slice(0, Math.max(0, limit));\n\n  let completed = 0;\n\n  for (const job of due) {\n    remove(job.id);\n\n    try {\n      await runHandler(job);\n      completed += 1;\n    } catch (error) {\n      const attempts = job.attempts + 1;\n\n      if (attempts >= MAX_ATTEMPTS) {\n        logger.error(\"job dropped after max attempts\", {\n          id: job.id,\n          kind: job.kind,\n          attempts,\n        });\n        continue;\n      }\n\n      pending.push({\n        ...job,\n        attempts,\n        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),\n      });\n\n      logger.warn(\"job retry scheduled\", {\n        id: job.id,\n        kind: job.kind,\n        attempts,\n        reason: error instanceof Error ? error.message : String(error),\n      });\n    }\n  }\n\n  return completed;\n}\n\nexport function pendingCount(): number {\n  return pending.length;\n}\n\n/** Test hook: empties the queue. Never call this from application code. */\nexport function resetQueue(): void {\n  pending.length = 0;\n}\n\n/** 1s, 2s, 4s, 8s … capped at one minute. */\nfunction backoffMs(attempts: number): number {\n  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);\n}\n\nfunction remove(id: string): void {\n  const at = pending.findIndex((job) => job.id === id);\n  if (at >= 0) pending.splice(at, 1);\n}\n\n/**\n * Dispatches one queued job to its runner. The imports are dynamic so the\n * queue module stays free of a cycle: every job module imports this one to\n * enqueue follow-up work.\n */\nasync function runHandler(job: QueuedJob): Promise<void> {\n  const now = new Date();\n\n  switch (job.kind) {\n    case \"digest-email\": {\n      const { runDigestEmailJob } = await import(\"./digest-email-job\");\n      await runDigestEmailJob(now);\n      return;\n    }\n    case \"overdue-issues\": {\n      const { runOverdueIssueJob } = await import(\"./overdue-issue-job\");\n      await runOverdueIssueJob(now);\n      return;\n    }\n    case \"webhook-delivery\": {\n      const { runWebhookDeliveryJob } = await import(\"./webhook-delivery-job\");\n      await runWebhookDeliveryJob(now);\n      return;\n    }\n    case \"usage-rollup\": {\n      const { runUsageRollupJob } = await import(\"./usage-rollup-job\");\n      await runUsageRollupJob(now);\n      return;\n    }\n    case \"search-reindex\": {\n      const { runSearchReindexJob } = await import(\"./search-reindex-job\");\n      const orgId = job.payload.orgId;\n      if (typeof orgId !== \"string\") return;\n      await runSearchReindexJob(orgId as Parameters<typeof runSearchReindexJob>[0]);\n      return;\n    }\n    case \"cleanup-archived\": {\n      const { runCleanupArchivedJob } = await import(\"./cleanup-archived-job\");\n      await runCleanupArchivedJob(now);\n      return;\n    }\n    case \"trial-expiry\": {\n      const { runTrialExpiryJob } = await import(\"./trial-expiry-job\");\n      await runTrialExpiryJob(now);\n      return;\n    }\n  }\n}\n","/**\n * Append-only audit log. Never updated, never deleted before the plan's retention window.\n */\nimport { and, count, desc, eq, gte, inArray, lt, lte } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { activityEvents, getDb } from \"@/server/db\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toActivityEvent } from \"./_mappers\";\nimport type { ActivityFilterInput } from \"@/schemas/activity\";\nimport type { ActivityEvent, ActivitySubjectKind } from \"@/types/activity\";\nimport type { IsoTimestamp, OrgId, Page } from \"@/types/common\";\n\nexport async function insertActivity(\n  event: Omit<ActivityEvent, \"id\">,\n): Promise<ActivityEvent> {\n  const row = getDb()\n    .insert(activityEvents)\n    .values({\n      id: newId(),\n      orgId: event.orgId,\n      action: event.action,\n      actorId: event.actorId,\n      subjectKind: event.subjectKind,\n      subjectId: event.subjectId,\n      projectId: event.projectId,\n      summary: event.summary,\n      metadata: JSON.stringify(event.metadata),\n      occurredAt: event.occurredAt,\n    })\n    .returning()\n    .get();\n\n  return toActivityEvent(row);\n}\n\nexport async function listActivity(\n  input: ActivityFilterInput,\n): Promise<Page<ActivityEvent>> {\n  const db = getDb();\n  const sort = {\n    sortColumn: activityEvents.occurredAt,\n    idColumn: activityEvents.id,\n  };\n\n  const filters = compact(\n    orgPredicate(activityEvents.orgId, input.orgId),\n    input.action === undefined || input.action.length === 0\n      ? undefined\n      : inArray(activityEvents.action, [...input.action]),\n    input.actorId === undefined\n      ? undefined\n      : eq(activityEvents.actorId, input.actorId),\n    input.projectId === undefined\n      ? undefined\n      : eq(activityEvents.projectId, input.projectId),\n    input.subjectKind === undefined\n      ? undefined\n      : eq(activityEvents.subjectKind, input.subjectKind),\n    input.since === undefined\n      ? undefined\n      : gte(activityEvents.occurredAt, input.since),\n    input.until === undefined\n      ? undefined\n      : lte(activityEvents.occurredAt, input.until),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(activityEvents)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(activityEvents)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    toActivityEvent,\n    (row) => ({ id: row.id, sortValue: row.occurredAt }),\n  );\n}\n\n/** The \"history\" tab of one issue, project or member. */\nexport async function listActivityForSubject(\n  orgId: OrgId,\n  subjectKind: ActivitySubjectKind,\n  subjectId: string,\n): Promise<readonly ActivityEvent[]> {\n  const rows = getDb()\n    .select()\n    .from(activityEvents)\n    .where(\n      and(\n        orgPredicate(activityEvents.orgId, orgId),\n        eq(activityEvents.subjectKind, subjectKind),\n        eq(activityEvents.subjectId, subjectId),\n      ),\n    )\n    .orderBy(desc(activityEvents.occurredAt))\n    .all();\n\n  return rows.map(toActivityEvent);\n}\n\n/**\n * The only sanctioned deletion path: the retention sweep. `before` comes from\n * the plan's `retentionDays`, never from a user-supplied date.\n */\nexport async function purgeActivityBefore(\n  orgId: OrgId,\n  before: IsoTimestamp,\n): Promise<number> {\n  const rows = getDb()\n    .delete(activityEvents)\n    .where(\n      and(\n        orgPredicate(activityEvents.orgId, orgId),\n        lt(activityEvents.occurredAt, before),\n      ),\n    )\n    .returning({ id: activityEvents.id })\n    .all();\n\n  return rows.length;\n}\n","/**\n * In-app notification rows and unread counters.\n */\nimport { and, count, desc, eq, gte, inArray, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, notifications } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toNotification } from \"./_mappers\";\nimport type { ListNotificationsInput } from \"@/schemas/notification\";\nimport type {\n  IsoTimestamp,\n  NotificationId,\n  OrgId,\n  Page,\n  UserId,\n} from \"@/types/common\";\nimport type { Notification } from \"@/types/notification\";\n\ntype NewNotification = Omit<\n  Notification,\n  \"id\" | \"createdAt\" | \"updatedAt\" | \"readAt\"\n>;\n\nexport async function listNotifications(\n  input: ListNotificationsInput,\n): Promise<Page<Notification>> {\n  const db = getDb();\n  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };\n\n  const filters = compact(\n    orgPredicate(notifications.orgId, input.orgId),\n    eq(notifications.recipientId, input.recipientId),\n    input.unreadOnly ? isNull(notifications.readAt) : undefined,\n    input.kind === undefined || input.kind.length === 0\n      ? undefined\n      : inArray(notifications.kind, [...input.kind]),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(notifications)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(notifications)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(notifications.createdAt), desc(notifications.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({\n    id: row.id,\n    sortValue: row.createdAt,\n  }));\n}\n\n/** Powers the bell badge, so it stays a single indexed count query. */\nexport async function countUnread(\n  orgId: OrgId,\n  recipientId: UserId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(notifications)\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertNotification(\n  orgId: OrgId,\n  input: NewNotification,\n): Promise<Notification> {\n  const inserted = await insertNotifications(orgId, [input]);\n  const row = inserted.at(0);\n  if (!row) throw new Error(\"Notification insert produced no row\");\n  return row;\n}\n\n/** Bulk insert used by the fan-out; one statement per recipient batch. */\nexport async function insertNotifications(\n  orgId: OrgId,\n  inputs: readonly NewNotification[],\n): Promise<readonly Notification[]> {\n  if (inputs.length === 0) return [];\n\n  const stamp = toIsoTimestamp(new Date());\n  const rows = getDb()\n    .insert(notifications)\n    .values(\n      inputs.map((input) => ({\n        id: newId(),\n        orgId,\n        recipientId: input.recipientId,\n        kind: input.kind,\n        title: input.title,\n        body: input.body,\n        href: input.href,\n        actorId: input.actorId,\n        readAt: null,\n        channels: JSON.stringify(input.channels),\n        createdAt: stamp,\n        updatedAt: stamp,\n      })),\n    )\n    .returning()\n    .all();\n\n  return rows.map(toNotification);\n}\n\nexport async function markRead(\n  orgId: OrgId,\n  notificationId: NotificationId,\n  at: IsoTimestamp,\n): Promise<Notification> {\n  const row = getDb()\n    .update(notifications)\n    .set({ readAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.id, notificationId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Notification ${notificationId} not found`);\n  return toNotification(row);\n}\n\nexport async function markAllRead(\n  orgId: OrgId,\n  recipientId: UserId,\n  at: IsoTimestamp,\n): Promise<number> {\n  const rows = getDb()\n    .update(notifications)\n    .set({ readAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n      ),\n    )\n    .returning({ id: notifications.id })\n    .all();\n\n  return rows.length;\n}\n\n/** The digest window query: everything still unread since `since`. */\nexport async function listUnreadSince(\n  orgId: OrgId,\n  recipientId: UserId,\n  since: IsoTimestamp,\n): Promise<readonly Notification[]> {\n  const rows = getDb()\n    .select()\n    .from(notifications)\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n        gte(notifications.createdAt, since),\n      ),\n    )\n    .orderBy(desc(notifications.createdAt))\n    .all();\n\n  return rows.map(toNotification);\n}\n","/**\n * Per-user, per-kind delivery matrix consulted before every fan-out.\n */\nimport { and, eq } from \"drizzle-orm\";\nimport { getDb, notificationPreferences } from \"@/server/db\";\nimport { orgPredicate } from \"./base-repository\";\nimport { brandId, toPreference } from \"./_mappers\";\nimport type { UpdateNotificationPreferenceInput } from \"@/schemas/notification\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type {\n  NotificationKind,\n  NotificationPreference,\n} from \"@/types/notification\";\n\nexport async function listPreferences(\n  orgId: OrgId,\n  userId: UserId,\n): Promise<readonly NotificationPreference[]> {\n  const rows = getDb()\n    .select()\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.userId, userId),\n      ),\n    )\n    .all();\n  return rows.map(toPreference);\n}\n\n/**\n * `null` means \"no explicit row\" — the fan-out then falls back to the default\n * channel set rather than treating the absence as \"everything off\".\n */\nexport async function getPreference(\n  orgId: OrgId,\n  userId: UserId,\n  kind: NotificationKind,\n): Promise<NotificationPreference | null> {\n  const row = getDb()\n    .select()\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.userId, userId),\n        eq(notificationPreferences.kind, kind),\n      ),\n    )\n    .get();\n  return row ? toPreference(row) : null;\n}\n\nexport async function upsertPreference(\n  input: UpdateNotificationPreferenceInput,\n): Promise<NotificationPreference> {\n  const row = getDb()\n    .insert(notificationPreferences)\n    .values({\n      orgId: input.orgId,\n      userId: input.userId,\n      kind: input.kind,\n      inApp: input.inApp,\n      email: input.email,\n      digestOnly: input.digestOnly,\n    })\n    .onConflictDoUpdate({\n      target: [\n        notificationPreferences.orgId,\n        notificationPreferences.userId,\n        notificationPreferences.kind,\n      ],\n      set: {\n        inApp: input.inApp,\n        email: input.email,\n        digestOnly: input.digestOnly,\n      },\n    })\n    .returning()\n    .get();\n\n  return toPreference(row);\n}\n\n/** Distinct users with at least one `digestOnly` preference in this org. */\nexport async function listDigestSubscribers(\n  orgId: OrgId,\n): Promise<readonly UserId[]> {\n  const rows = getDb()\n    .selectDistinct({ userId: notificationPreferences.userId })\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.digestOnly, true),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => brandId<UserId>(row.userId));\n}\n","/**\n * Organization rows plus slug uniqueness lookups.\n *\n * Must call (do not reimplement): archivePatch, uniqueSlug\n */\nimport { and, eq, isNull, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { uniqueSlug } from \"@/lib/slug\";\nimport { archivePatch } from \"@/lib/soft-delete\";\nimport { getDb, members, organizations } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { toOrganization } from \"./_mappers\";\nimport type {\n  CreateOrganizationInput,\n  UpdateOrganizationInput,\n} from \"@/schemas/organization\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { Organization } from \"@/types/organization\";\n\nexport async function findOrgById(orgId: OrgId): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(eq(organizations.id, orgId))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\nexport async function findOrgBySlug(slug: string): Promise<Organization | null> {\n  const row = getDb()\n    .select()\n    .from(organizations)\n    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))\n    .get();\n  return row ? toOrganization(row) : null;\n}\n\n/** Every org the user still holds a live membership in. */\nexport async function listOrgsForUser(\n  userId: UserId,\n): Promise<readonly Organization[]> {\n  const rows = getDb()\n    .select({ org: organizations })\n    .from(members)\n    .innerJoin(organizations, eq(organizations.id, members.orgId))\n    .where(\n      and(\n        eq(members.userId, userId),\n        isNull(members.archivedAt),\n        isNull(organizations.archivedAt),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => toOrganization(row.org));\n}\n\n/**\n * Creates the org row. The slug is de-duplicated here rather than in the\n * service so a race on the unique index still resolves to a usable slug.\n */\nexport async function insertOrg(\n  input: CreateOrganizationInput,\n  ownerId: UserId,\n): Promise<Organization> {\n  const taken = await listTakenOrgSlugs(input.slug);\n  const slug = uniqueSlug(input.slug, taken);\n  const stamp = toIsoTimestamp(new Date());\n\n  const row = getDb()\n    .insert(organizations)\n    .values({\n      id: newId(),\n      name: input.name,\n      slug,\n      ownerId,\n      plan: input.plan,\n      logoUrl: null,\n      trialEndsAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function updateOrg(\n  orgId: OrgId,\n  patch: UpdateOrganizationInput,\n): Promise<Organization> {\n  const current = await findOrgById(orgId);\n  if (!current) throw new Error(`Organization ${orgId} not found`);\n\n  const settings = { ...current.settings, ...(patch.settings ?? {}) };\n\n  const row = getDb()\n    .update(organizations)\n    .set({\n      ...(patch.name === undefined ? {} : { name: patch.name }),\n      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),\n      defaultIssueStatus: settings.defaultIssueStatus,\n      allowPublicProjects: settings.allowPublicProjects,\n      requireTwoFactor: settings.requireTwoFactor,\n      digestHourUtc: settings.digestHourUtc,\n      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  return toOrganization(row);\n}\n\nexport async function archiveOrg(orgId: OrgId): Promise<Organization> {\n  const row = getDb()\n    .update(organizations)\n    .set(archivePatch())\n    .where(eq(organizations.id, orgId))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Organization ${orgId} not found`);\n  return toOrganization(row);\n}\n\n/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */\nexport async function listTakenOrgSlugs(\n  prefix: string,\n): Promise<readonly string[]> {\n  const rows = getDb()\n    .select({ slug: organizations.slug })\n    .from(organizations)\n    .where(like(organizations.slug, `${prefix}%`))\n    .all();\n  return rows.map((row) => row.slug);\n}\n","/**\n * Denormalised search index kept in step by `SearchService`.\n */\nimport { and, count, desc, eq, inArray, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, searchIndex } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport type { SearchQueryInput } from \"@/schemas/search\";\nimport type { SearchIndexRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId, Page, ProjectId } from \"@/types/common\";\n\n/**\n * Upsert by (org, kind, subject) rather than by row id: the indexer is called\n * on every write and must be idempotent.\n */\nexport async function upsertSearchDocument(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n  content: string,\n  projectId: ProjectId | null,\n): Promise<void> {\n  const db = getDb();\n  const indexedAt = toIsoTimestamp(new Date());\n\n  const existing = db\n    .select({ id: searchIndex.id })\n    .from(searchIndex)\n    .where(\n      and(\n        orgPredicate(searchIndex.orgId, orgId),\n        eq(searchIndex.subjectKind, subjectKind),\n        eq(searchIndex.subjectId, subjectId),\n      ),\n    )\n    .get();\n\n  if (existing) {\n    db.update(searchIndex)\n      .set({ content, projectId, indexedAt })\n      .where(eq(searchIndex.id, existing.id))\n      .run();\n    return;\n  }\n\n  db.insert(searchIndex)\n    .values({\n      id: newId(),\n      orgId,\n      subjectKind,\n      subjectId,\n      projectId,\n      content,\n      indexedAt,\n    })\n    .run();\n}\n\nexport async function deleteSearchDocument(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n): Promise<void> {\n  getDb()\n    .delete(searchIndex)\n    .where(\n      and(\n        orgPredicate(searchIndex.orgId, orgId),\n        eq(searchIndex.subjectKind, subjectKind),\n        eq(searchIndex.subjectId, subjectId),\n      ),\n    )\n    .run();\n}\n\n/**\n * Substring match over the denormalised content column. Deliberately simple —\n * the index is a convenience layer, not a search engine, and the tenant filter\n * is what actually matters here.\n */\nexport async function searchDocuments(\n  input: SearchQueryInput,\n): Promise<Page<SearchIndexRow>> {\n  const db = getDb();\n  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };\n\n  const filters = compact(\n    orgPredicate(searchIndex.orgId, input.orgId),\n    like(searchIndex.content, `%${input.q}%`),\n    input.kinds.length === 0\n      ? undefined\n      : inArray(searchIndex.subjectKind, [...input.kinds]),\n    input.projectId === undefined\n      ? undefined\n      : eq(searchIndex.projectId, input.projectId),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(searchIndex)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(searchIndex)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => row,\n    (row) => ({ id: row.id, sortValue: row.indexedAt }),\n  );\n}\n\n/** Drift alarm input: how many documents this org currently has indexed. */\nexport async function countIndexed(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(searchIndex)\n    .where(orgPredicate(searchIndex.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport type SearchSubjectKind = 'issue' | 'comment' | 'project';\n","/**\n * The `organization_usage` counters read by every plan-limit check.\n */\nimport { and, count, eq, isNull, sql } from \"drizzle-orm\";\nimport {\n  attachments,\n  getDb,\n  issues,\n  members,\n  organizationUsage,\n  projects,\n} from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { toUsage } from \"./_mappers\";\nimport { brandId } from \"./_mappers\";\nimport type { OrgId } from \"@/types/common\";\nimport type { OrganizationUsage } from \"@/types/organization\";\n\nconst BYTES_PER_MB = 1024 * 1024;\n\n/**\n * Reads the cached counters, materialising a zeroed row the first time an org\n * is asked about. A limit check must never fail because the rollup has not run.\n */\nexport async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {\n  const row = getDb()\n    .select()\n    .from(organizationUsage)\n    .where(eq(organizationUsage.orgId, orgId))\n    .get();\n\n  if (row) return toUsage(row);\n\n  const created = getDb()\n    .insert(organizationUsage)\n    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })\n    .returning()\n    .get();\n\n  return toUsage(created);\n}\n\n/**\n * Recounts every dimension from the source tables and rewrites the cache.\n * Called by the rollup job and after any bulk change that would drift.\n */\nexport async function recomputeUsage(\n  orgId: OrgId,\n): Promise<OrganizationUsage> {\n  const db = getDb();\n\n  const seats = db\n    .select({ value: count() })\n    .from(members)\n    .where(\n      and(\n        eq(members.orgId, orgId),\n        eq(members.status, \"active\"),\n        isNull(members.archivedAt),\n      ),\n    )\n    .get();\n\n  const projectCount = db\n    .select({ value: count() })\n    .from(projects)\n    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))\n    .get();\n\n  const issueCount = db\n    .select({ value: count() })\n    .from(issues)\n    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))\n    .get();\n\n  const bytes = db\n    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })\n    .from(attachments)\n    .where(eq(attachments.orgId, orgId))\n    .get();\n\n  const next = {\n    orgId,\n    seatsUsed: seats?.value ?? 0,\n    projectsUsed: projectCount?.value ?? 0,\n    issuesUsed: issueCount?.value ?? 0,\n    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),\n    measuredAt: toIsoTimestamp(new Date()),\n  };\n\n  const row = db\n    .insert(organizationUsage)\n    .values(next)\n    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })\n    .returning()\n    .get();\n\n  return toUsage(row);\n}\n\n/**\n * Cheap delta applied on the write path so a quota check right after a create\n * sees the new number without waiting for the rollup.\n */\nexport async function incrementUsage(\n  orgId: OrgId,\n  patch: Partial<\n    Pick<\n      OrganizationUsage,\n      \"seatsUsed\" | \"projectsUsed\" | \"issuesUsed\" | \"storageMbUsed\"\n    >\n  >,\n): Promise<OrganizationUsage> {\n  const current = await getUsage(orgId);\n\n  const row = getDb()\n    .update(organizationUsage)\n    .set({\n      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),\n      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),\n      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),\n      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),\n      measuredAt: toIsoTimestamp(new Date()),\n    })\n    .where(eq(organizationUsage.orgId, orgId))\n    .returning()\n    .get();\n\n  return toUsage(row);\n}\n\n/** The rollup job's work list: the oldest measurements first. */\nexport async function listOrgIdsForRollup(\n  limit: number,\n): Promise<readonly OrgId[]> {\n  const rows = getDb()\n    .select({ orgId: organizationUsage.orgId })\n    .from(organizationUsage)\n    .orderBy(organizationUsage.measuredAt)\n    .limit(Math.max(1, limit))\n    .all();\n\n  return rows.map((row) => brandId<OrgId>(row.orgId));\n}\n","/**\n * Webhook endpoints and their delivery attempts.\n */\nimport { and, asc, count, eq } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, webhookDeliveries, webhookEndpoints } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport type { CreateWebhookInput, UpdateWebhookInput } from \"@/schemas/webhook\";\nimport type {\n  WebhookDeliveryRow,\n  WebhookEndpointRow,\n} from \"@/server/db/schema/webhooks\";\nimport type { IsoTimestamp, OrgId, WebhookId } from \"@/types/common\";\n\nexport async function listEndpoints(\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  return getDb()\n    .select()\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .orderBy(asc(webhookEndpoints.createdAt))\n    .all();\n}\n\nexport async function insertEndpoint(\n  input: CreateWebhookInput,\n  secret: string,\n): Promise<WebhookEndpointRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookEndpoints)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      url: input.url,\n      secret,\n      eventTypes: JSON.stringify(input.eventTypes),\n      enabled: true,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\nexport async function updateEndpoint(\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  const row = getDb()\n    .update(webhookEndpoints)\n    .set({\n      ...(input.url === undefined ? {} : { url: input.url }),\n      ...(input.eventTypes === undefined\n        ? {}\n        : { eventTypes: JSON.stringify(input.eventTypes) }),\n      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, input.orgId),\n        eq(webhookEndpoints.id, input.webhookId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);\n  return row;\n}\n\nexport async function deleteEndpoint(\n  orgId: OrgId,\n  webhookId: WebhookId,\n): Promise<void> {\n  const db = getDb();\n  db.delete(webhookDeliveries)\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.endpointId, webhookId),\n      ),\n    )\n    .run();\n  db.delete(webhookEndpoints)\n    .where(\n      and(\n        orgPredicate(webhookEndpoints.orgId, orgId),\n        eq(webhookEndpoints.id, webhookId),\n      ),\n    )\n    .run();\n}\n\n/** The `webhooks` quota compares against this. */\nexport async function countEndpoints(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(webhookEndpoints)\n    .where(orgPredicate(webhookEndpoints.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function enqueueDelivery(\n  orgId: OrgId,\n  endpointId: string,\n  eventType: string,\n  payload: string,\n): Promise<WebhookDeliveryRow> {\n  const stamp = toIsoTimestamp(new Date());\n  return getDb()\n    .insert(webhookDeliveries)\n    .values({\n      id: newId(),\n      orgId,\n      endpointId,\n      eventType,\n      payload,\n      status: \"pending\",\n      attempts: 0,\n      lastError: null,\n      deliveredAt: null,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n}\n\n/**\n * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is\n * drained by a background worker, not by a request — and the attempt counter\n * is bumped on claim so a crashed worker cannot retry forever.\n */\nexport async function claimPendingDeliveries(\n  limit: number,\n): Promise<readonly WebhookDeliveryRow[]> {\n  const db = getDb();\n  const pending = db\n    .select()\n    .from(webhookDeliveries)\n    .where(eq(webhookDeliveries.status, \"pending\"))\n    .orderBy(asc(webhookDeliveries.createdAt))\n    .limit(Math.max(1, limit))\n    .all();\n\n  return pending.map((row) =>\n    db\n      .update(webhookDeliveries)\n      .set({\n        attempts: row.attempts + 1,\n        updatedAt: toIsoTimestamp(new Date()),\n      })\n      .where(eq(webhookDeliveries.id, row.id))\n      .returning()\n      .get(),\n  );\n}\n\nexport async function markDelivered(\n  orgId: OrgId,\n  deliveryId: string,\n  at: IsoTimestamp,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({ status: \"delivered\", deliveredAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n\nexport async function markDeliveryFailed(\n  orgId: OrgId,\n  deliveryId: string,\n  error: string,\n): Promise<void> {\n  getDb()\n    .update(webhookDeliveries)\n    .set({\n      status: \"failed\",\n      lastError: error.slice(0, 500),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(webhookDeliveries.orgId, orgId),\n        eq(webhookDeliveries.id, deliveryId),\n      ),\n    )\n    .run();\n}\n","/**\n * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.\n *\n * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners\n */\nimport { subscribe } from \"@/lib/event-bus\";\nimport { createLogger } from \"@/lib/logger\";\nimport { enqueue } from \"@/server/jobs/queue\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { registerActivityListeners } from \"./activity-service\";\nimport { registerSearchListeners } from \"./search-service\";\nimport { registerUsageListeners } from \"./usage-service\";\nimport { registerWebhookListeners } from \"./webhook-service\";\nimport type { Unsubscribe } from \"@/types/event\";\n\n/**\n * Importing this module also loads `notification-service` transitively, which\n * attaches the notification fan-out on first import — that hub has no\n * `register*` entry point of its own.\n */\nimport \"./notification-service\";\n\nconst logger = createLogger(\"event-registry\");\n\n/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */\nlet detach: Unsubscribe | null = null;\n\n/**\n * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`\n * runs per server process, but a hot reload in dev can call it again and must\n * not double-deliver every event.\n */\nexport function registerEventHandlers(): void {\n  if (detach !== null) return;\n\n  const offs: Unsubscribe[] = [\n    registerActivityListeners(),\n    registerSearchListeners(),\n    registerUsageListeners(),\n    registerWebhookListeners(),\n    registerDigestBridge(),\n  ];\n\n  detach = () => {\n    for (const off of offs) off();\n  };\n\n  logger.info(\"event handlers registered\", { groups: offs.length });\n}\n\nexport function unregisterEventHandlers(): void {\n  detach?.();\n  detach = null;\n}\n\n/**\n * The one piece of wiring that belongs to no single service: turning a\n * `digest.due` event into a queued job. Keeping it here rather than inside\n * `DigestService` stops the service layer from depending on the job layer.\n */\nfunction registerDigestBridge(): Unsubscribe {\n  return subscribe(\"digest.due\", (payload) => {\n    enqueue({\n      id: `digest:${payload.orgId}:${payload.recipientId}`,\n      kind: \"digest-email\",\n      runAt: toIsoTimestamp(new Date()),\n      attempts: 0,\n      payload: {\n        orgId: payload.orgId,\n        recipientId: payload.recipientId,\n        windowStart: payload.windowStart,\n      },\n    });\n  });\n}\n","/**\n * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv\n */\nimport { toCsv } from \"@/lib/csv\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as activityRepo from \"@/server/repositories/activity-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { activityResource } from \"./_support\";\nimport type { ActivityFilterInput, ExportActivityInput } from \"@/schemas/activity\";\nimport type {\n  ActivityAction,\n  ActivityEvent,\n  ActivityGroup,\n  ActivitySubjectKind,\n} from \"@/types/activity\";\nimport type { OrgId, Page, ProjectId, UserId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { Actor } from \"@/types/member\";\n\nexport type ActivityRecordInput = {\n  actorId: UserId | null;\n  subjectKind: ActivitySubjectKind;\n  subjectId: string;\n  projectId: ProjectId | null;\n  summary: string;\n  metadata?: Readonly<Record<string, string | number | boolean | null>>;\n};\n\n/** Columns of the audit-log CSV export, in the order the file lists them. */\nconst EXPORT_COLUMNS = [\n  \"occurredAt\",\n  \"action\",\n  \"actorId\",\n  \"subjectKind\",\n  \"subjectId\",\n  \"summary\",\n] as const;\n\n/**\n * Appends one audit row. Deliberately takes no `Actor`: the writer is usually\n * an event handler running outside a request, and the row's `actorId` comes\n * from the event payload rather than from an authenticated principal.\n */\nexport async function record(\n  orgId: OrgId,\n  action: ActivityAction,\n  input: ActivityRecordInput,\n): Promise<ActivityEvent> {\n  return activityRepo.insertActivity({\n    orgId,\n    action,\n    actorId: input.actorId,\n    subjectKind: input.subjectKind,\n    subjectId: input.subjectId,\n    projectId: input.projectId,\n    summary: input.summary,\n    metadata: input.metadata ?? {},\n    occurredAt: toIsoTimestamp(new Date()),\n  });\n}\n\nexport async function listActivity(\n  actor: Actor,\n  input: ActivityFilterInput,\n): Promise<Page<ActivityEvent>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"activity:read\", activityResource(input.orgId));\n  return activityRepo.listActivity(input);\n}\n\n/** Groups a feed page by calendar day, newest day first. */\nexport function groupByDay(\n  events: readonly ActivityEvent[],\n): readonly ActivityGroup[] {\n  const byDay = new Map<string, ActivityEvent[]>();\n\n  for (const event of events) {\n    const day = event.occurredAt.slice(0, 10);\n    const bucket = byDay.get(day) ?? [];\n    bucket.push(event);\n    byDay.set(day, bucket);\n  }\n\n  return [...byDay.entries()]\n    .sort(([a], [b]) => (a < b ? 1 : -1))\n    .map(([day, dayEvents]) => ({ day, events: dayEvents }));\n}\n\n/**\n * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`\n * for the role, and on the `csv_export` flag for the plan.\n */\nexport async function exportActivity(\n  actor: Actor,\n  input: ExportActivityInput,\n): Promise<string> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"activity:export\", activityResource(input.orgId));\n\n  const org = await orgRepo.findOrgById(input.orgId);\n  const flagEnabled = isEnabled(\"csv_export\", {\n    orgId: input.orgId,\n    userId: actor.userId,\n    plan: org?.plan ?? \"free\",\n    role: actor.role,\n    overrides: org?.settings.enabledFlagOverrides,\n  });\n\n  if (input.format === \"csv\" && !flagEnabled) {\n    throw new Error(\"CSV export is not included in this plan\");\n  }\n\n  const page = await activityRepo.listActivity({\n    orgId: input.orgId,\n    since: input.since,\n    until: input.until,\n    limit: 100,\n    cursor: null,\n  });\n\n  if (input.format === \"json\") {\n    return JSON.stringify(page.items, null, 2);\n  }\n\n  return toCsv(\n    page.items.map((event) => ({\n      occurredAt: event.occurredAt,\n      action: event.action,\n      actorId: event.actorId,\n      subjectKind: event.subjectKind,\n      subjectId: event.subjectId,\n      summary: event.summary,\n    })),\n    [...EXPORT_COLUMNS],\n  );\n}\n\n/**\n * Attaches one handler per audited event type. Called once from\n * `event-registry`; the returned function detaches all of them, which is what\n * the test suite uses to keep the bus clean between cases.\n */\nexport function registerActivityListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"project.created\", (payload) =>\n      record(payload.orgId, \"project.created\", {\n        actorId: payload.actorId,\n        subjectKind: \"project\",\n        subjectId: payload.projectId,\n        projectId: payload.projectId,\n        summary: `Created project ${payload.name}`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"project.archived\", (payload) =>\n      record(payload.orgId, \"project.archived\", {\n        actorId: payload.actorId,\n        subjectKind: \"project\",\n        subjectId: payload.projectId,\n        projectId: payload.projectId,\n        summary: `Archived project with ${payload.issuesArchived} issues`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"issue.created\", (payload) =>\n      record(payload.orgId, \"issue.created\", {\n        actorId: payload.actorId,\n        subjectKind: \"issue\",\n        subjectId: payload.issueId,\n        projectId: payload.projectId,\n        summary: `Created issue \"${payload.title}\"`,\n        metadata: { priority: payload.priority },\n      }).then(() => undefined),\n    ),\n    subscribe(\"issue.status_changed\", (payload) =>\n      record(payload.orgId, \"issue.status_changed\", {\n        actorId: payload.actorId,\n        subjectKind: \"issue\",\n        subjectId: payload.issueId,\n        projectId: payload.projectId,\n        summary: `Status ${payload.from} → ${payload.to}`,\n        metadata: { from: payload.from, to: payload.to },\n      }).then(() => undefined),\n    ),\n    subscribe(\"issue.assigned\", (payload) =>\n      record(payload.orgId, \"issue.assigned\", {\n        actorId: payload.actorId,\n        subjectKind: \"issue\",\n        subjectId: payload.issueId,\n        projectId: payload.projectId,\n        summary: `Assigned to ${payload.assigneeId}`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"comment.created\", (payload) =>\n      record(payload.orgId, \"comment.created\", {\n        actorId: payload.actorId,\n        subjectKind: \"comment\",\n        subjectId: payload.commentId,\n        projectId: null,\n        summary: `Commented on issue ${payload.issueId}`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"member.invited\", (payload) =>\n      record(payload.orgId, \"member.invited\", {\n        actorId: payload.actorId,\n        subjectKind: \"member\",\n        subjectId: payload.email,\n        projectId: null,\n        summary: `Invited ${payload.email} as ${payload.role}`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"member.role_changed\", (payload) =>\n      record(payload.orgId, \"member.role_changed\", {\n        actorId: payload.actorId,\n        subjectKind: \"member\",\n        subjectId: payload.memberId,\n        projectId: null,\n        summary: `Role ${payload.from} → ${payload.to}`,\n      }).then(() => undefined),\n    ),\n    subscribe(\"billing.plan_changed\", (payload) =>\n      record(payload.orgId, \"billing.plan_changed\", {\n        actorId: payload.actorId,\n        subjectKind: \"subscription\",\n        subjectId: payload.orgId,\n        projectId: null,\n        summary: `Plan ${payload.from} → ${payload.to}`,\n      }).then(() => undefined),\n    ),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n","/**\n * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe\n */\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as notificationRepo from \"@/server/repositories/notification-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as preferenceRepo from \"@/server/repositories/notification-preference-repository\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { notificationResource, requireFound } from \"./_support\";\nimport type {\n  ListNotificationsInput,\n  MarkNotificationReadInput,\n  UpdateNotificationPreferenceInput,\n} from \"@/schemas/notification\";\nimport type { OrgId, Page, UserId } from \"@/types/common\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type {\n  Notification,\n  NotificationChannel,\n  NotificationKind,\n  NotificationPreference,\n} from \"@/types/notification\";\n\nexport type NotificationPayload = {\n  title: string;\n  body: string;\n  href: string;\n  actorId: UserId | null;\n};\n\n/** Channels used when a recipient has never touched their preferences. */\nconst DEFAULT_CHANNELS: readonly NotificationChannel[] = [\"in_app\", \"email\"];\n\n/**\n * Writes one notification row per recipient, each with the channel set that\n * recipient's preferences allow. A recipient who has muted every channel is\n * skipped entirely rather than given a row nobody will ever see.\n */\nexport async function notify(\n  orgId: OrgId,\n  kind: NotificationKind,\n  recipients: readonly UserId[],\n  payload: NotificationPayload,\n): Promise<readonly Notification[]> {\n  if (recipients.length === 0) return [];\n\n  const org = await orgRepo.findOrgById(orgId);\n  const flags: FlagContext = {\n    orgId,\n    userId: payload.actorId,\n    plan: org?.plan ?? \"free\",\n    role: null,\n    overrides: org?.settings.enabledFlagOverrides,\n  };\n\n  const rows = [];\n\n  for (const recipientId of new Set(recipients)) {\n    if (recipientId === payload.actorId) continue;\n\n    const preference = await preferenceRepo.getPreference(\n      orgId,\n      recipientId,\n      kind,\n    );\n    const channels = resolveChannels(preference, flags);\n    if (channels.length === 0) continue;\n\n    rows.push({\n      orgId,\n      recipientId,\n      kind,\n      title: payload.title,\n      body: payload.body,\n      href: payload.href,\n      actorId: payload.actorId,\n      channels,\n    });\n  }\n\n  return notificationRepo.insertNotifications(orgId, rows);\n}\n\nexport async function listNotifications(\n  actor: Actor,\n  input: ListNotificationsInput,\n): Promise<Page<Notification>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:read\",\n    notificationResource(input.orgId, input.recipientId),\n  );\n  return notificationRepo.listNotifications(input);\n}\n\nexport async function markRead(\n  actor: Actor,\n  input: MarkNotificationReadInput,\n): Promise<Notification> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(input.orgId, actor.userId),\n  );\n  return notificationRepo.markRead(\n    input.orgId,\n    input.notificationId,\n    toIsoTimestamp(new Date()),\n  );\n}\n\nexport async function markAllRead(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<number> {\n  assertOrgScope(actor, orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(orgId, actor.userId),\n  );\n  return notificationRepo.markAllRead(\n    orgId,\n    actor.userId,\n    toIsoTimestamp(new Date()),\n  );\n}\n\nexport async function updatePreference(\n  actor: Actor,\n  input: UpdateNotificationPreferenceInput,\n): Promise<NotificationPreference> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(input.orgId, input.userId),\n  );\n  return preferenceRepo.upsertPreference(input);\n}\n\n/**\n * Turns a stored preference into the channels one notification will use.\n * `digestOnly` suppresses the immediate email but keeps the in-app row, and\n * the email channel additionally requires the org's `digest_email` plan flag.\n */\nexport function resolveChannels(\n  preference: NotificationPreference | null,\n  flags: FlagContext,\n): readonly NotificationChannel[] {\n  if (preference === null) return DEFAULT_CHANNELS;\n\n  const channels: NotificationChannel[] = [];\n  if (preference.inApp) channels.push(\"in_app\");\n\n  const emailAllowed =\n    preference.email &&\n    (!preference.digestOnly || isEnabled(\"digest_email\", flags));\n\n  if (emailAllowed) channels.push(\"email\");\n  return channels;\n}\n\n/**\n * The bus wiring. Attached at module load rather than from `event-registry`\n * because the fan-out has no other public entry point — importing this module\n * is what makes an org start receiving notifications.\n */\nlet registered = false;\n\nfunction registerFanOut(): void {\n  if (registered) return;\n  registered = true;\n\n  subscribe(\"issue.assigned\", async (payload) => {\n    await notify(payload.orgId, \"issue_assigned\", [payload.assigneeId], {\n      title: \"You were assigned an issue\",\n      body: `Issue ${payload.issueId} is now yours`,\n      href: `/issues/${payload.issueId}`,\n      actorId: payload.actorId,\n    });\n  });\n\n  subscribe(\"issue.overdue\", async (payload) => {\n    if (payload.assigneeId === null) return;\n    await notify(payload.orgId, \"issue_overdue\", [payload.assigneeId], {\n      title: \"An issue is overdue\",\n      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,\n      href: `/issues/${payload.issueId}`,\n      actorId: null,\n    });\n  });\n\n  subscribe(\"comment.created\", async (payload) => {\n    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n    const watchers = issue\n      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]\n      : [];\n\n    await notify(payload.orgId, \"comment_created\", watchers, {\n      title: \"New comment\",\n      body: `A comment was added to issue ${payload.issueId}`,\n      href: `/issues/${payload.issueId}`,\n      actorId: payload.actorId,\n    });\n\n    if (payload.mentionedUserIds.length > 0) {\n      await notify(\n        payload.orgId,\n        \"comment_mention\",\n        payload.mentionedUserIds,\n        {\n          title: \"You were mentioned\",\n          body: `You were mentioned on issue ${payload.issueId}`,\n          href: `/issues/${payload.issueId}`,\n          actorId: payload.actorId,\n        },\n      );\n    }\n  });\n\n  subscribe(\"member.joined\", async (payload) => {\n    const org = requireFound(\n      await orgRepo.findOrgById(payload.orgId),\n      \"Organization\",\n      payload.orgId,\n    );\n    await notify(payload.orgId, \"member_joined\", [org.ownerId], {\n      title: \"A new member joined\",\n      body: `${payload.userId} joined as ${payload.role}`,\n      href: \"/settings/members\",\n      actorId: payload.userId,\n    });\n  });\n}\n\nregisterFanOut();\n","/**\n * Private helpers shared by the service layer.\n *\n * Two jobs only: build the `PermissionResource` descriptors `can()` expects\n * from a loaded row, and stamp the `EventEnvelope` every domain event carries.\n * Neither re-implements a cross-cutting concern — they are adapters onto\n * `@/lib/permissions` and `@/lib/event-bus`.\n */\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { Comment } from \"@/types/comment\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type { EventEnvelope } from \"@/types/event\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Actor, Member } from \"@/types/member\";\nimport type { PermissionResource } from \"@/types/permission\";\nimport type { Project } from \"@/types/project\";\nimport type { WebhookId } from \"@/types/common\";\n\n/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */\nexport class NotFoundError extends Error {\n  readonly code = \"not_found\" as const;\n\n  constructor(\n    readonly entity: string,\n    readonly id: string,\n  ) {\n    super(`${entity} ${id} was not found`);\n    this.name = \"NotFoundError\";\n  }\n}\n\n/** Unwraps a repository read, turning the `null` case into a domain error. */\nexport function requireFound<T>(\n  value: T | null | undefined,\n  entity: string,\n  id: string,\n): T {\n  if (value === null || value === undefined) {\n    throw new NotFoundError(entity, id);\n  }\n  return value;\n}\n\nexport function orgResource(orgId: OrgId): PermissionResource {\n  return { kind: \"organization\", orgId };\n}\n\nexport function billingResource(orgId: OrgId): PermissionResource {\n  return { kind: \"billing\", orgId };\n}\n\nexport function activityResource(orgId: OrgId): PermissionResource {\n  return { kind: \"activity\", orgId };\n}\n\nexport function notificationResource(\n  orgId: OrgId,\n  recipientId: UserId,\n): PermissionResource {\n  return { kind: \"notification\", orgId, recipientId };\n}\n\nexport function webhookResource(\n  orgId: OrgId,\n  webhookId: WebhookId | null,\n): PermissionResource {\n  return { kind: \"webhook\", orgId, webhookId };\n}\n\nexport function memberResource(member: Member): PermissionResource {\n  return {\n    kind: \"member\",\n    orgId: member.orgId,\n    memberId: member.id,\n    targetUserId: member.userId,\n    targetRole: member.role,\n  };\n}\n\nexport function projectResource(project: Project): PermissionResource {\n  return {\n    kind: \"project\",\n    orgId: project.orgId,\n    projectId: project.id,\n    visibility: project.visibility,\n    leadId: project.leadId,\n  };\n}\n\nexport function issueResource(issue: Issue): PermissionResource {\n  return {\n    kind: \"issue\",\n    orgId: issue.orgId,\n    projectId: issue.projectId,\n    issueId: issue.id,\n    authorId: issue.authorId,\n    assigneeId: issue.assigneeId,\n  };\n}\n\nexport function commentResource(comment: Comment): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId: comment.orgId,\n    commentId: comment.id,\n    authorId: comment.authorId,\n  };\n}\n\n/** The three fields the bus stamps on every payload. */\nexport function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {\n  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };\n}\n\n/** Same envelope, taken from an `Actor` rather than assembled by hand. */\nexport function actorEnvelope(actor: Actor): EventEnvelope {\n  return envelope(actor.orgId, actor.userId);\n}\n\n/** Names the fields an update actually changed, for `issue.updated`. */\nexport function changedFields<T extends object>(\n  before: T,\n  after: T,\n): readonly string[] {\n  return Object.keys(after).filter(\n    (key) =>\n      JSON.stringify(before[key as keyof T]) !==\n      JSON.stringify(after[key as keyof T]),\n  );\n}\n","/**\n * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit\n */\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { consumeRateLimit } from \"@/lib/rate-limit\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport * as searchRepo from \"@/server/repositories/search-repository\";\nimport { orgResource } from \"./_support\";\nimport type { SearchQueryInput } from \"@/schemas/search\";\nimport type { SearchSubjectKind } from \"@/server/repositories/search-repository\";\nimport type { Comment } from \"@/types/comment\";\nimport type { OrgId, Page } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Actor } from \"@/types/member\";\nimport type { Project } from \"@/types/project\";\n\nexport type SearchHit = {\n  kind: SearchSubjectKind;\n  id: string;\n  title: string;\n  snippet: string;\n  href: string;\n};\n\n/** Characters of surrounding context kept on either side of a match. */\nconst SNIPPET_RADIUS = 60;\n\n/** Token bucket protecting the index from query bursts. */\nconst SEARCH_QUERY_BUCKET = \"search:query\";\n\n/**\n * Runs a query against the denormalised index. Field-scoped syntax\n * (`status:done`) is an `advanced_search` feature, so a query containing a\n * colon is rejected for plans that do not include it rather than silently\n * being treated as literal text.\n */\nexport async function search(\n  actor: Actor,\n  input: SearchQueryInput,\n): Promise<Page<SearchHit>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"issue:read\", orgResource(input.orgId));\n\n  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);\n  if (!verdict.allowed) {\n    throw new Error(\n      `Search rate limit reached; try again after ${verdict.resetAt}`,\n    );\n  }\n\n  const org = await orgRepo.findOrgById(input.orgId);\n  const advanced = isEnabled(\"advanced_search\", {\n    orgId: input.orgId,\n    userId: actor.userId,\n    plan: org?.plan ?? \"free\",\n    role: actor.role,\n    overrides: org?.settings.enabledFlagOverrides,\n  });\n\n  if (input.q.includes(\":\") && !advanced) {\n    throw new Error(\"Field-scoped search is not included in this plan\");\n  }\n\n  const page = await searchRepo.searchDocuments(input);\n\n  return {\n    items: page.items.map((row) => ({\n      kind: row.subjectKind,\n      id: row.subjectId,\n      title: row.content.split(\"\\n\")[0] ?? row.subjectId,\n      snippet: snippetAround(row.content, input.q),\n      href: hrefFor(row.subjectKind, row.subjectId),\n    })),\n    nextCursor: page.nextCursor,\n    total: page.total,\n  };\n}\n\nexport async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"issue\",\n    issue.id,\n    [issue.title, issue.description ?? \"\"].join(\"\\n\"),\n    issue.projectId,\n  );\n}\n\nexport async function indexComment(\n  orgId: OrgId,\n  comment: Comment,\n): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"comment\",\n    comment.id,\n    comment.body,\n    null,\n  );\n}\n\nexport async function indexProject(\n  orgId: OrgId,\n  project: Project,\n): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"project\",\n    project.id,\n    [project.name, project.description ?? \"\"].join(\"\\n\"),\n    project.id,\n  );\n}\n\nexport async function removeFromIndex(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n): Promise<void> {\n  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);\n}\n\n/**\n * Keeps the index in step with writes. Every handler re-reads the row rather\n * than trusting the event payload, so a partially-applied write can never be\n * indexed as if it had succeeded.\n */\nexport function registerSearchListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"issue.created\", async (payload) => {\n      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n    subscribe(\"issue.updated\", async (payload) => {\n      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n    subscribe(\"issue.archived\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"issue\", payload.issueId);\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      const comment = await commentRepo.findCommentById(\n        payload.orgId,\n        payload.commentId,\n      );\n      if (comment) await indexComment(payload.orgId, comment);\n    }),\n    subscribe(\"comment.deleted\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"comment\", payload.commentId);\n    }),\n    subscribe(\"project.created\", async (payload) => {\n      const project = await projectRepo.findProjectById(\n        payload.orgId,\n        payload.projectId,\n      );\n      if (project) await indexProject(payload.orgId, project);\n    }),\n    subscribe(\"project.archived\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"project\", payload.projectId);\n    }),\n    subscribe(\"search.reindex_requested\", async (payload) => {\n      if (payload.subjectKind !== \"issue\") return;\n      const issue = await issueRepo.findIssueById(\n        payload.orgId,\n        payload.subjectId as Issue[\"id\"],\n      );\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nfunction hrefFor(kind: SearchSubjectKind, subjectId: string): string {\n  switch (kind) {\n    case \"issue\":\n      return `/issues/${subjectId}`;\n    case \"comment\":\n      return `/comments/${subjectId}`;\n    case \"project\":\n      return `/projects/${subjectId}`;\n  }\n}\n\nfunction snippetAround(content: string, query: string): string {\n  const at = content.toLowerCase().indexOf(query.toLowerCase());\n  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);\n\n  const start = Math.max(0, at - SNIPPET_RADIUS);\n  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);\n  return `${start > 0 ? \"…\" : \"\"}${content.slice(start, end)}${\n    end < content.length ? \"…\" : \"\"\n  }`;\n}\n","/**\n * Comment rows, soft deleted so a deleted comment keeps its place in the thread.\n *\n * Must call (do not reimplement): archivePatch, shouldFilterArchived\n */\nimport { and, asc, count, desc, eq, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { archivePatch, shouldFilterArchived } from \"@/lib/soft-delete\";\nimport { comments, getDb, users } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toComment, toUser } from \"./_mappers\";\nimport type {\n  CreateCommentInput,\n  ListCommentsInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type {\n  Comment,\n  CommentThreadNode,\n  CommentWithAuthor,\n} from \"@/types/comment\";\nimport type { CommentId, IssueId, OrgId, Page, UserId } from \"@/types/common\";\n\nexport async function findCommentById(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment | null> {\n  const row = getDb()\n    .select()\n    .from(comments)\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .get();\n  return row ? toComment(row) : null;\n}\n\nexport async function listComments(\n  input: ListCommentsInput,\n): Promise<Page<CommentWithAuthor>> {\n  const db = getDb();\n  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };\n\n  const filters = compact(\n    orgPredicate(comments.orgId, input.orgId),\n    eq(comments.issueId, input.issueId),\n    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(comments)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(comments.createdAt), desc(comments.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),\n    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),\n  );\n}\n\n/**\n * The whole thread for one issue, in reading order: top-level comments oldest\n * first, each followed by its replies. Archived comments are kept so a reply\n * chain never loses its anchor — the UI renders them as \"deleted\".\n */\nexport async function listThread(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  const rows = getDb()\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(comments.createdAt))\n    .all();\n\n  const decorated: CommentWithAuthor[] = rows.map((row) => ({\n    ...toComment(row.comment),\n    author: toUser(row.author),\n  }));\n\n  const repliesBy = new Map<string, CommentWithAuthor[]>();\n  for (const comment of decorated) {\n    if (comment.parentId === null) continue;\n    const bucket = repliesBy.get(comment.parentId) ?? [];\n    bucket.push(comment);\n    repliesBy.set(comment.parentId, bucket);\n  }\n\n  return decorated\n    .filter((comment) => comment.parentId === null)\n    .map((comment) => ({\n      comment,\n      replies: repliesBy.get(comment.id) ?? [],\n    }));\n}\n\nexport async function countComments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(comments)\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n        isNull(comments.archivedAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertComment(\n  input: CreateCommentInput,\n  authorId: UserId,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(comments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      authorId,\n      body: input.body,\n      parentId: input.parentId,\n      editedAt: null,\n      mentionedUserIds: JSON.stringify(input.mentionedUserIds),\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toComment(row);\n}\n\n/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */\nexport async function updateComment(\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .update(comments)\n    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })\n    .where(\n      and(\n        orgPredicate(comments.orgId, input.orgId),\n        eq(comments.id, input.commentId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${input.commentId} not found`);\n  return toComment(row);\n}\n\nexport async function archiveComment(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment> {\n  const row = getDb()\n    .update(comments)\n    .set(archivePatch())\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${commentId} not found`);\n  return toComment(row);\n}\n","/**\n * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.\n *\n * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug\n */\nimport { and, count, desc, eq, inArray, isNotNull, like, lt, sql } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { uniqueSlug } from \"@/lib/slug\";\nimport {\n  archivePatch,\n  restorePatch,\n  shouldFilterArchived,\n} from \"@/lib/soft-delete\";\nimport { getDb, issues, projects } from \"@/server/db\";\nimport { CLOSED_ISSUE_STATUSES } from \"@/types/issue\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { livePredicate, orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toProject } from \"./_mappers\";\nimport type {\n  CreateProjectInput,\n  ListProjectsInput,\n  UpdateProjectInput,\n} from \"@/schemas/project\";\nimport type { ArchiveScope, OrgId, Page, ProjectId } from \"@/types/common\";\nimport type { Project, ProjectStats } from \"@/types/project\";\n\nexport async function findProjectById(\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<Project | null> {\n  const row = getDb()\n    .select()\n    .from(projects)\n    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))\n    .get();\n  return row ? toProject(row) : null;\n}\n\nexport async function findProjectBySlug(\n  orgId: OrgId,\n  slug: string,\n): Promise<Project | null> {\n  const row = getDb()\n    .select()\n    .from(projects)\n    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))\n    .get();\n  return row ? toProject(row) : null;\n}\n\nexport async function listProjects(\n  input: ListProjectsInput,\n): Promise<Page<Project>> {\n  const db = getDb();\n  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };\n\n  // The rows and the total must agree on the archive scope, so normalise the\n  // filter's loose `includeArchived` into one `ArchiveScope` up front.\n  const scope: ArchiveScope = shouldFilterArchived(input)\n    ? {}\n    : { includeArchived: true };\n\n  const filters = compact(\n    orgPredicate(projects.orgId, input.orgId),\n    livePredicate(projects.archivedAt, scope),\n    input.status === undefined ? undefined : eq(projects.status, input.status),\n    input.query === undefined\n      ? undefined\n      : like(projects.name, `%${input.query}%`),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(projects)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(projects)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(projects.createdAt), desc(projects.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({\n    id: row.id,\n    sortValue: row.createdAt,\n  }));\n}\n\n/** Counts live projects by default; the `projects` quota reads this. */\nexport async function countProjects(\n  orgId: OrgId,\n  scope: ArchiveScope = {},\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(projects)\n    .where(\n      and(\n        ...compact(\n          orgPredicate(projects.orgId, orgId),\n          livePredicate(projects.archivedAt, scope),\n        ),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertProject(\n  input: CreateProjectInput,\n): Promise<Project> {\n  const taken = await listTakenProjectSlugs(input.orgId);\n  const slug = uniqueSlug(input.slug, taken);\n  const stamp = toIsoTimestamp(new Date());\n\n  const row = getDb()\n    .insert(projects)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      name: input.name,\n      slug,\n      key: input.key,\n      description: input.description,\n      visibility: input.visibility,\n      status: \"active\",\n      leadId: input.leadId,\n      color: input.color,\n      startsAt: null,\n      targetDate: input.targetDate,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toProject(row);\n}\n\nexport async function updateProject(\n  input: UpdateProjectInput,\n): Promise<Project> {\n  const row = getDb()\n    .update(projects)\n    .set({\n      ...(input.name === undefined ? {} : { name: input.name }),\n      ...(input.description === undefined\n        ? {}\n        : { description: input.description }),\n      ...(input.visibility === undefined\n        ? {}\n        : { visibility: input.visibility }),\n      ...(input.status === undefined ? {} : { status: input.status }),\n      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),\n      ...(input.color === undefined ? {} : { color: input.color }),\n      ...(input.targetDate === undefined\n        ? {}\n        : { targetDate: input.targetDate }),\n      updatedAt: toIsoTimestamp(new Date()),\n    })\n    .where(\n      and(\n        orgPredicate(projects.orgId, input.orgId),\n        eq(projects.id, input.projectId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Project ${input.projectId} not found`);\n  return toProject(row);\n}\n\nexport async function archiveProject(\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<Project> {\n  const row = getDb()\n    .update(projects)\n    .set(archivePatch())\n    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Project ${projectId} not found`);\n  return toProject(row);\n}\n\nexport async function restoreProject(\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<Project> {\n  const row = getDb()\n    .update(projects)\n    .set(restorePatch())\n    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Project ${projectId} not found`);\n  return toProject(row);\n}\n\n/** Includes archived slugs — a restored project must not collide. */\nexport async function listTakenProjectSlugs(\n  orgId: OrgId,\n): Promise<readonly string[]> {\n  const rows = getDb()\n    .select({ slug: projects.slug })\n    .from(projects)\n    .where(orgPredicate(projects.orgId, orgId))\n    .all();\n  return rows.map((row) => row.slug);\n}\n\n/** Open/closed/overdue counters plus the last write, for the project card. */\nexport async function getProjectStats(\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<ProjectStats> {\n  const db = getDb();\n  const scope = and(\n    orgPredicate(issues.orgId, orgId),\n    eq(issues.projectId, projectId),\n    ...compact(livePredicate(issues.archivedAt, {})),\n  );\n\n  const closed = db\n    .select({ value: count() })\n    .from(issues)\n    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))\n    .get();\n\n  const all = db.select({ value: count() }).from(issues).where(scope).get();\n\n  const overdue = db\n    .select({ value: count() })\n    .from(issues)\n    .where(\n      and(\n        scope,\n        isNotNull(issues.dueAt),\n        lt(issues.dueAt, toIsoTimestamp(new Date())),\n      ),\n    )\n    .get();\n\n  const lastActivity = db\n    .select({ value: sql<string | null>`max(${issues.updatedAt})` })\n    .from(issues)\n    .where(scope)\n    .get();\n\n  const closedCount = closed?.value ?? 0;\n\n  return {\n    projectId,\n    openIssues: (all?.value ?? 0) - closedCount,\n    closedIssues: closedCount,\n    overdueIssues: overdue?.value ?? 0,\n    lastActivityAt:\n      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),\n  };\n}\n","/**\n * Recomputes the usage counters that every `LimitCheck` compares against.\n *\n * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits\n */\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport { emit, subscribe } from \"@/lib/event-bus\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as usageRepo from \"@/server/repositories/usage-repository\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { Actor } from \"@/types/member\";\nimport type { OrganizationUsage } from \"@/types/organization\";\n\n/** Fraction of a quota at which the \"approaching limit\" event fires. */\nconst WARN_THRESHOLD = 0.9;\n\nexport async function getUsage(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<OrganizationUsage> {\n  assertOrgScope(actor, orgId);\n  return usageRepo.getUsage(orgId);\n}\n\n/**\n * Full recount from the source tables. Called by the rollup job and by every\n * event that could have moved a counter — after recounting, the seat and\n * project totals are checked against the plan so a breach surfaces as an\n * event rather than waiting for the next write to be rejected.\n */\nexport async function recomputeUsage(\n  orgId: OrgId,\n): Promise<OrganizationUsage> {\n  const usage = await usageRepo.recomputeUsage(orgId);\n  const org = await orgRepo.findOrgById(orgId);\n  if (!org) return usage;\n\n  const limits = getPlanLimits(org.plan);\n\n  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {\n    await emit(\"billing.limit_exceeded\", {\n      orgId,\n      actorId: null,\n      occurredAt: toIsoTimestamp(new Date()),\n      resource: \"seats\",\n      limit: limits.seats,\n      used: usage.seatsUsed,\n    });\n  }\n\n  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {\n    await emit(\"billing.limit_exceeded\", {\n      orgId,\n      actorId: null,\n      occurredAt: toIsoTimestamp(new Date()),\n      resource: \"projects\",\n      limit: limits.projects,\n      used: usage.projectsUsed,\n    });\n  }\n\n  return usage;\n}\n\n/**\n * Every event that changes a counted resource nudges the cache. The deltas are\n * cheap; the periodic rollup is what corrects any drift they accumulate.\n */\nexport function registerUsageListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"issue.created\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });\n    }),\n    subscribe(\"issue.archived\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });\n    }),\n    subscribe(\"project.created\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });\n    }),\n    subscribe(\"project.archived\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, {\n        projectsUsed: -1,\n        issuesUsed: -payload.issuesArchived,\n      });\n    }),\n    subscribe(\"member.joined\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });\n    }),\n    subscribe(\"member.removed\", async (payload) => {\n      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n","/**\n * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit\n */\nimport { createHmac } from \"node:crypto\";\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { randomToken } from \"@/lib/hash\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { requireFound, webhookResource } from \"./_support\";\nimport type {\n  CreateWebhookInput,\n  DeleteWebhookInput,\n  UpdateWebhookInput,\n} from \"@/schemas/webhook\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\n\n/** Length in bytes of a generated endpoint signing secret. */\nconst SECRET_BYTES = 32;\n\nexport async function listWebhooks(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(orgId, null));\n  return webhookRepo.listEndpoints(orgId);\n}\n\n/**\n * Creating an endpoint is gated twice: the `webhooks` flag has to be on for\n * the org's plan, and the plan's endpoint count must have room. A secret is\n * minted here and never regenerated — rotating it means deleting the endpoint.\n */\nexport async function createWebhook(\n  actor: Actor,\n  input: CreateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, null));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  if (!isEnabled(\"webhooks\", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {\n    throw new Error(\"Outgoing webhooks are not included in this plan\");\n  }\n\n  const used = await webhookRepo.countEndpoints(input.orgId);\n  if (wouldExceedLimit(org.plan, \"webhooks\", used)) {\n    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);\n  }\n\n  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));\n}\n\nexport async function updateWebhook(\n  actor: Actor,\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  return webhookRepo.updateEndpoint(input);\n}\n\nexport async function deleteWebhook(\n  actor: Actor,\n  inp