nction enqueueForOrg(\n  orgId: OrgId,\n  eventType: string,\n  payload: string,\n): Promise<void> {\n  const endpoints = await webhookRepo.listEndpoints(orgId);\n\n  for (const endpoint of endpoints) {\n    if (!endpoint.enabled) continue;\n\n    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];\n    if (!wanted.includes(eventType)) continue;\n\n    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);\n  }\n}\n\nfunction flagContextFor(\n  actor: Actor,\n  plan: FlagContext[\"plan\"],\n  overrides: readonly string[],\n): FlagContext {\n  return {\n    orgId: actor.orgId,\n    userId: actor.userId,\n    plan,\n    role: actor.role,\n    overrides,\n  };\n}\n"],"names":["UNLIMITED","Number","POSITIVE_INFINITY","PLAN_LIMITS","free","plan","seats","projects","issuesPerProject","storageMb","apiRequestsPerHour","webhooks","retentionDays","includedFlags","priceCentsPerSeatMonthly","starter","growth","enterprise","PLAN_ORDER","getPlanLimits","getLimit","resource","planAtLeast","minPlan","indexOf","wouldExceedLimit","used","requested","handlers","Map","errorSinks","Set","subscribe","type","handler","set","get","add","delete","subscribeOnce","off","payload","emit","size","results","Promise","allSettled","map","result","status","reportHandlerError","reason","emitAndForget","catch","error","onHandlerError","sink","subscriberCount","resetEventBus","clear","FEATURE_FLAG_DEFINITIONS","kanban_board","key","label","description","strategy","kind","overridable","ai_issue_summary","percent","command_palette","activity_feed","public_projects","csv_export","digest_email","issue_templates","minRole","advanced_search","FEATURE_FLAG_KEYS1","Object","keys","getFlagDefinition","isFeatureFlagKey","value","prototype","hasOwnProperty","call","KEY_LENGTH","SALT_BYTES","PREFIX","deriveKey","password","salt","resolve","reject","scrypt","normalize","hashPassword","randomBytes","toString","verifyPassword","hash","scheme","saltHex","keyHex","split","