./.next/server/chunks/ssr/corpus_taskflow_src_05u_ud1._.js.map:1:{"version":3,"sources":["../../../../../../corpus/taskflow/src/components/domain/issue/issue-card.tsx","../../../../../../corpus/taskflow/src/components/domain/issue/issue-tone.ts","../../../../../../corpus/taskflow/src/components/ui/avatar.tsx","../../../../../../corpus/taskflow/src/components/ui/card.tsx","../../../../../../corpus/taskflow/src/components/ui/empty-state.tsx","../../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts","../../../../../../corpus/taskflow/src/server/services/issue-service.ts","../../../../../../corpus/taskflow/src/server/repositories/attachment-repository.ts"],"sourcesContent":["/**\n * Compact issue summary tile used by lists and the board.\n */\nimport Link from \"next/link\";\nimport { Avatar } from \"@/components/ui/avatar\";\nimport { Badge } from \"@/components/ui/badge\";\nimport { Card } from \"@/components/ui/card\";\nimport { cn } from \"@/lib/cn\";\nimport { formatRelative, isOverdue } from \"@/lib/date\";\nimport { humanizePriority, humanizeStatus } from \"@/lib/format\";\nimport type { Issue, IssueLabel, IssuePriority } from \"@/types/issue\";\nimport type { User } from \"@/types/member\";\nimport type { ReactElement } from \"react\";\nimport { PRIORITY_TONE, STATUS_TONE } from \"./issue-tone\";\n\nexport type IssueCardProps = {\n  issue: Issue;\n  assignee?: User | null;\n  labels?: readonly IssueLabel[];\n  href: string;\n  compact?: boolean;\n};\n\n/** Priorities worth shouting about; `none`/`low` stay silent on a card. */\nfunction shouldShowPriority(priority: IssuePriority): boolean {\n  return priority !== \"none\" && priority !== \"low\";\n}\n\nexport function IssueCard(props: IssueCardProps): ReactElement | null {\n  const { issue, assignee = null, labels = [], href, compact = false } = props;\n  const overdue = isOverdue(issue.dueAt);\n\n  return (\n    <Card padded={!compact} className=\"issue-card\">\n      <div className={cn(\"flex items-start gap-3\", compact && \"text-sm\")}>\n        <div className=\"min-w-0 flex-1\">\n          <Link href={href} className=\"block font-medium hover:underline\">\n            <span className=\"mr-2 text-neutral-500\">#{issue.number}</span>\n            {issue.title}\n          </Link>\n\n          <div className=\"mt-1 flex flex-wrap items-center gap-2\">\n            <Badge tone={STATUS_TONE[issue.status]} size=\"sm\">\n              {humanizeStatus(issue.status)}\n            </Badge>\n\n            {shouldShowPriority(issue.priority) ? (\n              <Badge tone={PRIORITY_TONE[issue.priority]} size=\"sm\">\n                {humanizePriority(issue.priority)}\n              </Badge>\n            ) : null}\n\n            {labels.map((label) => (\n              <Badge key={label.id} tone=\"neutral\" size=\"sm\">\n                {label.name}\n              </Badge>\n            ))}\n\n            {issue.dueAt !== null ? (\n              <span className={cn(\"text-xs\", overdue && \"text-red-600\")}>\n                {overdue ? \"overdue \" : \"due \"}\n                {formatRelative(issue.dueAt)}\n              </span>\n            ) : null}\n\n            {issue.archivedAt !== null ? (\n              <Badge tone=\"warning\" size=\"sm\">\n                Archived\n              </Badge>\n            ) : null}\n          </div>\n        </div>\n\n        {assignee !== null ? (\n          <Avatar name={assignee.name} src={assignee.avatarUrl} size=\"sm\" />\n        ) : (\n          <Badge tone=\"neutral\" size=\"sm\">\n            Unassigned\n          </Badge>\n        )}\n      </div>\n    </Card>\n  );\n}\n","/**\n * The status/priority → badge tone mapping.\n *\n * The list, the row, the card, the board column header and the detail rail all\n * colour the same status, so the table lives in one place; drifting colours\n * between the board and the list is the kind of bug nobody files but everybody\n * notices.\n */\nimport type { BadgeProps } from \"@/components/ui/badge\";\nimport type { IssuePriority, IssueStatus } from \"@/types/issue\";\n\ntype Tone = NonNullable<BadgeProps[\"tone\"]>;\n\nexport const STATUS_TONE: Readonly<Record<IssueStatus, Tone>> = {\n  backlog: \"neutral\",\n  todo: \"neutral\",\n  in_progress: \"brand\",\n  in_review: \"warning\",\n  done: \"success\",\n  canceled: \"danger\",\n};\n\nexport const PRIORITY_TONE: Readonly<Record<IssuePriority, Tone>> = {\n  none: \"neutral\",\n  low: \"neutral\",\n  medium: \"brand\",\n  high: \"warning\",\n  urgent: \"danger\",\n};\n\n/** Board column order: the workflow left-to-right, not the enum order. */\nexport const BOARD_STATUS_ORDER: readonly IssueStatus[] = [\n  \"backlog\",\n  \"todo\",\n  \"in_progress\",\n  \"in_review\",\n  \"done\",\n  \"canceled\",\n];\n","/**\n * User avatar falling back to initials.\n *\n * Owner A — design system. Server-renderable. The colour is derived from the\n * name so the same person keeps the same swatch across every list without the\n * server having to store one.\n */\nimport type { ReactElement } from \"react\";\nimport { cn } from \"@/lib/cn\";\n\nexport type AvatarProps = { name: string; src?: string | null; size?: 'xs' | 'sm' | 'md' | 'lg'; className?: string };\n\nconst SIZES = {\n  xs: \"h-5 w-5 text-[10px]\",\n  sm: \"h-6 w-6 text-[11px]\",\n  md: \"h-8 w-8 text-xs\",\n  lg: \"h-12 w-12 text-base\",\n} as const;\n\nconst SWATCHES = [\n  \"bg-brand-500\",\n  \"bg-emerald-600\",\n  \"bg-amber-600\",\n  \"bg-rose-600\",\n  \"bg-violet-600\",\n  \"bg-cyan-700\",\n] as const;\n\n/** First letter of the first two words, e.g. `\"Ada Lovelace\"` → `\"AL\"`. */\nexport function initialsOf(name: string): string {\n  const words = name.trim().split(/\\s+/).filter(Boolean).slice(0, 2);\n  if (words.length === 0) return \"?\";\n  return words.map((word) => word.charAt(0).toUpperCase()).join(\"\");\n}\n\nfunction swatchFor(name: string): string {\n  let hash = 0;\n  for (let i = 0; i < name.length; i += 1) {\n    hash = (hash * 31 + name.charCodeAt(i)) % 1_000_003;\n  }\n  return SWATCHES[hash % SWATCHES.length] ?? SWATCHES[0];\n}\n\nexport function Avatar(props: AvatarProps): ReactElement | null {\n  const { name, src, size = \"md\", className } = props;\n\n  const shared = cn(\n    \"inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full\",\n    SIZES[size],\n    className,\n  );\n\n  if (src) {\n    // Avatars come from arbitrary user-supplied URLs; next/image would need\n    // every one of those hosts configured up front, so a plain img wins here.\n    return (\n      /* eslint-disable-next-line @next/next/no-img-element */\n      <img src={src} alt={name} title={name} className={cn(shared, \"object-cover\")} />\n    );\n  }\n\n  return (\n    <span\n      role=\"img\"\n      aria-label={name}\n      title={name}\n      className={cn(shared, swatchFor(name), \"font-semibold text-white\")}\n    >\n      {initialsOf(name)}\n    </span>\n  );\n}\n","/**\n * Surface container; also exports header/title/content/footer parts.\n *\n * Owner A — design system. Server-renderable compound component: the parts are\n * plain layout wrappers so a Server Component can build a card without pulling\n * a client boundary in.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { cn } from \"@/lib/cn\";\nimport { SURFACE } from \"./_lib/tokens\";\n\nexport type CardProps = { padded?: boolean; className?: string; children?: ReactNode };\n\ntype PartProps = { className?: string; children?: ReactNode };\n\nexport function Card(props: CardProps): ReactElement | null {\n  const { padded = false, className, children } = props;\n\n  return (\n    <section\n      className={cn(\n        SURFACE,\n        \"rounded-lg shadow-sm\",\n        padded && \"p-4\",\n        className,\n      )}\n    >\n      {children}\n    </section>\n  );\n}\n\nexport function CardHeader(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <header\n      className={cn(\n        \"flex items-start justify-between gap-3 border-b border-black/8 px-4 py-3\",\n        className,\n      )}\n    >\n      {children}\n    </header>\n  );\n}\n\nexport function CardTitle(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <h2\n      className={cn(\n        \"text-sm font-semibold text-black/85 dark:text-white/85\",\n        className,\n      )}\n    >\n      {children}\n    </h2>\n  );\n}\n\nexport function CardDescription(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <p className={cn(\"mt-0.5 text-xs text-black/55 dark:text-white/55\", className)}>\n      {children}\n    </p>\n  );\n}\n\nexport function CardContent(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return <div className={cn(\"px-4 py-3\", className)}>{children}</div>;\n}\n\nexport function CardFooter(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <footer\n      className={cn(\n        \"flex items-center justify-end gap-2 border-t border-black/8 px-4 py-3\",\n        className,\n      )}\n    >\n      {children}\n    </footer>\n  );\n}\n","/**\n * Zero-data placeholder.\n *\n * Owner A — design system. Server-renderable. The `action` slot takes an\n * already-permission-gated node: this component never decides whether the\n * viewer may create anything.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { SURFACE } from \"./_lib/tokens\";\nimport { cn } from \"@/lib/cn\";\n\nexport type EmptyStateProps = { title: string; description?: string; icon?: ReactNode; action?: ReactNode };\n\nexport function EmptyState(props: EmptyStateProps): ReactElement | null {\n  const { title, description, icon, action } = props;\n\n  return (\n    <div\n      className={cn(\n        SURFACE,\n        \"flex flex-col items-center gap-2 rounded-lg border-dashed px-6 py-10 text-center\",\n      )}\n    >\n      {icon !== undefined ? (\n        <span aria-hidden=\"true\" className=\"text-black/30 dark:text-white/30\">\n          {icon}\n        </span>\n      ) : null}\n      <p className=\"text-sm font-semibold text-black/80 dark:text-white/80\">\n        {title}\n      </p>\n      {description !== undefined ? (\n        <p className=\"max-w-sm text-xs leading-5 text-black/55 dark:text-white/55\">\n          {description}\n        </p>\n      ) : null}\n      {action !== undefined ? <div className=\"mt-2\">{action}</div> : null}\n    </div>\n  );\n}\n","/**\n * Comment rows, soft deleted so a deleted comment keeps its place in the thread.\n *\n * Must call (do not reimplement): archivePatch, shouldFilterArchived\n */\nimport { and, asc, count, desc, eq, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { archivePatch, shouldFilterArchived } from \"@/lib/soft-delete\";\nimport { comments, getDb, users } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toComment, toUser } from \"./_mappers\";\nimport type {\n  CreateCommentInput,\n  ListCommentsInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type {\n  Comment,\n  CommentThreadNode,\n  CommentWithAuthor,\n} from \"@/types/comment\";\nimport type { CommentId, IssueId, OrgId, Page, UserId } from \"@/types/common\";\n\nexport async function findCommentById(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment | null> {\n  const row = getDb()\n    .select()\n    .from(comments)\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .get();\n  return row ? toComment(row) : null;\n}\n\nexport async function listComments(\n  input: ListCommentsInput,\n): Promise<Page<CommentWithAuthor>> {\n  const db = getDb();\n  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };\n\n  const filters = compact(\n    orgPredicate(comments.orgId, input.orgId),\n    eq(comments.issueId, input.issueId),\n    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(comments)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(comments.createdAt), desc(comments.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),\n    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),\n  );\n}\n\n/**\n * The whole thread for one issue, in reading order: top-level comments oldest\n * first, each followed by its replies. Archived comments are kept so a reply\n * chain never loses its anchor — the UI renders them as \"deleted\".\n */\nexport async function listThread(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  const rows = getDb()\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(comments.createdAt))\n    .all();\n\n  const decorated: CommentWithAuthor[] = rows.map((row) => ({\n    ...toComment(row.comment),\n    author: toUser(row.author),\n  }));\n\n  const repliesBy = new Map<string, CommentWithAuthor[]>();\n  for (const comment of decorated) {\n    if (comment.parentId === null) continue;\n    const bucket = repliesBy.get(comment.parentId) ?? [];\n    bucket.push(comment);\n    repliesBy.set(comment.parentId, bucket);\n  }\n\n  return decorated\n    .filter((comment) => comment.parentId === null)\n    .map((comment) => ({\n      comment,\n      replies: repliesBy.get(comment.id) ?? [],\n    }));\n}\n\nexport async function countComments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(comments)\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n        isNull(comments.archivedAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertComment(\n  input: CreateCommentInput,\n  authorId: UserId,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(comments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      authorId,\n      body: input.body,\n      parentId: input.parentId,\n      editedAt: null,\n      mentionedUserIds: JSON.stringify(input.mentionedUserIds),\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toComment(row);\n}\n\n/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */\nexport async function updateComment(\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .update(comments)\n    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })\n    .where(\n      and(\n        orgPredicate(comments.orgId, input.orgId),\n        eq(comments.id, input.commentId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${input.commentId} not found`);\n  return toComment(row);\n}\n\nexport async function archiveComment(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment> {\n  const row = getDb()\n    .update(comments)\n    .set(archivePatch())\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${commentId} not found`);\n  return toComment(row);\n}\n","/**\n * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived\n */\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { emit } from \"@/lib/event-bus\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertNotArchived } from \"@/lib/soft-delete\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as labelRepo from \"@/server/repositories/label-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as attachmentRepo from \"@/server/repositories/attachment-repository\";\nimport {\n  actorEnvelope,\n  issueResource,\n  orgResource,\n  projectResource,\n  requireFound,\n} from \"./_support\";\nimport type {\n  AssignIssueInput,\n  ChangeIssueStatusInput,\n  CreateIssueInput,\n  IssueFilterInput,\n  MoveIssueInput,\n  UpdateIssueInput,\n} from \"@/schemas/issue\";\nimport type { IssueId, OrgId, Page, ProjectId } from \"@/types/common\";\nimport type { Issue, IssueBoardColumn, IssueWithRelations } from \"@/types/issue\";\nimport type { Actor } from \"@/types/member\";\n\n/**\n * Creates an issue after four gates: tenant scope, the `issue:create`\n * permission, a live parent project and the plan's per-project issue quota.\n * Only then is a number allocated and `issue.created` published — everything\n * reactive (notifications, search, webhooks, the audit log) hangs off that.\n */\nexport async function createIssue(\n  actor: Actor,\n  input: CreateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(input.orgId, input.projectId),\n    \"Project\",\n    input.projectId,\n  );\n  assertNotArchived(\"Project\", project.id, project);\n  assertCan(actor, \"issue:create\", projectResource(project));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n  const used = await issueRepo.countIssues(input.orgId, input.projectId);\n  if (wouldExceedLimit(org.plan, \"issuesPerProject\", used)) {\n    throw new Error(\n      `Plan ${org.plan} allows no more issues in project ${project.key}`,\n    );\n  }\n\n  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);\n  const issue = await issueRepo.insertIssue(input, actor.userId, number);\n\n  await emit(\"issue.created\", {\n    ...actorEnvelope(actor),\n    issueId: issue.id,\n    projectId: issue.projectId,\n    title: issue.title,\n    assigneeId: issue.assigneeId,\n    priority: issue.priority,\n  });\n\n  return issue;\n}\n\nexport async function updateIssue(\n  actor: Actor,\n  input: UpdateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.updateIssue(input);\n\n  await emit(\"issue.updated\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    changedFields: Object.keys(input).filter(\n      (key) => key !== \"orgId\" && key !== \"issueId\",\n    ),\n  });\n\n  return after;\n}\n\n/** Status transitions are an `issue:update`, not a separate permission. */\nexport async function changeIssueStatus(\n  actor: Actor,\n  input: ChangeIssueStatusInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  if (before.status === input.status) return before;\n\n  const after = await issueRepo.setIssueStatus(\n    input.orgId,\n    input.issueId,\n    input.status,\n  );\n\n  await emit(\"issue.status_changed\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    from: before.status,\n    to: after.status,\n  });\n\n  return after;\n}\n\n/**\n * Assignment has its own permission because a member may reassign work they\n * do not otherwise own. Un-assigning publishes `issue.updated` instead, since\n * `issue.assigned` carries a non-null assignee by contract.\n */\nexport async function assignIssue(\n  actor: Actor,\n  input: AssignIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:assign\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.setIssueAssignee(\n    input.orgId,\n    input.issueId,\n    input.assigneeId,\n  );\n\n  if (input.assigneeId === null) {\n    await emit(\"issue.updated\", {\n      ...actorEnvelope(actor),\n      issueId: after.id,\n      projectId: after.projectId,\n      changedFields: [\"assigneeId\"],\n    });\n    return after;\n  }\n\n  await emit(\"issue.assigned\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    previousAssigneeId: before.assigneeId,\n    assigneeId: input.assigneeId,\n  });\n\n  return after;\n}\n\nexport async function archiveIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<Issue> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:archive\", issueResource(issue));\n  assertNotArchived(\"Issue\", issue.id, issue);\n\n  const archived = await issueRepo.archiveIssue(orgId, issueId);\n\n  await emit(\"issue.archived\", {\n    ...actorEnvelope(actor),\n    issueId: archived.id,\n    projectId: archived.projectId,\n  });\n\n  return archived;\n}\n\n/**\n * Board drag-and-drop. The index is presentation-only — the board renders by\n * `updated_at` — so a move is a status change plus a touch.\n */\nexport async function moveIssue(\n  actor: Actor,\n  input: MoveIssueInput,\n): Promise<Issue> {\n  return changeIssueStatus(actor, {\n    orgId: input.orgId,\n    issueId: input.issueId,\n    status: input.toStatus,\n  });\n}\n\nexport async function getIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<IssueWithRelations> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:read\", issueResource(issue));\n\n  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);\n\n  return {\n    issue,\n    labels: labels[issue.id] ?? [],\n    commentCount: await commentRepo.countComments(orgId, issue.id),\n    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))\n      .length,\n  };\n}\n\nexport async function listIssues(\n  actor: Actor,\n  input: IssueFilterInput,\n): Promise<Page<Issue>> {\n  assertOrgScope(actor, input.orgId);\n  // A cross-project list is an org-wide read; per-project visibility is\n  // enforced when the caller opens an individual issue.\n  assertCan(actor, \"issue:read\", orgResource(input.orgId));\n  return issueRepo.listIssues(input);\n}\n\nexport async function getBoard(\n  actor: Actor,\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<readonly IssueBoardColumn[]> {\n  assertOrgScope(actor, orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(orgId, projectId),\n    \"Project\",\n    projectId,\n  );\n  assertCan(actor, \"issue:read\", projectResource(project));\n\n  return issueRepo.listBoardColumns(orgId, projectId);\n}\n","/**\n * Attachment metadata; the byte total feeds the `storageMb` quota check.\n */\nimport { and, asc, eq, sql } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { attachments, getDb } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { toAttachment } from \"./_mappers\";\nimport type { CreateAttachmentInput } from \"@/schemas/attachment\";\nimport type { AttachmentId, IssueId, OrgId, UserId } from \"@/types/common\";\nimport type { IssueAttachment } from \"@/types/issue\";\n\nexport async function listAttachments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly IssueAttachment[]> {\n  const rows = getDb()\n    .select()\n    .from(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(attachments.createdAt))\n    .all();\n  return rows.map(toAttachment);\n}\n\nexport async function insertAttachment(\n  input: CreateAttachmentInput,\n  uploadedBy: UserId,\n): Promise<IssueAttachment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(attachments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      filename: input.filename,\n      contentType: input.contentType,\n      sizeBytes: input.sizeBytes,\n      uploadedBy,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toAttachment(row);\n}\n\n/** Attachments are hard deleted — the bytes are gone, so the row goes too. */\nexport async function deleteAttachment(\n  orgId: OrgId,\n  attachmentId: AttachmentId,\n): Promise<void> {\n  getDb()\n    .delete(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.id, attachmentId),\n      ),\n    )\n    .run();\n}\n\n/** Total stored bytes for one tenant; `BillingService` converts to megabytes. */\nexport async function sumStorageBytes(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({\n      value: sql<number | null>`sum(${attachments.sizeBytes})`,\n    })\n    .from(attachments)\n    .where(orgPredicate(attachments.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n"],"names":["shouldShowPriority","priority","IssueCard","props","issue","assignee","labels","href","compact","overdue","dueAt","padded","className","number","title","tone","status","size","map","label","name","id","archivedAt","src","avatarUrl","STATUS_TONE","backlog","todo","in_progress","in_review","done","canceled","PRIORITY_TONE","none","low","medium","high","urgent","BOARD_STATUS_ORDER","SIZES","xs","sm","md","lg","SWATCHES","initialsOf","words","trim","split","filter","Boolean","slice","length","word","charAt","toUpperCase","join","swatchFor","hash","i","charCodeAt","Avatar","shared","alt","role","Card","children","CardHeader","CardTitle","CardDescription","CardContent","CardFooter","EmptyState","description","icon","action","undefined","findCommentById","orgId","commentId","row","select","from","where","get","listComments","input","db","sort","sortColumn","createdAt","idColumn","filters","issueId","shouldFilterArchived","total","value","rows","comment","author","innerJoin","authorId","keysetPredicate","cursor","orderBy","desc","limit","probeLimit","all","toPage","sortValue","listThread","decorated","repliesBy","Map","parentId","bucket","push","set","replies","countComments","insertComment","stamp","Date",