verReference } from 'react-server-dom-webpack/server'\n","\"use server\";\n\n/**\n * Registers a webhook endpoint; plan and flag gated.\n *\n * Owner D. Two independent gates: the `webhooks` feature flag (which is itself\n * plan-derived) and the numeric `webhooks` quota. Both are checked because a\n * flag can be force-enabled through an org override while the quota still\n * applies.\n *\n * Must call (do not reimplement): createWebhookSchema, can, isEnabled,\n * getPlanLimits, getActor, toActionResult\n */\n\nimport {\n  FeatureUnavailableError,\n  ForbiddenActionError,\n  PlanLimitError,\n} from \"@/actions/_lib/action-errors\";\nimport { withAction } from \"@/actions/_lib/with-action\";\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport { CACHE_PROFILES, orgTag, revalidateTagged } from \"@/lib/cache\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { can } from \"@/lib/permissions\";\nimport { createWebhookSchema, type CreateWebhookInput } from \"@/schemas/webhook\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { getOrganizationSummary } from \"@/server/services/organization-service\";\nimport { createWebhook, listWebhooks } from \"@/server/services/webhook-service\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { ActionResult } from \"@/types/api\";\n\nconst run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(\n  createWebhookSchema,\n  async (raw, actor) => {\n    const input = raw as CreateWebhookInput;\n\n    const allowed = can(actor, \"webhook:manage\", {\n      kind: \"webhook\",\n      orgId: input.orgId,\n      webhookId: null,\n    });\n    if (!allowed) {\n      throw new ForbiddenActionError(\"webhook:manage\");\n    }\n\n    const { organization } = await getOrganizationSummary(actor, input.orgId);\n    if (!isEnabled(\"webhooks\", buildFlagContext(actor, organization))) {\n      throw new FeatureUnavailableError(\"webhooks\");\n    }\n\n    const limits = getPlanLimits(organization.plan);\n    const existing = await listWebhooks(actor, input.orgId);\n    if (existing.length >= limits.webhooks) {\n      throw new PlanLimitError(\"webhooks\", limits.webhooks, existing.length);\n    }\n\n    const endpoint = await createWebhook(actor, input);\n    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);\n    return endpoint;\n  },\n  { revalidate: [\"webhooks\"], cacheProfile: \"hours\" },\n);\n\nexport async function createWebhookAction(\n  raw: unknown,\n): Promise<ActionResult<WebhookEndpointRow>> {\n  return run(raw);\n}\n","import { z } from \"zod\";\nimport { orgIdSchema, webhookIdSchema } from \"./common\";\n\nexport const webhookEventTypeSchema = z.enum([\n  \"issue.created\",\n  \"issue.updated\",\n  \"issue.status_changed\",\n  \"issue.assigned\",\n  \"comment.created\",\n  \"member.joined\",\n  \"project.created\",\n  \"project.archived\",\n  \"billing.plan_changed\",\n]);\n\nexport const createWebhookSchema = z.object({\n  orgId: orgIdSchema,\n  url: z.url().max(2_000),\n  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20),\n});\n\nexport const updateWebhookSchema = z.object({\n  orgId: orgIdSchema,\n  webhookId: webhookIdSchema,\n  url: z.url().max(2_000).optional(),\n  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20).optional(),\n  enabled: z.boolean().optional(),\n});\n\nexport const deleteWebhookSchema = z.object({\n  orgId: orgIdSchema,\n  webhookId: webhookIdSchema,\n});\n\n/** Body accepted by the inbound webhook receiver route handler. */\nexport const inboundWebhookSchema = z.object({\n  source: z.enum([\"billing\", \"email\", \"ci\"]),\n  eventId: z.string().min(1).max(128),\n  occurredAt: z.iso.datetime(),\n  payload: z.record(z.string(), z.unknown()).default({}),\n});\n\nexport type CreateWebhookInput = z.infer<typeof createWebhookSchema>;\nexport type UpdateWebhookInput = z.infer<typeof updateWebhookSchema>;\nexport type DeleteWebhookInput = z.infer<typeof deleteWebhookSchema>;\nexport type InboundWebhookInput = z.infer<typeof inboundWebhookSchema>;\n","/**\n * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit\n */\nimport { createHmac } from \"node:crypto\";\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { randomToken } from \"@/lib/hash\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as webhookRepo from \"@/server/repositories/webhook-repository\";\nimport { requireFound, webhookResource } from \"./_support\";\nimport type {\n  CreateWebhookInput,\n  DeleteWebhookInput,\n  UpdateWebhookInput,\n} from \"@/schemas/webhook\";\nimport type { WebhookEndpointRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\n\n/** Length in bytes of a generated endpoint signing secret. */\nconst SECRET_BYTES = 32;\n\nexport async function listWebhooks(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly WebhookEndpointRow[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(orgId, null));\n  return webhookRepo.listEndpoints(orgId);\n}\n\n/**\n * Creating an endpoint is gated twice: the `webhooks` flag has to be on for\n * the org's plan, and the plan's endpoint count must have room. A secret is\n * minted here and never regenerated — rotating it means deleting the endpoint.\n */\nexport async function createWebhook(\n  actor: Actor,\n  input: CreateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, null));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  if (!isEnabled(\"webhooks\", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {\n    throw new Error(\"Outgoing webhooks are not included in this plan\");\n  }\n\n  const used = await webhookRepo.countEndpoints(input.orgId);\n  if (wouldExceedLimit(org.plan, \"webhooks\", used)) {\n    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);\n  }\n\n  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));\n}\n\nexport async function updateWebhook(\n  actor: Actor,\n  input: UpdateWebhookInput,\n): Promise<WebhookEndpointRow> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  return webhookRepo.updateEndpoint(input);\n}\n\nexport async function deleteWebhook(\n  actor: Actor,\n  input: DeleteWebhookInput,\n): Promise<void> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"webhook:manage\", webhookResource(input.orgId, input.webhookId));\n  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);\n}\n\n/**\n * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes\n * this from the same secret — it is the only thing proving the delivery came\n * from Taskflow, so the payload string must be signed byte-for-byte as sent.\n */\nexport function signPayload(secret: string, payload: string): string {\n  return createHmac(\"sha256\", secret).update(payload, \"utf8\").digest(\"hex\");\n}\n\n/**\n * Fans domain events out into the delivery table. Each org's endpoints\n * declare which event types they want, so an endpoint only ever receives what\n * it subscribed to; the job drains the rows afterwards.\n */\nexport function registerWebhookListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"webhook.delivery_requested\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        payload.eventType,\n        JSON.stringify(payload.payload),\n      );\n    }),\n    subscribe(\"issue.created\", async (payload) => {\n      await enqueueForOrg(payload.orgId, \"issue.created\", JSON.stringify(payload));\n    }),\n    subscribe(\"issue.status_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"issue.status_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"comment.created\",\n        JSON.stringify(payload),\n      );\n    }),\n    subscribe(\"billing.plan_changed\", async (payload) => {\n      await enqueueForOrg(\n        payload.orgId,\n        \"billing.plan_changed\",\n        JSON.stringify(payload),\n      );\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nasync function enqueueForOrg(\n  orgId: OrgId,\n  eventType: string,\n  payload: string,\n): Promise<void> {\n  const endpoints = await webhookRepo.listEndpoints(orgId);\n\n  for (const endpoint of endpoints) {\n    if (!endpoint.enabled) continue;\n\n    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];\n    if (!wanted.includes(eventType)) continue;\n\n    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);\n  }\n}\n\nfunction flagContextFor(\n  actor: Actor,\n  plan: FlagContext[\"plan\"],\n  overrides: readonly string[],\n): FlagContext {\n  return {\n    orgId: actor.orgId,\n    userId: actor.userId,\n    plan,\n    role: actor.role,\n    overrides,\n  };\n}\n","\"use server\";\n\n/**\n * Removes an endpoint.\n *\n * Owner D. Unlike creation this is not flag-gated — an org that loses the\n * `webhooks` capability on a downgrade must still be able to clean up the\n * endpoints it already has.\n *\n * Must call (do not reimplement): deleteWebhookSchema, can, getActor,\n * toActionResult\n */\n\nimport { ForbiddenActionError } from \"@/actions/_lib/action-errors\";\nimport { withAction } from \"@/actions/_lib/with-action\";\nimport { CACHE_PROFILES, orgTag, revalidateTagged } from \"@/lib/cache\";\nimport { can } from \"@/lib/permissions\";\nimport { deleteWebhookSchema, type DeleteWebhookInput } from \"@/schemas/webhook\";\nimport { deleteWebhook } from \"@/server/services/webhook-service\";\nimport type { ActionResult } from \"@/types/api\";\n\nconst run = withAction<typeof deleteWebhookSchema, null>(\n  deleteWebhookSchema,\n  async (raw, actor) => {\n    const input = raw as DeleteWebhookInput;\n\n    const allowed = can(actor, \"webhook:manage\", {\n      kind: \"webhook\",\n      orgId: input.orgId,\n      webhookId: input.webhookId,\n    });\n    if (!allowed) {\n      throw new ForbiddenActionError(\"webhook:manage\");\n    }\n\n    await deleteWebhook(actor, input);\n    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);\n    return null;\n  },\n  { revalidate: [\"webhooks\"], cacheProfile: \"hours\" },\n);\n\nexport async function deleteWebhookAction(raw: unknown): Promise<ActionResult<null>> {\n  return run(raw);\n}\n","/**\n * Maps thrown domain errors onto `AppErrorShape`.\n *\n * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,\n * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,\n * `ZodError`); Server Actions and Route Handlers never propagate those to the\n * client. Everything funnels through `toAppError()` so one thrown class maps\n * to exactly one `ErrorCode` and one HTTP status, app-wide.\n */\nimport { FeatureDisabledError } from \"@/lib/feature-flags\";\nimport { PermissionDeniedError } from \"@/lib/permissions\";\nimport { InvalidSlugError } from \"@/lib/slug\";\nimport { AlreadyArchivedError } from \"@/lib/soft-delete\";\nimport { TenantScopeError } from \"@/lib/tenant\";\nimport type { ActionResult, AppErrorShape, ErrorCode } from \"@/types/api\";\nimport { ZodError, type ZodIssue } from \"zod\";\n\nexport const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {\n  unauthorized: 401,\n  forbidden: 403,\n  not_found: 404,\n  validation_failed: 422,\n  conflict: 409,\n  rate_limited: 429,\n  plan_limit_exceeded: 402,\n  tenant_scope_violation: 403,\n  internal_error: 500,\n};\n\n/** True for the error classes this module knows how to translate faithfully. */\nexport function isDomainError(error: unknown): boolean {\n  return (\n    error instanceof PermissionDeniedError ||\n    error instanceof TenantScopeError ||\n    error instanceof FeatureDisabledError ||\n    error instanceof AlreadyArchivedError ||\n    error instanceof InvalidSlugError ||\n    error instanceof ZodError\n  );\n}\n\n/** Collapses a `ZodError` into the `field → messages` map forms consume. */\nexport function fieldErrorsFromZod(\n  error: ZodError,\n): Readonly<Record<string, readonly string[]>> {\n  const fields: Record<string, string[]> = {};\n  for (const issue of error.issues as readonly ZodIssue[]) {\n    const key = issue.path.length === 0 ? \"_root\" : issue.path.join(\".\");\n    (fields[key] ??= []).push(issue.message);\n  }\n  return fields;\n}\n\nexport function toAppError(error: unknown): AppErrorShape {\n  if (error instanceof ZodError) {\n    return {\n      code: \"validation_failed\",\n      message: \"Please correct the highlighted fields.\",\n      fieldErrors: fieldErrorsFromZod(error),\n    };\n  }\n\n  if (error instanceof PermissionDeniedError) {\n    return {\n      code: \"forbidden\",\n      message: error.message,\n      meta: {\n        action: error.action,\n        resourceKind: error.decision.resourceKind,\n        reason: error.decision.reason,\n      },\n    };\n  }\n\n  if (error instanceof TenantScopeError) {\n    return {\n      code: \"tenant_scope_violation\",\n      message: \"That resource belongs to a different organization.\",\n      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },\n    };\n  }\n\n  if (error instanceof FeatureDisabledError) {\n    return {\n      code: \"forbidden\",\n      message: error.message,\n      meta: { flag: error.flag },\n    };\n  }\n\n  if (error instanceof AlreadyArchivedError) {\n    return {\n      code: \"conflict\",\n      message: error.message,\n      meta: { entity: error.entity, id: error.id },\n    };\n  }\n\n  if (error instanceof InvalidSlugError) {\n    return {\n      code: \"validation_failed\",\n      message: error.message,\n      fieldErrors: { slug: [error.message] },\n      meta: { value: error.value },\n    };\n  }\n\n  return {\n    code: \"internal_error\",\n    message:\n      error instanceof Error ? error.message : \"Something went wrong. Try again.\",\n  };\n}\n\n/** The failure envelope a Server Action returns instead of throwing. */\nexport function toActionResult(error: unknown): ActionResult<never> {\n  return {\n    ok: false,\n    error: toAppError(error),\n    submittedAt: new Date().toISOString(),\n  };\n}\n"],"names":["ensureServerEntryExports","actions","i","length","action","Error","registerServerReference","min","webhookEventTypeSchema","enum","createWebhookSchema","object","orgId","url","max","eventTypes","array","updateWebhookSchema","webhookId","optional","enabled","boolean","deleteWebhookSchema","inboundWebhookSchema","source","eventId","string","occurredAt","iso","datetime","payload","record","unknown","default","HTTP_STATUS_BY_CODE","unauthorized","forbidden","not_found","validation_failed","conflict","rate_limited","plan_limit_exceeded","tenant_scope_violation","internal_error","isDomainError","error","fieldErrorsFromZod","fields","issue","issues","key","path","join","push","message","toAppError","code","fieldErrors","meta","resourceKind","decision","reason","expectedOrgId","actualOrgId","flag","entity","id","slug","value","toActionRes