./.next/server/chunks/ssr/corpus_taskflow_src_1rovbkd._.js.map:1:{"version":3,"sources":["../../../../../../corpus/taskflow/src/actions/_lib/permission-resources.ts","../../../../../../corpus/taskflow/src/app/%28dashboard%29/%5BorgSlug%5D/_lib/tenant-context.ts","../../../../../../corpus/taskflow/src/components/domain/issue/issue-row.tsx/__nextjs-internal-proxy.mjs","../../../../../../corpus/taskflow/src/components/domain/issue/issue-list.tsx","../../../../../../corpus/taskflow/src/components/domain/permission/resources.ts","../../../../../../corpus/taskflow/src/components/ui/_lib/tokens.ts","../../../../../../corpus/taskflow/src/components/ui/empty-state.tsx","../../../../../../corpus/taskflow/src/components/ui/table.tsx","../../../../../../corpus/taskflow/src/lib/actor.ts","../../../../../../corpus/taskflow/src/schemas/pagination.ts","../../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts","../../../../../../corpus/taskflow/src/server/services/issue-service.ts","../../../../../../corpus/taskflow/src/server/repositories/attachment-repository.ts"],"sourcesContent":["/**\n * Placeholder branded ids for `can()` calls about rows that do not exist yet.\n *\n * `PermissionResource` is a closed discriminated union, so asking \"may this\n * actor create an issue in this project?\" still has to name an `issueId`. The\n * ownership escalations inside `can()` compare ids for equality, and an empty\n * string never matches a real ULID — so a create check falls through to the\n * role matrix, which is exactly the intent.\n */\n\nimport type {\n  CommentId,\n  IssueId,\n  MemberId,\n  OrgId,\n  ProjectId,\n} from \"@/types/common\";\n\nexport const PENDING_ISSUE_ID = \"\" as IssueId;\nexport const PENDING_PROJECT_ID = \"\" as ProjectId;\nexport const PENDING_COMMENT_ID = \"\" as CommentId;\nexport const PENDING_MEMBER_ID = \"\" as MemberId;\n\n/**\n * Bucket owner for rate limits consumed before any tenant is known — the login\n * and password-reset flows, which are reachable without a session.\n */\nexport const ANONYMOUS_ORG_ID = \"\" as OrgId;\n","/**\n * Loads the three things every page under `[orgSlug]` needs: the organization,\n * the caller's `Actor` inside it, and the feature-flag snapshot.\n *\n * Owner D. Private to the tenant subtree. It exists so that no page has to\n * remember the order of operations — resolve the org, resolve the actor, assert\n * they agree, only then evaluate flags. Getting that order wrong is how a page\n * ends up evaluating flags against somebody else's plan.\n */\n\nimport { notFound } from \"next/navigation\";\nimport { getActor } from \"@/lib/actor\";\nimport { snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { resolveOrgBySlug } from \"@/server/services/organization-service\";\nimport type { FeatureFlagSnapshot } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\nexport type TenantContext = {\n  readonly org: Organization;\n  readonly actor: Actor;\n  readonly flags: FeatureFlagSnapshot;\n};\n\n/**\n * A missing organization and an organization the caller cannot reach are the\n * same 404 on purpose: distinguishing them would leak which slugs exist.\n */\nexport async function loadTenantContext(orgSlug: string): Promise<TenantContext> {\n  const org = await resolveOrgBySlug(orgSlug);\n  if (org === null) {\n    notFound();\n  }\n\n  const actor = await getActor(orgSlug);\n  assertOrgScope(actor, org.id);\n\n  const flags = snapshotFlags(buildFlagContext(actor, org));\n  return { org, actor, flags };\n}\n","// This file is generated by next-core EcmascriptClientReferenceModule.\nimport { registerClientReference } from \"react-server-dom-turbopack/server\";\nexport const IssueRow = registerClientReference(\n    function() { throw new Error(\"Attempted to call IssueRow() from the server but IssueRow is on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.\"); },\n    \"[project]/corpus/taskflow/src/components/domain/issue/issue-row.tsx\",\n    \"IssueRow\",\n);\n","/**\n * Virtualised issue list; hides row actions the actor may not perform.\n *\n * Must call (do not reimplement): can\n */\nimport { EmptyState } from \"@/components/ui/empty-state\";\nimport {\n  Table,\n  TableBody,\n  TableHead,\n  TableHeaderCell,\n  TableRow,\n} from \"@/components/ui/table\";\nimport { can } from \"@/lib/permissions\";\nimport { isArchived } from \"@/lib/soft-delete\";\nimport type { IssueId } from \"@/types/common\";\nimport type { IssueWithRelations } from \"@/types/issue\";\nimport type { Actor, User } from \"@/types/member\";\nimport type { ReactElement } from \"react\";\nimport { organizationResource } from \"../permission/resources\";\nimport { IssueRow } from \"./issue-row\";\n\nexport type IssueListProps = {\n  issues: readonly IssueWithRelations[];\n  actor: Actor;\n  emptyLabel?: string;\n  onArchive?: (issueId: IssueId) => void;\n  /** Assignee lookup for the rows; the page joins users once, not per row. */\n  users?: Readonly<Record<string, User>>;\n};\n\nconst COLUMNS: readonly string[] = [\n  \"#\",\n  \"Title\",\n  \"Status\",\n  \"Priority\",\n  \"Assignee\",\n  \"Due\",\n  \"\",\n];\n\nexport function IssueList(props: IssueListProps): ReactElement | null {\n  const { issues, actor, emptyLabel, onArchive, users = {} } = props;\n\n  // One coarse check for the whole list: an actor who cannot read issues at\n  // all sees the empty state rather than a table of hidden rows.\n  if (!can(actor, \"issue:read\", organizationResource(actor.orgId))) {\n    return (\n      <EmptyState\n        title=\"No access\"\n        description=\"Your role does not include issue access in this organization.\"\n      />\n    );\n  }\n\n  if (issues.length === 0) {\n    return (\n      <EmptyState\n        title={emptyLabel ?? \"No issues match this filter\"}\n        description=\"Adjust the filters or create the first issue.\"\n      />\n    );\n  }\n\n  // Live rows first; archived ones stay visible but sink to the bottom.\n  const ordered = [...issues].sort((a, b) => {\n    const archivedDelta =\n      Number(isArchived(a.issue)) - Number(isArchived(b.issue));\n    if (archivedDelta !== 0) return archivedDelta;\n    return b.issue.updatedAt.localeCompare(a.issue.updatedAt);\n  });\n\n  return (\n    <Table caption=\"Issues\">\n      <TableHead>\n        <TableRow>\n          {COLUMNS.map((column, index) => (\n            <TableHeaderCell key={column.length === 0 ? `col-${index}` : column}>\n              {column}\n            </TableHeaderCell>\n          ))}\n        </TableRow>\n      </TableHead>\n      <TableBody>\n        {ordered.map(({ issue }) => (\n          <IssueRow\n            key={issue.id}\n            issue={issue}\n            actor={actor}\n            assignee={\n              issue.assigneeId === null ? null : users[issue.assigneeId] ?? null\n            }\n            {...(onArchive !== undefined ? { onArchive } : {})}\n          />\n        ))}\n      </TableBody>\n    </Table>\n  );\n}\n","/**\n * Builders for the `PermissionResource` values the UI hands to `can()`.\n *\n * Every domain component that gates a control needs the same discriminated\n * object, and assembling it inline in twenty files is how ownership fields\n * quietly drift apart. These builders are the only place a component-side\n * resource is shaped — the decision itself still belongs to\n * `can()` in `@/lib/permissions`.\n */\nimport type { Comment } from \"@/types/comment\";\nimport type { CommentId, OrgId, UserId } from \"@/types/common\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Member, MemberWithUser } from \"@/types/member\";\nimport type { Project } from \"@/types/project\";\nimport type { PermissionResource } from \"@/types/permission\";\n\nexport function organizationResource(orgId: OrgId): PermissionResource {\n  return { kind: \"organization\", orgId };\n}\n\nexport function billingResource(orgId: OrgId): PermissionResource {\n  return { kind: \"billing\", orgId };\n}\n\nexport function activityResource(orgId: OrgId): PermissionResource {\n  return { kind: \"activity\", orgId };\n}\n\nexport function notificationResource(\n  orgId: OrgId,\n  recipientId: UserId,\n): PermissionResource {\n  return { kind: \"notification\", orgId, recipientId };\n}\n\nexport function memberResource(\n  member: Member | MemberWithUser,\n): PermissionResource {\n  return {\n    kind: \"member\",\n    orgId: member.orgId,\n    memberId: member.id,\n    targetUserId: member.userId,\n    targetRole: member.role,\n  };\n}\n\nexport function projectResource(project: Project): PermissionResource {\n  return {\n    kind: \"project\",\n    orgId: project.orgId,\n    projectId: project.id,\n    visibility: project.visibility,\n    leadId: project.leadId,\n  };\n}\n\nexport function issueResource(issue: Issue): PermissionResource {\n  return {\n    kind: \"issue\",\n    orgId: issue.orgId,\n    projectId: issue.projectId,\n    issueId: issue.id,\n    authorId: issue.authorId,\n    assigneeId: issue.assigneeId,\n  };\n}\n\nexport function commentResource(comment: Comment): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId: comment.orgId,\n    commentId: comment.id,\n    authorId: comment.authorId,\n  };\n}\n\n/**\n * A comment resource for a comment that does not exist yet (the composer asks\n * \"may I create a comment here?\" before there is an id to name).\n */\nexport function draftCommentResource(\n  orgId: OrgId,\n  authorId: UserId,\n): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId,\n    commentId: \"\" as CommentId,\n    authorId,\n  };\n}\n","/**\n * Private design tokens for `src/components/ui`.\n *\n * Not part of the public design-system surface: nothing outside\n * `src/components/ui/**` may import from here. Keeping the Tailwind class\n * strings in one place is what makes the variant maps below auditable —\n * a tone rename is a single-file change instead of a 30-file sweep.\n */\n\nexport const FOCUS_RING =\n  \"outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 focus-visible:ring-offset-surface\";\n\nexport const SURFACE = \"bg-surface border border-black/10 dark:border-white/15\";\n\nexport const OVERLAY = \"fixed inset-0 z-40 bg-black/40 backdrop-blur-[1px]\";\n\nexport const CONTROL_BASE =\n  \"w-full rounded-md border bg-surface px-3 text-sm text-black/85 dark:text-white/85 placeholder:text-black/40 disabled:cursor-not-allowed disabled:opacity-60\";\n\nexport const CONTROL_BORDER = \"border-black/15 dark:border-white/20\";\n\nexport const CONTROL_INVALID = \"border-red-500 focus-visible:ring-red-500\";\n\n/** Shared tone vocabulary. Badge, Alert and Toast all key off these names. */\nexport const TONE_TEXT = {\n  neutral: \"text-black/70 dark:text-white/70\",\n  brand: \"text-brand-600\",\n  info: \"text-brand-600\",\n  success: \"text-emerald-700\",\n  warning: \"text-amber-700\",\n  danger: \"text-red-700\",\n} as const;\n\nexport const TONE_SURFACE = {\n  neutral: \"bg-surface-muted text-black/75 border-black/10\",\n  brand: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  info: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  success: \"bg-emerald-50 text-emerald-800 border-emerald-500/25\",\n  warning: \"bg-amber-50 text-amber-800 border-amber-500/25\",\n  danger: \"bg-red-50 text-red-800 border-red-500/25\",\n} as const;\n\nexport const TONE_FILL = {\n  brand: \"bg-brand-500\",\n  warning: \"bg-amber-500\",\n  danger: \"bg-red-500\",\n} as const;\n\nexport type Tone = keyof typeof TONE_SURFACE;\n","/**\n * Zero-data placeholder.\n *\n * Owner A — design system. Server-renderable. The `action` slot takes an\n * already-permission-gated node: this component never decides whether the\n * viewer may create anything.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { SURFACE } from \"./_lib/tokens\";\nimport { cn } from \"@/lib/cn\";\n\nexport type EmptyStateProps = { title: string; description?: string; icon?: ReactNode; action?: ReactNode };\n\nexport function EmptyState(props: EmptyStateProps): ReactElement | null {\n  const { title, description, icon, action } = props;\n\n  return (\n    <div\n      className={cn(\n        SURFACE,\n        \"flex flex-col items-center gap-2 rounded-lg border-dashed px-6 py-10 text-center\",\n      )}\n    >\n      {icon !== undefined ? (\n        <span aria-hidden=\"true\" className=\"text-black/30 dark:text-white/30\">\n          {icon}\n        </span>\n      ) : null}\n      <p className=\"text-sm font-semibold text-black/80 dark:text-white/80\">\n        {title}\n      </p>\n      {description !== undefined ? (\n        <p className=\"max-w-sm text-xs leading-5 text-black/55 dark:text-white/55\">\n          {description}\n        </p>\n      ) : null}\n      {action !== undefined ? <div className=\"mt-2\">{action}</div> : null}\n    </div>\n  );\n}\n","/**\n * Data table primitives (head/body/row/cell).\n *\n * Owner A — design system. Server-renderable. The wrapper owns the horizontal\n * scroll so a wide issue table never widens the dashboard shell.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { cn } from \"@/lib/cn\";\n\nexport type TableProps = { caption?: string; className?: string; children?: ReactNode };\n\ntype PartProps = { className?: string; children?: ReactNode };\n\nexport function Table(props: TableProps): ReactElement | null {\n  const { caption, className, children } = props;\n\n  return (\n    <div className=\"w-full overflow-x-auto\">\n      <table\n        className={cn(\n          \"w-full border-collapse text-left text-sm text-black/80 dark:text-white/80\",\n          className,\n        )}\n      >\n        {caption !== undefined ? (\n          <caption className=\"sr-only\">{caption}</caption>\n        ) : null}\n        {children}\n      </table>\n    </div>\n  );\n}\n\nexport function TableHead(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <thead\n      className={cn(\n        \"border-b border-black/10 bg-surface-muted text-xs uppercase tracking-wide text-black/55\",\n        className,\n      )}\n    >\n      {children}\n    </thead>\n  );\n}\n\nexport function TableBody(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <tbody className={cn(\"divide-y divide-black/8\", className)}>\n      {children}\n    </tbody>\n  );\n}\n\nexport function TableRow(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <tr className={cn(\"transition-colors hover:bg-surface-muted/70\", className)}>\n      {children}\n    </tr>\n  );\n}\n\nexport function TableHeaderCell(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return (\n    <th scope=\"col\" className={cn(\"px-3 py-2 font-medium\", className)}>\n      {children}\n    </th>\n  );\n}\n\nexport function TableCell(props: PartProps): ReactElement | null {\n  const { className, children } = props;\n  return <td className={cn(\"px-3 py-2 align-middle\", className)}>{children}</td>;\n}\n","/**\n * Resolves the request's `Actor` for a given org slug, or throws\n * `unauthorized` / `forbidden`. Every Server Action starts here.\n *\n * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so\n * this module is the seam between \"there is an HTTP request with a cookie\"\n * and the rest of the app, which knows nothing about requests.\n */\nimport { getSessionPrincipal } from \"@/lib/session\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { findOrgById } from \"@/server/repositories/organization-repository\";\nimport { resolveActorForOrg } from \"@/server/services/session-service\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Actor } from \"@/types/member\";\n\n/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */\nexport class UnauthorizedError extends Error {\n  readonly code = \"unauthorized\" as const;\n\n  constructor(message = \"Sign in to continue.\") {\n    super(message);\n    this.name = \"UnauthorizedError\";\n  }\n}\n\n/** Thrown when the session is valid but has no membership in the target org. */\nexport class NoMembershipError extends Error {\n  readonly code = \"forbidden\" as const;\n\n  constructor(readonly orgSlug: string) {\n    super(`You are not a member of \"${orgSlug}\".`);\n    this.name = \"NoMembershipError\";\n  }\n}\n\n/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */\nexport async function getActor(orgSlug: string): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n\n  const actor = await resolveActorForOrg(principal, orgSlug);\n  if (actor === null) throw new NoMembershipError(orgSlug);\n\n  return actor;\n}\n\n/** Non-throwing variant, for layouts that render a signed-out state. */\nexport async function tryGetActor(orgSlug: string): Promise<Actor | null> {\n  try {\n    return await getActor(orgSlug);\n  } catch (error) {\n    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {\n      return null;\n    }\n    throw error;\n  }\n}\n\n/**\n * The `Actor` for an org already identified by id — used by Route Handlers\n * that receive an `orgId` in the payload rather than a slug in the path. The\n * session's active org must match, which `assertOrgScope()` enforces.\n *\n * `resolveActorForOrg` keys off the org *slug*, so the id is translated here\n * with a single repository lookup rather than by widening that signature —\n * the slug is the only handle the session layer knows.\n */\nexport async function requireActorFor(orgId: OrgId): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);\n\n  const org = await findOrgById(orgId);\n  if (org === null) throw new NoMembershipError(orgId);\n\n  const actor = await resolveActorForOrg(principal, org.slug);\n  if (actor === null) throw new NoMembershipError(org.slug);\n\n  assertOrgScope(actor, orgId);\n  return actor;\n}\n","import { z } from \"zod\";\n\n/**\n * Coercions for reading pagination out of `searchParams`. Remember that in\n * Next 16 `searchParams` is a Promise — `await` it before parsing.\n */\nexport const searchParamsPaginationSchema = z.object({\n  page: z.coerce.number().int().min(1).catch(1),\n  perPage: z.coerce.number().int().min(1).max(100).catch(25),\n  cursor: z.string().optional(),\n});\n\nexport const searchParamsSortSchema = z.object({\n  sort: z.string().max(40).optional(),\n  dir: z.enum([\"asc\", \"desc\"]).catch(\"desc\"),\n});\n\nexport function toOffset(page: number, perPage: number): number {\n  return (page - 1) * perPage;\n}\n\nexport type SearchParamsPagination = z.infer<\n  typeof searchParamsPaginationSchema\n>;\nexport type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;\n","/**\n * Comment rows, soft deleted so a deleted comment keeps its place in the thread.\n *\n * Must call (do not reimplement): archivePatch, shouldFilterArchived\n */\nimport { and, asc, count, desc, eq, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { archivePatch, shouldFilterArchived } from \"@/lib/soft-delete\";\nimport { comments, getDb, users } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toComment, toUser } from \"./_mappers\";\nimport type {\n  CreateCommentInput,\n  ListCommentsInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type {\n  Comment,\n  CommentThreadNode,\n  CommentWithAuthor,\n} from \"@/types/comment\";\nimport type { CommentId, IssueId, OrgId, Page, UserId } from \"@/types/common\";\n\nexport async function findCommentById(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment | null> {\n  const row = getDb()\n    .select()\n    .from(comments)\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .get();\n  return row ? toComment(row) : null;\n}\n\nexport async function listComments(\n  input: ListCommentsInput,\n): Promise<Page<CommentWithAuthor>> {\n  const db = getDb();\n  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };\n\n  const filters = compact(\n    orgPredicate(comments.orgId, input.orgId),\n    eq(comments.issueId, input.issueId),\n    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(comments)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(comments.createdAt), desc(comments.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),\n    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),\n  );\n}\n\n/**\n * The whole thread for one issue, in reading order: top-level comments oldest\n * first, each followed by its replies. Archived comments are kept so a reply\n * chain never loses its anchor — the UI renders them as \"deleted\".\n */\nexport async function listThread(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  const rows = getDb()\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(comments.createdAt))\n    .all();\n\n  const decorated: CommentWithAuthor[] = rows.map((row) => ({\n    ...toComment(row.comment),\n    author: toUser(row.author),\n  }));\n\n  const repliesBy = new Map<string, CommentWithAuthor[]>();\n  for (const comment of decorated) {\n    if (comment.parentId === null) continue;\n    const bucket = repliesBy.get(comment.parentId) ?? [];\n    bucket.push(comment);\n    repliesBy.set(comment.parentId, bucket);\n  }\n\n  return decorated\n    .filter((comment) => comment.parentId === null)\n    .map((comment) => ({\n      comment,\n      replies: repliesBy.get(comment.id) ?? [],\n    }));\n}\n\nexport async function countComments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(comments)\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n        isNull(comments.archivedAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertComment(\n  input: CreateCommentInput,\n  authorId: UserId,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(comments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      authorId,\n      body: input.body,\n      parentId: input.parentId,\n      editedAt: null,\n      mentionedUserIds: JSON.stringify(input.mentionedUserIds),\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toComment(row);\n}\n\n/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */\nexport async function updateComment(\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .update(comments)\n    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })\n    .where(\n      and(\n        orgPredicate(comments.orgId, input.orgId),\n        eq(comments.id, input.commentId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${input.commentId} not found`);\n  return toComment(row);\n}\n\nexport async function archiveComment(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment> {\n  const row = getDb()\n    .update(comments)\n    .set(archivePatch())\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${commentId} not found`);\n  return toComment(row);\n}\n","/**\n * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived\n */\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { emit } from \"@/lib/event-bus\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertNotArchived } from \"@/lib/soft-delete\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as labelRepo from \"@/server/repositories/label-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as attachmentRepo from \"@/server/repositories/attachment-repository\";\nimport {\n  actorEnvelope,\n  issueResource,\n  orgResource,\n  projectResource,\n  requireFound,\n} from \"./_support\";\nimport type {\n  AssignIssueInput,\n  ChangeIssueStatusInput,\n  CreateIssueInput,\n  IssueFilterInput,\n  MoveIssueInput,\n  UpdateIssueInput,\n} from \"@/schemas/issue\";\nimport type { IssueId, OrgId, Page, ProjectId } from \"@/types/common\";\nimport type { Issue, IssueBoardColumn, IssueWithRelations } from \"@/types/issue\";\nimport type { Actor } from \"@/types/member\";\n\n/**\n * Creates an issue after four gates: tenant scope, the `issue:create`\n * permission, a live parent project and the plan's per-project issue quota.\n * Only then is a number allocated and `issue.created` published — everything\n * reactive (notifications, search, webhooks, the audit log) hangs off that.\n */\nexport async function createIssue(\n  actor: Actor,\n  input: CreateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(input.orgId, input.projectId),\n    \"Project\",\n    input.projectId,\n  );\n  assertNotArchived(\"Project\", project.id, project);\n  assertCan(actor, \"issue:create\", projectResource(project));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n  const used = await issueRepo.countIssues(input.orgId, input.projectId);\n  if (wouldExceedLimit(org.plan, \"issuesPerProject\", used)) {\n    throw new Error(\n      `Plan ${org.plan} allows no more issues in project ${project.key}`,\n    );\n  }\n\n  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);\n  const issue = await issueRepo.insertIssue(input, actor.userId, number);\n\n  await emit(\"issue.created\", {\n    ...actorEnvelope(actor),\n    issueId: issue.id,\n    projectId: issue.projectId,\n    title: issue.title,\n    assigneeId: issue.assigneeId,\n    priority: issue.priority,\n  });\n\n  return issue;\n}\n\nexport async function updateIssue(\n  actor: Actor,\n  input: UpdateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.updateIssue(input);\n\n  await emit(\"issue.updated\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    changedFields: Object.keys(input).filter(\n      (key) => key !== \"orgId\" && key !== \"issueId\",\n    ),\n  });\n\n  return after;\n}\n\n/** Status transitions are an `issue:update`, not a separate permission. */\nexport async function changeIssueStatus(\n  actor: Actor,\n  input: ChangeIssueStatusInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  if (before.status === input.status) return before;\n\n  const after = await issueRepo.setIssueStatus(\n    input.orgId,\n    input.issueId,\n    input.status,\n  );\n\n  await emit(\"issue.status_changed\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    from: before.status,\n    to: after.status,\n  });\n\n  return after;\n}\n\n/**\n * Assignment has its own permission because a member may reassign work they\n * do not otherwise own. Un-assigning publishes `issue.updated` instead, since\n * `issue.assigned` carries a non-null assignee by contract.\n */\nexport async function assignIssue(\n  actor: Actor,\n  input: AssignIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:assign\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.setIssueAssignee(\n    input.orgId,\n    input.issueId,\n    input.assigneeId,\n  );\n\n  if (input.assigneeId === null) {\n    await emit(\"issue.updated\", {\n      ...actorEnvelope(actor),\n      issueId: after.id,\n      projectId: after.projectId,\n      changedFields: [\"assigneeId\"],\n    });\n    return after;\n  }\n\n  await emit(\"issue.assigned\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    previousAssigneeId: before.assigneeId,\n    assigneeId: input.assigneeId,\n  });\n\n  return after;\n}\n\nexport async function archiveIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<Issue> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:archive\", issueResource(issue));\n  assertNotArchived(\"Issue\", issue.id, issue);\n\n  const archived = await issueRepo.archiveIssue(orgId, issueId);\n\n  await emit(\"issue.archived\", {\n    ...actorEnvelope(actor),\n    issueId: archived.id,\n    projectId: archived.projectId,\n  });\n\n  return archived;\n}\n\n/**\n * Board drag-and-drop. The index is presentation-only — the board renders by\n * `updated_at` — so a move is a status change plus a touch.\n */\nexport async function moveIssue(\n  actor: Actor,\n  input: MoveIssueInput,\n): Promise<Issue> {\n  return changeIssueStatus(actor, {\n    orgId: input.orgId,\n    issueId: input.issueId,\n    status: input.toStatus,\n  });\n}\n\nexport async function getIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<IssueWithRelations> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:read\", issueResource(issue));\n\n  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);\n\n  return {\n    issue,\n    labels: labels[issue.id] ?? [],\n    commentCount: await commentRepo.countComments(orgId, issue.id),\n    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))\n      .length,\n  };\n}\n\nexport async function listIssues(\n  actor: Actor,\n  input: IssueFilterInput,\n): Promise<Page<Issue>> {\n  assertOrgScope(actor, input.orgId);\n  // A cross-project list is an org-wide read; per-project visibility is\n  // enforced when the caller opens an individual issue.\n  assertCan(actor, \"issue:read\", orgResource(input.orgId));\n  return issueRepo.listIssues(input);\n}\n\nexport async function getBoard(\n  actor: Actor,\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<readonly IssueBoardColumn[]> {\n  assertOrgScope(actor, orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(orgId, projectId),\n    \"Project\",\n    projectId,\n  );\n  assertCan(actor, \"issue:read\", projectResource(project));\n\n  return issueRepo.listBoardColumns(orgId, projectId);\n}\n","/**\n * Attachment metadata; the byte total feeds the `storageMb` quota check.\n */\nimport { and, asc, eq, sql } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { attachments, getDb } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { toAttachment } from \"./_mappers\";\nimport type { CreateAttachmentInput } from \"@/schemas/attachment\";\nimport type { AttachmentId, IssueId, OrgId, UserId } from \"@/types/common\";\nimport type { IssueAttachment } from \"@/types/issue\";\n\nexport async function listAttachments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly IssueAttachment[]> {\n  const rows = getDb()\n    .select()\n    .from(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(attachments.createdAt))\n    .all();\n  return rows.map(toAttachment);\n}\n\nexport async function insertAttachment(\n  input: CreateAttachmentInput,\n  uploadedBy: UserId,\n): Promise<IssueAttachment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(attachments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      filename: input.filename,\n      contentType: input.contentType,\n      sizeBytes: input.sizeBytes,\n      uploadedBy,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toAttachment(row);\n}\n\n/** Attachments are hard deleted — the bytes are gone, so the row goes too. */\nexport async function deleteAttachment(\n  orgId: OrgId,\n  attachmentId: AttachmentId,\n): Promise<void> {\n  getDb()\n    .delete(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.id, attachmentId),\n      ),\n    )\n    .run();\n}\n\n/** Total stored bytes for one tenant; `BillingService` converts to megabytes. */\nexport async function sumStorageBytes(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({\n      value: sql<number | null>`sum(${attachments.sizeBytes})`,\n    })\n    .from(attachments)\n    .where(orgPredicate(attachments.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n"],"names":["PENDING_ISSUE_ID","PENDING_PROJECT_ID","PENDING_COMMENT_ID","PENDING_MEMBER_ID","ANONYMOUS_ORG_ID","loadTenantContext","orgSlug","org","actor","id","flags","IssueRow","Error","COLUMNS","IssueList","props","issues","emptyLabel","onArchive","users","orgId","title","description","length","ordered","sort","a","b","archivedDelta","Number","issue","updatedAt","localeCompare","caption","map","column","index","assignee","assigneeId","und