./.next/server/chunks/ssr/corpus_taskflow_0aazpb_._.js.map:1:{"version":3,"sources":["../../../../../../corpus/taskflow/node_modules/.pnpm/next%4016.3.4_%40babel%2Bcore%407.29.7_%40types%2Bnode%4025.9.5_react-dom%4019.2.8_react%4019.2.8__react%4019.2.8/node_modules/next/src/build/webpack/loaders/next-flight-loader/action-validate.ts","../../../../../../corpus/taskflow/node_modules/.pnpm/next%4016.3.4_%40babel%2Bcore%407.29.7_%40types%2Bnode%4025.9.5_react-dom%4019.2.8_react%4019.2.8__react%4019.2.8/node_modules/next/src/build/webpack/loaders/next-flight-loader/server-reference.ts","../../../../../../corpus/taskflow/src/lib/errors.ts","../../../../../../corpus/taskflow/src/schemas/issue.ts","../../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts","../../../../../../corpus/taskflow/src/server/services/issue-service.ts","../../../../../../corpus/taskflow/src/server/repositories/attachment-repository.ts"],"sourcesContent":["// This function ensures that all the exported values are valid server actions,\n// during the runtime. By definition all actions are required to be async\n// functions, but here we can only check that they are functions.\nexport function ensureServerEntryExports(actions: any[]) {\n  for (let i = 0; i < actions.length; i++) {\n    const action = actions[i]\n    if (typeof action !== 'function') {\n      throw new Error(\n        `A \"use server\" file can only export async functions, found ${typeof action}.\\nRead more: https://nextjs.org/docs/messages/invalid-use-server-value`\n      )\n    }\n  }\n}\n","/* eslint-disable import/no-extraneous-dependencies */\nexport { registerServerReference } from 'react-server-dom-webpack/server'\n","/**\n * Maps thrown domain errors onto `AppErrorShape`.\n *\n * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,\n * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,\n * `ZodError`); Server Actions and Route Handlers never propagate those to the\n * client. Everything funnels through `toAppError()` so one thrown class maps\n * to exactly one `ErrorCode` and one HTTP status, app-wide.\n */\nimport { FeatureDisabledError } from \"@/lib/feature-flags\";\nimport { PermissionDeniedError } from \"@/lib/permissions\";\nimport { InvalidSlugError } from \"@/lib/slug\";\nimport { AlreadyArchivedError } from \"@/lib/soft-delete\";\nimport { TenantScopeError } from \"@/lib/tenant\";\nimport type { ActionResult, AppErrorShape, ErrorCode } from \"@/types/api\";\nimport { ZodError, type ZodIssue } from \"zod\";\n\nexport const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {\n  unauthorized: 401,\n  forbidden: 403,\n  not_found: 404,\n  validation_failed: 422,\n  conflict: 409,\n  rate_limited: 429,\n  plan_limit_exceeded: 402,\n  tenant_scope_violation: 403,\n  internal_error: 500,\n};\n\n/** True for the error classes this module knows how to translate faithfully. */\nexport function isDomainError(error: unknown): boolean {\n  return (\n    error instanceof PermissionDeniedError ||\n    error instanceof TenantScopeError ||\n    error instanceof FeatureDisabledError ||\n    error instanceof AlreadyArchivedError ||\n    error instanceof InvalidSlugError ||\n    error instanceof ZodError\n  );\n}\n\n/** Collapses a `ZodError` into the `field → messages` map forms consume. */\nexport function fieldErrorsFromZod(\n  error: ZodError,\n): Readonly<Record<string, readonly string[]>> {\n  const fields: Record<string, string[]> = {};\n  for (const issue of error.issues as readonly ZodIssue[]) {\n    const key = issue.path.length === 0 ? \"_root\" : issue.path.join(\".\");\n    (fields[key] ??= []).push(issue.message);\n  }\n  return fields;\n}\n\nexport function toAppError(error: unknown): AppErrorShape {\n  if (error instanceof ZodError) {\n    return {\n      code: \"validation_failed\",\n      message: \"Please correct the highlighted fields.\",\n      fieldErrors: fieldErrorsFromZod(error),\n    };\n  }\n\n  if (error instanceof PermissionDeniedError) {\n    return {\n      code: \"forbidden\",\n      message: error.message,\n      meta: {\n        action: error.action,\n        resourceKind: error.decision.resourceKind,\n        reason: error.decision.reason,\n      },\n    };\n  }\n\n  if (error instanceof TenantScopeError) {\n    return {\n      code: \"tenant_scope_violation\",\n      message: \"That resource belongs to a different organization.\",\n      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },\n    };\n  }\n\n  if (error instanceof FeatureDisabledError) {\n    return {\n      code: \"forbidden\",\n      message: error.message,\n      meta: { flag: error.flag },\n    };\n  }\n\n  if (error instanceof AlreadyArchivedError) {\n    return {\n      code: \"conflict\",\n      message: error.message,\n      meta: { entity: error.entity, id: error.id },\n    };\n  }\n\n  if (error instanceof InvalidSlugError) {\n    return {\n      code: \"validation_failed\",\n      message: error.message,\n      fieldErrors: { slug: [error.message] },\n      meta: { value: error.value },\n    };\n  }\n\n  return {\n    code: \"internal_error\",\n    message:\n      error instanceof Error ? error.message : \"Something went wrong. Try again.\",\n  };\n}\n\n/** The failure envelope a Server Action returns instead of throwing. */\nexport function toActionResult(error: unknown): ActionResult<never> {\n  return {\n    ok: false,\n    error: toAppError(error),\n    submittedAt: new Date().toISOString(),\n  };\n}\n","import { z } from \"zod\";\nimport type { IssuePriority, IssueStatus } from \"@/types/issue\";\nimport {\n  archiveScopeSchema,\n  isoTimestampSchema,\n  issueIdSchema,\n  labelIdSchema,\n  orgIdSchema,\n  pageRequestSchema,\n  projectIdSchema,\n  userIdSchema,\n} from \"./common\";\n\nexport const issueStatusSchema = z.enum([\n  \"backlog\",\n  \"todo\",\n  \"in_progress\",\n  \"in_review\",\n  \"done\",\n  \"canceled\",\n]);\n\nexport const issuePrioritySchema = z.enum([\n  \"none\",\n  \"low\",\n  \"medium\",\n  \"high\",\n  \"urgent\",\n]);\n\nexport const createIssueSchema = z.object({\n  orgId: orgIdSchema,\n  projectId: projectIdSchema,\n  title: z.string().min(3, \"give the issue a title\").max(200),\n  description: z.string().max(20_000).nullable().default(null),\n  status: issueStatusSchema.default(\"backlog\"),\n  priority: issuePrioritySchema.default(\"none\"),\n  assigneeId: userIdSchema.nullable().default(null),\n  parentId: issueIdSchema.nullable().default(null),\n  estimate: z.number().int().min(0).max(100).nullable().default(null),\n  dueAt: isoTimestampSchema.nullable().default(null),\n  labelIds: z.array(labelIdSchema).max(20).default([]),\n});\n\nexport const updateIssueSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n  title: z.string().min(3).max(200).optional(),\n  description: z.string().max(20_000).nullable().optional(),\n  priority: issuePrioritySchema.optional(),\n  estimate: z.number().int().min(0).max(100).nullable().optional(),\n  dueAt: isoTimestampSchema.nullable().optional(),\n  labelIds: z.array(labelIdSchema).max(20).optional(),\n});\n\nexport const changeIssueStatusSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n  status: issueStatusSchema,\n});\n\nexport const assignIssueSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n  assigneeId: userIdSchema.nullable(),\n});\n\nexport const archiveIssueSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n});\n\nexport const issueFilterSchema = z\n  .object({\n    orgId: orgIdSchema,\n    projectId: projectIdSchema.optional(),\n    status: z.array(issueStatusSchema).optional(),\n    priority: z.array(issuePrioritySchema).optional(),\n    assigneeId: userIdSchema.nullable().optional(),\n    authorId: userIdSchema.optional(),\n    labelIds: z.array(labelIdSchema).optional(),\n    query: z.string().max(200).optional(),\n    dueBefore: isoTimestampSchema.optional(),\n  })\n  .extend(pageRequestSchema.shape)\n  .extend(archiveScopeSchema.shape);\n\n/** Board drag-and-drop payload: move one issue into a column at an index. */\nexport const moveIssueSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n  toStatus: issueStatusSchema,\n  toIndex: z.number().int().min(0),\n});\n\nconst _statusParity: IssueStatus = \"in_review\" satisfies z.infer<\n  typeof issueStatusSchema\n>;\nconst _priorityParity: IssuePriority = \"urgent\" satisfies z.infer<\n  typeof issuePrioritySchema\n>;\nvoid _statusParity;\nvoid _priorityParity;\n\nexport type CreateIssueInput = z.infer<typeof createIssueSchema>;\nexport type UpdateIssueInput = z.infer<typeof updateIssueSchema>;\nexport type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;\nexport type AssignIssueInput = z.infer<typeof assignIssueSchema>;\nexport type IssueFilterInput = z.infer<typeof issueFilterSchema>;\nexport type MoveIssueInput = z.infer<typeof moveIssueSchema>;\n","/**\n * Comment rows, soft deleted so a deleted comment keeps its place in the thread.\n *\n * Must call (do not reimplement): archivePatch, shouldFilterArchived\n */\nimport { and, asc, count, desc, eq, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { archivePatch, shouldFilterArchived } from \"@/lib/soft-delete\";\nimport { comments, getDb, users } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toComment, toUser } from \"./_mappers\";\nimport type {\n  CreateCommentInput,\n  ListCommentsInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type {\n  Comment,\n  CommentThreadNode,\n  CommentWithAuthor,\n} from \"@/types/comment\";\nimport type { CommentId, IssueId, OrgId, Page, UserId } from \"@/types/common\";\n\nexport async function findCommentById(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment | null> {\n  const row = getDb()\n    .select()\n    .from(comments)\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .get();\n  return row ? toComment(row) : null;\n}\n\nexport async function listComments(\n  input: ListCommentsInput,\n): Promise<Page<CommentWithAuthor>> {\n  const db = getDb();\n  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };\n\n  const filters = compact(\n    orgPredicate(comments.orgId, input.orgId),\n    eq(comments.issueId, input.issueId),\n    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(comments)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(comments.createdAt), desc(comments.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),\n    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),\n  );\n}\n\n/**\n * The whole thread for one issue, in reading order: top-level comments oldest\n * first, each followed by its replies. Archived comments are kept so a reply\n * chain never loses its anchor — the UI renders them as \"deleted\".\n */\nexport async function listThread(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  const rows = getDb()\n    .select({ comment: comments, author: users })\n    .from(comments)\n    .innerJoin(users, eq(users.id, comments.authorId))\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(comments.createdAt))\n    .all();\n\n  const decorated: CommentWithAuthor[] = rows.map((row) => ({\n    ...toComment(row.comment),\n    author: toUser(row.author),\n  }));\n\n  const repliesBy = new Map<string, CommentWithAuthor[]>();\n  for (const comment of decorated) {\n    if (comment.parentId === null) continue;\n    const bucket = repliesBy.get(comment.parentId) ?? [];\n    bucket.push(comment);\n    repliesBy.set(comment.parentId, bucket);\n  }\n\n  return decorated\n    .filter((comment) => comment.parentId === null)\n    .map((comment) => ({\n      comment,\n      replies: repliesBy.get(comment.id) ?? [],\n    }));\n}\n\nexport async function countComments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(comments)\n    .where(\n      and(\n        orgPredicate(comments.orgId, orgId),\n        eq(comments.issueId, issueId),\n        isNull(comments.archivedAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertComment(\n  input: CreateCommentInput,\n  authorId: UserId,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(comments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      authorId,\n      body: input.body,\n      parentId: input.parentId,\n      editedAt: null,\n      mentionedUserIds: JSON.stringify(input.mentionedUserIds),\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toComment(row);\n}\n\n/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */\nexport async function updateComment(\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .update(comments)\n    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })\n    .where(\n      and(\n        orgPredicate(comments.orgId, input.orgId),\n        eq(comments.id, input.commentId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${input.commentId} not found`);\n  return toComment(row);\n}\n\nexport async function archiveComment(\n  orgId: OrgId,\n  commentId: CommentId,\n): Promise<Comment> {\n  const row = getDb()\n    .update(comments)\n    .set(archivePatch())\n    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Comment ${commentId} not found`);\n  return toComment(row);\n}\n","/**\n * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived\n */\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { emit } from \"@/lib/event-bus\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertNotArchived } from \"@/lib/soft-delete\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as labelRepo from \"@/server/repositories/label-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as attachmentRepo from \"@/server/repositories/attachment-repository\";\nimport {\n  actorEnvelope,\n  issueResource,\n  orgResource,\n  projectResource,\n  requireFound,\n} from \"./_support\";\nimport type {\n  AssignIssueInput,\n  ChangeIssueStatusInput,\n  CreateIssueInput,\n  IssueFilterInput,\n  MoveIssueInput,\n  UpdateIssueInput,\n} from \"@/schemas/issue\";\nimport type { IssueId, OrgId, Page, ProjectId } from \"@/types/common\";\nimport type { Issue, IssueBoardColumn, IssueWithRelations } from \"@/types/issue\";\nimport type { Actor } from \"@/types/member\";\n\n/**\n * Creates an issue after four gates: tenant scope, the `issue:create`\n * permission, a live parent project and the plan's per-project issue quota.\n * Only then is a number allocated and `issue.created` published — everything\n * reactive (notifications, search, webhooks, the audit log) hangs off that.\n */\nexport async function createIssue(\n  actor: Actor,\n  input: CreateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(input.orgId, input.projectId),\n    \"Project\",\n    input.projectId,\n  );\n  assertNotArchived(\"Project\", project.id, project);\n  assertCan(actor, \"issue:create\", projectResource(project));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n  const used = await issueRepo.countIssues(input.orgId, input.projectId);\n  if (wouldExceedLimit(org.plan, \"issuesPerProject\", used)) {\n    throw new Error(\n      `Plan ${org.plan} allows no more issues in project ${project.key}`,\n    );\n  }\n\n  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);\n  const issue = await issueRepo.insertIssue(input, actor.userId, number);\n\n  await emit(\"issue.created\", {\n    ...actorEnvelope(actor),\n    issueId: issue.id,\n    projectId: issue.projectId,\n    title: issue.title,\n    assigneeId: issue.assigneeId,\n    priority: issue.priority,\n  });\n\n  return issue;\n}\n\nexport async function updateIssue(\n  actor: Actor,\n  input: UpdateIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.updateIssue(input);\n\n  await emit(\"issue.updated\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    changedFields: Object.keys(input).filter(\n      (key) => key !== \"orgId\" && key !== \"issueId\",\n    ),\n  });\n\n  return after;\n}\n\n/** Status transitions are an `issue:update`, not a separate permission. */\nexport async function changeIssueStatus(\n  actor: Actor,\n  input: ChangeIssueStatusInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:update\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  if (before.status === input.status) return before;\n\n  const after = await issueRepo.setIssueStatus(\n    input.orgId,\n    input.issueId,\n    input.status,\n  );\n\n  await emit(\"issue.status_changed\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    from: before.status,\n    to: after.status,\n  });\n\n  return after;\n}\n\n/**\n * Assignment has its own permission because a member may reassign work they\n * do not otherwise own. Un-assigning publishes `issue.updated` instead, since\n * `issue.assigned` carries a non-null assignee by contract.\n */\nexport async function assignIssue(\n  actor: Actor,\n  input: AssignIssueInput,\n): Promise<Issue> {\n  assertOrgScope(actor, input.orgId);\n\n  const before = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"issue:assign\", issueResource(before));\n  assertNotArchived(\"Issue\", before.id, before);\n\n  const after = await issueRepo.setIssueAssignee(\n    input.orgId,\n    input.issueId,\n    input.assigneeId,\n  );\n\n  if (input.assigneeId === null) {\n    await emit(\"issue.updated\", {\n      ...actorEnvelope(actor),\n      issueId: after.id,\n      projectId: after.projectId,\n      changedFields: [\"assigneeId\"],\n    });\n    return after;\n  }\n\n  await emit(\"issue.assigned\", {\n    ...actorEnvelope(actor),\n    issueId: after.id,\n    projectId: after.projectId,\n    previousAssigneeId: before.assigneeId,\n    assigneeId: input.assigneeId,\n  });\n\n  return after;\n}\n\nexport async function archiveIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<Issue> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:archive\", issueResource(issue));\n  assertNotArchived(\"Issue\", issue.id, issue);\n\n  const archived = await issueRepo.archiveIssue(orgId, issueId);\n\n  await emit(\"issue.archived\", {\n    ...actorEnvelope(actor),\n    issueId: archived.id,\n    projectId: archived.projectId,\n  });\n\n  return archived;\n}\n\n/**\n * Board drag-and-drop. The index is presentation-only — the board renders by\n * `updated_at` — so a move is a status change plus a touch.\n */\nexport async function moveIssue(\n  actor: Actor,\n  input: MoveIssueInput,\n): Promise<Issue> {\n  return changeIssueStatus(actor, {\n    orgId: input.orgId,\n    issueId: input.issueId,\n    status: input.toStatus,\n  });\n}\n\nexport async function getIssue(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<IssueWithRelations> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"issue:read\", issueResource(issue));\n\n  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);\n\n  return {\n    issue,\n    labels: labels[issue.id] ?? [],\n    commentCount: await commentRepo.countComments(orgId, issue.id),\n    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))\n      .length,\n  };\n}\n\nexport async function listIssues(\n  actor: Actor,\n  input: IssueFilterInput,\n): Promise<Page<Issue>> {\n  assertOrgScope(actor, input.orgId);\n  // A cross-project list is an org-wide read; per-project visibility is\n  // enforced when the caller opens an individual issue.\n  assertCan(actor, \"issue:read\", orgResource(input.orgId));\n  return issueRepo.listIssues(input);\n}\n\nexport async function getBoard(\n  actor: Actor,\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<readonly IssueBoardColumn[]> {\n  assertOrgScope(actor, orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(orgId, projectId),\n    \"Project\",\n    projectId,\n  );\n  assertCan(actor, \"issue:read\", projectResource(project));\n\n  return issueRepo.listBoardColumns(orgId, projectId);\n}\n","/**\n * Attachment metadata; the byte total feeds the `storageMb` quota check.\n */\nimport { and, asc, eq, sql } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { attachments, getDb } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { toAttachment } from \"./_mappers\";\nimport type { CreateAttachmentInput } from \"@/schemas/attachment\";\nimport type { AttachmentId, IssueId, OrgId, UserId } from \"@/types/common\";\nimport type { IssueAttachment } from \"@/types/issue\";\n\nexport async function listAttachments(\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly IssueAttachment[]> {\n  const rows = getDb()\n    .select()\n    .from(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.issueId, issueId),\n      ),\n    )\n    .orderBy(asc(attachments.createdAt))\n    .all();\n  return rows.map(toAttachment);\n}\n\nexport async function insertAttachment(\n  input: CreateAttachmentInput,\n  uploadedBy: UserId,\n): Promise<IssueAttachment> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(attachments)\n    .values({\n      id: newId(),\n      orgId: input.orgId,\n      issueId: input.issueId,\n      filename: input.filename,\n      contentType: input.contentType,\n      sizeBytes: input.sizeBytes,\n      uploadedBy,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toAttachment(row);\n}\n\n/** Attachments are hard deleted — the bytes are gone, so the row goes too. */\nexport async function deleteAttachment(\n  orgId: OrgId,\n  attachmentId: AttachmentId,\n): Promise<void> {\n  getDb()\n    .delete(attachments)\n    .where(\n      and(\n        orgPredicate(attachments.orgId, orgId),\n        eq(attachments.id, attachmentId),\n      ),\n    )\n    .run();\n}\n\n/** Total stored bytes for one tenant; `BillingService` converts to megabytes. */\nexport async function sumStorageBytes(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({\n      value: sql<number | null>`sum(${attachments.sizeBytes})`,\n    })\n    .from(attachments)\n    .where(orgPredicate(attachments.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n"],"names":["ensureServerEntryExports","actions","i","length","action","Error","registerServerReference","HTTP_STATUS_BY_CODE","unauthorized","forbidden","not_found","validation_failed","conflict","rate_limited","plan_limit_exceeded","tenant_scope_violation","internal_error","isDomainError","error","fieldErrorsFromZod","fields","issue","issues","key","path","join","push","message","toAppError","code","fieldErrors","meta","resourceKind","decision","reason","expectedOrgId","actualOrgId","flag","entity","id","slug","value","toActionResult","ok","submittedAt","Date","toISOString","issueStatusSchema","enum","issuePrioritySchema","createIssueSchema","object","orgId","projectId","title","string","min","max","description","nullable","default","status","priority","assigneeId","parentId","estimate","number","int","dueAt","labelIds","array","updat