./.next/server/chunks/ssr/corpus_taskflow_src_13illra._.js.map:1:{"version":3,"sources":["../../../../../../corpus/taskflow/src/app/%28dashboard%29/%5BorgSlug%5D/_lib/tenant-context.ts","../../../../../../corpus/taskflow/src/app/%28dashboard%29/%5BorgSlug%5D/search/page.tsx","../../../../../../corpus/taskflow/src/schemas/search.ts","../../../../../../corpus/taskflow/src/server/services/search-service.ts","../../../../../../corpus/taskflow/src/server/repositories/search-repository.ts","../../../../../../corpus/taskflow/src/components/ui/_lib/tokens.ts","../../../../../../corpus/taskflow/src/components/ui/empty-state.tsx","../../../../../../corpus/taskflow/src/lib/actor.ts","../../../../../../corpus/taskflow/src/lib/rate-limit.ts","../../../../../../corpus/taskflow/src/server/repositories/comment-repository.ts"],"sourcesContent":["/**\n * Loads the three things every page under `[orgSlug]` needs: the organization,\n * the caller's `Actor` inside it, and the feature-flag snapshot.\n *\n * Owner D. Private to the tenant subtree. It exists so that no page has to\n * remember the order of operations — resolve the org, resolve the actor, assert\n * they agree, only then evaluate flags. Getting that order wrong is how a page\n * ends up evaluating flags against somebody else's plan.\n */\n\nimport { notFound } from \"next/navigation\";\nimport { getActor } from \"@/lib/actor\";\nimport { snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { resolveOrgBySlug } from \"@/server/services/organization-service\";\nimport type { FeatureFlagSnapshot } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\nexport type TenantContext = {\n  readonly org: Organization;\n  readonly actor: Actor;\n  readonly flags: FeatureFlagSnapshot;\n};\n\n/**\n * A missing organization and an organization the caller cannot reach are the\n * same 404 on purpose: distinguishing them would leak which slugs exist.\n */\nexport async function loadTenantContext(orgSlug: string): Promise<TenantContext> {\n  const org = await resolveOrgBySlug(orgSlug);\n  if (org === null) {\n    notFound();\n  }\n\n  const actor = await getActor(orgSlug);\n  assertOrgScope(actor, org.id);\n\n  const flags = snapshotFlags(buildFlagContext(actor, org));\n  return { org, actor, flags };\n}\n","/**\n * Full-page search results.\n *\n * Owner D. The command palette and this page share one action, so the flag\n * check has to live in both places — the palette narrows what it asks for, and\n * this page explains why comments are missing from the results.\n *\n * Must call (do not reimplement): isEnabled\n */\n\nimport Link from \"next/link\";\nimport type { Metadata } from \"next\";\nimport { EmptyState } from \"@/components/ui/empty-state\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { searchQuerySchema } from \"@/schemas/search\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { search as runSearch } from \"@/server/services/search-service\";\nimport { loadTenantContext } from \"../_lib/tenant-context\";\n\ntype PageParams = { orgSlug: string };\n\nexport const dynamic = \"force-dynamic\";\n\nexport const metadata: Metadata = {\n  title: \"Search\",\n};\n\nconst RESULT_LIMIT = 30;\n\nexport default async function Page(props: {\n  params: Promise<PageParams>;\n  searchParams: Promise<Record<string, string | string[] | undefined>>;\n}) {\n  // Next.js 16: params and searchParams are Promises and MUST be awaited.\n  const { orgSlug } = await props.params;\n  const search = await props.searchParams;\n\n  const { org, actor } = await loadTenantContext(orgSlug);\n\n  const advanced = isEnabled(\"advanced_search\", buildFlagContext(actor, org));\n  const query = typeof search.q === \"string\" ? search.q : \"\";\n\n  if (query.length === 0) {\n    return (\n      <div className=\"space-y-8\">\n        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />\n        <EmptyState\n          title=\"Search this organization\"\n          description=\"Type at least one character to look through issues, and — on the higher plans — comments and projects too.\"\n        />\n      </div>\n    );\n  }\n\n  const parsed = searchQuerySchema.safeParse({\n    orgId: org.id,\n    q: query,\n    kinds: advanced ? [\"issue\", \"comment\", \"project\"] : [\"issue\"],\n    limit: RESULT_LIMIT,\n  });\n\n  if (!parsed.success) {\n    return (\n      <div className=\"space-y-8\">\n        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />\n        <EmptyState title=\"That query is not valid\" description=\"Try something shorter.\" />\n      </div>\n    );\n  }\n\n  const page = await runSearch(actor, parsed.data);\n\n  return (\n    <div className=\"space-y-8\">\n      <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />\n\n      {page.items.length === 0 ? (\n        <EmptyState title={`Nothing matches “${query}”`} />\n      ) : (\n        <ul className=\"space-y-4\">\n          {page.items.map((hit) => (\n            <li key={`${hit.kind}:${hit.id}`}>\n              <Link href={hit.href} className=\"block\">\n                <span className=\"text-xs uppercase tracking-wide text-slate-400\">\n                  {hit.kind}\n                </span>\n                <span className=\"mt-0.5 block text-sm font-medium\">\n                  {hit.title}\n                </span>\n                <span className=\"mt-0.5 block text-sm text-slate-600\">\n                  {hit.snippet}\n                </span>\n              </Link>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  );\n}\n\nfunction SearchHeader(props: {\n  orgSlug: string;\n  query: string;\n  advanced: boolean;\n}) {\n  return (\n    <header>\n      <h1 className=\"text-2xl font-semibold tracking-tight\">Search</h1>\n      <form action={`/${props.orgSlug}/search`} className=\"mt-4 max-w-md\">\n        <input\n          name=\"q\"\n          type=\"search\"\n          defaultValue={props.query}\n          placeholder=\"Search issues…\"\n          className=\"w-full rounded-md border border-slate-300 px-3 py-2 text-sm\"\n        />\n      </form>\n      {!props.advanced ? (\n        <p className=\"mt-2 text-xs text-slate-500\">\n          Comments and projects are searchable on the growth plan and above.\n        </p>\n      ) : null}\n    </header>\n  );\n}\n","import { z } from \"zod\";\nimport { orgIdSchema, pageRequestSchema, projectIdSchema } from \"./common\";\n\nexport const searchSubjectKindSchema = z.enum([\"issue\", \"comment\", \"project\"]);\n\nexport const searchQuerySchema = z\n  .object({\n    orgId: orgIdSchema,\n    q: z.string().min(1, \"type something to search\").max(200),\n    kinds: z.array(searchSubjectKindSchema).default([\"issue\"]),\n    projectId: projectIdSchema.optional(),\n  })\n  .extend(pageRequestSchema.shape);\n\nexport const reindexRequestSchema = z.object({\n  orgId: orgIdSchema,\n  subjectKind: searchSubjectKindSchema,\n  subjectId: z.string().min(1),\n});\n\nexport type SearchQueryInput = z.infer<typeof searchQuerySchema>;\nexport type ReindexRequestInput = z.infer<typeof reindexRequestSchema>;\n","/**\n * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit\n */\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { consumeRateLimit } from \"@/lib/rate-limit\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport * as searchRepo from \"@/server/repositories/search-repository\";\nimport { orgResource } from \"./_support\";\nimport type { SearchQueryInput } from \"@/schemas/search\";\nimport type { SearchSubjectKind } from \"@/server/repositories/search-repository\";\nimport type { Comment } from \"@/types/comment\";\nimport type { OrgId, Page } from \"@/types/common\";\nimport type { Unsubscribe } from \"@/types/event\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Actor } from \"@/types/member\";\nimport type { Project } from \"@/types/project\";\n\nexport type SearchHit = {\n  kind: SearchSubjectKind;\n  id: string;\n  title: string;\n  snippet: string;\n  href: string;\n};\n\n/** Characters of surrounding context kept on either side of a match. */\nconst SNIPPET_RADIUS = 60;\n\n/** Token bucket protecting the index from query bursts. */\nconst SEARCH_QUERY_BUCKET = \"search:query\";\n\n/**\n * Runs a query against the denormalised index. Field-scoped syntax\n * (`status:done`) is an `advanced_search` feature, so a query containing a\n * colon is rejected for plans that do not include it rather than silently\n * being treated as literal text.\n */\nexport async function search(\n  actor: Actor,\n  input: SearchQueryInput,\n): Promise<Page<SearchHit>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"issue:read\", orgResource(input.orgId));\n\n  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);\n  if (!verdict.allowed) {\n    throw new Error(\n      `Search rate limit reached; try again after ${verdict.resetAt}`,\n    );\n  }\n\n  const org = await orgRepo.findOrgById(input.orgId);\n  const advanced = isEnabled(\"advanced_search\", {\n    orgId: input.orgId,\n    userId: actor.userId,\n    plan: org?.plan ?? \"free\",\n    role: actor.role,\n    overrides: org?.settings.enabledFlagOverrides,\n  });\n\n  if (input.q.includes(\":\") && !advanced) {\n    throw new Error(\"Field-scoped search is not included in this plan\");\n  }\n\n  const page = await searchRepo.searchDocuments(input);\n\n  return {\n    items: page.items.map((row) => ({\n      kind: row.subjectKind,\n      id: row.subjectId,\n      title: row.content.split(\"\\n\")[0] ?? row.subjectId,\n      snippet: snippetAround(row.content, input.q),\n      href: hrefFor(row.subjectKind, row.subjectId),\n    })),\n    nextCursor: page.nextCursor,\n    total: page.total,\n  };\n}\n\nexport async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"issue\",\n    issue.id,\n    [issue.title, issue.description ?? \"\"].join(\"\\n\"),\n    issue.projectId,\n  );\n}\n\nexport async function indexComment(\n  orgId: OrgId,\n  comment: Comment,\n): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"comment\",\n    comment.id,\n    comment.body,\n    null,\n  );\n}\n\nexport async function indexProject(\n  orgId: OrgId,\n  project: Project,\n): Promise<void> {\n  await searchRepo.upsertSearchDocument(\n    orgId,\n    \"project\",\n    project.id,\n    [project.name, project.description ?? \"\"].join(\"\\n\"),\n    project.id,\n  );\n}\n\nexport async function removeFromIndex(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n): Promise<void> {\n  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);\n}\n\n/**\n * Keeps the index in step with writes. Every handler re-reads the row rather\n * than trusting the event payload, so a partially-applied write can never be\n * indexed as if it had succeeded.\n */\nexport function registerSearchListeners(): Unsubscribe {\n  const offs: Unsubscribe[] = [\n    subscribe(\"issue.created\", async (payload) => {\n      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n    subscribe(\"issue.updated\", async (payload) => {\n      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n    subscribe(\"issue.archived\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"issue\", payload.issueId);\n    }),\n    subscribe(\"comment.created\", async (payload) => {\n      const comment = await commentRepo.findCommentById(\n        payload.orgId,\n        payload.commentId,\n      );\n      if (comment) await indexComment(payload.orgId, comment);\n    }),\n    subscribe(\"comment.deleted\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"comment\", payload.commentId);\n    }),\n    subscribe(\"project.created\", async (payload) => {\n      const project = await projectRepo.findProjectById(\n        payload.orgId,\n        payload.projectId,\n      );\n      if (project) await indexProject(payload.orgId, project);\n    }),\n    subscribe(\"project.archived\", async (payload) => {\n      await removeFromIndex(payload.orgId, \"project\", payload.projectId);\n    }),\n    subscribe(\"search.reindex_requested\", async (payload) => {\n      if (payload.subjectKind !== \"issue\") return;\n      const issue = await issueRepo.findIssueById(\n        payload.orgId,\n        payload.subjectId as Issue[\"id\"],\n      );\n      if (issue) await indexIssue(payload.orgId, issue);\n    }),\n  ];\n\n  return () => {\n    for (const off of offs) off();\n  };\n}\n\nfunction hrefFor(kind: SearchSubjectKind, subjectId: string): string {\n  switch (kind) {\n    case \"issue\":\n      return `/issues/${subjectId}`;\n    case \"comment\":\n      return `/comments/${subjectId}`;\n    case \"project\":\n      return `/projects/${subjectId}`;\n  }\n}\n\nfunction snippetAround(content: string, query: string): string {\n  const at = content.toLowerCase().indexOf(query.toLowerCase());\n  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);\n\n  const start = Math.max(0, at - SNIPPET_RADIUS);\n  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);\n  return `${start > 0 ? \"…\" : \"\"}${content.slice(start, end)}${\n    end < content.length ? \"…\" : \"\"\n  }`;\n}\n","/**\n * Denormalised search index kept in step by `SearchService`.\n */\nimport { and, count, desc, eq, inArray, like } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, searchIndex } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport type { SearchQueryInput } from \"@/schemas/search\";\nimport type { SearchIndexRow } from \"@/server/db/schema/webhooks\";\nimport type { OrgId, Page, ProjectId } from \"@/types/common\";\n\n/**\n * Upsert by (org, kind, subject) rather than by row id: the indexer is called\n * on every write and must be idempotent.\n */\nexport async function upsertSearchDocument(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n  content: string,\n  projectId: ProjectId | null,\n): Promise<void> {\n  const db = getDb();\n  const indexedAt = toIsoTimestamp(new Date());\n\n  const existing = db\n    .select({ id: searchIndex.id })\n    .from(searchIndex)\n    .where(\n      and(\n        orgPredicate(searchIndex.orgId, orgId),\n        eq(searchIndex.subjectKind, subjectKind),\n        eq(searchIndex.subjectId, subjectId),\n      ),\n    )\n    .get();\n\n  if (existing) {\n    db.update(searchIndex)\n      .set({ content, projectId, indexedAt })\n      .where(eq(searchIndex.id, existing.id))\n      .run();\n    return;\n  }\n\n  db.insert(searchIndex)\n    .values({\n      id: newId(),\n      orgId,\n      subjectKind,\n      subjectId,\n      projectId,\n      content,\n      indexedAt,\n    })\n    .run();\n}\n\nexport async function deleteSearchDocument(\n  orgId: OrgId,\n  subjectKind: SearchSubjectKind,\n  subjectId: string,\n): Promise<void> {\n  getDb()\n    .delete(searchIndex)\n    .where(\n      and(\n        orgPredicate(searchIndex.orgId, orgId),\n        eq(searchIndex.subjectKind, subjectKind),\n        eq(searchIndex.subjectId, subjectId),\n      ),\n    )\n    .run();\n}\n\n/**\n * Substring match over the denormalised content column. Deliberately simple —\n * the index is a convenience layer, not a search engine, and the tenant filter\n * is what actually matters here.\n */\nexport async function searchDocuments(\n  input: SearchQueryInput,\n): Promise<Page<SearchIndexRow>> {\n  const db = getDb();\n  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };\n\n  const filters = compact(\n    orgPredicate(searchIndex.orgId, input.orgId),\n    like(searchIndex.content, `%${input.q}%`),\n    input.kinds.length === 0\n      ? undefined\n      : inArray(searchIndex.subjectKind, [...input.kinds]),\n    input.projectId === undefined\n      ? undefined\n      : eq(searchIndex.projectId, input.projectId),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(searchIndex)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(searchIndex)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(\n    rows,\n    input.limit,\n    total?.value ?? 0,\n    (row) => row,\n    (row) => ({ id: row.id, sortValue: row.indexedAt }),\n  );\n}\n\n/** Drift alarm input: how many documents this org currently has indexed. */\nexport async function countIndexed(orgId: OrgId): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(searchIndex)\n    .where(orgPredicate(searchIndex.orgId, orgId))\n    .get();\n  return row?.value ?? 0;\n}\n\nexport type SearchSubjectKind = 'issue' | 'comment' | 'project';\n","/**\n * Private design tokens for `src/components/ui`.\n *\n * Not part of the public design-system surface: nothing outside\n * `src/components/ui/**` may import from here. Keeping the Tailwind class\n * strings in one place is what makes the variant maps below auditable —\n * a tone rename is a single-file change instead of a 30-file sweep.\n */\n\nexport const FOCUS_RING =\n  \"outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 focus-visible:ring-offset-surface\";\n\nexport const SURFACE = \"bg-surface border border-black/10 dark:border-white/15\";\n\nexport const OVERLAY = \"fixed inset-0 z-40 bg-black/40 backdrop-blur-[1px]\";\n\nexport const CONTROL_BASE =\n  \"w-full rounded-md border bg-surface px-3 text-sm text-black/85 dark:text-white/85 placeholder:text-black/40 disabled:cursor-not-allowed disabled:opacity-60\";\n\nexport const CONTROL_BORDER = \"border-black/15 dark:border-white/20\";\n\nexport const CONTROL_INVALID = \"border-red-500 focus-visible:ring-red-500\";\n\n/** Shared tone vocabulary. Badge, Alert and Toast all key off these names. */\nexport const TONE_TEXT = {\n  neutral: \"text-black/70 dark:text-white/70\",\n  brand: \"text-brand-600\",\n  info: \"text-brand-600\",\n  success: \"text-emerald-700\",\n  warning: \"text-amber-700\",\n  danger: \"text-red-700\",\n} as const;\n\nexport const TONE_SURFACE = {\n  neutral: \"bg-surface-muted text-black/75 border-black/10\",\n  brand: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  info: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  success: \"bg-emerald-50 text-emerald-800 border-emerald-500/25\",\n  warning: \"bg-amber-50 text-amber-800 border-amber-500/25\",\n  danger: \"bg-red-50 text-red-800 border-red-500/25\",\n} as const;\n\nexport const TONE_FILL = {\n  brand: \"bg-brand-500\",\n  warning: \"bg-amber-500\",\n  danger: \"bg-red-500\",\n} as const;\n\nexport type Tone = keyof typeof TONE_SURFACE;\n","/**\n * Zero-data placeholder.\n *\n * Owner A — design system. Server-renderable. The `action` slot takes an\n * already-permission-gated node: this component never decides whether the\n * viewer may create anything.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { SURFACE } from \"./_lib/tokens\";\nimport { cn } from \"@/lib/cn\";\n\nexport type EmptyStateProps = { title: string; description?: string; icon?: ReactNode; action?: ReactNode };\n\nexport function EmptyState(props: EmptyStateProps): ReactElement | null {\n  const { title, description, icon, action } = props;\n\n  return (\n    <div\n      className={cn(\n        SURFACE,\n        \"flex flex-col items-center gap-2 rounded-lg border-dashed px-6 py-10 text-center\",\n      )}\n    >\n      {icon !== undefined ? (\n        <span aria-hidden=\"true\" className=\"text-black/30 dark:text-white/30\">\n          {icon}\n        </span>\n      ) : null}\n      <p className=\"text-sm font-semibold text-black/80 dark:text-white/80\">\n        {title}\n      </p>\n      {description !== undefined ? (\n        <p className=\"max-w-sm text-xs leading-5 text-black/55 dark:text-white/55\">\n          {description}\n        </p>\n      ) : null}\n      {action !== undefined ? <div className=\"mt-2\">{action}</div> : null}\n    </div>\n  );\n}\n","/**\n * Resolves the request's `Actor` for a given org slug, or throws\n * `unauthorized` / `forbidden`. Every Server Action starts here.\n *\n * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so\n * this module is the seam between \"there is an HTTP request with a cookie\"\n * and the rest of the app, which knows nothing about requests.\n */\nimport { getSessionPrincipal } from \"@/lib/session\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { findOrgById } from \"@/server/repositories/organization-repository\";\nimport { resolveActorForOrg } from \"@/server/services/session-service\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Actor } from \"@/types/member\";\n\n/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */\nexport class UnauthorizedError extends Error {\n  readonly code = \"unauthorized\" as const;\n\n  constructor(message = \"Sign in to continue.\") {\n    super(message);\n    this.name = \"UnauthorizedError\";\n  }\n}\n\n/** Thrown when the session is valid but has no membership in the target org. */\nexport class NoMembershipError extends Error {\n  readonly code = \"forbidden\" as const;\n\n  constructor(readonly orgSlug: string) {\n    super(`You are not a member of \"${orgSlug}\".`);\n    this.name = \"NoMembershipError\";\n  }\n}\n\n/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */\nexport async function getActor(orgSlug: string): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n\n  const actor = await resolveActorForOrg(principal, orgSlug);\n  if (actor === null) throw new NoMembershipError(orgSlug);\n\n  return actor;\n}\n\n/** Non-throwing variant, for layouts that render a signed-out state. */\nexport async function tryGetActor(orgSlug: string): Promise<Actor | null> {\n  try {\n    return await getActor(orgSlug);\n  } catch (error) {\n    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {\n      return null;\n    }\n    throw error;\n  }\n}\n\n/**\n * The `Actor` for an org already identified by id — used by Route Handlers\n * that receive an `orgId` in the payload rather than a slug in the path. The\n * session's active org must match, which `assertOrgScope()` enforces.\n *\n * `resolveActorForOrg` keys off the org *slug*, so the id is translated here\n * with a single repository lookup rather than by widening that signature —\n * the slug is the only handle the session layer knows.\n */\nexport async function requireActorFor(orgId: OrgId): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);\n\n  const org = await findOrgById(orgId);\n  if (org === null) throw new NoMembershipError(orgId);\n\n  const actor = await resolveActorForOrg(principal, org.slug);\n  if (actor === null) throw new NoMembershipError(org.slug);\n\n  assertOrgScope(actor, orgId);\n  return actor;\n}\n","/**\n * Token-bucket limiter applied to invites, comments, search and password\n * resets.\n *\n * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow\n * runs single-writer, and the corpus has no external cache. Capacity scales\n * with the org's plan through `getPlanLimits()`, so a growth org is not held\n * to a free org's ceiling; the per-bucket shape below is the base rate.\n */\nimport { getPlanLimits } from \"@/config/plan-limits\";\nimport type { PlanId } from \"@/types/billing\";\nimport type { IsoTimestamp, OrgId } from \"@/types/common\";\nimport { toIsoTimestamp } from \"@/types/common\";\n\nexport type RateLimitVerdict = {\n  allowed: boolean;\n  remaining: number;\n  resetAt: IsoTimestamp;\n};\n\nexport type RateLimitConfig = { capacity: number; refillPerMinute: number };\n\nexport const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {\n  \"member:invite\": { capacity: 20, refillPerMinute: 2 },\n  \"comment:create\": { capacity: 60, refillPerMinute: 20 },\n  \"issue:create\": { capacity: 60, refillPerMinute: 20 },\n  \"search:query\": { capacity: 120, refillPerMinute: 60 },\n  \"auth:password-reset\": { capacity: 5, refillPerMinute: 1 },\n  \"webhook:deliver\": { capacity: 100, refillPerMinute: 50 },\n};\n\n/** Applied to any key not in the table above. */\nconst DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };\n\ntype BucketState = { tokens: number; updatedAt: number };\n\nconst buckets = new Map<string, BucketState>();\n\n/** Plan-aware org context; services set this when they know the org's plan. */\nconst planByOrg = new Map<OrgId, PlanId>();\n\n/** Records an org's plan so subsequent bucket sizes scale with its quota. */\nexport function setOrgPlan(orgId: OrgId, plan: PlanId): void {\n  planByOrg.set(orgId, plan);\n}\n\nexport function getBucketConfig(bucketKey: string): RateLimitConfig {\n  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;\n}\n\n/**\n * Scales the base bucket by the org's hourly API allowance, so the limiter\n * and the plan catalogue can never drift apart: the plan is the source of\n * the ceiling, this table only sets the relative shape.\n */\nfunction configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {\n  const base = getBucketConfig(bucketKey);\n  const plan = planByOrg.get(orgId) ?? \"free\";\n  const hourly = getPlanLimits(plan).apiRequestsPerHour;\n  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;\n\n  return {\n    capacity: Math.min(base.capacity * factor, base.capacity * 100),\n    refillPerMinute: Math.min(\n      base.refillPerMinute * factor,\n      base.refillPerMinute * 100,\n    ),\n  };\n}\n\n/**\n * Spends `cost` tokens from the bucket, refilling first for the elapsed time.\n * Async because the production limiter is expected to move behind a store —\n * every call site already awaits it.\n */\nexport async function consumeRateLimit(\n  orgId: OrgId,\n  bucketKey: string,\n  cost = 1,\n): Promise<RateLimitVerdict> {\n  const config = configFor(orgId, bucketKey);\n  const key = `${orgId}:${bucketKey}`;\n  const nowMs = Date.now();\n\n  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };\n  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;\n  const tokens = Math.min(\n    config.capacity,\n    state.tokens + elapsedMinutes * config.refillPerMinute,\n  );\n\n  const allowed = tokens >= cost;\n  const remaining = allowed ? tokens - cost : tokens;\n  buckets.set(key, { tokens: remaining, update