./.next/server/chunks/ssr/corpus_taskflow_src_1r62-7w._.js.map:1:{"version":3,"sources":["../../../../../../corpus/taskflow/src/app/%28dashboard%29/%5BorgSlug%5D/_lib/tenant-context.ts","../../../../../../corpus/taskflow/src/app/%28dashboard%29/%5BorgSlug%5D/activity/page.tsx","../../../../../../corpus/taskflow/src/components/domain/activity/activity-feed.tsx","../../../../../../corpus/taskflow/src/components/domain/activity/activity-labels.ts","../../../../../../corpus/taskflow/src/components/domain/permission/resources.ts","../../../../../../corpus/taskflow/src/components/ui/_lib/tokens.ts","../../../../../../corpus/taskflow/src/components/ui/avatar.tsx","../../../../../../corpus/taskflow/src/components/ui/button.tsx/__nextjs-internal-proxy.mjs","../../../../../../corpus/taskflow/src/components/ui/empty-state.tsx","../../../../../../corpus/taskflow/src/lib/actor.ts","../../../../../../corpus/taskflow/src/schemas/pagination.ts","../../../../../../corpus/taskflow/src/server/services/member-service.ts"],"sourcesContent":["/**\n * Loads the three things every page under `[orgSlug]` needs: the organization,\n * the caller's `Actor` inside it, and the feature-flag snapshot.\n *\n * Owner D. Private to the tenant subtree. It exists so that no page has to\n * remember the order of operations — resolve the org, resolve the actor, assert\n * they agree, only then evaluate flags. Getting that order wrong is how a page\n * ends up evaluating flags against somebody else's plan.\n */\n\nimport { notFound } from \"next/navigation\";\nimport { getActor } from \"@/lib/actor\";\nimport { snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { resolveOrgBySlug } from \"@/server/services/organization-service\";\nimport type { FeatureFlagSnapshot } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\nexport type TenantContext = {\n  readonly org: Organization;\n  readonly actor: Actor;\n  readonly flags: FeatureFlagSnapshot;\n};\n\n/**\n * A missing organization and an organization the caller cannot reach are the\n * same 404 on purpose: distinguishing them would leak which slugs exist.\n */\nexport async function loadTenantContext(orgSlug: string): Promise<TenantContext> {\n  const org = await resolveOrgBySlug(orgSlug);\n  if (org === null) {\n    notFound();\n  }\n\n  const actor = await getActor(orgSlug);\n  assertOrgScope(actor, org.id);\n\n  const flags = snapshotFlags(buildFlagContext(actor, org));\n  return { org, actor, flags };\n}\n","/**\n * Organization activity feed; requires `activity:read` and the `activity_feed`\n * flag.\n *\n * Owner D. Two gates that fail differently on purpose: a missing permission is\n * a 404 (the page should not exist for you), a disabled flag is an explanation\n * (the page exists, your plan does not include it).\n *\n * Must call (do not reimplement): can, isEnabled\n */\n\nimport { notFound } from \"next/navigation\";\nimport type { Metadata } from \"next\";\nimport { ActivityFeed } from \"@/components/domain/activity/activity-feed\";\nimport { EmptyState } from \"@/components/ui/empty-state\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { can } from \"@/lib/permissions\";\nimport { groupByDay, listActivity } from \"@/server/services/activity-service\";\nimport { buildFlagContext } from \"@/server/services/feature-flag-service\";\nimport { listMembers } from \"@/server/services/member-service\";\nimport { searchParamsPaginationSchema } from \"@/schemas/pagination\";\nimport type { User } from \"@/types/member\";\nimport { loadTenantContext } from \"../_lib/tenant-context\";\n\ntype PageParams = { orgSlug: string };\n\nexport const dynamic = \"force-dynamic\";\n\nexport const metadata: Metadata = {\n  title: \"Activity\",\n};\n\nconst MEMBER_LOOKUP_LIMIT = 100;\n\nexport default async function Page(props: {\n  params: Promise<PageParams>;\n  searchParams: Promise<Record<string, string | string[] | undefined>>;\n}) {\n  // Next.js 16: params and searchParams are Promises and MUST be awaited.\n  const { orgSlug } = await props.params;\n  const search = await props.searchParams;\n\n  const { org, actor } = await loadTenantContext(orgSlug);\n\n  if (!can(actor, \"activity:read\", { kind: \"activity\", orgId: org.id })) {\n    notFound();\n  }\n\n  if (!isEnabled(\"activity_feed\", buildFlagContext(actor, org))) {\n    return (\n      <EmptyState\n        title=\"The activity feed is not part of this plan\"\n        description=\"Upgrade in Settings → Billing to keep an audit trail of every change.\"\n      />\n    );\n  }\n\n  const pagination = searchParamsPaginationSchema.parse(search);\n\n  const [page, members] = await Promise.all([\n    listActivity(actor, {\n      orgId: org.id,\n      limit: pagination.perPage,\n      cursor: pagination.cursor ?? null,\n    }),\n    listMembers(actor, { orgId: org.id, limit: MEMBER_LOOKUP_LIMIT }),\n  ]);\n\n  const actors: Record<string, User> = {};\n  for (const member of members.items) {\n    actors[member.userId] = member.user;\n  }\n\n  return (\n    <div className=\"space-y-8\">\n      <header>\n        <h1 className=\"text-2xl font-semibold tracking-tight\">Activity</h1>\n        <p className=\"mt-1 text-sm text-slate-600\">\n          Every change made in {org.name}, newest first.\n        </p>\n      </header>\n\n      <ActivityFeed groups={groupByDay(page.items)} actors={actors} actor={actor} />\n    </div>\n  );\n}\n","/**\n * Grouped audit trail; the export button needs `activity:export`.\n *\n * Must call (do not reimplement): can, isEnabled\n */\nimport { Avatar } from \"@/components/ui/avatar\";\nimport { Button } from \"@/components/ui/button\";\nimport { EmptyState } from \"@/components/ui/empty-state\";\nimport { formatRelative } from \"@/lib/date\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { can } from \"@/lib/permissions\";\nimport type { ActivityGroup } from \"@/types/activity\";\nimport type { PlanId } from \"@/types/billing\";\nimport type { Actor, User } from \"@/types/member\";\nimport type { ReactElement } from \"react\";\nimport { activityResource } from \"../permission/resources\";\nimport { activityLabel } from \"./activity-labels\";\n\nexport type ActivityFeedProps = {\n  groups: readonly ActivityGroup[];\n  actors: Readonly<Record<string, User>>;\n  actor: Actor;\n  /** The org's plan, so the CSV flag can be evaluated for this tenant. */\n  plan?: PlanId;\n};\n\nexport function ActivityFeed(props: ActivityFeedProps): ReactElement | null {\n  const { groups, actors, actor, plan = \"free\" } = props;\n  const resource = activityResource(actor.orgId);\n\n  if (!can(actor, \"activity:read\", resource)) {\n    return (\n      <EmptyState\n        title=\"Activity is not visible to your role\"\n        description=\"Ask an administrator if you need the audit trail.\"\n      />\n    );\n  }\n\n  // Two independent gates: the plan must include CSV export, and the actor\n  // must hold `activity:export` (admin and above).\n  const exportEnabled =\n    isEnabled(\"csv_export\", {\n      orgId: actor.orgId,\n      userId: actor.userId,\n      plan,\n      role: actor.role,\n    }) && can(actor, \"activity:export\", resource);\n\n  if (groups.length === 0) {\n    return <EmptyState title=\"No activity recorded in this window\" />;\n  }\n\n  return (\n    <section className=\"activity-feed space-y-6\">\n      {exportEnabled ? (\n        <div className=\"flex justify-end\">\n          <Button variant=\"secondary\" size=\"sm\">\n            Export CSV\n          </Button>\n        </div>\n      ) : null}\n\n      {groups.map((group) => (\n        <div key={group.day}>\n          <h2 className=\"mb-2 text-sm font-medium text-neutral-500\">\n            {group.day}\n          </h2>\n          <ol className=\"space-y-2 border-l pl-4\">\n            {group.events.map((event) => {\n              const author =\n                event.actorId === null ? undefined : actors[event.actorId];\n              return (\n                <li key={event.id} className=\"flex items-start gap-2 text-sm\">\n                  {author !== undefined ? (\n                    <Avatar\n                      name={author.name}\n                      src={author.avatarUrl}\n                      size=\"xs\"\n                    />\n                  ) : null}\n                  <span>\n                    <strong>{author?.name ?? \"Taskflow\"}</strong>{\" \"}\n                    {activityLabel(event.action)} — {event.summary}\n                    <span className=\"ml-2 text-neutral-500\">\n                      {formatRelative(event.occurredAt)}\n                    </span>\n                  </span>\n                </li>\n              );\n            })}\n          </ol>\n        </div>\n      ))}\n    </section>\n  );\n}\n","/**\n * Presentation helpers for the audit trail.\n *\n * `ActivityEvent.summary` is written by the service layer and is authoritative;\n * these helpers only supply the verb chip and the day grouping the feed and the\n * per-issue panel both render, so the two views never disagree about what a\n * day boundary is.\n */\nimport type { ActivityAction, ActivityEvent, ActivityGroup } from \"@/types/activity\";\n\nexport const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {\n  \"organization.updated\": \"updated the organization\",\n  \"project.created\": \"created a project\",\n  \"project.updated\": \"updated a project\",\n  \"project.archived\": \"archived a project\",\n  \"project.restored\": \"restored a project\",\n  \"issue.created\": \"created an issue\",\n  \"issue.updated\": \"updated an issue\",\n  \"issue.status_changed\": \"changed status\",\n  \"issue.assigned\": \"assigned an issue\",\n  \"issue.archived\": \"archived an issue\",\n  \"issue.restored\": \"restored an issue\",\n  \"comment.created\": \"commented\",\n  \"comment.updated\": \"edited a comment\",\n  \"comment.deleted\": \"deleted a comment\",\n  \"member.invited\": \"invited a member\",\n  \"member.joined\": \"joined the organization\",\n  \"member.role_changed\": \"changed a role\",\n  \"member.removed\": \"removed a member\",\n  \"billing.plan_changed\": \"changed the plan\",\n  \"flag.toggled\": \"toggled a feature flag\",\n};\n\nexport function activityLabel(action: ActivityAction): string {\n  return ACTIVITY_LABELS[action] ?? action;\n}\n\n/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */\nexport function activityDay(event: ActivityEvent): string {\n  return event.occurredAt.slice(0, 10);\n}\n\n/**\n * Groups a flat event list into the day buckets `ActivityFeed` consumes,\n * newest day first and newest event first within a day.\n */\nexport function groupEventsByDay(\n  events: readonly ActivityEvent[],\n): readonly ActivityGroup[] {\n  const byDay = new Map<string, ActivityEvent[]>();\n\n  for (const event of events) {\n    const day = activityDay(event);\n    const bucket = byDay.get(day) ?? [];\n    bucket.push(event);\n    byDay.set(day, bucket);\n  }\n\n  return [...byDay.entries()]\n    .sort(([a], [b]) => b.localeCompare(a))\n    .map(([day, bucket]) => ({\n      day,\n      events: [...bucket].sort((a, b) =>\n        b.occurredAt.localeCompare(a.occurredAt),\n      ),\n    }));\n}\n","/**\n * Builders for the `PermissionResource` values the UI hands to `can()`.\n *\n * Every domain component that gates a control needs the same discriminated\n * object, and assembling it inline in twenty files is how ownership fields\n * quietly drift apart. These builders are the only place a component-side\n * resource is shaped — the decision itself still belongs to\n * `can()` in `@/lib/permissions`.\n */\nimport type { Comment } from \"@/types/comment\";\nimport type { CommentId, OrgId, UserId } from \"@/types/common\";\nimport type { Issue } from \"@/types/issue\";\nimport type { Member, MemberWithUser } from \"@/types/member\";\nimport type { Project } from \"@/types/project\";\nimport type { PermissionResource } from \"@/types/permission\";\n\nexport function organizationResource(orgId: OrgId): PermissionResource {\n  return { kind: \"organization\", orgId };\n}\n\nexport function billingResource(orgId: OrgId): PermissionResource {\n  return { kind: \"billing\", orgId };\n}\n\nexport function activityResource(orgId: OrgId): PermissionResource {\n  return { kind: \"activity\", orgId };\n}\n\nexport function notificationResource(\n  orgId: OrgId,\n  recipientId: UserId,\n): PermissionResource {\n  return { kind: \"notification\", orgId, recipientId };\n}\n\nexport function memberResource(\n  member: Member | MemberWithUser,\n): PermissionResource {\n  return {\n    kind: \"member\",\n    orgId: member.orgId,\n    memberId: member.id,\n    targetUserId: member.userId,\n    targetRole: member.role,\n  };\n}\n\nexport function projectResource(project: Project): PermissionResource {\n  return {\n    kind: \"project\",\n    orgId: project.orgId,\n    projectId: project.id,\n    visibility: project.visibility,\n    leadId: project.leadId,\n  };\n}\n\nexport function issueResource(issue: Issue): PermissionResource {\n  return {\n    kind: \"issue\",\n    orgId: issue.orgId,\n    projectId: issue.projectId,\n    issueId: issue.id,\n    authorId: issue.authorId,\n    assigneeId: issue.assigneeId,\n  };\n}\n\nexport function commentResource(comment: Comment): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId: comment.orgId,\n    commentId: comment.id,\n    authorId: comment.authorId,\n  };\n}\n\n/**\n * A comment resource for a comment that does not exist yet (the composer asks\n * \"may I create a comment here?\" before there is an id to name).\n */\nexport function draftCommentResource(\n  orgId: OrgId,\n  authorId: UserId,\n): PermissionResource {\n  return {\n    kind: \"comment\",\n    orgId,\n    commentId: \"\" as CommentId,\n    authorId,\n  };\n}\n","/**\n * Private design tokens for `src/components/ui`.\n *\n * Not part of the public design-system surface: nothing outside\n * `src/components/ui/**` may import from here. Keeping the Tailwind class\n * strings in one place is what makes the variant maps below auditable —\n * a tone rename is a single-file change instead of a 30-file sweep.\n */\n\nexport const FOCUS_RING =\n  \"outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 focus-visible:ring-offset-surface\";\n\nexport const SURFACE = \"bg-surface border border-black/10 dark:border-white/15\";\n\nexport const OVERLAY = \"fixed inset-0 z-40 bg-black/40 backdrop-blur-[1px]\";\n\nexport const CONTROL_BASE =\n  \"w-full rounded-md border bg-surface px-3 text-sm text-black/85 dark:text-white/85 placeholder:text-black/40 disabled:cursor-not-allowed disabled:opacity-60\";\n\nexport const CONTROL_BORDER = \"border-black/15 dark:border-white/20\";\n\nexport const CONTROL_INVALID = \"border-red-500 focus-visible:ring-red-500\";\n\n/** Shared tone vocabulary. Badge, Alert and Toast all key off these names. */\nexport const TONE_TEXT = {\n  neutral: \"text-black/70 dark:text-white/70\",\n  brand: \"text-brand-600\",\n  info: \"text-brand-600\",\n  success: \"text-emerald-700\",\n  warning: \"text-amber-700\",\n  danger: \"text-red-700\",\n} as const;\n\nexport const TONE_SURFACE = {\n  neutral: \"bg-surface-muted text-black/75 border-black/10\",\n  brand: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  info: \"bg-brand-50 text-brand-600 border-brand-500/25\",\n  success: \"bg-emerald-50 text-emerald-800 border-emerald-500/25\",\n  warning: \"bg-amber-50 text-amber-800 border-amber-500/25\",\n  danger: \"bg-red-50 text-red-800 border-red-500/25\",\n} as const;\n\nexport const TONE_FILL = {\n  brand: \"bg-brand-500\",\n  warning: \"bg-amber-500\",\n  danger: \"bg-red-500\",\n} as const;\n\nexport type Tone = keyof typeof TONE_SURFACE;\n","/**\n * User avatar falling back to initials.\n *\n * Owner A — design system. Server-renderable. The colour is derived from the\n * name so the same person keeps the same swatch across every list without the\n * server having to store one.\n */\nimport type { ReactElement } from \"react\";\nimport { cn } from \"@/lib/cn\";\n\nexport type AvatarProps = { name: string; src?: string | null; size?: 'xs' | 'sm' | 'md' | 'lg'; className?: string };\n\nconst SIZES = {\n  xs: \"h-5 w-5 text-[10px]\",\n  sm: \"h-6 w-6 text-[11px]\",\n  md: \"h-8 w-8 text-xs\",\n  lg: \"h-12 w-12 text-base\",\n} as const;\n\nconst SWATCHES = [\n  \"bg-brand-500\",\n  \"bg-emerald-600\",\n  \"bg-amber-600\",\n  \"bg-rose-600\",\n  \"bg-violet-600\",\n  \"bg-cyan-700\",\n] as const;\n\n/** First letter of the first two words, e.g. `\"Ada Lovelace\"` → `\"AL\"`. */\nexport function initialsOf(name: string): string {\n  const words = name.trim().split(/\\s+/).filter(Boolean).slice(0, 2);\n  if (words.length === 0) return \"?\";\n  return words.map((word) => word.charAt(0).toUpperCase()).join(\"\");\n}\n\nfunction swatchFor(name: string): string {\n  let hash = 0;\n  for (let i = 0; i < name.length; i += 1) {\n    hash = (hash * 31 + name.charCodeAt(i)) % 1_000_003;\n  }\n  return SWATCHES[hash % SWATCHES.length] ?? SWATCHES[0];\n}\n\nexport function Avatar(props: AvatarProps): ReactElement | null {\n  const { name, src, size = \"md\", className } = props;\n\n  const shared = cn(\n    \"inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full\",\n    SIZES[size],\n    className,\n  );\n\n  if (src) {\n    // Avatars come from arbitrary user-supplied URLs; next/image would need\n    // every one of those hosts configured up front, so a plain img wins here.\n    return (\n      /* eslint-disable-next-line @next/next/no-img-element */\n      <img src={src} alt={name} title={name} className={cn(shared, \"object-cover\")} />\n    );\n  }\n\n  return (\n    <span\n      role=\"img\"\n      aria-label={name}\n      title={name}\n      className={cn(shared, swatchFor(name), \"font-semibold text-white\")}\n    >\n      {initialsOf(name)}\n    </span>\n  );\n}\n","// This file is generated by next-core EcmascriptClientReferenceModule.\nimport { registerClientReference } from \"react-server-dom-turbopack/server\";\nexport const Button = registerClientReference(\n    function() { throw new Error(\"Attempted to call Button() from the server but Button is on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.\"); },\n    \"[project]/corpus/taskflow/src/components/ui/button.tsx\",\n    \"Button\",\n);\n","/**\n * Zero-data placeholder.\n *\n * Owner A — design system. Server-renderable. The `action` slot takes an\n * already-permission-gated node: this component never decides whether the\n * viewer may create anything.\n */\nimport type { ReactElement, ReactNode } from \"react\";\nimport { SURFACE } from \"./_lib/tokens\";\nimport { cn } from \"@/lib/cn\";\n\nexport type EmptyStateProps = { title: string; description?: string; icon?: ReactNode; action?: ReactNode };\n\nexport function EmptyState(props: EmptyStateProps): ReactElement | null {\n  const { title, description, icon, action } = props;\n\n  return (\n    <div\n      className={cn(\n        SURFACE,\n        \"flex flex-col items-center gap-2 rounded-lg border-dashed px-6 py-10 text-center\",\n      )}\n    >\n      {icon !== undefined ? (\n        <span aria-hidden=\"true\" className=\"text-black/30 dark:text-white/30\">\n          {icon}\n        </span>\n      ) : null}\n      <p className=\"text-sm font-semibold text-black/80 dark:text-white/80\">\n        {title}\n      </p>\n      {description !== undefined ? (\n        <p className=\"max-w-sm text-xs leading-5 text-black/55 dark:text-white/55\">\n          {description}\n        </p>\n      ) : null}\n      {action !== undefined ? <div className=\"mt-2\">{action}</div> : null}\n    </div>\n  );\n}\n","/**\n * Resolves the request's `Actor` for a given org slug, or throws\n * `unauthorized` / `forbidden`. Every Server Action starts here.\n *\n * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so\n * this module is the seam between \"there is an HTTP request with a cookie\"\n * and the rest of the app, which knows nothing about requests.\n */\nimport { getSessionPrincipal } from \"@/lib/session\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport { findOrgById } from \"@/server/repositories/organization-repository\";\nimport { resolveActorForOrg } from \"@/server/services/session-service\";\nimport type { OrgId } from \"@/types/common\";\nimport type { Actor } from \"@/types/member\";\n\n/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */\nexport class UnauthorizedError extends Error {\n  readonly code = \"unauthorized\" as const;\n\n  constructor(message = \"Sign in to continue.\") {\n    super(message);\n    this.name = \"UnauthorizedError\";\n  }\n}\n\n/** Thrown when the session is valid but has no membership in the target org. */\nexport class NoMembershipError extends Error {\n  readonly code = \"forbidden\" as const;\n\n  constructor(readonly orgSlug: string) {\n    super(`You are not a member of \"${orgSlug}\".`);\n    this.name = \"NoMembershipError\";\n  }\n}\n\n/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */\nexport async function getActor(orgSlug: string): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n\n  const actor = await resolveActorForOrg(principal, orgSlug);\n  if (actor === null) throw new NoMembershipError(orgSlug);\n\n  return actor;\n}\n\n/** Non-throwing variant, for layouts that render a signed-out state. */\nexport async function tryGetActor(orgSlug: string): Promise<Actor | null> {\n  try {\n    return await getActor(orgSlug);\n  } catch (error) {\n    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {\n      return null;\n    }\n    throw error;\n  }\n}\n\n/**\n * The `Actor` for an org already identified by id — used by Route Handlers\n * that receive an `orgId` in the payload rather than a slug in the path. The\n * session's active org must match, which `assertOrgScope()` enforces.\n *\n * `resolveActorForOrg` keys off the org *slug*, so the id is translated here\n * with a single repository lookup rather than by widening that signature —\n * the slug is the only handle the session layer knows.\n */\nexport async function requireActorFor(orgId: OrgId): Promise<Actor> {\n  const principal = await getSessionPrincipal();\n  if (principal === null) throw new UnauthorizedError();\n  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);\n\n  const org = await findOrgById(orgId);\n  if (org === null) throw new NoMembershipError(orgId);\n\n  const actor = await resolveActorForOrg(principal, org.slug);\n  if (actor === null) throw new NoMembershipError(org.slug);\n\n  assertOrgScope(actor, orgId);\n  return actor;\n}\n","import { z } from \"zod\";\n\n/**\n * Coercions for reading pagination out of `searchParams`. Remember that in\n * Next 16 `searchParams` is a Promise — `await` it before parsing.\n */\nexport const searchParamsPaginationSchema = z.object({\n  page: z.coerce.number().int().min(1).catch(1),\n  perPage: z.coerce.number().int().min(1).max(100).catch(25),\n  cursor: z.string().optional(),\n});\n\nexport const searchParamsSortSchema = z.object({\n  sort: z.string().max(40).optional(),\n  dir: z.enum([\"asc\", \"desc\"]).catch(\"desc\"),\n});\n\nexport function toOffset(page: number, perPage: number): number {\n  return (page - 1) * perPage;\n}\n\nexport type SearchParamsPagination = z.infer<\n  typeof searchParamsPaginationSchema\n>;\nexport type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;\n","/**\n * Membership and role changes, including the invariant that an organization always keeps one owner.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast\n */\nimport { emit } from \"@/lib/event-bus\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as memberRepo from \"@/server/repositories/member-repository\";\nimport { hasRoleAtLeast } from \"@/types/member\";\nimport { actorEnvelope, memberResource, requireFound } from \"./_support\";\nimport type {\n  ListMembersInput,\n  RemoveMemberInput,\n  UpdateMemberRoleInput,\n} from \"@/schemas/member\";\nimport type { MemberId, OrgId, Page, UserId } from \"@/types/common\";\nimport type { Actor, Member, MemberWithUser, Role } from \"@/types/member\";\n\n/** How many members are scanned when counting the remaining owners. */\nconst OWNER_SCAN_LIMIT = 100;\n\nexport async function listMembers(\n  actor: Actor,\n  input: ListMembersInput,\n): Promise<Page<MemberWithUser>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"member:read\", {\n    kind: \"organization\",\n    orgId: input.orgId,\n  });\n  return memberRepo.listMembers(input);\n}\n\n/**\n * Role changes carry two rules the permission matrix cannot express:\n * nobody may grant a role above their own, and the last owner may not be\n * demoted. Both are checked after `can()` has had its say.\n */\nexport async function updateMemberRole(\n  actor: Actor,\n  input: UpdateMemberRoleInput,\n): Promise<Member> {\n  assertOrgScope(actor, input.orgId);\n\n  const member = requireFound(\n    await memberRepo.findMemberById(input.orgId, input.memberId),\n    \"Member\",\n    input.memberId,\n  );\n  assertCan(actor, \"member:update_role\", memberResource(member));\n\n  if (!hasRoleAtLeast(actor.role, input.role)) {\n    throw new Error(\n      `A ${actor.role} cannot grant the ${input.role} role`,\n    );\n  }\n\n  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);\n\n  const updated = await memberRepo.updateMemberRole(\n    input.orgId,\n    input.memberId,\n    input.role,\n  );\n\n  await emit(\"member.role_changed\", {\n    ...actorEnvelope(actor),\n    memberId: updated.id,\n    from: member.role,\n    to: updated.role,\n  });\n\n  return updated;\n}\n\n/**\n * Removal is a soft delete, and it is subject to the same last-owner rule as a\n * demotion — a removed owner is a demotion to \"no role at all\".\n */\nexport async function removeMember(\n  actor: Actor,\n  input: RemoveMemberInput,\n): Promise<Member> {\n  assertOrgScope(actor, input.orgId);\n\n  const member = requireFound(\n    await memberRepo.findMemberById(input.orgId, input.memberId),\n    \"Member\",\n    input.memberId,\n  );\n  assertCan(actor, \"member:remove\", memberResource(member));\n\n  await assertLastOwnerRetained(input.orgId, input.memberId, \"member\");\n\n  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);\n\n  await emit(\"member.removed\", {\n    ...actorEnvelope(actor),\n    memberId: removed.id,\n    userId: removed.userId,\n  });\n\n  return removed;\n}\n\n/**\n * Turns a (user, org) pair into the `Actor` every service method takes. The\n * only place an `Actor` is minted from stored state — jobs and the session\n * layer both come through here.\n */\nexport async function resolveActor(\n  userId: UserId,\n  orgId: OrgId,\n): Promise<Actor | null> {\n  const member = await memberRepo.findMember(orgId, userId);\n  if (!member || member.status !== \"active\") return null;\n\n  return { userId, orgId, role: member.role };\n}\n\n/**\n * Throws when applying `nextRole` to `memberId` would leave the organization\n * without an owner. Exported because both the demote and the remove path need\n * it, and the invariant must not be stated twice.\n */\nexport async function assertLastOwnerRetained(\n  orgId: OrgId,\n  memberId: MemberId,\n  nextRole: Role,\n): Promise<void> {\n  if