,\n): Promise<Subscription> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"org:manage_billing\", billingResource(input.orgId));\n\n  const subscription = requireFound(\n    await subscriptionRepo.findSubscription(input.orgId),\n    \"Subscription\",\n    input.orgId,\n  );\n\n  return subscriptionRepo.cancelSubscription(\n    input.orgId,\n    input.cancelImmediately\n      ? toIsoTimestamp(new Date())\n      : subscription.currentPeriodEnd,\n  );\n}\n\nexport async function listInvoices(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<readonly Invoice[]> {\n  assertOrgScope(actor, orgId);\n  assertCan(actor, \"org:manage_billing\", billingResource(orgId));\n  return invoiceRepo.listInvoices(orgId);\n}\n\n/**\n * The subscription row is the authority on which plan an org is on; the\n * denormalised `organizations.plan` column is only a display convenience, so\n * every quota decision reads the subscription first.\n */\nasync function planFor(orgId: OrgId): Promise<PlanId> {\n  const subscription = await subscriptionRepo.findSubscription(orgId);\n  if (subscription) return subscription.plan;\n\n  const org = requireFound(\n    await orgRepo.findOrgById(orgId),\n    \"Organization\",\n    orgId,\n  );\n  return org.plan;\n}\n\n/** Maps a quota dimension onto the counter that measures it. */\nasync function usageFor(\n  orgId: OrgId,\n  resource: LimitedResource,\n): Promise<number> {\n  const usage = await usageRepo.getUsage(orgId);\n\n  switch (resource) {\n    case \"seats\":\n      return usage.seatsUsed;\n    case \"projects\":\n      return usage.projectsUsed;\n    case \"issuesPerProject\":\n      return usage.issuesUsed;\n    case \"storageMb\":\n      return usage.storageMbUsed;\n    case \"webhooks\":\n      return webhookRepo.countEndpoints(orgId);\n    case \"apiRequestsPerHour\":\n      return 0;\n  }\n}\n","/**\n * Invoice history for the billing page.\n */\nimport { and, desc, eq } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, invoices } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { toInvoice } from \"./_mappers\";\nimport type { Invoice } from \"@/types/billing\";\nimport type { OrgId } from \"@/types/common\";\n\nexport async function listInvoices(\n  orgId: OrgId,\n): Promise<readonly Invoice[]> {\n  const rows = getDb()\n    .select()\n    .from(invoices)\n    .where(orgPredicate(invoices.orgId, orgId))\n    .orderBy(desc(invoices.periodStart))\n    .all();\n  return rows.map(toInvoice);\n}\n\nexport async function insertInvoice(\n  orgId: OrgId,\n  invoice: Omit<Invoice, \"id\" | \"createdAt\" | \"updatedAt\">,\n): Promise<Invoice> {\n  const stamp = toIsoTimestamp(new Date());\n  const row = getDb()\n    .insert(invoices)\n    .values({\n      id: newId(),\n      orgId,\n      number: invoice.number,\n      amountCents: invoice.amountCents,\n      currency: invoice.currency,\n      periodStart: invoice.periodStart,\n      periodEnd: invoice.periodEnd,\n      paidAt: invoice.paidAt,\n      createdAt: stamp,\n      updatedAt: stamp,\n    })\n    .returning()\n    .get();\n\n  return toInvoice(row);\n}\n\nexport async function findInvoice(\n  orgId: OrgId,\n  invoiceId: string,\n): Promise<Invoice | null> {\n  const row = getDb()\n    .select()\n    .from(invoices)\n    .where(and(orgPredicate(invoices.orgId, orgId), eq(invoices.id, invoiceId)))\n    .get();\n  return row ? toInvoice(row) : null;\n}\n","/**\n * Server-side flag context construction and the org-level override toggle.\n *\n * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit\n */\nimport { emit } from \"@/lib/event-bus\";\nimport { isEnabled, snapshotFlags } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { getFlagDefinition } from \"@/config/feature-flags\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport { actorEnvelope, orgResource, requireFound } from \"./_support\";\nimport type { ToggleFeatureFlagInput } from \"@/schemas/feature-flag\";\nimport type { FeatureFlagSnapshot, FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type { Organization } from \"@/types/organization\";\n\n/**\n * Builds the evaluation context every `isEnabled()` call needs. Both halves\n * are nullable so marketing pages — no session, no org — can still ask about\n * a flag and get the free-plan answer.\n */\nexport function buildFlagContext(\n  actor: Actor | null,\n  org: Organization | null,\n): FlagContext {\n  return {\n    orgId: org?.id ?? actor?.orgId ?? null,\n    userId: actor?.userId ?? null,\n    plan: org?.plan ?? \"free\",\n    role: actor?.role ?? null,\n    overrides: org?.settings.enabledFlagOverrides,\n  };\n}\n\n/**\n * The serialisable snapshot the dashboard layout hands to the client provider,\n * so `useFeatureFlag()` answers without a round trip and cannot disagree with\n * the server.\n */\nexport function getSnapshot(\n  actor: Actor,\n  org: Organization,\n): FeatureFlagSnapshot {\n  return snapshotFlags(buildFlagContext(actor, org));\n}\n\n/**\n * Adds or removes an org-level override. Only flags declared `overridable`\n * accept one — a flag gated purely on plan cannot be switched on by an admin,\n * which is what keeps the plan boundary meaningful.\n */\nexport async function toggleFlag(\n  actor: Actor,\n  input: ToggleFeatureFlagInput,\n): Promise<Organization> {\n  assertCan(actor, \"org:manage_flags\", orgResource(input.orgId));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  const definition = getFlagDefinition(input.flag);\n  if (!definition.overridable) {\n    throw new Error(`Feature \"${input.flag}\" cannot be overridden per org`);\n  }\n\n  const current = new Set(org.settings.enabledFlagOverrides);\n  if (input.enabled) {\n    current.add(input.flag);\n  } else {\n    current.delete(input.flag);\n  }\n\n  const updated = await orgRepo.updateOrg(input.orgId, {\n    orgId: input.orgId,\n    settings: { enabledFlagOverrides: [...current] },\n  });\n\n  await emit(\"flag.toggled\", {\n    ...actorEnvelope(actor),\n    flag: input.flag,\n    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),\n  });\n\n  return updated;\n}\n","/**\n * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe\n */\nimport { subscribe } from \"@/lib/event-bus\";\nimport { isEnabled } from \"@/lib/feature-flags\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as notificationRepo from \"@/server/repositories/notification-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as preferenceRepo from \"@/server/repositories/notification-preference-repository\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { notificationResource, requireFound } from \"./_support\";\nimport type {\n  ListNotificationsInput,\n  MarkNotificationReadInput,\n  UpdateNotificationPreferenceInput,\n} from \"@/schemas/notification\";\nimport type { OrgId, Page, UserId } from \"@/types/common\";\nimport type { FlagContext } from \"@/types/feature-flag\";\nimport type { Actor } from \"@/types/member\";\nimport type {\n  Notification,\n  NotificationChannel,\n  NotificationKind,\n  NotificationPreference,\n} from \"@/types/notification\";\n\nexport type NotificationPayload = {\n  title: string;\n  body: string;\n  href: string;\n  actorId: UserId | null;\n};\n\n/** Channels used when a recipient has never touched their preferences. */\nconst DEFAULT_CHANNELS: readonly NotificationChannel[] = [\"in_app\", \"email\"];\n\n/**\n * Writes one notification row per recipient, each with the channel set that\n * recipient's preferences allow. A recipient who has muted every channel is\n * skipped entirely rather than given a row nobody will ever see.\n */\nexport async function notify(\n  orgId: OrgId,\n  kind: NotificationKind,\n  recipients: readonly UserId[],\n  payload: NotificationPayload,\n): Promise<readonly Notification[]> {\n  if (recipients.length === 0) return [];\n\n  const org = await orgRepo.findOrgById(orgId);\n  const flags: FlagContext = {\n    orgId,\n    userId: payload.actorId,\n    plan: org?.plan ?? \"free\",\n    role: null,\n    overrides: org?.settings.enabledFlagOverrides,\n  };\n\n  const rows = [];\n\n  for (const recipientId of new Set(recipients)) {\n    if (recipientId === payload.actorId) continue;\n\n    const preference = await preferenceRepo.getPreference(\n      orgId,\n      recipientId,\n      kind,\n    );\n    const channels = resolveChannels(preference, flags);\n    if (channels.length === 0) continue;\n\n    rows.push({\n      orgId,\n      recipientId,\n      kind,\n      title: payload.title,\n      body: payload.body,\n      href: payload.href,\n      actorId: payload.actorId,\n      channels,\n    });\n  }\n\n  return notificationRepo.insertNotifications(orgId, rows);\n}\n\nexport async function listNotifications(\n  actor: Actor,\n  input: ListNotificationsInput,\n): Promise<Page<Notification>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:read\",\n    notificationResource(input.orgId, input.recipientId),\n  );\n  return notificationRepo.listNotifications(input);\n}\n\nexport async function markRead(\n  actor: Actor,\n  input: MarkNotificationReadInput,\n): Promise<Notification> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(input.orgId, actor.userId),\n  );\n  return notificationRepo.markRead(\n    input.orgId,\n    input.notificationId,\n    toIsoTimestamp(new Date()),\n  );\n}\n\nexport async function markAllRead(\n  actor: Actor,\n  orgId: OrgId,\n): Promise<number> {\n  assertOrgScope(actor, orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(orgId, actor.userId),\n  );\n  return notificationRepo.markAllRead(\n    orgId,\n    actor.userId,\n    toIsoTimestamp(new Date()),\n  );\n}\n\nexport async function updatePreference(\n  actor: Actor,\n  input: UpdateNotificationPreferenceInput,\n): Promise<NotificationPreference> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(\n    actor,\n    \"notification:manage\",\n    notificationResource(input.orgId, input.userId),\n  );\n  return preferenceRepo.upsertPreference(input);\n}\n\n/**\n * Turns a stored preference into the channels one notification will use.\n * `digestOnly` suppresses the immediate email but keeps the in-app row, and\n * the email channel additionally requires the org's `digest_email` plan flag.\n */\nexport function resolveChannels(\n  preference: NotificationPreference | null,\n  flags: FlagContext,\n): readonly NotificationChannel[] {\n  if (preference === null) return DEFAULT_CHANNELS;\n\n  const channels: NotificationChannel[] = [];\n  if (preference.inApp) channels.push(\"in_app\");\n\n  const emailAllowed =\n    preference.email &&\n    (!preference.digestOnly || isEnabled(\"digest_email\", flags));\n\n  if (emailAllowed) channels.push(\"email\");\n  return channels;\n}\n\n/**\n * The bus wiring. Attached at module load rather than from `event-registry`\n * because the fan-out has no other public entry point — importing this module\n * is what makes an org start receiving notifications.\n */\nlet registered = false;\n\nfunction registerFanOut(): void {\n  if (registered) return;\n  registered = true;\n\n  subscribe(\"issue.assigned\", async (payload) => {\n    await notify(payload.orgId, \"issue_assigned\", [payload.assigneeId], {\n      title: \"You were assigned an issue\",\n      body: `Issue ${payload.issueId} is now yours`,\n      href: `/issues/${payload.issueId}`,\n      actorId: payload.actorId,\n    });\n  });\n\n  subscribe(\"issue.overdue\", async (payload) => {\n    if (payload.assigneeId === null) return;\n    await notify(payload.orgId, \"issue_overdue\", [payload.assigneeId], {\n      title: \"An issue is overdue\",\n      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,\n      href: `/issues/${payload.issueId}`,\n      actorId: null,\n    });\n  });\n\n  subscribe(\"comment.created\", async (payload) => {\n    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);\n    const watchers = issue\n      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]\n      : [];\n\n    await notify(payload.orgId, \"comment_created\", watchers, {\n      title: \"New comment\",\n      body: `A comment was added to issue ${payload.issueId}`,\n      href: `/issues/${payload.issueId}`,\n      actorId: payload.actorId,\n    });\n\n    if (payload.mentionedUserIds.length > 0) {\n      await notify(\n        payload.orgId,\n        \"comment_mention\",\n        payload.mentionedUserIds,\n        {\n          title: \"You were mentioned\",\n          body: `You were mentioned on issue ${payload.issueId}`,\n          href: `/issues/${payload.issueId}`,\n          actorId: payload.actorId,\n        },\n      );\n    }\n  });\n\n  subscribe(\"member.joined\", async (payload) => {\n    const org = requireFound(\n      await orgRepo.findOrgById(payload.orgId),\n      \"Organization\",\n      payload.orgId,\n    );\n    await notify(payload.orgId, \"member_joined\", [org.ownerId], {\n      title: \"A new member joined\",\n      body: `${payload.userId} joined as ${payload.role}`,\n      href: \"/settings/members\",\n      actorId: payload.userId,\n    });\n  });\n}\n\nregisterFanOut();\n","/**\n * In-app notification rows and unread counters.\n */\nimport { and, count, desc, eq, gte, inArray, isNull } from \"drizzle-orm\";\nimport { newId } from \"@/lib/id\";\nimport { getDb, notifications } from \"@/server/db\";\nimport { toIsoTimestamp } from \"@/types/common\";\nimport { orgPredicate } from \"./base-repository\";\nimport { compact, keysetPredicate, probeLimit, toPage } from \"./_paging\";\nimport { toNotification } from \"./_mappers\";\nimport type { ListNotificationsInput } from \"@/schemas/notification\";\nimport type {\n  IsoTimestamp,\n  NotificationId,\n  OrgId,\n  Page,\n  UserId,\n} from \"@/types/common\";\nimport type { Notification } from \"@/types/notification\";\n\ntype NewNotification = Omit<\n  Notification,\n  \"id\" | \"createdAt\" | \"updatedAt\" | \"readAt\"\n>;\n\nexport async function listNotifications(\n  input: ListNotificationsInput,\n): Promise<Page<Notification>> {\n  const db = getDb();\n  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };\n\n  const filters = compact(\n    orgPredicate(notifications.orgId, input.orgId),\n    eq(notifications.recipientId, input.recipientId),\n    input.unreadOnly ? isNull(notifications.readAt) : undefined,\n    input.kind === undefined || input.kind.length === 0\n      ? undefined\n      : inArray(notifications.kind, [...input.kind]),\n  );\n\n  const total = db\n    .select({ value: count() })\n    .from(notifications)\n    .where(and(...filters))\n    .get();\n\n  const rows = db\n    .select()\n    .from(notifications)\n    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))\n    .orderBy(desc(notifications.createdAt), desc(notifications.id))\n    .limit(probeLimit(input.limit))\n    .all();\n\n  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({\n    id: row.id,\n    sortValue: row.createdAt,\n  }));\n}\n\n/** Powers the bell badge, so it stays a single indexed count query. */\nexport async function countUnread(\n  orgId: OrgId,\n  recipientId: UserId,\n): Promise<number> {\n  const row = getDb()\n    .select({ value: count() })\n    .from(notifications)\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n      ),\n    )\n    .get();\n  return row?.value ?? 0;\n}\n\nexport async function insertNotification(\n  orgId: OrgId,\n  input: NewNotification,\n): Promise<Notification> {\n  const inserted = await insertNotifications(orgId, [input]);\n  const row = inserted.at(0);\n  if (!row) throw new Error(\"Notification insert produced no row\");\n  return row;\n}\n\n/** Bulk insert used by the fan-out; one statement per recipient batch. */\nexport async function insertNotifications(\n  orgId: OrgId,\n  inputs: readonly NewNotification[],\n): Promise<readonly Notification[]> {\n  if (inputs.length === 0) return [];\n\n  const stamp = toIsoTimestamp(new Date());\n  const rows = getDb()\n    .insert(notifications)\n    .values(\n      inputs.map((input) => ({\n        id: newId(),\n        orgId,\n        recipientId: input.recipientId,\n        kind: input.kind,\n        title: input.title,\n        body: input.body,\n        href: input.href,\n        actorId: input.actorId,\n        readAt: null,\n        channels: JSON.stringify(input.channels),\n        createdAt: stamp,\n        updatedAt: stamp,\n      })),\n    )\n    .returning()\n    .all();\n\n  return rows.map(toNotification);\n}\n\nexport async function markRead(\n  orgId: OrgId,\n  notificationId: NotificationId,\n  at: IsoTimestamp,\n): Promise<Notification> {\n  const row = getDb()\n    .update(notifications)\n    .set({ readAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.id, notificationId),\n      ),\n    )\n    .returning()\n    .get();\n\n  if (!row) throw new Error(`Notification ${notificationId} not found`);\n  return toNotification(row);\n}\n\nexport async function markAllRead(\n  orgId: OrgId,\n  recipientId: UserId,\n  at: IsoTimestamp,\n): Promise<number> {\n  const rows = getDb()\n    .update(notifications)\n    .set({ readAt: at, updatedAt: at })\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n      ),\n    )\n    .returning({ id: notifications.id })\n    .all();\n\n  return rows.length;\n}\n\n/** The digest window query: everything still unread since `since`. */\nexport async function listUnreadSince(\n  orgId: OrgId,\n  recipientId: UserId,\n  since: IsoTimestamp,\n): Promise<readonly Notification[]> {\n  const rows = getDb()\n    .select()\n    .from(notifications)\n    .where(\n      and(\n        orgPredicate(notifications.orgId, orgId),\n        eq(notifications.recipientId, recipientId),\n        isNull(notifications.readAt),\n        gte(notifications.createdAt, since),\n      ),\n    )\n    .orderBy(desc(notifications.createdAt))\n    .all();\n\n  return rows.map(toNotification);\n}\n","/**\n * Per-user, per-kind delivery matrix consulted before every fan-out.\n */\nimport { and, eq } from \"drizzle-orm\";\nimport { getDb, notificationPreferences } from \"@/server/db\";\nimport { orgPredicate } from \"./base-repository\";\nimport { brandId, toPreference } from \"./_mappers\";\nimport type { UpdateNotificationPreferenceInput } from \"@/schemas/notification\";\nimport type { OrgId, UserId } from \"@/types/common\";\nimport type {\n  NotificationKind,\n  NotificationPreference,\n} from \"@/types/notification\";\n\nexport async function listPreferences(\n  orgId: OrgId,\n  userId: UserId,\n): Promise<readonly NotificationPreference[]> {\n  const rows = getDb()\n    .select()\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.userId, userId),\n      ),\n    )\n    .all();\n  return rows.map(toPreference);\n}\n\n/**\n * `null` means \"no explicit row\" — the fan-out then falls back to the default\n * channel set rather than treating the absence as \"everything off\".\n */\nexport async function getPreference(\n  orgId: OrgId,\n  userId: UserId,\n  kind: NotificationKind,\n): Promise<NotificationPreference | null> {\n  const row = getDb()\n    .select()\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.userId, userId),\n        eq(notificationPreferences.kind, kind),\n      ),\n    )\n    .get();\n  return row ? toPreference(row) : null;\n}\n\nexport async function upsertPreference(\n  input: UpdateNotificationPreferenceInput,\n): Promise<NotificationPreference> {\n  const row = getDb()\n    .insert(notificationPreferences)\n    .values({\n      orgId: input.orgId,\n      userId: input.userId,\n      kind: input.kind,\n      inApp: input.inApp,\n      email: input.email,\n      digestOnly: input.digestOnly,\n    })\n    .onConflictDoUpdate({\n      target: [\n        notificationPreferences.orgId,\n        notificationPreferences.userId,\n        notificationPreferences.kind,\n      ],\n      set: {\n        inApp: input.inApp,\n        email: input.email,\n        digestOnly: input.digestOnly,\n      },\n    })\n    .returning()\n    .get();\n\n  return toPreference(row);\n}\n\n/** Distinct users with at least one `digestOnly` preference in this org. */\nexport async function listDigestSubscribers(\n  orgId: OrgId,\n): Promise<readonly UserId[]> {\n  const rows = getDb()\n    .selectDistinct({ userId: notificationPreferences.userId })\n    .from(notificationPreferences)\n    .where(\n      and(\n        orgPredicate(notificationPreferences.orgId, orgId),\n        eq(notificationPreferences.digestOnly, true),\n      ),\n    )\n    .all();\n\n  return rows.map((row) => brandId<UserId>(row.userId));\n}\n","/**\n * Project lifecycle including the project-count quota and the cascade that archives a project's issues.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName\n */\nimport { wouldExceedLimit } from \"@/config/plan-limits\";\nimport { emit } from \"@/lib/event-bus\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { projectKeyFromName, uniqueSlug } from \"@/lib/slug\";\nimport { assertNotArchived } from \"@/lib/soft-delete\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as orgRepo from \"@/server/repositories/organization-repository\";\nimport * as projectRepo from \"@/server/repositories/project-repository\";\nimport {\n  actorEnvelope,\n  orgResource,\n  projectResource,\n  requireFound,\n} from \"./_support\";\nimport type {\n  ArchiveProjectInput,\n  CreateProjectInput,\n  ListProjectsInput,\n  UpdateProjectInput,\n} from \"@/schemas/project\";\nimport type { OrgId, Page, ProjectId } from \"@/types/common\";\nimport type { Actor } from \"@/types/member\";\nimport type { Project, ProjectWithStats } from \"@/types/project\";\n\n/**\n * Creates a project once the plan still has room for one. The key is derived\n * from the name when the caller left it blank, so the issue numbering scheme\n * (`TF-12`) is never invented at the call site.\n */\nexport async function createProject(\n  actor: Actor,\n  input: CreateProjectInput,\n): Promise<Project> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"project:create\", orgResource(input.orgId));\n\n  const org = requireFound(\n    await orgRepo.findOrgById(input.orgId),\n    \"Organization\",\n    input.orgId,\n  );\n\n  const used = await projectRepo.countProjects(input.orgId);\n  if (wouldExceedLimit(org.plan, \"projects\", used)) {\n    throw new Error(\n      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,\n    );\n  }\n\n  const slug = await suggestProjectSlug(input.orgId, input.name);\n\n  const project = await projectRepo.insertProject({\n    ...input,\n    slug,\n    key: input.key || projectKeyFromName(input.name),\n  });\n\n  await emit(\"project.created\", {\n    ...actorEnvelope(actor),\n    projectId: project.id,\n    name: project.name,\n    slug: project.slug,\n  });\n\n  return project;\n}\n\nexport async function updateProject(\n  actor: Actor,\n  input: UpdateProjectInput,\n): Promise<Project> {\n  assertOrgScope(actor, input.orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(input.orgId, input.projectId),\n    \"Project\",\n    input.projectId,\n  );\n  assertCan(actor, \"project:update\", projectResource(project));\n  assertNotArchived(\"Project\", project.id, project);\n\n  return projectRepo.updateProject(input);\n}\n\n/**\n * Archiving a project cascades to its issues by default — leaving live issues\n * behind an archived project is the drift this flag exists to prevent.\n */\nexport async function archiveProject(\n  actor: Actor,\n  input: ArchiveProjectInput,\n): Promise<Project> {\n  assertOrgScope(actor, input.orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(input.orgId, input.projectId),\n    \"Project\",\n    input.projectId,\n  );\n  assertCan(actor, \"project:archive\", projectResource(project));\n  assertNotArchived(\"Project\", project.id, project);\n\n  const issuesArchived = input.archiveIssues\n    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)\n    : 0;\n\n  const archived = await projectRepo.archiveProject(\n    input.orgId,\n    input.projectId,\n  );\n\n  await emit(\"project.archived\", {\n    ...actorEnvelope(actor),\n    projectId: archived.id,\n    issuesArchived,\n  });\n\n  return archived;\n}\n\n/** Restore does not un-archive the issues: they are restored individually. */\nexport async function restoreProject(\n  actor: Actor,\n  orgId: OrgId,\n  projectId: ProjectId,\n): Promise<Project> {\n  assertOrgScope(actor, orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectById(orgId, projectId),\n    \"Project\",\n    projectId,\n  );\n  assertCan(actor, \"project:archive\", projectResource(project));\n\n  const restored = await projectRepo.restoreProject(orgId, projectId);\n\n  await emit(\"project.restored\", {\n    ...actorEnvelope(actor),\n    projectId: restored.id,\n  });\n\n  return restored;\n}\n\nexport async function getProject(\n  actor: Actor,\n  orgId: OrgId,\n  slug: string,\n): Promise<ProjectWithStats> {\n  assertOrgScope(actor, orgId);\n\n  const project = requireFound(\n    await projectRepo.findProjectBySlug(orgId, slug),\n    \"Project\",\n    slug,\n  );\n  assertCan(actor, \"project:read\", projectResource(project));\n\n  return {\n    project,\n    stats: await projectRepo.getProjectStats(orgId, project.id),\n  };\n}\n\nexport async function listProjects(\n  actor: Actor,\n  input: ListProjectsInput,\n): Promise<Page<ProjectWithStats>> {\n  assertOrgScope(actor, input.orgId);\n  assertCan(actor, \"project:read\", orgResource(input.orgId));\n\n  const page = await projectRepo.listProjects(input);\n\n  const items = await Promise.all(\n    page.items.map(async (project) => ({\n      project,\n      stats: await projectRepo.getProjectStats(input.orgId, project.id),\n    })),\n  );\n\n  return { items, nextCursor: page.nextCursor, total: page.total };\n}\n\n/**\n * Slug preview used by both the create form and `createProject`, so what the\n * user sees while typing is what the row ends up with.\n */\nexport async function suggestProjectSlug(\n  orgId: OrgId,\n  name: string,\n): Promise<string> {\n  const taken = await projectRepo.listTakenProjectSlugs(orgId);\n  return uniqueSlug(name, taken);\n}\n"],"names":["UnauthorizedActionError","Error","code","message","name","ForbiddenActionError","action","PlanLimitError","resource","limit","used","RateLimitedError","bucketKey","resetAt","FeatureUnavailableError","flag","ActionNotFoundError","what"