\"@/lib/permissions\";\nimport { findIssueByNumber } from \"@/server/repositories/issue-repository\";\nimport { listActivityForSubject } from \"@/server/repositories/activity-repository\";\nimport { findUserById } from \"@/server/repositories/user-repository\";\nimport { getThread } from \"@/server/services/comment-service\";\nimport { getIssue } from \"@/server/services/issue-service\";\nimport { listMembers } from \"@/server/services/member-service\";\nimport type { CommentId } from \"@/types/common\";\nimport type { User } from \"@/types/member\";\nimport { loadProjectContext } from \"../../../../_lib/project-context\";\n\ntype PageParams = {\n  orgSlug: string;\n  projectSlug: string;\n  issueNumber: string;\n};\n\nexport const dynamic = \"force-dynamic\";\n\nexport const metadata: Metadata = {\n  title: \"Issue\",\n};\n\nconst MEMBER_PICKER_LIMIT = 100;\n\nexport default async function Page(props: {\n  params: Promise<PageParams>;\n  searchParams: Promise<Record<string, string | string[] | undefined>>;\n}) {\n  // Next.js 16: params and searchParams are Promises and MUST be awaited.\n  const { orgSlug, projectSlug, issueNumber } = await props.params;\n  await props.searchParams;\n\n  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);\n\n  const number = Number.parseInt(issueNumber, 10);\n  if (!Number.isInteger(number) || number < 1) {\n    notFound();\n  }\n\n  // The number is only unique within a project, so the lookup is scoped to both\n  // the org and the project — never to the number alone.\n  const found = await findIssueByNumber(org.id, project.id, number);\n  if (found === null) {\n    notFound();\n  }\n\n  const allowed = can(actor, \"issue:read\", {\n    kind: \"issue\",\n    orgId: org.id,\n    projectId: project.id,\n    issueId: found.id,\n    authorId: found.authorId,\n    assigneeId: found.assigneeId,\n  });\n  if (!allowed) {\n    notFound();\n  }\n\n  const [issue, thread, members, activity, author, assignee] = await Promise.all([\n    getIssue(actor, org.id, found.id),\n    getThread(actor, org.id, found.id),\n    listMembers(actor, { orgId: org.id, limit: MEMBER_PICKER_LIMIT }),\n    listActivityForSubject(org.id, \"issue\", found.id),\n    findUserById(found.authorId),\n    found.assigneeId === null\n      ? Promise.resolve<User | null>(null)\n      : findUserById(found.assigneeId),\n  ]);\n\n  if (author === null) {\n    notFound();\n  }\n\n  const actors: Record<string, User> = {};\n  for (const member of members.items) {\n    actors[member.userId] = member.user;\n  }\n\n  async function deleteComment(commentId: CommentId): Promise<void> {\n    \"use server\";\n    await deleteCommentAction({ orgId: org.id, commentId });\n  }\n\n  return (\n    <div className=\"grid gap-10 lg:grid-cols-[minmax(0,1fr)_18rem]\">\n      <div className=\"space-y-10\">\n        <IssueDetail\n          issue={issue}\n          actor={actor}\n          author={author}\n          assignee={assignee}\n        />\n\n        <section className=\"space-y-6\">\n          <h2 className=\"text-sm font-semibold uppercase tracking-wide text-slate-500\">\n            Comments\n          </h2>\n\n          <CommentThread nodes={thread} actor={actor} onDelete={deleteComment} />\n\n          <CommentComposer\n            orgId={org.id}\n            issueId={found.id}\n            members={members.items}\n            onSubmit={createCommentAction}\n          />\n        </section>\n      </div>\n\n      <IssueActivityPanel events={activity} actors={actors} />\n    </div>\n  );\n}\n","\"use server\";\n\n/**\n * Posts a comment and fans out mention notifications; rate limited.\n *\n * Owner D. The notification fan-out itself is not triggered here — the service\n * emits `comment.created` and `NotificationService` subscribes to it. This\n * action only validates, authorizes, charges the rate limit and revalidates.\n *\n * Must call (do not reimplement): createCommentSchema, can, consumeRateLimit,\n * getActor, toActionResult\n */\n\nimport { ForbiddenActionError, RateLimitedError } from \"@/actions/_lib/action-errors\";\nimport { PENDING_COMMENT_ID } from \"@/actions/_lib/permission-resources\";\nimport { withAction } from \"@/actions/_lib/with-action\";\nimport { CACHE_PROFILES, issueTag, revalidateTagged } from \"@/lib/cache\";\nimport { can } from \"@/lib/permissions\";\nimport { consumeRateLimit } from \"@/lib/rate-limit\";\nimport { createCommentSchema, type CreateCommentInput } from \"@/schemas/comment\";\nimport { createComment } from \"@/server/services/comment-service\";\nimport type { ActionResult } from \"@/types/api\";\nimport type { Comment } from \"@/types/comment\";\n\nconst COMMENT_BUCKET = \"comment:create\";\n\nconst run = withAction<typeof createCommentSchema, Comment>(\n  createCommentSchema,\n  async (raw, actor) => {\n    const input = raw as CreateCommentInput;\n\n    const allowed = can(actor, \"comment:create\", {\n      kind: \"comment\",\n      orgId: input.orgId,\n      commentId: PENDING_COMMENT_ID,\n      authorId: actor.userId,\n    });\n    if (!allowed) {\n      throw new ForbiddenActionError(\"comment:create\");\n    }\n\n    const verdict = await consumeRateLimit(input.orgId, COMMENT_BUCKET);\n    if (!verdict.allowed) {\n      throw new RateLimitedError(COMMENT_BUCKET, verdict.resetAt);\n    }\n\n    const comment = await createComment(actor, input);\n    revalidateTagged([issueTag(input.issueId)], CACHE_PROFILES.seconds);\n    return comment;\n  },\n  { revalidate: [\"comments\"], cacheProfile: \"seconds\" },\n);\n\nexport async function createCommentAction(raw: unknown): Promise<ActionResult<Comment>> {\n  return run(raw);\n}\n","import { z } from \"zod\";\nimport {\n  commentIdSchema,\n  issueIdSchema,\n  orgIdSchema,\n  pageRequestSchema,\n  userIdSchema,\n} from \"./common\";\n\nexport const createCommentSchema = z.object({\n  orgId: orgIdSchema,\n  issueId: issueIdSchema,\n  body: z.string().min(1, \"write something\").max(10_000),\n  parentId: commentIdSchema.nullable().default(null),\n  mentionedUserIds: z.array(userIdSchema).max(50).default([]),\n});\n\nexport const updateCommentSchema = z.object({\n  orgId: orgIdSchema,\n  commentId: commentIdSchema,\n  body: z.string().min(1).max(10_000),\n});\n\nexport const deleteCommentSchema = z.object({\n  orgId: orgIdSchema,\n  commentId: commentIdSchema,\n});\n\nexport const listCommentsSchema = z\n  .object({\n    orgId: orgIdSchema,\n    issueId: issueIdSchema,\n    includeArchived: z.boolean().default(false),\n  })\n  .extend(pageRequestSchema.shape);\n\nexport type CreateCommentInput = z.infer<typeof createCommentSchema>;\nexport type UpdateCommentInput = z.infer<typeof updateCommentSchema>;\nexport type DeleteCommentInput = z.infer<typeof deleteCommentSchema>;\nexport type ListCommentsInput = z.infer<typeof listCommentsSchema>;\n","/**\n * Comment creation, edit window enforcement, mention extraction and soft delete.\n *\n * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit\n */\nimport { emit } from \"@/lib/event-bus\";\nimport { resolveMentions } from \"@/lib/mentions\";\nimport { assertCan } from \"@/lib/permissions\";\nimport { consumeRateLimit } from \"@/lib/rate-limit\";\nimport { archivePatch, assertNotArchived } from \"@/lib/soft-delete\";\nimport { assertOrgScope } from \"@/lib/tenant\";\nimport * as commentRepo from \"@/server/repositories/comment-repository\";\nimport * as issueRepo from \"@/server/repositories/issue-repository\";\nimport * as memberRepo from \"@/server/repositories/member-repository\";\nimport {\n  actorEnvelope,\n  commentResource,\n  issueResource,\n  requireFound,\n} from \"./_support\";\nimport type {\n  CreateCommentInput,\n  DeleteCommentInput,\n  UpdateCommentInput,\n} from \"@/schemas/comment\";\nimport type { Comment, CommentThreadNode } from \"@/types/comment\";\nimport type { IssueId, OrgId, UserId } from \"@/types/common\";\nimport type { Actor } from \"@/types/member\";\n\n/** How long after posting an author may still edit their own comment. */\nconst EDIT_WINDOW_MS = 15 * 60 * 1000;\n\n/** How many members are scanned when resolving `@handle` mentions. */\nconst MENTION_LOOKUP_LIMIT = 100;\n\n/** Token bucket protecting the comment thread from burst posting. */\nconst COMMENT_CREATE_BUCKET = \"comment:create\";\n\n/**\n * Posts a comment on a live issue. Mentions written as `@handle` in the body\n * are resolved against the org's members here, so the stored row and the\n * `comment.created` payload agree on who was mentioned — the notification\n * fan-out reads that list rather than re-parsing the markdown.\n */\nexport async function createComment(\n  actor: Actor,\n  input: CreateCommentInput,\n): Promise<Comment> {\n  assertOrgScope(actor, input.orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(input.orgId, input.issueId),\n    \"Issue\",\n    input.issueId,\n  );\n  assertCan(actor, \"comment:create\", issueResource(issue));\n  assertNotArchived(\"Issue\", issue.id, issue);\n\n  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);\n  if (!verdict.allowed) {\n    throw new Error(\n      `Comment rate limit reached; try again after ${verdict.resetAt}`,\n    );\n  }\n\n  const mentionedUserIds = await resolveMentionedUsers(\n    input.orgId,\n    input.body,\n    input.mentionedUserIds,\n  );\n\n  const comment = await commentRepo.insertComment(\n    { ...input, mentionedUserIds: [...mentionedUserIds] },\n    actor.userId,\n  );\n\n  await emit(\"comment.created\", {\n    ...actorEnvelope(actor),\n    commentId: comment.id,\n    issueId: comment.issueId,\n    mentionedUserIds,\n  });\n\n  return comment;\n}\n\n/**\n * Edits are allowed inside a fifteen-minute window, or by anyone the role\n * matrix already lets update a comment. `can()` decides the second half —\n * this service only owns the time window.\n */\nexport async function updateComment(\n  actor: Actor,\n  input: UpdateCommentInput,\n): Promise<Comment> {\n  assertOrgScope(actor, input.orgId);\n\n  const comment = requireFound(\n    await commentRepo.findCommentById(input.orgId, input.commentId),\n    \"Comment\",\n    input.commentId,\n  );\n  assertCan(actor, \"comment:update\", commentResource(comment));\n  assertNotArchived(\"Comment\", comment.id, comment);\n\n  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {\n    throw new Error(\"The edit window for this comment has closed\");\n  }\n\n  return commentRepo.updateComment(input);\n}\n\n/**\n * Deletion is soft: the row keeps its place so replies below it still have an\n * anchor. `archivePatch()` is what the repository writes; asking for it here\n * documents that this service deliberately never issues a hard delete.\n */\nexport async function deleteComment(\n  actor: Actor,\n  input: DeleteCommentInput,\n): Promise<Comment> {\n  assertOrgScope(actor, input.orgId);\n\n  const comment = requireFound(\n    await commentRepo.findCommentById(input.orgId, input.commentId),\n    \"Comment\",\n    input.commentId,\n  );\n  assertCan(actor, \"comment:delete\", commentResource(comment));\n  assertNotArchived(\"Comment\", comment.id, comment);\n\n  const { archivedAt } = archivePatch();\n  const archived = await commentRepo.archiveComment(\n    input.orgId,\n    input.commentId,\n  );\n\n  await emit(\"comment.deleted\", {\n    ...actorEnvelope(actor),\n    occurredAt: archivedAt,\n    commentId: archived.id,\n    issueId: archived.issueId,\n  });\n\n  return archived;\n}\n\nexport async function getThread(\n  actor: Actor,\n  orgId: OrgId,\n  issueId: IssueId,\n): Promise<readonly CommentThreadNode[]> {\n  assertOrgScope(actor, orgId);\n\n  const issue = requireFound(\n    await issueRepo.findIssueById(orgId, issueId),\n    \"Issue\",\n    issueId,\n  );\n  assertCan(actor, \"comment:read\", issueResource(issue));\n\n  return commentRepo.listThread(orgId, issueId);\n}\n\nfunction isPastEditWindow(comment: Comment): boolean {\n  const posted = new Date(comment.createdAt).getTime();\n  return Date.now() - posted > EDIT_WINDOW_MS;\n}\n\n/**\n * Union of the ids the client already resolved (optimistic UI) and the ones\n * parsed out of the body server-side. The server list wins on disagreement.\n */\nasync function resolveMentionedUsers(\n  orgId: OrgId,\n  body: string,\n  clientProvided: readonly UserId[],\n): Promise<readonly UserId[]> {\n  const members = await memberRepo.listMembers({\n    orgId,\n    limit: MENTION_LOOKUP_LIMIT,\n    cursor: null,\n  });\n\n  const resolved = resolveMentions(body, members.items);\n  const known = new Set(members.items.map((member) => member.userId));\n\n  return [\n    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),\n  ];\n}\n","/**\n * Extracts `@handle` mentions from comment bodies and resolves them to member\n * ids.\n *\n * A handle is the local part of a member's email address, lowercased — that\n * is what the comment composer autocompletes and what `CommentService` feeds\n * to the notification fan-out, so extraction and resolution must agree\n * exactly. Mentions inside code spans and fenced blocks are ignored.\n */\nimport type { UserId } from \"@/types/common\";\nimport type { MemberWithUser } from \"@/types/member\";\n\n/** `@` must start the line or follow whitespace/punctuation, never an email. */\nconst MENTION_PATTERN = /(^|[\\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;\n\nfunction withoutCode(body: string): string {\n  return body.replace(/```[\\s\\S]*?```/g, \" \").replace(/`[^`]*`/g, \" \");\n}\n\n/** The handle Taskflow addresses a member by, derived from their email. */\nexport function handleOf(member: MemberWithUser): string {\n  return (member.user.email.split(\"@\")[0] ?? \"\").toLowerCase();\n}\n\n/** Every distinct handle mentioned, in first-appearance order. */\nexport function extractMentions(body: string): readonly string[] {\n  const seen = new Set<string>();\n  const handles: string[] = [];\n\n  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {\n    const handle = (match[2] ?? \"\").toLowerCase();\n    if (handle === \"\" || seen.has(handle)) continue;\n    seen.add(handle);\n    handles.push(handle);\n  }\n\n  return handles;\n}\n\n/**\n * Maps the mentions in `body` onto the ids of members who actually exist in\n * the organization. Unknown handles are silently dropped — a typo must never\n * fail the comment write.\n */\nexport function resolveMentions(\n  body: string,\n  members: readonly MemberWithUser[],\n): readonly UserId[] {\n  const byHandle = new Map<string, UserId>();\n  for (const member of members) {\n    byHandle.set(handleOf(member), member.userId);\n  }\n\n  const resolved: UserId[] = [];\n  const seen = new Set<UserId>();\n  for (const handle of extractMentions(body)) {\n    const userId = byHandle.get(handle);\n    if (userId === undefined || seen.has(userId)) continue;\n    seen.add(userId);\n    resolved.push(userId);\n  }\n\n  return resolved;\n}\n\n/** Wraps every mention in a span so the comment renderer can style it. */\nexport function highlightMentions(body: string): string {\n  return body.replace(\n    MENTION_PATTERN,\n    (_match, prefix: string, handle: string) =>\n      `${prefix}<span class=\"mention\">@${handle}</span>`,\n  );\n}\n","\"use server\";\n\n/**\n * Soft-deletes a comment.\n *\n * Owner D. Deletion is a soft delete: `CommentService` stamps `archived_at`\n * through `archivePatch()` and the thread query filters it out, so replies\n * hanging off the comment keep their parent id.\n *\n * Must call (do not reimplement): deleteCommentSchema, can, getActor,\n * toActionResult\n */\n\nimport { ForbiddenActionError } from \"@/actions/_lib/action-errors\";\nimport { withAction } from \"@/actions/_lib/with-action\";\nimport { CACHE_PROFILES, issueTag, revalidateTagged } from \"@/lib/cache\";\nimport { can } from \"@/lib/permissions\";\nimport { deleteCommentSchema, type DeleteCommentInput } from \"@/schemas/comment\";\nimport { deleteComment } from \"@/server/services/comment-service\";\nimport type { ActionResult } from \"@/types/api\";\nimport type { Comment } from \"@/types/comment\";\n\nconst run = withAction<typeof deleteCommentSchema, Comment>(\n  deleteCommentSchema,\n  async (raw, actor) => {\n    const input = raw as DeleteCommentInput;\n\n    const allowed = can(actor, \"comment:delete\", {\n      kind: \"comment\",\n      orgId: input.orgId,\n      commentId: input.commentId,\n      authorId: actor.userId,\n    });\n    if (!allowed) {\n      throw new ForbiddenActionError(\"comment:delete\");\n    }\n\n    const comment = await deleteComment(actor, input);\n    revalidateTagged([issueTag(comment.issueId)], CACHE_PROFILES.seconds);\n    return comment;\n  },\n  { revalidate: [\"comments\"], cacheProfile: \"seconds\" },\n);\n\nexport async function deleteCommentAction(raw: unknown): Promise<ActionResult<Comment>> {\n  return run(raw);\n}\n","/**\n * Threaded comment list, hiding delete for non-authors.\n *\n * Must call (do not reimplement): can\n */\nimport { EmptyState } from \"@/components/ui/empty-state\";\nimport { can } from \"@/lib/permissions\";\nimport { isLive } from \"@/lib/soft-delete\";\nimport type { CommentId } from \"@/types/common\";\nimport type { CommentThreadNode } from \"@/types/comment\";\nimport type { Actor } from \"@/types/member\";\nimport type { ReactElement } from \"react\";\nimport { organizationResource } from \"../permission/resources\";\nimport { CommentItem } from \"./comment-item\";\n\nexport type CommentThreadProps = {\n  nodes: readonly CommentThreadNode[];\n  actor: Actor;\n  onDelete: (commentId: CommentId) => void;\n  onEdit?: (commentId: CommentId) => void;\n};\n\n/** Oldest first: a discussion reads top to bottom, unlike a feed. */\nexport function orderThread(\n  nodes: readonly CommentThreadNode[],\n): readonly CommentThreadNode[] {\n  return [...nodes].sort((a, b) =>\n    a.comment.createdAt.localeCompare(b.comment.createdAt),\n  );\n}\n\nexport function CommentThread(props: CommentThreadProps): ReactElement | null {\n  const { nodes, actor, onDelete, onEdit } = props;\n\n  if (!can(actor, \"comment:read\", organizationResource(actor.orgId))) {\n    return null;\n  }\n\n  const visible = orderThread(nodes).filter((node) => isLive(node.comment));\n\n  if (visible.length === 0) {\n    return <EmptyState title=\"No comments yet\" description=\"Start the thread.\" />;\n  }\n\n  return (\n    <ol className=\"comment-thread divide-y\">\n      {visible.map((node) => (\n        <li key={node.comment.id}>\n          <ol>\n            <CommentItem\n              comment={node.comment}\n              actor={actor}\n              depth={0}\n              onDelete={onDelete}\n              {...(onEdit !== undefined ? { onEdit } : {})}\n            />\n            {node.replies\n              .filter(isLive)\n              .sort((a, b) => a.createdAt.localeCompare(b.createdAt))\n              .map((reply) => (\n                <CommentItem\n                  key={reply.id}\n                  comment={reply}\n                  actor={actor}\n                  depth={1}\n                  onDelete={onDelete}\n                  {...(onEdit !== undefined ? { onEdit } : {})}\n                />\n              ))}\n          </ol>\n        </li>\n      ))}\n    </ol>\n  );\n}\n","/**\n * One comment with author, timestamp and inline actions.\n *\n * Must call (do not reimplement): can\n */\nimport { Avatar } from \"@/components/ui/avatar\";\nimport { Button } from \"@/components/ui/button\";\nimport { cn } from \"@/lib/cn\";\nimport { formatRelative } from \"@/lib/date\";\nimport { highlightMentions } from \"@/lib/mentions\";\nimport { can } from \"@/lib/permissions\";\nimport { isArchived } from \"@/lib/soft-delete\";\nimport type { CommentId } from \"@/types/common\";\nimport type { CommentWithAuthor } from \"@/types/comment\";\nimport type { Actor } from \"@/types/member\";\nimport type { ReactElement } from \"react\";\nimport { commentResource } from \"../permission/resources\";\n\nexport type CommentItemProps = {\n  comment: CommentWithAuthor;\n  actor: Actor;\n  depth: number;\n  onEdit?: (commentId: CommentId) => void;\n  onDelete?: (commentId: CommentId) => void;\n};\n\n/** Replies are indented once; deeper nesting is flattened by the thread. */\nconst INDENT_REM = 2;\n\nexport function CommentItem(props: CommentItemProps): ReactElement | null {\n  const { comment, actor, depth, onEdit, onDelete } = props;\n  const resource = commentResource(comment);\n\n  // Authors may edit and delete their own comments below the matrix rank —\n  // that escalation lives in `can()`, not here.\n  const mayEdit = can(actor, \"comment:update\", resource);\n  const mayDelete = can(actor, \"comment:delete\", resource);\n\n  if (isArchived(comment)) {\n    return (\n      <li className=\"text-sm italic text-neutral-500\">\n        This comment was deleted.\n      </li>\n    );\n  }\n\n  return (\n    <li\n      className={cn(\"comment-item flex gap-2 py-2\")}\n      style={{ marginLeft: `${Math.min(depth, 1) * INDENT_REM}rem` }}\n    >\n      <Avatar\n        name={comment.author.name}\n        src={comment.author.avatarUrl}\n        size=\"sm\"\n      />\n\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"text-sm\">\n          <strong>{comment.author.name}</strong>\n          <span className=\"ml-2 text-neutral-500\">\n            {formatRelative(comment.createdAt)}\n          </span>\n          {comment.editedAt !== null ? (\n            <span className=\"ml-2 text-xs text-neutral-400\">(edited)</span>\n          ) : null}\n        </p>\n\n        <div\n          className=\"mt-1 text-sm\"\n          dangerouslySetInnerHTML={{ __html: highlightMentions(comment.body) }}\n        />\n\n        {mayEdit || mayDelete ? (\n          <div className=\"mt-1 flex gap-1\">\n            {mayEdit && onEdit !== undefined ? (